const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "// Prisma schema — Logiqdev OS API\n//\n// Module coverage:\n//   01 Users, Members, Organizations, Branches & Permissions  → docs/features/01-users-organizations-permissions.md (LOG-406)\n//   02 CRM & Sales Management (incl. platform custom fields, tags, saved views) → docs/features/02-crm-sales-management.md (LOG-404)\n//   03 Proposals & Quotations (incl. platform number sequences) → docs/features/03-proposal-quotation-generator.md (LOG-303)\n//   04 Contracts (incl. the in-house e-signature service) → docs/features/04-contracts.md (LOG-349)\n//   05 Project Management → docs/features/05-project-management.md (LOG-405)\n//   06 Task Management → docs/features/06-task-management.md (LOG-102)\n//   07 Customer Portal (portal settings only) → docs/features/07-customer-portal.md (LOG-103)\n//   08 Financial Management & Payment Providers (incl. platform products catalog) → docs/features/08-financial-management-stripe-integration.md (LOG-104)\n//   09 Income & Expense Management (ledger, VAT, periods, payroll cost) → docs/features/09-income-expense-management.md (LOG-105)\n//   10 Employee Management (HR, leave, attendance, capacity) → docs/features/10-employee-management-system.md (LOG-107)\n//   11 Communication Center (outbound email/SMS, templates, campaigns) → docs/features/11-communication-center.md (LOG-106)\n//   12 Messaging & Team Communication (channels, messages) → docs/features/12-messaging-team-communication.md (LOG-313)\n//   13 Customer Support (conversations, tickets, SLA, knowledge base) → docs/features/13-customer-support-communication-hub.md (LOG-342)\n//   14 Notifications & Activity Center → docs/features/14-notifications-activity-center.md (LOG-403)\n//   15 Business Docs (wiki, forms, AI knowledge) → docs/features/15-notion-business-docs.md (LOG-341)\n//   17 Documents & File Management (incl. the Document model, vault) → docs/features/17-documents-file-management.md (LOG-407)\n//   18 Time Tracking → docs/features/18-time-tracking.md (LOG-408)\n//   19 Calendar → docs/features/19-calendar.md (LOG-409)\n//   20 Automation Engine (rules, jobs, event bus, webhooks) → docs/features/20-automation-engine.md (LOG-410)\n//   16 is a parking lot (no tables). Section banners below are parsed by docs/scripts/sync-feature-schema-refs.mjs.\n//\n// Conventions:\n//   - Table names snake_case plural via @@map; columns snake_case.\n//   - Primary keys are uuid strings; foreign keys end in _id.\n//   - Records that belong to a tenant carry organization_id (01 §9).\n//   - Every module's tables live in its own banner section. Cross-module references are Prisma relations;\n//     a few remain plain string ids (documented in a comment naming the owning module) where a relation\n//     would be circular or the target is an array/JSON of ids.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// =====================================================================\n// Enums — 01 Users, Organizations & Permissions\n// =====================================================================\n\n/// Platform-level role (01 §64). Operates the SaaS itself; not an organization role.\nenum AuthRole {\n  USER\n  ADMIN\n  SUPER_ADMIN\n  SUPPORT\n}\n\n/// 01 §5\nenum UserStatus {\n  INVITED\n  PENDING_VERIFICATION\n  ACTIVE\n  SUSPENDED\n  LOCKED\n  DEACTIVATED\n}\n\n/// 01 §6, §74\nenum AuthMethodType {\n  PASSWORD\n  MAGIC_LINK\n  PASSKEY\n  OAUTH\n  SSO\n  TOTP\n  SMS_OTP\n  EMAIL_OTP\n  RECOVERY_CODES\n}\n\n/// 01 §10\nenum OrganizationStatus {\n  SETUP\n  ACTIVE\n  SUSPENDED\n  READ_ONLY\n  ARCHIVED\n  PENDING_DELETION\n  DELETED\n}\n\n/// 01 §19\nenum BranchStatus {\n  ACTIVE\n  PLANNED\n  TEMPORARILY_CLOSED\n  SUSPENDED\n  ARCHIVED\n}\n\n/// 01 §16, §119 — what the branch represents; never implies legal status.\nenum BranchKind {\n  OPERATIONAL\n  OFFICE\n  REGIONAL_UNIT\n  SUBSIDIARY_REFERENCE\n  SERVICE_CENTER\n  REMOTE\n}\n\n/// 01 §24, §77–79 — the nature of a membership.\nenum MembershipType {\n  INTERNAL\n  EXTERNAL_COLLABORATOR\n  GUEST\n}\n\n/// 01 §24 membership status\nenum MembershipStatus {\n  INVITED\n  ACTIVE\n  SUSPENDED\n  DEACTIVATED\n}\n\n/// 01 §41, §43\nenum TeamKind {\n  TEAM\n  DEPARTMENT\n  BUSINESS_UNIT\n  PROJECT_TEAM\n}\n\n/// 01 §45 — role types. CUSTOMER_PORTAL roles bundle portal.* permissions (01 §79).\nenum RoleType {\n  SYSTEM\n  ORGANIZATION\n  BRANCH\n  TEAM\n  PROJECT\n  CUSTOMER_PORTAL\n}\n\nenum RoleStatus {\n  DRAFT\n  PUBLISHED\n  DEPRECATED\n}\n\n/// 01 §22, §50 — where a role assignment or grant applies.\nenum ScopeType {\n  ORGANIZATION\n  BRANCH\n  BRANCH_HIERARCHY\n  TEAM\n  PROJECT\n  RESOURCE\n  CUSTOMER\n}\n\n/// 01 §53\nenum PermissionEffect {\n  ALLOW\n  DENY\n}\n\n/// 01 §56 — products that can be enabled per organization and per member.\nenum ModuleKey {\n  CRM\n  PROPOSALS\n  CONTRACTS\n  PROJECTS\n  TASKS\n  CUSTOMER_PORTAL\n  FINANCE\n  INCOME_EXPENSE\n  EMPLOYEES\n  COMMUNICATION\n  MESSAGING\n  SUPPORT\n  NOTIFICATIONS\n  BUSINESS_DOCS\n  DOCUMENTS\n  TIME_TRACKING\n  CALENDAR\n  AUTOMATION\n  ADMINISTRATION\n}\n\n/// 01 §66\nenum InvitationStatus {\n  PENDING\n  ACCEPTED\n  EXPIRED\n  CANCELLED\n  REJECTED\n}\n\n/// 01 §65, §67 — how a membership or invitation was provisioned.\nenum ProvisioningSource {\n  MANUAL\n  INVITATION_LINK\n  BULK_IMPORT\n  SSO\n  SCIM\n  API\n}\n\n/// 01 §69\nenum SsoProtocol {\n  SAML\n  OIDC\n}\n\n/// 01 §70\nenum DomainVerificationStatus {\n  PENDING\n  VERIFIED\n  FAILED\n  REVOKED\n}\n\n/// 01 §74\nenum MfaPolicy {\n  OPTIONAL\n  REQUIRED_FOR_ADMINS\n  REQUIRED_FOR_ALL\n  REQUIRED_FOR_SENSITIVE_MODULES\n}\n\n/// 01 §76\nenum ServiceAccountStatus {\n  ACTIVE\n  SUSPENDED\n  REVOKED\n}\n\n/// 01 §94\nenum DelegationStatus {\n  SCHEDULED\n  ACTIVE\n  EXPIRED\n  REVOKED\n}\n\n/// 01 §73 — who may invite members.\nenum InvitationPolicy {\n  PERMISSION_HOLDERS\n  ADMINS_ONLY\n}\n\n/// 01 §65, §79 — what an invitation grants.\nenum InvitationAudience {\n  MEMBER\n  CUSTOMER_PORTAL\n}\n\n/// 01 §98 — access review campaign lifecycle.\nenum AccessReviewStatus {\n  DRAFT\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\n/// 01 §98 — a reviewer's decision about one member's access.\nenum AccessReviewDecision {\n  PENDING\n  CERTIFIED\n  REVOKED\n  MODIFIED\n}\n\n/// 01 §157 — third-party services an organization connects with its own credentials. LAUNCH SET ONLY: to support another provider add a value\n/// here, an entry in api/src/shared/constants/integration-providers.ts and an adapter in the owning module. The domain enums PaymentProvider (08) and\n/// CommProviderKind (11) already reserve more providers; they stay reserved until their adapter and value are added here.\nenum IntegrationProvider {\n  OPENAI\n  RESEND\n  TWILIO\n  STRIPE\n  VIVA_WALLET\n}\n\n/// 01 §157 — what a connection is used for. Modules resolve a connection by category (+ default, branch).\nenum IntegrationCategory {\n  AI\n  EMAIL\n  SMS\n  PAYMENTS\n}\n\n/// 01 §157 — PENDING = saved but not verified yet; ACTIVE = verified and usable; ERROR = last verification or call failed\n/// (see last_error); DISABLED = switched off by an admin (secret kept); DISCONNECTED = secret destroyed.\nenum IntegrationStatus {\n  PENDING\n  ACTIVE\n  ERROR\n  DISABLED\n  DISCONNECTED\n}\n\n/// 01 §157 — provider environment of the credentials (Stripe test/live, sandbox accounts).\nenum IntegrationMode {\n  LIVE\n  TEST\n}\n\n/// 01 §160 — ORGANIZATION = the organization's own key (default). PLATFORM = Logiqdev-provided key from the platform\n/// environment, only for organizations Logiqdev explicitly enables (plan, trial, local development seeds).\nenum IntegrationCredentialSource {\n  ORGANIZATION\n  PLATFORM\n}\n\n/// 01 §99–100, §139 — who performed an audited action.\nenum AuditActorType {\n  USER\n  SERVICE_ACCOUNT\n  SYSTEM\n  PLATFORM_ADMIN\n}\n\n/// Coarse file kind on Document (17 §2, §4); kept for branding uploads (01 §15). Configurable\n/// categories live in document_categories.\nenum DocumentType {\n  LOGO\n  BANNER\n  IMAGE\n  VIDEO\n  AUDIO\n  PDF\n  DOCUMENT\n  OTHER\n  SPREADSHEET\n  PRESENTATION\n  TEXT\n  CODE\n  ARCHIVE\n  LINK\n}\n\n// =====================================================================\n// Identity — 01 §4–7, §72, §74, §127\n// =====================================================================\n\n/// 01 §4 — a global human identity. Never tenant-scoped.\nmodel User {\n  id                      String     @id @default(uuid())\n  email                   String     @unique\n  phone                   String?    @unique\n  password                String\n  /// Platform-level role (01 §64). Organization permissions are modelled through Membership, not here.\n  role                    AuthRole   @default(USER)\n  status                  UserStatus @default(ACTIVE)\n  first_name              String?\n  last_name               String?\n  display_name            String?\n  profile_photo_url       String?\n  locale                  String?\n  timezone                String?\n  language                String?\n  email_verified_at       DateTime?\n  phone_verified_at       DateTime?\n  mfa_enabled             Boolean    @default(false)\n  /// Last time the password was set or changed; with password_max_age_days (OrganizationSecurityPolicy) it drives forced rotation.\n  password_changed_at     DateTime?\n  last_login_at           DateTime?\n  /// 01 §127 — not permissions.\n  default_organization_id String?\n  deactivated_at          DateTime?\n  created_at              DateTime   @default(now())\n  updated_at              DateTime   @updatedAt\n\n  password_reset_tokens          PasswordResetToken[]\n  auth_methods                   UserAuthMethod[]\n  sessions                       UserSession[]\n  preferences                    UserPreference?\n  memberships                    Membership[]\n  customer_memberships           CustomerPortalMembership[]\n  invitations_sent               Invitation[]                         @relation(\"InvitationInviter\")\n  audit_events                   AuditEvent[]                         @relation(\"AuditActorUser\")\n  portal_profile_change_requests CustomerPortalProfileChangeRequest[] @relation(\"PortalProfileChangeRequester\")\n  external_channel_memberships   ChannelMember[]                      @relation(\"ChannelExternalMember\")\n  external_messages              Message[]                            @relation(\"MessageExternalAuthor\")\n  support_conversations          SupportConversation[]                @relation(\"SupportConversationCustomer\")\n  support_messages               SupportMessage[]                     @relation(\"SupportMessageAuthorUser\")\n  requested_tickets              Ticket[]                             @relation(\"TicketRequesterUser\")\n  support_csat_ratings           SupportCsatRating[]                  @relation(\"SupportCsatRatedBy\")\n  knowledge_article_feedback     KnowledgeArticleFeedback[]           @relation(\"KnowledgeArticleFeedbackUser\")\n  notifications                  Notification[]                       @relation(\"NotificationRecipientUser\")\n  push_devices                   NotificationPushDevice[]\n  portal_document_shares         DocumentShare[]                      @relation(\"DocumentSharePortalUser\")\n  portal_document_approvals      DocumentApprover[]                   @relation(\"DocumentApproverPortalUser\")\n  portal_vault_grants            VaultEntryGrant[]                    @relation(\"VaultGrantPortalUser\")\n  vault_access_logs              VaultAccessLog[]                     @relation(\"VaultAccessActorUser\")\n  calendar_event_attendances     CalendarEventAttendee[]\n  calendar_bookings              CalendarBooking[]\n  platform_events                PlatformEvent[]                      @relation(\"PlatformEventActor\")\n\n  @@index([email])\n  @@index([phone])\n  @@index([status])\n  @@map(\"users\")\n}\n\nmodel PasswordResetToken {\n  id         String    @id @default(uuid())\n  token_hash String    @unique\n  user_uuid  String\n  expires_at DateTime\n  used_at    DateTime?\n  created_at DateTime  @default(now())\n\n  user User @relation(fields: [user_uuid], references: [id], onDelete: Cascade)\n\n  @@index([user_uuid])\n  @@index([expires_at])\n  @@map(\"password_reset_tokens\")\n}\n\n/// 01 §6, §74 — configured authentication factors per user (passkeys, OAuth links, MFA).\nmodel UserAuthMethod {\n  id           String         @id @default(uuid())\n  user_id      String\n  type         AuthMethodType\n  /// Provider or credential identifier: OAuth subject, passkey credential id, phone number, etc.\n  identifier   String?\n  /// Hashed secret where applicable (TOTP seed, recovery codes). Never plain text.\n  secret_hash  String?\n  label        String?\n  /// Provider-specific data (OAuth provider name, passkey public key, transports, …).\n  metadata     Json?\n  verified_at  DateTime?\n  last_used_at DateTime?\n  disabled_at  DateTime?\n  created_at   DateTime       @default(now())\n  updated_at   DateTime       @updatedAt\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@unique([user_id, type, identifier])\n  @@index([user_id])\n  @@map(\"user_auth_methods\")\n}\n\n/// 01 §72 — active sessions, revocable by the user or by security policy.\nmodel UserSession {\n  id                     String    @id @default(uuid())\n  user_id                String\n  /// Organization active in this session (01 §26). Null before the user picks one.\n  active_organization_id String?\n  /// 01 §27 — selected branch context; null means entire organization.\n  active_branch_id       String?\n  /// 01 §27 — several selected branches (multiple selected branches). Empty and active_branch_id null = entire organization.\n  active_branch_ids      String[]  @default([])\n  token_hash             String    @unique\n  device                 String?\n  browser                String?\n  ip_address             String?\n  location_approx        String?\n  user_agent             String?\n  last_activity_at       DateTime  @default(now())\n  expires_at             DateTime\n  revoked_at             DateTime?\n  revoked_reason         String?\n  created_at             DateTime  @default(now())\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@index([user_id])\n  @@index([expires_at])\n  @@map(\"user_sessions\")\n}\n\n/// 01 §127 — user-specific preferences. These are not permissions.\nmodel UserPreference {\n  user_id                 String   @id\n  theme                   String?\n  default_organization_id String?\n  default_branch_id       String?\n  default_team_id         String?\n  dashboard_layout        Json?\n  updated_at              DateTime @updatedAt\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@map(\"user_preferences\")\n}\n\n// =====================================================================\n// Organization (tenant) — 01 §8–15, §70, §73, §128\n// =====================================================================\n\n/// 01 §8 — the tenant. Every major resource belongs to exactly one Organization (01 §9).\nmodel Organization {\n  id              String             @id @default(uuid())\n  legal_name      String\n  display_name    String\n  short_name      String?\n  slug            String             @unique\n  logo_url        String?\n  website         String?\n  country         String?\n  contact_email   String?\n  contact_phone   String?\n  address         Json?\n  tax_identifiers Json?\n  status          OrganizationStatus @default(SETUP)\n\n  // 01 §14, §128 — organization defaults; branches and users may override.\n  default_currency String  @default(\"EUR\")\n  default_timezone String  @default(\"Europe/Athens\")\n  default_language String  @default(\"en\")\n  default_locale   String?\n  date_format      String?\n  number_format    String?\n  week_start       Int     @default(1)\n  working_days     Json?\n  business_hours   Json?\n\n  /// 01 §15 — consumed by every module instead of per-module branding.\n  branding Json?\n  /// Non-structured organization defaults (project defaults, document defaults, notification defaults).\n  settings Json?\n\n  /// 01 §103 — deletion lifecycle.\n  deletion_requested_at DateTime?\n  deletion_scheduled_at DateTime?\n  deleted_at            DateTime?\n  created_at            DateTime  @default(now())\n  updated_at            DateTime  @updatedAt\n\n  security_policy         OrganizationSecurityPolicy?\n  domains                 OrganizationDomain[]\n  modules                 OrganizationModule[]\n  branches                Branch[]\n  teams                   Team[]\n  memberships             Membership[]\n  roles                   Role[]\n  invitations             Invitation[]\n  sso_configurations      SsoConfiguration[]\n  service_accounts        ServiceAccount[]\n  api_keys                ApiKey[]\n  access_reviews          AccessReview[]\n  integration_connections IntegrationConnection[]\n  integration_usage       IntegrationUsageDaily[]\n  delegations             Delegation[]\n  customer_memberships    CustomerPortalMembership[]\n  audit_events            AuditEvent[]\n\n  // 02 CRM\n  crm_companies                    CrmCompany[]\n  crm_contacts                     CrmContact[]\n  crm_leads                        CrmLead[]\n  crm_deals                        CrmDeal[]\n  crm_pipelines                    CrmPipeline[]\n  crm_lead_sources                 CrmLeadSource[]\n  crm_lead_statuses                CrmLeadStatus[]\n  crm_lifecycle_stages             CrmLifecycleStage[]\n  crm_activities                   CrmActivity[]\n  crm_notes                        CrmNote[]\n  crm_assignment_rules             CrmAssignmentRule[]\n  crm_import_jobs                  CrmImportJob[]\n  // 03 Proposals\n  proposal_templates               ProposalTemplate[]\n  proposals                        Proposal[]\n  number_sequences                 NumberSequence[]\n  // 04 Contracts\n  contract_types                   ContractType[]\n  contract_templates               ContractTemplate[]\n  contract_clauses                 ContractClause[]\n  contract_approval_rules          ContractApprovalRule[]\n  contracts                        Contract[]\n  signature_requests               SignatureRequest[]\n  // 05 Projects\n  project_types                    ProjectType[]\n  project_statuses                 ProjectStatus[]\n  project_templates                ProjectTemplate[]\n  projects                         Project[]\n  // 06 Tasks\n  task_statuses                    TaskStatus[]\n  task_types                       TaskType[]\n  task_labels                      TaskLabel[]\n  // 07 Customer Portal\n  portal_settings                  CustomerPortalSettings?\n  // 08 Finance\n  billing_profiles                 BillingProfile[]\n  products                         Product[]\n  tax_rates                        TaxRate[]\n  coupons                          Coupon[]\n  invoices                         Invoice[]\n  payments                         Payment[]\n  credit_notes                     CreditNote[]\n  subscriptions                    Subscription[]\n  dunning_policies                 DunningPolicy[]\n  provider_webhook_events          ProviderWebhookEvent[]\n  tasks                            Task[]\n  cycles                           Cycle[]\n  releases                         Release[]\n  custom_field_groups              CustomFieldGroup[]\n  custom_field_definitions         CustomFieldDefinition[]\n  tags                             Tag[]\n  saved_views                      SavedView[]\n  // 07 Customer Portal\n  portal_profile_change_requests   CustomerPortalProfileChangeRequest[]\n  invoice_templates                InvoiceTemplate[]\n  ledger_settings                  LedgerSettings?\n  ledger_categories                LedgerCategory[]\n  ledger_payment_methods           LedgerPaymentMethod[]\n  ledger_supplier_profiles         LedgerSupplierProfile[]\n  ledger_records                   LedgerRecord[]\n  ledger_invoice_imports           LedgerInvoiceImport[]\n  recurring_expenses               RecurringExpense[]\n  payroll_schedules                PayrollSchedule[]\n  payroll_entries                  PayrollEntry[]\n  financial_periods                FinancialPeriod[]\n  financial_period_summaries       FinancialPeriodSummary[]\n  ledger_profitability_snapshots   LedgerProfitabilitySnapshot[]\n  ledger_insights                  LedgerInsight[]\n  employee_hr_settings             EmployeeHrSettings?\n  employees                        Employee[]\n  skills                           Skill[]\n  employee_availability_entries    EmployeeAvailabilityEntry[]\n  leave_types                      LeaveType[]\n  leave_policies                   LeavePolicy[]\n  leave_balances                   LeaveBalance[]\n  leave_requests                   LeaveRequest[]\n  company_holidays                 CompanyHoliday[]\n  attendance_records               AttendanceRecord[]\n  attendance_summaries             AttendanceSummary[]\n  employee_capacity_periods        EmployeeCapacityPeriod[]\n  performance_review_cycles        PerformanceReviewCycle[]\n  performance_reviews              PerformanceReview[]\n  performance_goals                PerformanceGoal[]\n  performance_feedback             PerformanceFeedback[]\n  performance_improvement_plans    PerformanceImprovementPlan[]\n  employee_documents               EmployeeDocument[]\n  employee_hr_notes                EmployeeHrNote[]\n  employee_profile_change_requests EmployeeProfileChangeRequest[]\n  comm_provider_accounts           CommProviderAccount[]\n  comm_sender_domains              CommSenderDomain[]\n  comm_sender_identities           CommSenderIdentity[]\n  comm_signatures                  CommSignature[]\n  comm_templates                   CommTemplate[]\n  comm_threads                     CommThread[]\n  comm_messages                    CommMessage[]\n  comm_delivery_events             CommDeliveryEvent[]\n  comm_tracked_links               CommTrackedLink[]\n  comm_recipient_lists             CommRecipientList[]\n  segments                         Segment[]\n  comm_consents                    CommConsent[]\n  comm_suppressions                CommSuppression[]\n  campaigns                        Campaign[]\n  comm_daily_stats                 CommDailyStat[]\n  comm_ai_generations              CommAiGeneration[]\n  messaging_settings               MessagingSettings?\n  messaging_retention_policies     MessagingRetentionPolicy[]\n  channel_templates                ChannelTemplate[]\n  channels                         Channel[]\n  channel_member_restrictions      ChannelMemberRestriction[]\n  messages                         Message[]\n  message_reminders                MessageReminder[]\n  messaging_keywords               MessagingKeyword[]\n  channel_sections                 ChannelSection[]\n  messaging_presence               MessagingPresence[]\n  message_reports                  MessageReport[]\n  messaging_export_jobs            MessagingExportJob[]\n  messaging_integrations           MessagingIntegration[]\n  channel_calls                    ChannelCall[]\n  messaging_usage_daily            MessagingUsageDaily[]\n  support_settings                 SupportSettings?\n  support_inboxes                  SupportInbox[]\n  support_channels                 SupportChannel[]\n  support_conversations            SupportConversation[]\n  ticket_statuses                  TicketStatus[]\n  ticket_categories                TicketCategory[]\n  sla_policies                     SlaPolicy[]\n  tickets                          Ticket[]\n  support_incidents                SupportIncident[]\n  support_csat_ratings             SupportCsatRating[]\n  support_canned_responses         SupportCannedResponse[]\n  knowledge_categories             KnowledgeCategory[]\n  knowledge_articles               KnowledgeArticle[]\n  support_ai_sessions              SupportAiSession[]\n  support_ai_suggestions           SupportAiSuggestion[]\n  notification_event_types         NotificationEventType[]\n  notification_events              NotificationEvent[]\n  notifications                    Notification[]\n  notification_deliveries          NotificationDelivery[]\n  notification_templates           NotificationTemplate[]\n  notification_org_settings        NotificationOrgSettings?\n  notification_org_defaults        NotificationOrgDefault[]\n  notification_recipient_settings  NotificationRecipientSettings[]\n  notification_preferences         NotificationPreference[]\n  notification_keywords            NotificationKeyword[]\n  notification_digests             NotificationDigest[]\n  notification_delivery_rules      NotificationDeliveryRule[]\n  wiki_spaces                      WikiSpace[]\n  wiki_page_templates              WikiPageTemplate[]\n  wiki_pages                       WikiPage[]\n  wiki_checklists                  WikiChecklist[]\n  wiki_checklist_runs              WikiChecklistRun[]\n  custom_forms                     CustomForm[]\n  form_assignments                 FormAssignment[]\n  form_submissions                 FormSubmission[]\n  wiki_ai_index_entries            WikiAiIndexEntry[]\n  wiki_ai_suggestions              WikiAiSuggestion[]\n  document_settings                DocumentSettings?\n  document_categories              DocumentCategory[]\n  document_storage_connections     DocumentStorageConnection[]\n  document_retention_policies      DocumentRetentionPolicy[]\n  folder_templates                 FolderTemplate[]\n  folders                          Folder[]\n  documents                        Document[]\n  document_upload_jobs             DocumentUploadJob[]\n  document_attachments             DocumentAttachment[]\n  document_shares                  DocumentShare[]\n  document_approvals               DocumentApproval[]\n  document_deletion_requests       DocumentDeletionRequest[]\n  vault_keys                       VaultKey[]\n  vault_entries                    VaultEntry[]\n  vault_access_logs                VaultAccessLog[]\n  time_tracking_settings           TimeTrackingSettings?\n  time_activity_types              TimeActivityType[]\n  billing_rates                    BillingRate[]\n  time_entries                     TimeEntry[]\n  timers                           Timer[]\n  time_import_jobs                 TimeImportJob[]\n  time_suggestions                 TimeSuggestion[]\n  time_entry_adjustments           TimeEntryAdjustment[]\n  timesheets                       Timesheet[]\n  time_utilization_periods         TimeUtilizationPeriod[]\n  calendar_event_types             CalendarEventType[]\n  calendars                        Calendar[]\n  calendar_resources               CalendarResource[]\n  calendar_events                  CalendarEvent[]\n  calendar_availability_schedules  CalendarAvailabilitySchedule[]\n  booking_links                    BookingLink[]\n  calendar_bookings                CalendarBooking[]\n  calendar_connections             CalendarConnection[]\n  calendar_conferencing_accounts   CalendarConferencingAccount[]\n  // 20 Automation\n  automation_settings              AutomationSettings?\n  automation_rule_templates        AutomationRuleTemplate[]\n  automation_rules                 AutomationRule[]\n  platform_events                  PlatformEvent[]\n  automation_runs                  AutomationRun[]\n  automation_approvals             AutomationApproval[]\n  automation_ai_steps              AutomationAiStep[]\n  automation_run_locks             AutomationRunLock[]\n  scheduled_jobs                   ScheduledJob[]\n  scheduled_job_runs               ScheduledJobRun[]\n  outbound_webhooks                OutboundWebhook[]\n  webhook_deliveries               WebhookDelivery[]\n  inbound_webhooks                 AutomationInboundWebhook[]\n  support_messages                 SupportMessage[]\n  project_deliverable_reviews      ProjectDeliverableReview[]\n  project_status_update_comments   ProjectStatusUpdateComment[]\n  payment_provider_connections     PaymentProviderConnection[]\n  payment_provider_objects         PaymentProviderObject[]\n\n  crm_sales_targets       CrmSalesTarget[]\n  crm_forecast_snapshots  CrmForecastSnapshot[]\n  crm_dashboard_layouts   CrmDashboardLayout[]\n  crm_lead_scoring_rules  CrmLeadScoringRule[]\n  proposal_approval_rules ProposalApprovalRule[]\n\n  @@index([status])\n  @@map(\"organizations\")\n}\n\n/// 01 §73–74 — organization security policy.\nmodel OrganizationSecurityPolicy {\n  organization_id                 String           @id\n  password_min_length             Int              @default(10)\n  password_require_symbols        Boolean          @default(false)\n  password_max_age_days           Int?\n  mfa_policy                      MfaPolicy        @default(OPTIONAL)\n  sso_required                    Boolean          @default(false)\n  session_duration_minutes        Int              @default(43200)\n  idle_timeout_minutes            Int?\n  allowed_email_domains           String[]         @default([])\n  /// Invitations limited to allowed domains.\n  restrict_invitations_to_domains Boolean          @default(false)\n  allowed_ip_ranges               String[]         @default([])\n  /// ISO 3166-1 alpha-2 codes sign-in is allowed from; empty = no country restriction (01 §73 login restrictions).\n  allowed_countries               String[]         @default([])\n  /// 01 §73 — who may send invitations.\n  invitation_policy               InvitationPolicy @default(PERMISSION_HOLDERS)\n  /// 01 §72 — members may list and revoke their own sessions.\n  members_can_view_sessions       Boolean          @default(true)\n  /// Portal users may use the same policy or a lighter one (01 §79).\n  portal_mfa_policy               MfaPolicy        @default(OPTIONAL)\n  updated_at                      DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"organization_security_policies\")\n}\n\n/// 01 §70 — verified corporate email domains.\nmodel OrganizationDomain {\n  id                 String                   @id @default(uuid())\n  organization_id    String\n  domain             String\n  status             DomainVerificationStatus @default(PENDING)\n  verification_token String\n  verified_at        DateTime?\n  /// Allow users with this email domain to discover and request to join (01 §70).\n  allow_discovery    Boolean                  @default(false)\n  /// Automatically provision membership on SSO login from this domain.\n  auto_provision     Boolean                  @default(false)\n  created_at         DateTime                 @default(now())\n  updated_at         DateTime                 @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@unique([domain])\n  @@index([organization_id])\n  @@map(\"organization_domains\")\n}\n\n/// 01 §56 — which products are enabled for the organization.\nmodel OrganizationModule {\n  id              String    @id @default(uuid())\n  organization_id String\n  module          ModuleKey\n  enabled         Boolean   @default(true)\n  enabled_at      DateTime?\n  disabled_at     DateTime?\n  settings        Json?\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, module])\n  @@map(\"organization_modules\")\n}\n\n// =====================================================================\n// Branches — 01 §16–23, §120–122\n// =====================================================================\n\n/// 01 §18 — an organizational unit inside an Organization. Never a tenant.\nmodel Branch {\n  id               String       @id @default(uuid())\n  organization_id  String\n  parent_branch_id String?\n  name             String\n  code             String?\n  kind             BranchKind   @default(OPERATIONAL)\n  /// Marks the organization's headquarters (at most one per organization, enforced in the service).\n  is_headquarters  Boolean      @default(false)\n  status           BranchStatus @default(ACTIVE)\n  country          String?\n  region           String?\n  city             String?\n  address          Json?\n  phone            String?\n  email            String?\n  /// Materialized path of ancestor ids for hierarchy queries (01 §17, §52).\n  path             String       @default(\"\")\n  depth            Int          @default(0)\n  /// Cost center / currency references consumed by Finance (01 §34).\n  cost_center_code String?\n  currency         String?\n\n  // 01 §120–121 — overrides; organization defaults remain the fallback.\n  timezone       String?\n  locale         String?\n  language       String?\n  date_format    String?\n  week_start     Int?\n  working_days   Json?\n  business_hours Json?\n  /// 01 §120 branch-level branding override (optional).\n  branding       Json?\n  custom_fields  Json?\n\n  archived_at DateTime?\n  created_at  DateTime  @default(now())\n  updated_at  DateTime  @updatedAt\n\n  organization                 Organization                @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  payment_provider_connections PaymentProviderConnection[]\n  parent                       Branch?                     @relation(\"BranchHierarchy\", fields: [parent_branch_id], references: [id], onDelete: Restrict)\n  children                     Branch[]                    @relation(\"BranchHierarchy\")\n  managers                     BranchManager[]\n  integration_connections      IntegrationConnection[]\n  holidays                     BranchHoliday[]\n  memberships                  MembershipBranch[]\n  teams                        Team[]\n  invitations                  Invitation[]\n  group_mappings               SsoGroupMapping[]\n  crm_company_branches         CrmCompanyBranch[]\n  crm_leads                    CrmLead[]\n  crm_deals                    CrmDeal[]\n  proposals                    Proposal[]\n  contracts                    Contract[]\n  projects                     Project[]\n  project_branches             ProjectBranch[]\n  invoices                     Invoice[]\n  ledger_records               LedgerRecord[]\n  recurring_expenses           RecurringExpense[]\n  financial_period_summaries   FinancialPeriodSummary[]\n  employees                    Employee[]                  @relation(\"EmployeePrimaryBranch\")\n  employee_positions           EmployeePosition[]          @relation(\"EmployeePositionBranch\")\n  leave_policies               LeavePolicy[]               @relation(\"LeavePolicyBranch\")\n  comm_sender_identities       CommSenderIdentity[]\n  comm_templates               CommTemplate[]\n  comm_messages                CommMessage[]\n  campaigns                    Campaign[]\n  messaging_channels           Channel[]\n  messaging_retention_policies MessagingRetentionPolicy[]\n  support_inboxes              SupportInbox[]\n  support_tickets              Ticket[]\n  wiki_spaces                  WikiSpace[]\n  folders                      Folder[]\n  documents                    Document[]\n  time_entries                 TimeEntry[]\n  time_utilization_periods     TimeUtilizationPeriod[]\n  calendars                    Calendar[]\n  calendar_resources           CalendarResource[]\n  calendar_events              CalendarEvent[]\n  automation_rules             AutomationRule[]\n  scheduled_jobs               ScheduledJob[]\n\n  @@unique([organization_id, code])\n  @@index([organization_id])\n  @@index([parent_branch_id])\n  @@index([organization_id, status])\n  @@map(\"branches\")\n}\n\n/// 01 §20 — responsible Members for a branch.\nmodel BranchManager {\n  id            String   @id @default(uuid())\n  branch_id     String\n  membership_id String\n  title         String?\n  created_at    DateTime @default(now())\n\n  branch     Branch     @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([branch_id, membership_id])\n  @@map(\"branch_managers\")\n}\n\n/// 01 §122 — local holiday calendars consumed by Calendar (19) and Employees (10).\nmodel BranchHoliday {\n  id         String   @id @default(uuid())\n  branch_id  String\n  name       String\n  date       DateTime @db.Date\n  recurring  Boolean  @default(false)\n  created_at DateTime @default(now())\n\n  branch Branch @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n\n  @@unique([branch_id, date, name])\n  @@index([branch_id, date])\n  @@map(\"branch_holidays\")\n}\n\n// =====================================================================\n// Teams — 01 §40–43, §87–88\n// =====================================================================\n\n/// 01 §40 — functional collaboration group. Not a Branch.\nmodel Team {\n  id              String    @id @default(uuid())\n  organization_id String\n  parent_team_id  String?\n  /// 01 §88 — set when the team is restricted to one branch; null for organization-wide / cross-branch.\n  branch_id       String?\n  name            String\n  slug            String?\n  description     String?\n  kind            TeamKind  @default(TEAM)\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n  updated_at      DateTime  @updatedAt\n\n  organization                 Organization               @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent                       Team?                      @relation(\"TeamHierarchy\", fields: [parent_team_id], references: [id], onDelete: SetNull)\n  children                     Team[]                     @relation(\"TeamHierarchy\")\n  branch                       Branch?                    @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  members                      TeamMembership[]\n  invitations                  Invitation[]\n  group_mappings               SsoGroupMapping[]\n  crm_companies                CrmCompany[]\n  crm_deals                    CrmDeal[]\n  crm_pipelines                CrmPipeline[]\n  saved_views                  SavedView[]\n  projects                     Project[]\n  project_allocations          ProjectAllocation[]\n  tasks                        Task[]\n  task_statuses                TaskStatus[]\n  cycles                       Cycle[]\n  releases                     Release[]\n  department_employees         Employee[]                 @relation(\"EmployeeDepartment\")\n  employee_positions           EmployeePosition[]         @relation(\"EmployeePositionDepartment\")\n  messaging_channels           Channel[]\n  message_mentions             MessageMention[]\n  messaging_retention_policies MessagingRetentionPolicy[]\n  support_inboxes              SupportInbox[]\n  support_conversations        SupportConversation[]\n  support_tickets              Ticket[]\n  support_canned_responses     SupportCannedResponse[]\n  wiki_spaces                  WikiSpace[]\n  folders                      Folder[]\n  documents                    Document[]\n  document_shares              DocumentShare[]\n  vault_grants                 VaultEntryGrant[]\n  calendars                    Calendar[]\n  calendar_shares              CalendarShare[]\n  automation_rules             AutomationRule[]\n\n  // Department = Team of kind DEPARTMENT (01 §43) — records scoped to a department\n  department_ledger_records     LedgerRecord[]     @relation(\"LedgerRecordDepartment\")\n  department_recurring_expenses RecurringExpense[] @relation(\"RecurringExpenseDepartment\")\n  department_payroll_schedules  PayrollSchedule[]  @relation(\"PayrollScheduleDepartment\")\n  department_payroll_entries    PayrollEntry[]     @relation(\"PayrollEntryDepartment\")\n  department_wiki_spaces        WikiSpace[]        @relation(\"WikiSpaceDepartment\")\n  department_wiki_checklists    WikiChecklist[]    @relation(\"WikiChecklistDepartment\")\n\n  crm_sales_targets      CrmSalesTarget[]\n  crm_forecast_snapshots CrmForecastSnapshot[]\n  crm_dashboard_layouts  CrmDashboardLayout[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id])\n  @@index([parent_team_id])\n  @@index([branch_id])\n  @@map(\"teams\")\n}\n\n/// 01 §42\nmodel TeamMembership {\n  id            String    @id @default(uuid())\n  team_id       String\n  membership_id String\n  /// Free-form team role label (lead, member, …). Permissions come from Role assignments scoped to the team.\n  team_role     String?\n  /// Team lead (01 §42). team_role stays a free label.\n  is_lead       Boolean   @default(false)\n  is_primary    Boolean   @default(false)\n  started_at    DateTime  @default(now())\n  ended_at      DateTime?\n  created_at    DateTime  @default(now())\n\n  team       Team       @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([team_id, membership_id])\n  @@index([membership_id])\n  @@map(\"team_memberships\")\n}\n\n// =====================================================================\n// Membership — 01 §7, §21, §24–25, §77–78, §89–90, §125–126, §131\n// =====================================================================\n\n/// 01 §24, 12 §81 — the authorization relationship between a User and an Organization; the subject of every\n/// per-module permission check.\n/// Employee data (10) is NOT here; see 01 §80–81.\nmodel Membership {\n  id                  String             @id @default(uuid())\n  user_id             String\n  organization_id     String\n  type                MembershipType     @default(INTERNAL)\n  status              MembershipStatus   @default(ACTIVE)\n  provisioning_source ProvisioningSource @default(MANUAL)\n  /// SCIM / IdP external identifier (01 §68).\n  external_id         String?\n  invited_by_user_id  String?\n  /// 01 §125–126 — defaults for navigation and creation; never restrict permissions.\n  default_branch_id   String?\n  default_team_id     String?\n  job_title           String?\n  joined_at           DateTime           @default(now())\n  last_active_at      DateTime?\n  suspended_at        DateTime?\n  deactivated_at      DateTime?\n  /// 01 §131 — offboarding record (who, when, ownership transfers performed).\n  offboarding         Json?\n  created_at          DateTime           @default(now())\n  updated_at          DateTime           @updatedAt\n\n  user         User         @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  branches                        MembershipBranch[]\n  teams                           TeamMembership[]\n  managed_branches                BranchManager[]\n  module_access                   MembershipModuleAccess[]\n  role_assignments                RoleAssignment[]\n  permission_grants               PermissionGrant[]\n  api_keys                        ApiKey[]\n  created_access_reviews          AccessReview[]           @relation(\"AccessReviewCreator\")\n  access_review_subjects          AccessReviewItem[]       @relation(\"AccessReviewSubject\")\n  access_review_assignments       AccessReviewItem[]       @relation(\"AccessReviewReviewer\")\n  published_role_versions         RoleVersion[]            @relation(\"RoleVersionPublisher\")\n  created_integration_connections IntegrationConnection[]  @relation(\"IntegrationConnectionCreator\")\n  delegations_given               Delegation[]             @relation(\"DelegationDelegator\")\n  delegations_received            Delegation[]             @relation(\"DelegationDelegate\")\n  owned_service_accounts          ServiceAccount[]\n\n  // 02 CRM ownership (02 §20)\n  owned_companies                     CrmCompany[]                     @relation(\"CrmCompanyOwner\")\n  managed_companies                   CrmCompany[]                     @relation(\"CrmCompanyAccountManager\")\n  success_owned_companies             CrmCompany[]                     @relation(\"CrmCompanySuccessOwner\")\n  owned_contacts                      CrmContact[]                     @relation(\"CrmContactOwner\")\n  owned_leads                         CrmLead[]                        @relation(\"CrmLeadOwner\")\n  owned_deals                         CrmDeal[]                        @relation(\"CrmDealOwner\")\n  secondary_owned_deals               CrmDeal[]                        @relation(\"CrmDealSecondaryOwner\")\n  project_managed_deals               CrmDeal[]                        @relation(\"CrmDealProjectManager\")\n  secondary_owned_leads               CrmLead[]                        @relation(\"CrmLeadSecondaryOwner\")\n  secondary_owned_contacts            CrmContact[]                     @relation(\"CrmContactSecondaryOwner\")\n  secondary_owned_companies           CrmCompany[]                     @relation(\"CrmCompanySecondaryOwner\")\n  project_managed_companies           CrmCompany[]                     @relation(\"CrmCompanyProjectManager\")\n  crm_sales_targets                   CrmSalesTarget[]                 @relation(\"CrmSalesTargetOwner\")\n  crm_forecast_snapshots              CrmForecastSnapshot[]            @relation(\"CrmForecastSnapshotOwner\")\n  reviewed_contract_ai_findings       ContractAiFinding[]              @relation(\"ContractAiFindingReviewer\")\n  owned_activities                    CrmActivity[]                    @relation(\"CrmActivityOwner\")\n  authored_notes                      CrmNote[]                        @relation(\"CrmNoteAuthor\")\n  // 03 Proposals\n  owned_proposals                     Proposal[]                       @relation(\"ProposalOwner\")\n  proposal_approvals                  ProposalApproval[]               @relation(\"ProposalApprover\")\n  proposal_comments                   ProposalComment[]                @relation(\"ProposalCommentAuthor\")\n  // 04 Contracts\n  owned_contracts                     Contract[]                       @relation(\"ContractOwner\")\n  contract_reviews                    ContractReview[]                 @relation(\"ContractReviewer\")\n  contract_approvals                  ContractApproval[]               @relation(\"ContractApprover\")\n  contract_comments                   ContractComment[]                @relation(\"ContractCommentAuthor\")\n  contract_signatories                ContractSignatory[]\n  // 05 Projects\n  owned_projects                      Project[]                        @relation(\"ProjectOwner\")\n  project_memberships                 ProjectMember[]\n  project_allocations                 ProjectAllocation[]\n  project_gate_approvals              ProjectGate[]                    @relation(\"ProjectGateApprover\")\n  // 06 Tasks\n  assigned_tasks                      Task[]                           @relation(\"TaskAssignee\")\n  reported_tasks                      Task[]                           @relation(\"TaskReporter\")\n  task_assignments                    TaskAssignee[]\n  task_comments                       TaskComment[]                    @relation(\"TaskCommentAuthor\")\n  task_watches                        TaskWatcher[]\n  saved_views                         SavedView[]\n  crm_import_jobs                     CrmImportJob[]\n  created_ledger_records              LedgerRecord[]                   @relation(\"LedgerRecordCreator\")\n  approved_ledger_records             LedgerRecord[]                   @relation(\"LedgerRecordApprover\")\n  recorded_ledger_settlements         LedgerSettlement[]               @relation(\"LedgerSettlementRecorder\")\n  uploaded_ledger_imports             LedgerInvoiceImport[]            @relation(\"LedgerImportUploader\")\n  reviewed_ledger_imports             LedgerInvoiceImport[]            @relation(\"LedgerImportReviewer\")\n  approved_payroll_entries            PayrollEntry[]                   @relation(\"PayrollEntryApprover\")\n  closed_financial_periods            FinancialPeriod[]                @relation(\"FinancialPeriodCloser\")\n  resolved_ledger_insights            LedgerInsight[]                  @relation(\"LedgerInsightResolver\")\n  employee                            Employee?\n  decided_leave_requests              LeaveRequest[]                   @relation(\"LeaveRequestDecider\")\n  leave_request_approvals             LeaveRequestApproval[]           @relation(\"LeaveRequestApprover\")\n  performance_reviews_given           PerformanceReview[]              @relation(\"PerformanceReviewer\")\n  performance_feedback_authored       PerformanceFeedback[]            @relation(\"PerformanceFeedbackAuthor\")\n  employee_hr_notes_authored          EmployeeHrNote[]                 @relation(\"EmployeeHrNoteAuthor\")\n  comm_sender_identities              CommSenderIdentity[]             @relation(\"CommSenderIdentityMembership\")\n  comm_signatures                     CommSignature[]                  @relation(\"CommSignatureMembership\")\n  created_comm_templates              CommTemplate[]                   @relation(\"CommTemplateCreator\")\n  created_comm_template_versions      CommTemplateVersion[]            @relation(\"CommTemplateVersionCreator\")\n  sent_comm_messages                  CommMessage[]                    @relation(\"CommMessageSender\")\n  owned_comm_messages                 CommMessage[]                    @relation(\"CommMessageOwner\")\n  received_comm_messages              CommMessage[]                    @relation(\"CommMessageRecipientMembership\")\n  comm_message_recipients             CommMessageRecipient[]           @relation(\"CommMessageRecipientsMembership\")\n  created_comm_recipient_lists        CommRecipientList[]              @relation(\"CommRecipientListCreator\")\n  comm_recipient_list_memberships     CommRecipientListMember[]        @relation(\"CommRecipientListMemberMembership\")\n  created_segments                    Segment[]                        @relation(\"SegmentCreator\")\n  owned_campaigns                     Campaign[]                       @relation(\"CampaignOwner\")\n  approved_campaigns                  Campaign[]                       @relation(\"CampaignApprover\")\n  created_campaigns                   Campaign[]                       @relation(\"CampaignCreator\")\n  campaign_recipients                 CampaignRecipient[]              @relation(\"CampaignRecipientMembership\")\n  campaign_approvals                  CampaignApproval[]               @relation(\"CampaignApprovalApprover\")\n  comm_ai_generations                 CommAiGeneration[]               @relation(\"CommAiGenerationRequester\")\n  owned_channels                      Channel[]                        @relation(\"ChannelOwner\")\n  created_channels                    Channel[]                        @relation(\"ChannelCreator\")\n  channel_memberships                 ChannelMember[]\n  channel_restrictions                ChannelMemberRestriction[]       @relation(\"ChannelRestrictionTarget\")\n  messages                            Message[]                        @relation(\"MessageAuthor\")\n  message_reactions                   MessageReaction[]\n  message_mentions                    MessageMention[]                 @relation(\"MessageMentionMember\")\n  message_acknowledgements            MessageAcknowledgement[]\n  channel_read_states                 ChannelReadState[]\n  message_read_receipts               MessageReadReceipt[]\n  thread_follows                      MessageThreadFollower[]\n  pinned_messages                     ChannelPin[]                     @relation(\"ChannelPinner\")\n  saved_messages                      SavedMessage[]\n  message_reminders                   MessageReminder[]\n  message_drafts                      MessageDraft[]\n  messaging_keywords                  MessagingKeyword[]\n  channel_sections                    ChannelSection[]\n  messaging_presence                  MessagingPresence?\n  messaging_settings                  MessagingMemberSettings?\n  message_reports                     MessageReport[]                  @relation(\"MessageReportReporter\")\n  messaging_export_jobs               MessagingExportJob[]             @relation(\"MessagingExportRequester\")\n  started_calls                       ChannelCall[]                    @relation(\"ChannelCallStarter\")\n  call_participations                 ChannelCallParticipant[]\n  // 13 Support\n  support_inbox_defaults              SupportInbox[]                   @relation(\"SupportInboxDefaultAssignee\")\n  assigned_support_conversations      SupportConversation[]            @relation(\"SupportConversationAssignee\")\n  support_conversation_participations SupportConversationParticipant[] @relation(\"SupportConversationParticipant\")\n  support_messages                    SupportMessage[]                 @relation(\"SupportMessageAuthor\")\n  assigned_tickets                    Ticket[]                         @relation(\"TicketAssignee\")\n  ticket_follows                      TicketFollower[]                 @relation(\"TicketFollower\")\n  support_csat_ratings                SupportCsatRating[]              @relation(\"SupportCsatAgent\")\n  support_canned_responses            SupportCannedResponse[]          @relation(\"SupportCannedResponseOwner\")\n  knowledge_articles_authored         KnowledgeArticle[]               @relation(\"KnowledgeArticleAuthor\")\n  support_ai_suggestions_reviewed     SupportAiSuggestion[]            @relation(\"SupportAiSuggestionReviewer\")\n  notification_events_acted           NotificationEvent[]              @relation(\"NotificationEventActor\")\n  notifications                       Notification[]                   @relation(\"NotificationRecipientMembership\")\n  notifications_acted                 Notification[]                   @relation(\"NotificationActorMembership\")\n  notification_settings               NotificationRecipientSettings?\n  notification_preferences            NotificationPreference[]\n  notification_keywords               NotificationKeyword[]\n  notification_digests                NotificationDigest[]\n  owned_wiki_spaces                   WikiSpace[]                      @relation(\"WikiSpaceOwner\")\n  wiki_space_memberships              WikiSpaceMember[]\n  owned_wiki_pages                    WikiPage[]                       @relation(\"WikiPageOwner\")\n  wiki_page_reviews                   WikiPageReviewer[]\n  wiki_page_comments                  WikiPageComment[]                @relation(\"WikiPageCommentAuthor\")\n  wiki_page_favorites                 WikiPageFavorite[]\n  wiki_page_acknowledgements          WikiPageAcknowledgement[]\n  wiki_checklist_runs                 WikiChecklistRun[]               @relation(\"WikiChecklistRunSubject\")\n  owned_custom_forms                  CustomForm[]                     @relation(\"CustomFormOwner\")\n  form_assignment_receipts            FormAssignmentRecipient[]\n  form_submissions                    FormSubmission[]                 @relation(\"FormSubmissionRespondent\")\n  owned_documents                     Document[]                       @relation(\"DocumentOwner\")\n  authored_document_versions          DocumentVersion[]                @relation(\"DocumentVersionAuthor\")\n  document_upload_jobs                DocumentUploadJob[]              @relation(\"DocumentUploadJobInitiator\")\n  document_shares_received            DocumentShare[]                  @relation(\"DocumentShareMembership\")\n  document_shares_given               DocumentShare[]                  @relation(\"DocumentShareSharer\")\n  document_approvals_requested        DocumentApproval[]               @relation(\"DocumentApprovalRequester\")\n  document_approver_entries           DocumentApprover[]               @relation(\"DocumentApproverMembership\")\n  document_favorites                  DocumentFavorite[]\n  document_recent_accesses            DocumentRecentAccess[]\n  owned_vault_entries                 VaultEntry[]                     @relation(\"VaultEntryOwner\")\n  vault_grants                        VaultEntryGrant[]                @relation(\"VaultGrantMembership\")\n  vault_access_logs                   VaultAccessLog[]                 @relation(\"VaultAccessActorMembership\")\n  time_default_approver_for           TimeTrackingSettings[]           @relation(\"TimeTrackingDefaultApprover\")\n  time_project_approvals              TimeProjectSettings[]            @relation(\"TimeProjectApprover\")\n  billing_rates                       BillingRate[]                    @relation(\"BillingRateMember\")\n  created_billing_rates               BillingRate[]                    @relation(\"BillingRateCreator\")\n  time_entries                        TimeEntry[]                      @relation(\"TimeEntryMember\")\n  approved_time_entries               TimeEntry[]                      @relation(\"TimeEntryApprover\")\n  rejected_time_entries               TimeEntry[]                      @relation(\"TimeEntryRejecter\")\n  locked_time_entries                 TimeEntry[]                      @relation(\"TimeEntryLocker\")\n  unlocked_time_entries               TimeEntry[]                      @relation(\"TimeEntryUnlocker\")\n  timers                              Timer[]                          @relation(\"TimerMember\")\n  time_import_jobs                    TimeImportJob[]                  @relation(\"TimeImportJobCreator\")\n  time_suggestions                    TimeSuggestion[]                 @relation(\"TimeSuggestionMember\")\n  time_entry_adjustments              TimeEntryAdjustment[]            @relation(\"TimeEntryAdjustmentCreator\")\n  timesheets                          Timesheet[]                      @relation(\"TimesheetMember\")\n  timesheets_to_approve               Timesheet[]                      @relation(\"TimesheetApprover\")\n  approved_timesheets                 Timesheet[]                      @relation(\"TimesheetApprovedBy\")\n  rejected_timesheets                 Timesheet[]                      @relation(\"TimesheetRejectedBy\")\n  locked_timesheets                   Timesheet[]                      @relation(\"TimesheetLockedBy\")\n  unlocked_timesheets                 Timesheet[]                      @relation(\"TimesheetUnlockedBy\")\n  timesheet_actions                   TimesheetAction[]                @relation(\"TimesheetActionActor\")\n  time_utilization_periods            TimeUtilizationPeriod[]          @relation(\"TimeUtilizationMember\")\n  calendar_preference                 CalendarPreference?\n  owned_calendars                     Calendar[]                       @relation(\"CalendarOwner\")\n  calendar_shares                     CalendarShare[]\n  organized_calendar_events           CalendarEvent[]                  @relation(\"CalendarEventOrganizer\")\n  calendar_event_attendances          CalendarEventAttendee[]\n  calendar_event_reminders            CalendarEventReminder[]\n  calendar_availability_schedules     CalendarAvailabilitySchedule[]\n  owned_booking_links                 BookingLink[]                    @relation(\"BookingLinkOwner\")\n  booking_link_hosts                  BookingLinkHost[]\n  hosted_bookings                     CalendarBooking[]                @relation(\"CalendarBookingHost\")\n  calendar_connections                CalendarConnection[]\n  calendar_conferencing_accounts      CalendarConferencingAccount[]\n  // 20 Automation\n  authored_automation_templates       AutomationRuleTemplate[]         @relation(\"AutomationRuleTemplateAuthor\")\n  owned_automation_rules              AutomationRule[]                 @relation(\"AutomationRuleOwner\")\n  authored_automation_rule_versions   AutomationRuleVersion[]          @relation(\"AutomationRuleVersionAuthor\")\n  platform_events                     PlatformEvent[]                  @relation(\"PlatformEventActorMembership\")\n  triggered_automation_runs           AutomationRun[]                  @relation(\"AutomationRunActor\")\n  automation_approvals_requested      AutomationApproval[]             @relation(\"AutomationApprovalRequestedFrom\")\n  automation_approvals_decided        AutomationApproval[]             @relation(\"AutomationApprovalApprover\")\n  triggered_scheduled_job_runs        ScheduledJobRun[]                @relation(\"ScheduledJobRunTriggeredBy\")\n  created_outbound_webhooks           OutboundWebhook[]                @relation(\"OutboundWebhookCreator\")\n  created_inbound_webhooks            AutomationInboundWebhook[]       @relation(\"InboundWebhookCreator\")\n  project_deliverable_reviews         ProjectDeliverableReview[]       @relation(\"ProjectDeliverableReviewer\")\n  project_status_update_comments      ProjectStatusUpdateComment[]     @relation(\"ProjectStatusUpdateCommentAuthor\")\n\n  @@unique([user_id, organization_id])\n  @@unique([organization_id, external_id])\n  @@index([organization_id, status])\n  @@index([user_id])\n  @@map(\"memberships\")\n}\n\n/// 01 §21, §90 — a Member can belong to one or many branches.\nmodel MembershipBranch {\n  id               String    @id @default(uuid())\n  membership_id    String\n  branch_id        String\n  is_primary       Boolean   @default(false)\n  /// 01 §91 — whether access cascades to child branches.\n  include_children Boolean   @default(false)\n  started_at       DateTime  @default(now())\n  ended_at         DateTime?\n\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  branch     Branch     @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n\n  @@unique([membership_id, branch_id])\n  @@index([branch_id])\n  @@map(\"membership_branches\")\n}\n\n/// 01 §56–57 — per-member product access, evaluated before feature permissions.\nmodel MembershipModuleAccess {\n  id                 String    @id @default(uuid())\n  membership_id      String\n  module             ModuleKey\n  enabled            Boolean   @default(true)\n  granted_by_user_id String?\n  created_at         DateTime  @default(now())\n  updated_at         DateTime  @updatedAt\n\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([membership_id, module])\n  @@map(\"membership_module_access\")\n}\n\n// =====================================================================\n// Roles & Permissions — 01 §44–63, §92–97, §111–114\n// =====================================================================\n\n/// 01 §46 — the global permission catalog. Keys follow `<module>.<resource>.<action>`. Every module's\n/// \"Permissions\" section registers its keys here (06 §15, 07 §16, 14 §12, 17 §14, 18 §11, 19 §10, 20 §10,\n/// 12 §52, 13 §13, 15 §8).\nmodel Permission {\n  id             String    @id @default(uuid())\n  key            String    @unique\n  module         ModuleKey\n  resource       String\n  action         String\n  description    String?\n  /// 01 §59 — requires elevated roles; surfaced in conflict warnings (01 §97).\n  is_sensitive   Boolean   @default(false)\n  /// 01 §60 — field-level permission marker.\n  is_field_level Boolean   @default(false)\n  created_at     DateTime  @default(now())\n\n  roles  RolePermission[]\n  grants PermissionGrant[]\n\n  @@index([module])\n  @@map(\"permissions\")\n}\n\n/// 01 §44–45, §111 — reusable permission bundle. organization_id is null for system roles and\n/// platform-provided templates (01 §111) that organizations clone.\nmodel Role {\n  id               String      @id @default(uuid())\n  organization_id  String?\n  name             String\n  slug             String\n  description      String?\n  type             RoleType    @default(ORGANIZATION)\n  status           RoleStatus  @default(PUBLISHED)\n  is_system        Boolean     @default(false)\n  /// Template this role was cloned from (01 §111).\n  template_role_id String?\n  /// Default scope type this role is intended for (01 §50).\n  default_scope    ScopeType   @default(ORGANIZATION)\n  /// Modules this role grants product access to when assigned (01 §109).\n  modules          ModuleKey[] @default([])\n  /// Incremented each time the role is published (01 §109). History in RoleVersion.\n  version          Int         @default(1)\n  published_at     DateTime?\n  /// Role-level restrictions beyond per-permission conditions, e.g. { require_mfa: true, hide_rates: true } (01 §109).\n  restrictions     Json?\n  created_at       DateTime    @default(now())\n  updated_at       DateTime    @updatedAt\n\n  organization         Organization?              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  permissions          RolePermission[]\n  versions             RoleVersion[]\n  assignments          RoleAssignment[]\n  invitations          Invitation[]\n  group_mappings       SsoGroupMapping[]\n  customer_memberships CustomerPortalMembership[]\n  project_members      ProjectMember[]\n  message_mentions     MessageMention[]\n  wiki_checklists      WikiChecklist[]\n\n  crm_dashboard_layouts CrmDashboardLayout[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, type])\n  @@map(\"roles\")\n}\n\n/// 01 §44, §53 — permissions bundled in a role, with optional explicit deny.\nmodel RolePermission {\n  role_id       String\n  permission_id String\n  effect        PermissionEffect @default(ALLOW)\n  /// Optional field-level or resource-level restriction data (01 §48, §60).\n  conditions    Json?\n\n  role       Role       @relation(fields: [role_id], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permission_id], references: [id], onDelete: Cascade)\n\n  @@id([role_id, permission_id])\n  @@index([permission_id])\n  @@map(\"role_permissions\")\n}\n\n/// 01 §92–93 — a role given to a principal (Member or Service Account) within a scope.\n/// scope_id references the Branch, Team, Project (05), Customer (02) or resource identified by scope_type.\nmodel RoleAssignment {\n  id                 String    @id @default(uuid())\n  membership_id      String?\n  service_account_id String?\n  role_id            String\n  scope_type         ScopeType @default(ORGANIZATION)\n  scope_id           String?\n  granted_by_user_id String?\n  reason             String?\n  valid_from         DateTime  @default(now())\n  /// 01 §93 — temporary access; null means permanent.\n  valid_until        DateTime?\n  revoked_at         DateTime?\n  created_at         DateTime  @default(now())\n\n  membership      Membership?     @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  service_account ServiceAccount? @relation(fields: [service_account_id], references: [id], onDelete: Cascade)\n  role            Role            @relation(fields: [role_id], references: [id], onDelete: Cascade)\n\n  @@index([membership_id])\n  @@index([service_account_id])\n  @@index([role_id])\n  @@index([scope_type, scope_id])\n  @@map(\"role_assignments\")\n}\n\n/// 01 §49, §53 — explicit per-member allow or deny for one permission, outside any role.\nmodel PermissionGrant {\n  id                 String           @id @default(uuid())\n  membership_id      String\n  permission_id      String\n  effect             PermissionEffect @default(ALLOW)\n  scope_type         ScopeType        @default(ORGANIZATION)\n  scope_id           String?\n  granted_by_user_id String?\n  reason             String?\n  valid_from         DateTime         @default(now())\n  valid_until        DateTime?\n  revoked_at         DateTime?\n  created_at         DateTime         @default(now())\n\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permission_id], references: [id], onDelete: Cascade)\n\n  @@index([membership_id])\n  @@index([permission_id])\n  @@index([scope_type, scope_id])\n  @@map(\"permission_grants\")\n}\n\n/// 01 §94 — temporary delegation of selected responsibilities.\nmodel Delegation {\n  id                      String           @id @default(uuid())\n  organization_id         String\n  delegator_membership_id String\n  delegate_membership_id  String\n  /// Permission keys or role ids delegated.\n  permission_keys         String[]         @default([])\n  role_ids                String[]         @default([])\n  scope_type              ScopeType        @default(ORGANIZATION)\n  scope_id                String?\n  status                  DelegationStatus @default(SCHEDULED)\n  reason                  String?\n  starts_at               DateTime\n  ends_at                 DateTime\n  revoked_at              DateTime?\n  created_at              DateTime         @default(now())\n  updated_at              DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  delegator    Membership   @relation(\"DelegationDelegator\", fields: [delegator_membership_id], references: [id], onDelete: Cascade)\n  delegate     Membership   @relation(\"DelegationDelegate\", fields: [delegate_membership_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, status])\n  @@index([delegate_membership_id])\n  @@map(\"delegations\")\n}\n\n/// 01 §98 — periodic access review (certification campaign) over an organization, branch, team or module.\nmodel AccessReview {\n  id                       String             @id @default(uuid())\n  organization_id          String\n  name                     String\n  description              String?\n  status                   AccessReviewStatus @default(DRAFT)\n  /// What is reviewed: ORGANIZATION, BRANCH, BRANCH_HIERARCHY or TEAM (scope_id).\n  scope_type               ScopeType          @default(ORGANIZATION)\n  scope_id                 String?\n  /// Optional: only review members who hold access to these modules. Empty = all modules.\n  modules                  ModuleKey[]        @default([])\n  starts_at                DateTime?\n  due_at                   DateTime\n  completed_at             DateTime?\n  created_by_membership_id String?\n  created_at               DateTime           @default(now())\n  updated_at               DateTime           @updatedAt\n\n  organization Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  created_by   Membership?        @relation(\"AccessReviewCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  items        AccessReviewItem[]\n\n  @@index([organization_id, status])\n  @@index([organization_id, due_at])\n  @@map(\"access_reviews\")\n}\n\n/// 01 §98 — one member's access inside an access review, with the reviewer's decision.\nmodel AccessReviewItem {\n  id                     String               @id @default(uuid())\n  review_id              String\n  /// Member whose access is reviewed.\n  membership_id          String\n  reviewer_membership_id String?\n  decision               AccessReviewDecision @default(PENDING)\n  decided_at             DateTime?\n  comment                String?\n  /// Roles, grants, module access and branch scopes at review time, so the decision stays meaningful later.\n  access_snapshot        Json\n  /// Set when a REVOKED / MODIFIED decision has been applied to RoleAssignment / PermissionGrant / MembershipModuleAccess.\n  applied_at             DateTime?\n  created_at             DateTime             @default(now())\n  updated_at             DateTime             @updatedAt\n\n  review     AccessReview @relation(fields: [review_id], references: [id], onDelete: Cascade)\n  membership Membership   @relation(\"AccessReviewSubject\", fields: [membership_id], references: [id], onDelete: Cascade)\n  reviewer   Membership?  @relation(\"AccessReviewReviewer\", fields: [reviewer_membership_id], references: [id], onDelete: SetNull)\n\n  @@unique([review_id, membership_id])\n  @@index([reviewer_membership_id, decision])\n  @@map(\"access_review_items\")\n}\n\n/// 01 §109 — immutable snapshot of a role each time it is published.\nmodel RoleVersion {\n  id                         String      @id @default(uuid())\n  role_id                    String\n  version                    Int\n  name                       String\n  description                String?\n  default_scope              ScopeType\n  modules                    ModuleKey[] @default([])\n  /// [{ permission_key, effect, conditions }] as published.\n  permissions                Json\n  restrictions               Json?\n  note                       String?\n  published_by_membership_id String?\n  published_at               DateTime    @default(now())\n\n  role         Role        @relation(fields: [role_id], references: [id], onDelete: Cascade)\n  published_by Membership? @relation(\"RoleVersionPublisher\", fields: [published_by_membership_id], references: [id], onDelete: SetNull)\n\n  @@unique([role_id, version])\n  @@map(\"role_versions\")\n}\n\n/// 01 §157 — one connected third-party service of an organization (OpenAI, Resend, Stripe, Twilio ...) with the\n/// organization's OWN credentials, so provider keys do not live in the platform .env (01 §160). Secrets are write-only:\n/// envelope-encrypted under the organization's VaultKey (17 §12), never returned by any API, never logged, never copied\n/// into audit metadata (01 §158). Domain tables (08 PaymentProviderConnection, 11 CommProviderAccount) point here instead of storing credentials.\nmodel IntegrationConnection {\n  id                       String                      @id @default(uuid())\n  organization_id          String\n  provider                 IntegrationProvider\n  category                 IntegrationCategory\n  /// Label shown to admins (\"OpenAI production\", \"Stripe EU test\"). Unique per organization.\n  name                     String\n  status                   IntegrationStatus           @default(PENDING)\n  mode                     IntegrationMode             @default(LIVE)\n  credential_source        IntegrationCredentialSource @default(ORGANIZATION)\n  /// base64 ciphertext (nonce + tag included) of ALL secret fields as one JSON object, e.g. { \"api_key\": \"...\", \"webhook_secret\": \"...\" }.\n  /// Null for PLATFORM-source rows. Field names per provider: api/src/shared/constants/integration-providers.ts.\n  secret_ciphertext        String?\n  vault_key_id             String?\n  /// Non-reversible per-field hints for lists, e.g. { \"api_key\": \"sk-...a3f9\" } (prefix + last 4 characters at most).\n  secret_hints             Json?\n  /// Non-secret settings per provider (default model, region, from address, publishable key, account id ...).\n  config                   Json?\n  /// Result of the last verification: { account_id, account_name, models, domains, country, capabilities ... }.\n  capabilities             Json?\n  /// Organization-set guardrails, e.g. { monthly_spend_limit_usd, requests_per_minute }; enforced by the integration layer before calling the provider.\n  usage_limits             Json?\n  /// Public, unguessable id used in the callback URL of providers that send webhooks; resolves organization + secret without exposing ids.\n  webhook_token            String?                     @unique\n  /// At most one default per organization, category and mode (enforced by the service). Modules resolve a connection by category + default (01 §159).\n  is_default               Boolean                     @default(false)\n  /// 01 §34 — restrict the connection to one branch; null = whole organization.\n  branch_id                String?\n  expires_at               DateTime?\n  rotated_at               DateTime?\n  last_verified_at         DateTime?\n  last_used_at             DateTime?\n  last_error               String?\n  last_error_at            DateTime?\n  created_by_membership_id String?\n  connected_at             DateTime?\n  disconnected_at          DateTime?\n  created_at               DateTime                    @default(now())\n  updated_at               DateTime                    @updatedAt\n\n  organization                 Organization                @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  vault_key                    VaultKey?                   @relation(fields: [vault_key_id], references: [id], onDelete: Restrict)\n  branch                       Branch?                     @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  created_by                   Membership?                 @relation(\"IntegrationConnectionCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  usage                        IntegrationUsageDaily[]\n  payment_provider_connections PaymentProviderConnection[]\n  comm_provider_accounts       CommProviderAccount[]\n\n  @@unique([organization_id, name])\n  @@index([organization_id, category, status])\n  @@index([organization_id, provider])\n  @@map(\"integration_connections\")\n}\n\n/// 01 §157 — daily usage of one connection for the usage view and spend guardrails. Written only by the integration layer.\nmodel IntegrationUsageDaily {\n  id                        String   @id @default(uuid())\n  organization_id           String\n  integration_connection_id String\n  date                      DateTime @db.Date\n  requests                  Int      @default(0)\n  failures                  Int      @default(0)\n  /// Provider units consumed; meaning depends on the category: tokens (AI), messages (EMAIL, SMS), minor currency units processed (PAYMENTS).\n  units                     BigInt   @default(0)\n  /// Estimated cost in millionths of cost_currency when the provider price is known; null otherwise.\n  cost_micros               BigInt?\n  cost_currency             String?\n  /// Breakdown, e.g. AI: { input_tokens, output_tokens, by_model }.\n  breakdown                 Json?\n\n  organization           Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  integration_connection IntegrationConnection @relation(fields: [integration_connection_id], references: [id], onDelete: Cascade)\n\n  @@unique([integration_connection_id, date])\n  @@index([organization_id, date])\n  @@map(\"integration_usage_daily\")\n}\n\n// =====================================================================\n// Invitations — 01 §65–66\n// =====================================================================\n\nmodel Invitation {\n  id                   String             @id @default(uuid())\n  organization_id      String\n  email                String\n  type                 MembershipType     @default(INTERNAL)\n  /// MEMBER joins the organization (branch/team/role); CUSTOMER_PORTAL joins a customer company (customer_id) via the portal.\n  audience             InvitationAudience @default(MEMBER)\n  branch_id            String?\n  team_id              String?\n  role_id              String?\n  /// Modules to enable on acceptance (01 §65).\n  modules              ModuleKey[]        @default([])\n  token_hash           String             @unique\n  status               InvitationStatus   @default(PENDING)\n  source               ProvisioningSource @default(MANUAL)\n  message              String?\n  invited_by_user_id   String?\n  expires_at           DateTime\n  accepted_at          DateTime?\n  /// Membership created on acceptance.\n  membership_id        String?\n  /// 01 §79, 07 §2 — CRM Company (02) the invitee joins as a Customer Portal user; set instead of branch_id/team_id.\n  customer_id          String?\n  /// CustomerPortalMembership created on acceptance of a customer invitation.\n  portal_membership_id String?\n  cancelled_at         DateTime?\n  rejected_at          DateTime?\n  created_at           DateTime           @default(now())\n  updated_at           DateTime           @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch       Branch?      @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  role         Role?        @relation(fields: [role_id], references: [id], onDelete: SetNull)\n  invited_by   User?        @relation(\"InvitationInviter\", fields: [invited_by_user_id], references: [id], onDelete: SetNull)\n  customer     CrmCompany?  @relation(fields: [customer_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, status])\n  @@index([email])\n  @@index([expires_at])\n  @@index([organization_id, customer_id])\n  @@map(\"invitations\")\n}\n\n// =====================================================================\n// SSO & provisioning — 01 §68–71\n// =====================================================================\n\n/// 01 §69 — identity provider configuration per organization.\nmodel SsoConfiguration {\n  id                  String      @id @default(uuid())\n  organization_id     String\n  name                String\n  protocol            SsoProtocol\n  enabled             Boolean     @default(false)\n  /// Issuer, entity id, metadata URL, client id, certificates, attribute mapping. Secrets are stored encrypted.\n  config              Json\n  auto_provision      Boolean     @default(false)\n  /// 01 §67–68 — SCIM provisioning token hash and settings, when enabled.\n  scim_enabled        Boolean     @default(false)\n  scim_token_hash     String?\n  scim_last_synced_at DateTime?\n  created_at          DateTime    @default(now())\n  updated_at          DateTime    @updatedAt\n\n  organization   Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  group_mappings SsoGroupMapping[]\n\n  @@index([organization_id])\n  @@map(\"sso_configurations\")\n}\n\n/// 01 §71 — external IdP group → role / team / branch / module access.\nmodel SsoGroupMapping {\n  id                   String      @id @default(uuid())\n  sso_configuration_id String\n  external_group       String\n  role_id              String?\n  team_id              String?\n  branch_id            String?\n  modules              ModuleKey[] @default([])\n  created_at           DateTime    @default(now())\n\n  sso_configuration SsoConfiguration @relation(fields: [sso_configuration_id], references: [id], onDelete: Cascade)\n  role              Role?            @relation(fields: [role_id], references: [id], onDelete: SetNull)\n  team              Team?            @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  branch            Branch?          @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n\n  @@unique([sso_configuration_id, external_group])\n  @@map(\"sso_group_mappings\")\n}\n\n// =====================================================================\n// API access & service accounts — 01 §75–76\n// =====================================================================\n\n/// 01 §76 — non-human identity for automation. Permissions come from RoleAssignment.\nmodel ServiceAccount {\n  id                  String               @id @default(uuid())\n  organization_id     String\n  owner_membership_id String?\n  name                String\n  purpose             String?\n  status              ServiceAccountStatus @default(ACTIVE)\n  expires_at          DateTime?\n  created_at          DateTime             @default(now())\n  updated_at          DateTime             @updatedAt\n\n  organization                    Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner                           Membership?          @relation(fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  role_assignments                RoleAssignment[]\n  api_keys                        ApiKey[]\n  // 20 Automation\n  default_for_automation_settings AutomationSettings[] @relation(\"AutomationSettingsDefaultServiceAccount\")\n  automation_rules                AutomationRule[]     @relation(\"AutomationRuleRunAs\")\n  automation_runs                 AutomationRun[]      @relation(\"AutomationRunRunAs\")\n  platform_events                 PlatformEvent[]      @relation(\"PlatformEventActorServiceAccount\")\n\n  @@unique([organization_id, name])\n  @@index([organization_id, status])\n  @@map(\"service_accounts\")\n}\n\n/// 01 §75 — API credential owned by a Member or a Service Account. Never inherits unlimited permissions.\nmodel ApiKey {\n  id                 String    @id @default(uuid())\n  organization_id    String\n  membership_id      String?\n  service_account_id String?\n  name               String\n  /// First characters shown to the user for identification.\n  key_prefix         String\n  key_hash           String    @unique\n  /// Optional narrowing of the owner's permissions (permission keys).\n  scopes             String[]  @default([])\n  /// Where the key may act: ORGANIZATION, BRANCH, BRANCH_HIERARCHY, TEAM or PROJECT (01 §75). scopes[] narrows by permission key.\n  scope_type         ScopeType @default(ORGANIZATION)\n  scope_id           String?\n  /// When the owner should rotate the key (01 §75 rotation).\n  rotation_due_at    DateTime?\n  expires_at         DateTime?\n  last_used_at       DateTime?\n  rotated_from_id    String?\n  revoked_at         DateTime?\n  created_at         DateTime  @default(now())\n\n  organization    Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership      Membership?     @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  service_account ServiceAccount? @relation(fields: [service_account_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id])\n  @@index([membership_id])\n  @@index([service_account_id])\n  @@map(\"api_keys\")\n}\n\n// =====================================================================\n// Customer Portal identity — 01 §79\n// =====================================================================\n\n/// 01 §79 — a User's membership to a Customer (a CRM Company owned by docs/features/02, LOG-404)\n/// inside an agency Organization. customer_id has no relation until the CRM module defines companies.\nmodel CustomerPortalMembership {\n  id                 String           @id @default(uuid())\n  organization_id    String\n  /// CRM Company id (02). No FK until LOG-404 is implemented.\n  customer_id        String\n  user_id            String\n  /// Role of type CUSTOMER_PORTAL (01 §79 defaults: Owner, Administrator, Manager, Finance, Legal, Viewer).\n  role_id            String?\n  status             MembershipStatus @default(ACTIVE)\n  invited_by_user_id String?\n  joined_at          DateTime         @default(now())\n  last_active_at     DateTime?\n  deactivated_at     DateTime?\n  created_at         DateTime         @default(now())\n  updated_at         DateTime         @updatedAt\n\n  organization             Organization                   @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  user                     User                           @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  role                     Role?                          @relation(fields: [role_id], references: [id], onDelete: SetNull)\n  notifications            Notification[]\n  notification_settings    NotificationRecipientSettings?\n  notification_preferences NotificationPreference[]\n  notification_digests     NotificationDigest[]\n\n  @@unique([organization_id, customer_id, user_id])\n  @@index([customer_id])\n  @@index([user_id])\n  @@map(\"customer_portal_memberships\")\n}\n\n// =====================================================================\n// Audit — 01 §99–100, §139\n// =====================================================================\n\n/// Immutable audit event. Identity and access changes are written here by module 01;\n/// other modules append their own event types using the same table (06 §3, 07 §17, 09 \"Audit Trail\",\n/// 12 §51, 14 §13, 15 §9, 17 §15, 18 §12, 19 §11, 20 §11).\nmodel AuditEvent {\n  id                       String         @id @default(uuid())\n  organization_id          String?\n  actor_type               AuditActorType @default(USER)\n  actor_user_id            String?\n  actor_service_account_id String?\n  /// Stable key, e.g. `membership.role_assigned`, `user.login`, `sso.configuration_changed`.\n  event_type               String\n  resource_type            String?\n  resource_id              String?\n  /// Branch the event applies to (plain id, no relation: audit rows must survive branch deletion). Null = organization-wide.\n  branch_id                String?\n  /// Before/after values or event-specific payload.\n  metadata                 Json?\n  ip_address               String?\n  user_agent               String?\n  created_at               DateTime       @default(now())\n\n  organization Organization? @relation(fields: [organization_id], references: [id], onDelete: SetNull)\n  actor_user   User?         @relation(\"AuditActorUser\", fields: [actor_user_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, created_at])\n  @@index([organization_id, branch_id, created_at])\n  @@index([actor_user_id, created_at])\n  @@index([event_type])\n  @@index([resource_type, resource_id])\n  @@map(\"audit_events\")\n}\n\n// =====================================================================\n// Platform shared concepts defined by 02 CRM — custom fields (§24–26),\n// tags (§36), saved views (§29). Consumed by every module.\n// =====================================================================\n\n/// Entities that can carry custom fields, tags and saved views. Modules append their own values.\nenum RecordEntityType {\n  CRM_COMPANY\n  CRM_CONTACT\n  CRM_LEAD\n  CRM_DEAL\n  CRM_ACTIVITY\n  PROJECT\n  TASK\n  CONTRACT\n  PROPOSAL\n  TICKET\n  DOCUMENT\n  FINANCIAL_RECORD\n  EMPLOYEE\n  INVOICE\n  RECURRING_EXPENSE\n  PAYROLL_ENTRY\n  LEAVE_REQUEST\n  PERFORMANCE_REVIEW\n  PERFORMANCE_GOAL\n  COMM_MESSAGE\n  CAMPAIGN\n  COMM_TEMPLATE\n  CHANNEL\n  MESSAGE\n  PROJECT_MILESTONE\n  PROJECT_CHANGE_REQUEST\n  PAYMENT\n  SUPPORT_CONVERSATION\n  KNOWLEDGE_ARTICLE\n  NOTIFICATION\n  WIKI_SPACE\n  WIKI_PAGE\n  CUSTOM_FORM\n  FORM_SUBMISSION\n  FOLDER\n  VAULT_ENTRY\n  TIME_ENTRY\n  TIMESHEET\n  CALENDAR_EVENT\n  CALENDAR_BOOKING\n  AUTOMATION_RULE\n  AUTOMATION_RUN\n  SCHEDULED_JOB\n  SUBSCRIPTION\n}\n\n/// 02 §24 — supported field types.\nenum CustomFieldType {\n  TEXT\n  LONG_TEXT\n  NUMBER\n  DECIMAL\n  CURRENCY\n  PERCENTAGE\n  BOOLEAN\n  DATE\n  DATETIME\n  EMAIL\n  PHONE\n  URL\n  DROPDOWN\n  MULTI_SELECT\n  RADIO\n  USER\n  TEAM\n  COMPANY\n  CONTACT\n  DEAL\n  RECORD_REFERENCE\n}\n\nenum SavedViewVisibility {\n  PERSONAL\n  TEAM\n  ORGANIZATION\n}\n\n/// 02 §25 — logical sections for shared fields.\nmodel CustomFieldGroup {\n  id              String   @id @default(uuid())\n  organization_id String\n  name            String\n  description     String?\n  sort_order      Int      @default(0)\n  created_at      DateTime @default(now())\n\n  organization Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  fields       CustomFieldDefinition[]\n\n  @@unique([organization_id, name])\n  @@map(\"custom_field_groups\")\n}\n\n/// 02 §24–26 — one definition; shared fields list several entity types (02 §25).\n/// `key` is the stable API identifier (02 §26); `label` may change.\nmodel CustomFieldDefinition {\n  id              String             @id @default(uuid())\n  organization_id String\n  group_id        String?\n  key             String\n  label           String\n  description     String?\n  type            CustomFieldType\n  /// Entity types this field applies to. Length > 1 means a shared field (02 §25).\n  entity_types    RecordEntityType[]\n  is_shared       Boolean            @default(false)\n  is_required     Boolean            @default(false)\n  /// Options for DROPDOWN / MULTI_SELECT / RADIO: [{ value, label, color?, sort_order? }]\n  options         Json?\n  default_value   Json?\n  /// Validation rules (min, max, regex, length …).\n  validation      Json?\n  /// Role-based visibility and visibility rules (02 §24).\n  visibility      Json?\n  is_searchable   Boolean            @default(true)\n  is_filterable   Boolean            @default(true)\n  is_sortable     Boolean            @default(false)\n  sort_order      Int                @default(0)\n  archived_at     DateTime?\n  created_at      DateTime           @default(now())\n  updated_at      DateTime           @updatedAt\n\n  organization Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  group        CustomFieldGroup?  @relation(fields: [group_id], references: [id], onDelete: SetNull)\n  values       CustomFieldValue[]\n\n  @@unique([organization_id, key])\n  @@index([organization_id])\n  @@map(\"custom_field_definitions\")\n}\n\n/// Value of a custom field on a record. entity_id points at the table named by entity_type.\nmodel CustomFieldValue {\n  id            String           @id @default(uuid())\n  definition_id String\n  entity_type   RecordEntityType\n  entity_id     String\n  /// Typed value stored as JSON (string, number, boolean, ISO date, option value, option values[], referenced id).\n  value         Json?\n  /// Denormalized text for search/filter.\n  value_text    String?\n  updated_at    DateTime         @updatedAt\n\n  definition CustomFieldDefinition @relation(fields: [definition_id], references: [id], onDelete: Cascade)\n\n  @@unique([definition_id, entity_id])\n  @@index([entity_type, entity_id])\n  @@index([definition_id, value_text])\n  @@map(\"custom_field_values\")\n}\n\n/// Organization-scoped tags, applied to any record through Tagging.\nmodel Tag {\n  id              String             @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  color           String?\n  /// Restrict a tag to certain entity types; empty = any.\n  entity_types    RecordEntityType[] @default([])\n  created_at      DateTime           @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  taggings     Tagging[]\n\n  @@unique([organization_id, slug])\n  @@map(\"tags\")\n}\n\nmodel Tagging {\n  tag_id      String\n  entity_type RecordEntityType\n  entity_id   String\n  created_at  DateTime         @default(now())\n\n  tag Tag @relation(fields: [tag_id], references: [id], onDelete: Cascade)\n\n  @@id([tag_id, entity_type, entity_id])\n  @@index([entity_type, entity_id])\n  @@map(\"taggings\")\n}\n\n/// 02 §29, 06 §5 — saved views with filters, sorting, grouping, columns; personal, team or organization-wide. Used by every list/board view.\nmodel SavedView {\n  id                  String              @id @default(uuid())\n  organization_id     String\n  entity_type         RecordEntityType\n  name                String\n  /// table | kanban | pipeline | list | timeline | calendar | activity | forecast\n  layout              String              @default(\"table\")\n  visibility          SavedViewVisibility @default(PERSONAL)\n  owner_membership_id String?\n  team_id             String?\n  filters             Json?\n  sorting             Json?\n  grouping            Json?\n  columns             Json?\n  search              String?\n  is_default          Boolean             @default(false)\n  created_at          DateTime            @default(now())\n  updated_at          DateTime            @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner        Membership?  @relation(fields: [owner_membership_id], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  segments     Segment[]\n\n  @@index([organization_id, entity_type])\n  @@index([owner_membership_id])\n  @@map(\"saved_views\")\n}\n\n// =====================================================================\n// 02 CRM & Sales Management — docs/features/02-crm-sales-management.md (LOG-404)\n// Owns: Company, Contact, Lead, Deal, Pipeline, Activities, Notes, lifecycle, ownership.\n// Does not own: Tasks (06), Proposals (03), Contracts (04), Projects (05), Tickets (13),\n// Invoices/Payments/Subscriptions (08), Calendar events (19). Those are referenced by id only.\n// Record history (02 §34) is written to audit_events (01 §139).\n// =====================================================================\n\n/// 02 §2 — company type; lifecycle stage is a separate, configurable dimension (02 §17).\nenum CrmCompanyType {\n  PROSPECT\n  CUSTOMER\n  PARTNER\n  VENDOR\n  OTHER\n}\n\n/// 02 §3 — contact roles within a company; a contact may hold several.\nenum CrmContactRole {\n  PRIMARY\n  DECISION_MAKER\n  TECHNICAL\n  BILLING\n  PROJECT_STAKEHOLDER\n  EXECUTIVE\n}\n\n/// 02 §13 — activity types. MEETING activities link to a Calendar event (19).\nenum CrmActivityType {\n  CALL\n  MEETING\n  FOLLOW_UP\n  REMINDER\n  APPOINTMENT\n  INTERNAL_COMMENT\n  EMAIL\n  OTHER\n}\n\nenum CrmActivityStatus {\n  PLANNED\n  COMPLETED\n  CANCELLED\n  NO_SHOW\n}\n\nenum CrmPriority {\n  LOW\n  NORMAL\n  HIGH\n  URGENT\n}\n\n/// 02 §11 — forecast categories.\nenum CrmForecastCategory {\n  PIPELINE\n  BEST_CASE\n  COMMIT\n  CLOSED_WON\n  CLOSED_LOST\n}\n\n/// 02 §11 — period a sales target covers.\nenum CrmTargetPeriod {\n  MONTH\n  QUARTER\n  YEAR\n}\n\n/// 02 §11, §33 — what a sales target measures.\nenum CrmTargetMetric {\n  REVENUE_WON\n  PIPELINE_CREATED\n  DEALS_WON\n}\n\nenum CrmDealStatus {\n  OPEN\n  WON\n  LOST\n  ABANDONED\n}\n\n/// 02 §22 — import lifecycle.\nenum CrmImportStatus {\n  PENDING\n  VALIDATING\n  PREVIEW\n  IMPORTING\n  COMPLETED\n  FAILED\n  ROLLED_BACK\n}\n\n/// 01 §31 — how a branch relates to a company (one company, many branch relationships).\nenum CrmBranchRelationType {\n  OWNER\n  SALES\n  DELIVERY\n  SUPPORT\n  BILLING\n  OTHER\n}\n\n// --- Configuration -----------------------------------------------------------\n\n/// 02 §5 — configurable lead sources.\nmodel CrmLeadSource {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  is_default      Boolean   @default(false)\n  sort_order      Int       @default(0)\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  companies    CrmCompany[]\n  contacts     CrmContact[]\n  leads        CrmLead[]\n  deals        CrmDeal[]\n\n  @@unique([organization_id, slug])\n  @@map(\"crm_lead_sources\")\n}\n\n/// 02 §4 — configurable lead statuses.\nmodel CrmLeadStatus {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  color           String?\n  sort_order      Int       @default(0)\n  is_default      Boolean   @default(false)\n  is_converted    Boolean   @default(false)\n  is_lost         Boolean   @default(false)\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  leads        CrmLead[]\n\n  @@unique([organization_id, slug])\n  @@map(\"crm_lead_statuses\")\n}\n\n/// 02 §17 — configurable lifecycle stages (Lead → MQL → SQL → Opportunity → Customer → …).\nmodel CrmLifecycleStage {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  sort_order      Int       @default(0)\n  /// Reaching this stage marks the company as a Customer (terminology, Product_Specification §5a).\n  is_customer     Boolean   @default(false)\n  is_default      Boolean   @default(false)\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n\n  organization Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  companies    CrmCompany[]\n  contacts     CrmContact[]\n  history      CrmLifecycleHistory[]\n\n  @@unique([organization_id, slug])\n  @@map(\"crm_lifecycle_stages\")\n}\n\n/// 02 §17 — historical lifecycle changes.\nmodel CrmLifecycleHistory {\n  id                 String   @id @default(uuid())\n  company_id         String?\n  contact_id         String?\n  stage_id           String\n  changed_by_user_id String?\n  changed_at         DateTime @default(now())\n\n  company CrmCompany?       @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  contact CrmContact?       @relation(fields: [contact_id], references: [id], onDelete: Cascade)\n  stage   CrmLifecycleStage @relation(fields: [stage_id], references: [id], onDelete: Cascade)\n\n  @@index([company_id, changed_at])\n  @@index([contact_id, changed_at])\n  @@map(\"crm_lifecycle_history\")\n}\n\n/// 02 §8 — multiple pipelines per organization.\nmodel CrmPipeline {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  description     String?\n  /// Optional owning team (02 §21).\n  team_id         String?\n  is_default      Boolean   @default(false)\n  currency        String?\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n  updated_at      DateTime  @updatedAt\n\n  organization Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team         Team?              @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  stages       CrmPipelineStage[]\n  deals        CrmDeal[]\n\n  sales_targets      CrmSalesTarget[]\n  forecast_snapshots CrmForecastSnapshot[]\n\n  @@unique([organization_id, slug])\n  @@map(\"crm_pipelines\")\n}\n\n/// 02 §8 — pipeline-specific stages with default probability.\nmodel CrmPipelineStage {\n  id                String              @id @default(uuid())\n  pipeline_id       String\n  name              String\n  slug              String\n  sort_order        Int                 @default(0)\n  /// Default win probability (0–100) applied to deals entering this stage.\n  probability       Int                 @default(0)\n  forecast_category CrmForecastCategory @default(PIPELINE)\n  is_won            Boolean             @default(false)\n  is_lost           Boolean             @default(false)\n  /// Days after which a deal in this stage is considered stale (02 §31 inactive-deal rule).\n  stale_after_days  Int?\n  color             String?\n  created_at        DateTime            @default(now())\n  updated_at        DateTime            @updatedAt\n\n  pipeline     CrmPipeline           @relation(fields: [pipeline_id], references: [id], onDelete: Cascade)\n  deals        CrmDeal[]\n  history_from CrmDealStageHistory[] @relation(\"StageHistoryFrom\")\n  history_to   CrmDealStageHistory[] @relation(\"StageHistoryTo\")\n\n  @@unique([pipeline_id, slug])\n  @@index([pipeline_id, sort_order])\n  @@map(\"crm_pipeline_stages\")\n}\n\n// --- Core records -----------------------------------------------------------\n\n/// 02 §2 — any external legal entity: prospect, customer, partner or vendor. One record model.\n/// Never a platform Organization (01 §8) and never a Branch (01 §16).\nmodel CrmCompany {\n  id                            String         @id @default(uuid())\n  organization_id               String\n  parent_company_id             String?\n  name                          String\n  legal_name                    String?\n  type                          CrmCompanyType @default(PROSPECT)\n  lifecycle_stage_id            String?\n  industry                      String?\n  company_size                  String?\n  number_of_employees           Int?\n  annual_revenue                Decimal?       @db.Decimal(18, 2)\n  currency                      String?\n  website                       String?\n  email                         String?\n  phone                         String?\n  country                       String?\n  address                       Json?\n  tax_id                        String?\n  vat_number                    String?\n  registration_number           String?\n  description                   String?\n  lead_source_id                String?\n  customer_since                DateTime?\n  /// 02 §20 — ownership and responsibility.\n  owner_membership_id           String?\n  account_manager_membership_id String?\n  success_owner_membership_id   String?\n  /// 02 §20 — secondary owner and the project manager responsible for the customer's delivery work.\n  secondary_owner_membership_id String?\n  project_manager_membership_id String?\n  team_id                       String?\n  /// External system identifiers (02 §27). The billing profile itself is owned by 08.\n  external_ids                  Json?\n  last_activity_at              DateTime?\n  next_activity_at              DateTime?\n  archived_at                   DateTime?\n  created_by_user_id            String?\n  created_at                    DateTime       @default(now())\n  updated_at                    DateTime       @updatedAt\n\n  organization    Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent          CrmCompany?        @relation(\"CrmCompanyHierarchy\", fields: [parent_company_id], references: [id], onDelete: SetNull)\n  children        CrmCompany[]       @relation(\"CrmCompanyHierarchy\")\n  lifecycle_stage CrmLifecycleStage? @relation(fields: [lifecycle_stage_id], references: [id], onDelete: SetNull)\n  lead_source     CrmLeadSource?     @relation(fields: [lead_source_id], references: [id], onDelete: SetNull)\n  owner           Membership?        @relation(\"CrmCompanyOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  account_manager Membership?        @relation(\"CrmCompanyAccountManager\", fields: [account_manager_membership_id], references: [id], onDelete: SetNull)\n  success_owner   Membership?        @relation(\"CrmCompanySuccessOwner\", fields: [success_owner_membership_id], references: [id], onDelete: SetNull)\n  secondary_owner Membership?        @relation(\"CrmCompanySecondaryOwner\", fields: [secondary_owner_membership_id], references: [id], onDelete: SetNull)\n  project_manager Membership?        @relation(\"CrmCompanyProjectManager\", fields: [project_manager_membership_id], references: [id], onDelete: SetNull)\n  team            Team?              @relation(fields: [team_id], references: [id], onDelete: SetNull)\n\n  contacts                       CrmContact[]\n  leads                          CrmLead[]\n  deals                          CrmDeal[]\n  activities                     CrmActivity[]\n  branches                       CrmCompanyBranch[]\n  lifecycle_history              CrmLifecycleHistory[]\n  converted_from_leads           CrmLead[]                            @relation(\"LeadConvertedCompany\")\n  proposals                      Proposal[]\n  primary_contracts              Contract[]                           @relation(\"ContractPrimaryCompany\")\n  contract_parties               ContractParty[]\n  projects                       Project[]\n  billing_profiles               BillingProfile[]\n  invoices                       Invoice[]\n  subscriptions                  Subscription[]\n  portal_profile_change_requests CustomerPortalProfileChangeRequest[]\n  ledger_supplier_profile        LedgerSupplierProfile?\n  ledger_records                 LedgerRecord[]\n  ledger_invoice_imports         LedgerInvoiceImport[]\n  recurring_expenses             RecurringExpense[]\n  financial_period_summaries     FinancialPeriodSummary[]\n  ledger_profitability_snapshots LedgerProfitabilitySnapshot[]\n  comm_threads                   CommThread[]\n  comm_messages                  CommMessage[]\n  messaging_channels             Channel[]\n  support_conversations          SupportConversation[]\n  support_tickets                Ticket[]\n  folders                        Folder[]\n  documents                      Document[]\n  vault_entries                  VaultEntry[]\n  calendars                      Calendar[]\n  calendar_events                CalendarEvent[]\n  booking_links                  BookingLink[]\n  calendar_bookings              CalendarBooking[]\n  portal_invitations             Invitation[]\n\n  @@index([organization_id, name])\n  @@index([organization_id, type])\n  @@index([organization_id, lifecycle_stage_id])\n  @@index([owner_membership_id])\n  @@index([parent_company_id])\n  @@map(\"crm_companies\")\n}\n\n/// 01 §31, §37 — branch relationships on one company record instead of duplicate companies.\nmodel CrmCompanyBranch {\n  id            String                @id @default(uuid())\n  company_id    String\n  branch_id     String\n  relation_type CrmBranchRelationType @default(SALES)\n  is_primary    Boolean               @default(false)\n  created_at    DateTime              @default(now())\n\n  company CrmCompany @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  branch  Branch     @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n\n  @@unique([company_id, branch_id, relation_type])\n  @@index([branch_id])\n  @@map(\"crm_company_branches\")\n}\n\n/// 02 §3 — a person at a Company. Not a platform User (01 §4).\nmodel CrmContact {\n  id                            String           @id @default(uuid())\n  organization_id               String\n  company_id                    String?\n  first_name                    String\n  last_name                     String?\n  job_title                     String?\n  department                    String?\n  /// Primary email; additional addresses in `emails`.\n  email                         String?\n  emails                        Json?\n  phone                         String?\n  mobile                        String?\n  phones                        Json?\n  website                       String?\n  linkedin_url                  String?\n  social_profiles               Json?\n  roles                         CrmContactRole[] @default([])\n  contact_type                  String?\n  lifecycle_stage_id            String?\n  lead_source_id                String?\n  owner_membership_id           String?\n  /// 02 §20 — secondary owner.\n  secondary_owner_membership_id String?\n  timezone                      String?\n  language                      String?\n  /// Marketing consent per channel (consumed by 11 Communication Center).\n  consent                       Json?\n  description                   String?\n  last_activity_at              DateTime?\n  archived_at                   DateTime?\n  created_by_user_id            String?\n  created_at                    DateTime         @default(now())\n  updated_at                    DateTime         @updatedAt\n\n  organization    Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  company         CrmCompany?        @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  lifecycle_stage CrmLifecycleStage? @relation(fields: [lifecycle_stage_id], references: [id], onDelete: SetNull)\n  lead_source     CrmLeadSource?     @relation(fields: [lead_source_id], references: [id], onDelete: SetNull)\n  owner           Membership?        @relation(\"CrmContactOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  secondary_owner Membership?        @relation(\"CrmContactSecondaryOwner\", fields: [secondary_owner_membership_id], references: [id], onDelete: SetNull)\n\n  leads                           CrmLead[]\n  primary_deals                   CrmDeal[]                            @relation(\"CrmDealPrimaryContact\")\n  deal_links                      CrmDealContact[]\n  activities                      CrmActivityParticipant[]\n  lifecycle_history               CrmLifecycleHistory[]\n  converted_from_leads            CrmLead[]                            @relation(\"LeadConvertedContact\")\n  proposals                       Proposal[]\n  proposal_deliveries             ProposalDelivery[]\n  proposal_acceptances            ProposalAcceptance[]\n  contract_signatories            ContractSignatory[]\n  project_stakeholders            ProjectStakeholder[]\n  portal_profile_change_requests  CustomerPortalProfileChangeRequest[]\n  comm_threads                    CommThread[]\n  comm_messages                   CommMessage[]                        @relation(\"CommMessageRecipientContact\")\n  comm_message_recipients         CommMessageRecipient[]               @relation(\"CommMessageRecipientsContact\")\n  comm_recipient_list_memberships CommRecipientListMember[]            @relation(\"CommRecipientListMemberContact\")\n  comm_consents                   CommConsent[]                        @relation(\"CommConsentContact\")\n  comm_suppressions               CommSuppression[]                    @relation(\"CommSuppressionContact\")\n  campaign_recipients             CampaignRecipient[]                  @relation(\"CampaignRecipientContact\")\n  support_conversations           SupportConversation[]\n  support_tickets                 Ticket[]\n  support_csat_ratings            SupportCsatRating[]\n  calendar_event_attendances      CalendarEventAttendee[]\n  calendar_bookings               CalendarBooking[]\n\n  @@index([organization_id, email])\n  @@index([organization_id, last_name, first_name])\n  @@index([company_id])\n  @@index([owner_membership_id])\n  @@map(\"crm_contacts\")\n}\n\n/// 02 §4–7 — prospect before qualification. Conversion links to the created records (02 §7).\nmodel CrmLead {\n  id                            String    @id @default(uuid())\n  organization_id               String\n  branch_id                     String?\n  name                          String\n  company_id                    String?\n  contact_id                    String?\n  /// Free-text company/contact details captured before records exist.\n  company_name                  String?\n  contact_name                  String?\n  email                         String?\n  phone                         String?\n  website                       String?\n  industry                      String?\n  estimated_company_size        String?\n  estimated_value               Decimal?  @db.Decimal(18, 2)\n  currency                      String?\n  status_id                     String?\n  lead_source_id                String?\n  owner_membership_id           String?\n  /// 02 §20 — secondary owner.\n  secondary_owner_membership_id String?\n  /// 02 §6 — qualification criteria and answers.\n  qualification                 Json?\n  qualification_notes           String?\n  lead_score                    Int?\n  manual_score                  Int?\n  description                   String?\n  last_activity_at              DateTime?\n  next_follow_up_at             DateTime?\n  converted_at                  DateTime?\n  converted_company_id          String?\n  converted_contact_id          String?\n  converted_deal_id             String?\n  lost_reason                   String?\n  archived_at                   DateTime?\n  created_by_user_id            String?\n  created_at                    DateTime  @default(now())\n  updated_at                    DateTime  @updatedAt\n\n  organization      Organization   @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch            Branch?        @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  company           CrmCompany?    @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  contact           CrmContact?    @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n  status            CrmLeadStatus? @relation(fields: [status_id], references: [id], onDelete: SetNull)\n  lead_source       CrmLeadSource? @relation(fields: [lead_source_id], references: [id], onDelete: SetNull)\n  owner             Membership?    @relation(\"CrmLeadOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  secondary_owner   Membership?    @relation(\"CrmLeadSecondaryOwner\", fields: [secondary_owner_membership_id], references: [id], onDelete: SetNull)\n  converted_company CrmCompany?    @relation(\"LeadConvertedCompany\", fields: [converted_company_id], references: [id], onDelete: SetNull)\n  converted_contact CrmContact?    @relation(\"LeadConvertedContact\", fields: [converted_contact_id], references: [id], onDelete: SetNull)\n  converted_deal    CrmDeal?       @relation(\"LeadConvertedDeal\", fields: [converted_deal_id], references: [id], onDelete: SetNull)\n  activities        CrmActivity[]\n\n  @@index([organization_id, status_id])\n  @@index([organization_id, owner_membership_id])\n  @@index([organization_id, email])\n  @@map(\"crm_leads\")\n}\n\n/// 02 §9 — deal / opportunity. Totals derive from line items when any exist (02 §10).\nmodel CrmDeal {\n  id                            String              @id @default(uuid())\n  organization_id               String\n  branch_id                     String?\n  pipeline_id                   String\n  stage_id                      String\n  name                          String\n  company_id                    String?\n  primary_contact_id            String?\n  owner_membership_id           String?\n  /// 02 §20 — secondary owner (covers for the owner, shares credit) and the project manager who will deliver the deal.\n  secondary_owner_membership_id String?\n  project_manager_membership_id String?\n  team_id                       String?\n  status                        CrmDealStatus       @default(OPEN)\n  value                         Decimal             @default(0) @db.Decimal(18, 2)\n  recurring_value               Decimal             @default(0) @db.Decimal(18, 2)\n  one_time_value                Decimal             @default(0) @db.Decimal(18, 2)\n  discount_amount               Decimal             @default(0) @db.Decimal(18, 2)\n  tax_amount                    Decimal             @default(0) @db.Decimal(18, 2)\n  currency                      String\n  probability                   Int?\n  forecast_category             CrmForecastCategory @default(PIPELINE)\n  expected_close_date           DateTime?           @db.Date\n  actual_close_date             DateTime?           @db.Date\n  deal_type                     String?\n  lead_source_id                String?\n  competitor                    String?\n  lost_reason                   String?\n  next_step                     String?\n  description                   String?\n  /// References to records owned by other modules (ids only): 03, 04, 05.\n  proposal_id                   String?\n  contract_id                   String?\n  project_id                    String?\n  stage_entered_at              DateTime            @default(now())\n  last_activity_at              DateTime?\n  archived_at                   DateTime?\n  created_by_user_id            String?\n  created_at                    DateTime            @default(now())\n  updated_at                    DateTime            @updatedAt\n\n  organization    Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch          Branch?          @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  pipeline        CrmPipeline      @relation(fields: [pipeline_id], references: [id], onDelete: Restrict)\n  stage           CrmPipelineStage @relation(fields: [stage_id], references: [id], onDelete: Restrict)\n  company         CrmCompany?      @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  primary_contact CrmContact?      @relation(\"CrmDealPrimaryContact\", fields: [primary_contact_id], references: [id], onDelete: SetNull)\n  owner           Membership?      @relation(\"CrmDealOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  secondary_owner Membership?      @relation(\"CrmDealSecondaryOwner\", fields: [secondary_owner_membership_id], references: [id], onDelete: SetNull)\n  project_manager Membership?      @relation(\"CrmDealProjectManager\", fields: [project_manager_membership_id], references: [id], onDelete: SetNull)\n  team            Team?            @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  lead_source     CrmLeadSource?   @relation(fields: [lead_source_id], references: [id], onDelete: SetNull)\n  project         Project?         @relation(\"CrmDealProject\", fields: [project_id], references: [id], onDelete: SetNull)\n\n  contacts             CrmDealContact[]\n  line_items           CrmDealLineItem[]\n  stage_history        CrmDealStageHistory[]\n  activities           CrmActivity[]\n  converted_from_leads CrmLead[]             @relation(\"LeadConvertedDeal\")\n  proposals            Proposal[]\n\n  @@index([organization_id, pipeline_id, stage_id])\n  @@index([organization_id, status])\n  @@index([company_id])\n  @@index([owner_membership_id])\n  @@index([expected_close_date])\n  @@map(\"crm_deals\")\n}\n\n/// 02 §9 — additional contacts on a deal.\nmodel CrmDealContact {\n  deal_id    String\n  contact_id String\n  role       String?\n  created_at DateTime @default(now())\n\n  deal    CrmDeal    @relation(fields: [deal_id], references: [id], onDelete: Cascade)\n  contact CrmContact @relation(fields: [contact_id], references: [id], onDelete: Cascade)\n\n  @@id([deal_id, contact_id])\n  @@index([contact_id])\n  @@map(\"crm_deal_contacts\")\n}\n\n/// 02 §10 — deal line items. product_id references the Finance catalog (08); no FK until 08 exists.\nmodel CrmDealLineItem {\n  id                String   @id @default(uuid())\n  deal_id           String\n  product_id        String?\n  name              String\n  description       String?\n  quantity          Decimal  @default(1) @db.Decimal(12, 3)\n  unit_price        Decimal  @default(0) @db.Decimal(18, 2)\n  discount_percent  Decimal? @db.Decimal(5, 2)\n  discount_amount   Decimal  @default(0) @db.Decimal(18, 2)\n  tax_percent       Decimal? @db.Decimal(5, 2)\n  net_amount        Decimal  @default(0) @db.Decimal(18, 2)\n  tax_amount        Decimal  @default(0) @db.Decimal(18, 2)\n  gross_amount      Decimal  @default(0) @db.Decimal(18, 2)\n  is_recurring      Boolean  @default(false)\n  /// monthly | quarterly | annual | custom\n  billing_frequency String?\n  sort_order        Int      @default(0)\n  created_at        DateTime @default(now())\n  updated_at        DateTime @updatedAt\n\n  deal    CrmDeal  @relation(fields: [deal_id], references: [id], onDelete: Cascade)\n  product Product? @relation(fields: [product_id], references: [id], onDelete: SetNull)\n\n  @@index([deal_id])\n  @@map(\"crm_deal_line_items\")\n}\n\n/// 02 §8, §34 — stage transitions for duration, velocity and history.\nmodel CrmDealStageHistory {\n  id                 String   @id @default(uuid())\n  deal_id            String\n  from_stage_id      String?\n  to_stage_id        String\n  changed_by_user_id String?\n  changed_at         DateTime @default(now())\n  /// Seconds spent in from_stage.\n  duration_seconds   Int?\n\n  deal       CrmDeal           @relation(fields: [deal_id], references: [id], onDelete: Cascade)\n  from_stage CrmPipelineStage? @relation(\"StageHistoryFrom\", fields: [from_stage_id], references: [id], onDelete: SetNull)\n  to_stage   CrmPipelineStage  @relation(\"StageHistoryTo\", fields: [to_stage_id], references: [id], onDelete: Cascade)\n\n  @@index([deal_id, changed_at])\n  @@map(\"crm_deal_stage_history\")\n}\n\n// --- Activities & notes -----------------------------------------------------\n\n/// 02 §12–15 — unified CRM activity. Tasks are NOT activities: they live in 06 and link back to CRM\n/// records from Task Management. MEETING rows reference a Calendar event (19).\nmodel CrmActivity {\n  id                  String            @id @default(uuid())\n  organization_id     String\n  type                CrmActivityType\n  status              CrmActivityStatus @default(PLANNED)\n  priority            CrmPriority       @default(NORMAL)\n  title               String\n  description         String?\n  company_id          String?\n  contact_id          String?\n  lead_id             String?\n  deal_id             String?\n  /// Project reference (05); id only.\n  project_id          String?\n  owner_membership_id String?\n  starts_at           DateTime?\n  ends_at             DateTime?\n  duration_minutes    Int?\n  location            String?\n  meeting_url         String?\n  /// Calendar event id (19); id only.\n  calendar_event_id   String?\n  outcome             String?\n  /// Automation rule id (20) when created by a rule.\n  automation_rule_id  String?\n  completed_at        DateTime?\n  created_by_user_id  String?\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  organization    Organization             @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  company         CrmCompany?              @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  lead            CrmLead?                 @relation(fields: [lead_id], references: [id], onDelete: Cascade)\n  deal            CrmDeal?                 @relation(fields: [deal_id], references: [id], onDelete: Cascade)\n  owner           Membership?              @relation(\"CrmActivityOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  participants    CrmActivityParticipant[]\n  calendar_event  CalendarEvent?           @relation(fields: [calendar_event_id], references: [id], onDelete: SetNull)\n  automation_rule AutomationRule?          @relation(\"CrmActivityAutomationRule\", fields: [automation_rule_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, starts_at])\n  @@index([company_id])\n  @@index([contact_id])\n  @@index([deal_id])\n  @@index([lead_id])\n  @@index([owner_membership_id, status])\n  @@map(\"crm_activities\")\n}\n\n/// Participants of an activity: internal Members (by membership id) and CRM Contacts.\nmodel CrmActivityParticipant {\n  id            String  @id @default(uuid())\n  activity_id   String\n  membership_id String?\n  contact_id    String?\n  response      String?\n\n  activity CrmActivity @relation(fields: [activity_id], references: [id], onDelete: Cascade)\n  contact  CrmContact? @relation(fields: [contact_id], references: [id], onDelete: Cascade)\n\n  @@unique([activity_id, membership_id, contact_id])\n  @@index([contact_id])\n  @@map(\"crm_activity_participants\")\n}\n\n/// 02 §16 — notes attachable to companies, contacts, leads, deals and other modules' records.\nmodel CrmNote {\n  id                   String           @id @default(uuid())\n  organization_id      String\n  entity_type          RecordEntityType\n  entity_id            String\n  author_membership_id String?\n  /// Markdown / rich text body.\n  body                 String\n  is_private           Boolean          @default(false)\n  /// Mentioned membership ids.\n  mentions             String[]         @default([])\n  pinned               Boolean          @default(false)\n  edited_at            DateTime?\n  /// Previous bodies for edit history (02 §16).\n  edit_history         Json?\n  created_at           DateTime         @default(now())\n  updated_at           DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  author       Membership?  @relation(\"CrmNoteAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([entity_type, entity_id, created_at])\n  @@index([organization_id])\n  @@map(\"crm_notes\")\n}\n\n// --- Operations ---------------------------------------------------------------\n\n/// 02 §20 — automatic assignment rules (evaluated by the Automation Engine, 20).\nmodel CrmAssignmentRule {\n  id              String           @id @default(uuid())\n  organization_id String\n  name            String\n  entity_type     RecordEntityType\n  /// Conditions on record fields and custom fields.\n  conditions      Json\n  /// { membership_id } | { team_id, strategy: \"round_robin\" | \"least_loaded\" }\n  assign_to       Json\n  priority        Int              @default(0)\n  enabled         Boolean          @default(true)\n  created_at      DateTime         @default(now())\n  updated_at      DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, entity_type, enabled])\n  @@map(\"crm_assignment_rules\")\n}\n\n/// 02 §11, §33 — sales target for pipeline coverage and attainment. Scope: the whole organization (owner and team null), a team, or one\n/// person; optionally one pipeline. Coverage = open pipeline / target; attainment = actual / target.\nmodel CrmSalesTarget {\n  id                  String          @id @default(uuid())\n  organization_id     String\n  pipeline_id         String?\n  /// Individual target; null with team_id null = organization-wide.\n  owner_membership_id String?\n  team_id             String?\n  period              CrmTargetPeriod\n  period_start        DateTime        @db.Date\n  period_end          DateTime        @db.Date\n  metric              CrmTargetMetric @default(REVENUE_WON)\n  amount              Decimal         @db.Decimal(14, 2)\n  currency            String\n  created_by_user_id  String?\n  created_at          DateTime        @default(now())\n  updated_at          DateTime        @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  pipeline     CrmPipeline? @relation(fields: [pipeline_id], references: [id], onDelete: SetNull)\n  owner        Membership?  @relation(\"CrmSalesTargetOwner\", fields: [owner_membership_id], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, period_start])\n  @@index([owner_membership_id])\n  @@index([team_id])\n  @@map(\"crm_sales_targets\")\n}\n\n/// 02 §33 — periodic forecast snapshot (written by a daily job) so forecast accuracy can compare what was forecast with what closed.\n/// One row per pipeline and scope (organization, team or owner) and forecast period.\nmodel CrmForecastSnapshot {\n  id                  String   @id @default(uuid())\n  organization_id     String\n  pipeline_id         String\n  owner_membership_id String?\n  team_id             String?\n  snapshot_date       DateTime @db.Date\n  period_start        DateTime @db.Date\n  period_end          DateTime @db.Date\n  pipeline_amount     Decimal  @default(0) @db.Decimal(14, 2)\n  best_case_amount    Decimal  @default(0) @db.Decimal(14, 2)\n  commit_amount       Decimal  @default(0) @db.Decimal(14, 2)\n  closed_won_amount   Decimal  @default(0) @db.Decimal(14, 2)\n  weighted_amount     Decimal  @default(0) @db.Decimal(14, 2)\n  deal_count          Int      @default(0)\n  currency            String\n  created_at          DateTime @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  pipeline     CrmPipeline  @relation(fields: [pipeline_id], references: [id], onDelete: Cascade)\n  owner        Membership?  @relation(\"CrmForecastSnapshotOwner\", fields: [owner_membership_id], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, pipeline_id, snapshot_date])\n  @@index([organization_id, period_start])\n  @@map(\"crm_forecast_snapshots\")\n}\n\n/// 02 §32 — dashboard layout by role or team: which widgets and in which order. role_id and team_id both null = organization default.\n/// A person's own arrangement stays in UserPreference.dashboard_layout and wins over these.\nmodel CrmDashboardLayout {\n  id                 String   @id @default(uuid())\n  organization_id    String\n  name               String\n  role_id            String?\n  team_id            String?\n  /// Ordered widgets: [{ key, size, filters }].\n  widgets            Json\n  is_default         Boolean  @default(false)\n  created_by_user_id String?\n  created_at         DateTime @default(now())\n  updated_at         DateTime @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  role         Role?        @relation(fields: [role_id], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, role_id])\n  @@index([organization_id, team_id])\n  @@map(\"crm_dashboard_layouts\")\n}\n\n/// 02 §6 — configurable lead-scoring rule: when the conditions match, the points are added to CrmLead.lead_score (manual_score stays separate).\nmodel CrmLeadScoringRule {\n  id              String   @id @default(uuid())\n  organization_id String\n  name            String\n  description     String?\n  /// Conditions over lead fields, source, activity and engagement, e.g. [{ field, operator, value }].\n  conditions      Json\n  /// Points added (negative to subtract).\n  points          Int\n  enabled         Boolean  @default(true)\n  sort_order      Int      @default(0)\n  created_at      DateTime @default(now())\n  updated_at      DateTime @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, enabled])\n  @@map(\"crm_lead_scoring_rules\")\n}\n\n/// 02 §22 — CSV import jobs with mapping, preview, validation, history and rollback.\nmodel CrmImportJob {\n  id                       String           @id @default(uuid())\n  organization_id          String\n  entity_type              RecordEntityType\n  status                   CrmImportStatus  @default(PENDING)\n  /// Uploaded file (17 Documents); id only.\n  document_id              String?\n  file_name                String?\n  field_mapping            Json?\n  /// Duplicate detection strategy: match fields and merge behaviour.\n  duplicate_strategy       Json?\n  total_rows               Int              @default(0)\n  imported_rows            Int              @default(0)\n  updated_rows             Int              @default(0)\n  skipped_rows             Int              @default(0)\n  error_rows               Int              @default(0)\n  errors                   Json?\n  /// Ids created by this job, kept for rollback.\n  created_record_ids       String[]         @default([])\n  started_by_membership_id String?\n  started_at               DateTime?\n  completed_at             DateTime?\n  rolled_back_at           DateTime?\n  created_at               DateTime         @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  started_by   Membership?  @relation(fields: [started_by_membership_id], references: [id], onDelete: SetNull)\n  document     Document?    @relation(fields: [document_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@map(\"crm_import_jobs\")\n}\n\n// =====================================================================\n// Platform shared concept — document numbering (used by 03 Proposals, 04 Contracts, 08 Finance).\n// =====================================================================\n\n/// Per-organization numbering sequences, e.g. PRO-2026-0001 / CTR-2026-0001 / INV-2026-0001.\n/// Services increment `next_number` inside a transaction; numbers are never reused.\nmodel NumberSequence {\n  id              String   @id @default(uuid())\n  organization_id String\n  /// proposal | contract | invoice | credit_note | ticket …\n  entity_type     String\n  prefix          String\n  /// Null for sequences that do not reset yearly.\n  year            Int?\n  next_number     Int      @default(1)\n  padding         Int      @default(4)\n  updated_at      DateTime @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, entity_type, prefix, year])\n  @@map(\"number_sequences\")\n}\n\n// =====================================================================\n// 03 AI-Powered Proposal & Quotation Generator — docs/features/03-proposal-quotation-generator.md (LOG-303)\n// Owns: Proposal, versions, sections, line items, payment schedules, templates, internal review,\n// delivery, tracking, customer acceptance, conversion links.\n// Does not own: products catalog and tax rates (08), PDF files (17), signature requests (04),\n// contracts (04), projects (05), invoices/subscriptions (08), emails (11). Referenced by id only.\n// =====================================================================\n\n/// 03 \"Proposal Status\" — lifecycle of the proposal record (the latest/sent version drives it).\nenum ProposalStatus {\n  DRAFT\n  IN_REVIEW\n  PENDING_APPROVAL\n  APPROVED\n  SENT\n  VIEWED\n  CHANGES_REQUESTED\n  ACCEPTED\n  REJECTED\n  EXPIRED\n  CANCELLED\n}\n\n/// 03 \"Proposal Versions\" — a version is immutable once sent.\nenum ProposalVersionStatus {\n  DRAFT\n  IN_REVIEW\n  APPROVED\n  SENT\n  SUPERSEDED\n}\n\n/// 03 \"Proposal Review\" — internal approval decision.\nenum ProposalApprovalDecision {\n  PENDING\n  APPROVED\n  REJECTED\n  CHANGES_REQUESTED\n}\n\n/// 03 \"Customer Approval\".\nenum ProposalCustomerDecision {\n  ACCEPTED\n  REJECTED\n  CHANGES_REQUESTED\n}\n\n/// 03 \"Customer Delivery\".\nenum ProposalDeliveryChannel {\n  EMAIL\n  CUSTOMER_PORTAL\n  PDF\n  LINK\n}\n\nenum ProposalDeliveryStatus {\n  QUEUED\n  SENT\n  DELIVERED\n  FAILED\n}\n\n/// 03 \"Proposal Tracking\" — customer and system events on a proposal.\nenum ProposalEventType {\n  CREATED\n  VERSION_CREATED\n  SUBMITTED_FOR_REVIEW\n  APPROVED\n  SENT\n  VIEWED\n  DOWNLOADED\n  OPTIONAL_ITEM_TOGGLED\n  COMMENTED\n  CHANGES_REQUESTED\n  ACCEPTED\n  REJECTED\n  SIGNED\n  EXPIRED\n  CANCELLED\n  CONVERTED\n}\n\n/// 03 \"Reusable Templates\" / \"Dynamic Proposal Content\" — section types.\nenum ProposalSectionType {\n  COVER\n  EXECUTIVE_SUMMARY\n  OVERVIEW\n  REQUIREMENTS\n  SOLUTION\n  SCOPE\n  FEATURES\n  DELIVERABLES\n  PHASES\n  MILESTONES\n  TIMELINE\n  PRICING\n  PAYMENT_SCHEDULE\n  SUPPORT_OPTIONS\n  ASSUMPTIONS\n  EXCLUSIONS\n  WARRANTY\n  TERMS\n  NEXT_STEPS\n  SIGNATURE\n  CUSTOM\n}\n\n/// 03 \"Pricing & Quotation Builder\" — when a payment schedule item is due.\nenum ProposalPaymentTrigger {\n  ON_ACCEPTANCE\n  ON_SIGNATURE\n  ON_DATE\n  ON_MILESTONE\n  ON_DELIVERY\n  RECURRING\n}\n\n// --- Templates -------------------------------------------------------------------\n\n/// 03 \"Reusable Templates\" — branded, versioned template per work type. Organization-owned.\nmodel ProposalTemplate {\n  id                    String    @id @default(uuid())\n  organization_id       String\n  name                  String\n  slug                  String\n  description           String?\n  /// Work type the template targets (website, web app, mobile, custom software, SaaS, maintenance, support, consulting, …).\n  work_type             String?\n  language              String    @default(\"en\")\n  /// Branding overrides; organization branding (01 §15) is the fallback.\n  branding              Json?\n  /// Page layout: cover page, headers/footers, typography, table styles.\n  layout                Json?\n  /// Ordered section blueprint: [{ type, title, body_template, is_required, sort_order }].\n  sections              Json\n  /// Default terms, warranty, assumptions, exclusions, payment terms text.\n  defaults              Json?\n  /// Dynamic variables the template expects (03 \"Dynamic Proposal Content\").\n  variables             Json?\n  default_validity_days Int       @default(30)\n  is_default            Boolean   @default(false)\n  version               Int       @default(1)\n  archived_at           DateTime?\n  created_by_user_id    String?\n  created_at            DateTime  @default(now())\n  updated_at            DateTime  @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  proposals    Proposal[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, work_type])\n  @@map(\"proposal_templates\")\n}\n\n// --- Proposal --------------------------------------------------------------------\n\n/// 03 \"Proposal Creation\" — the proposal record. Content lives in versions; this row carries\n/// identity, relationships, status and snapshots of the current version's totals.\nmodel Proposal {\n  id                   String         @id @default(uuid())\n  organization_id      String\n  branch_id            String?\n  /// Organization numbering, e.g. PRO-2026-0001 (NumberSequence).\n  number               String\n  title                String\n  status               ProposalStatus @default(DRAFT)\n  template_id          String?\n  language             String         @default(\"en\")\n  currency             String\n  /// CRM references (02). company_id is the Customer the proposal is addressed to.\n  company_id           String?\n  contact_id           String?\n  deal_id              String?\n  owner_membership_id  String?\n  /// Project context the proposal was generated from or for (05); id only.\n  project_id           String?\n  /// Validity of the currently sent version.\n  valid_until          DateTime?      @db.Date\n  /// Version pointers.\n  current_version_id   String?        @unique\n  sent_version_id      String?        @unique\n  accepted_version_id  String?        @unique\n  /// Snapshot of current version totals for list views and dashboards.\n  net_total            Decimal        @default(0) @db.Decimal(18, 2)\n  discount_total       Decimal        @default(0) @db.Decimal(18, 2)\n  tax_total            Decimal        @default(0) @db.Decimal(18, 2)\n  gross_total          Decimal        @default(0) @db.Decimal(18, 2)\n  recurring_monthly    Decimal        @default(0) @db.Decimal(18, 2)\n  recurring_annual     Decimal        @default(0) @db.Decimal(18, 2)\n  /// Whether acceptance must produce a Contract before project/billing creation (03 \"Conversion to Project\").\n  requires_contract    Boolean        @default(false)\n  /// Public web view (03 \"Customer Delivery\"): hashed token; expires with valid_until.\n  public_token_hash    String?        @unique\n  /// Conversion links to records owned by other modules (ids only): 04, 05, 08.\n  contract_id          String?\n  converted_project_id String?\n  invoice_id           String?\n  subscription_id      String?\n  converted_at         DateTime?\n  sent_at              DateTime?\n  first_viewed_at      DateTime?\n  last_viewed_at       DateTime?\n  view_count           Int            @default(0)\n  accepted_at          DateTime?\n  rejected_at          DateTime?\n  expired_at           DateTime?\n  cancelled_at         DateTime?\n  archived_at          DateTime?\n  created_by_user_id   String?\n  created_at           DateTime       @default(now())\n  updated_at           DateTime       @updatedAt\n\n  organization      Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch            Branch?           @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  template          ProposalTemplate? @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  company           CrmCompany?       @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  contact           CrmContact?       @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n  deal              CrmDeal?          @relation(fields: [deal_id], references: [id], onDelete: SetNull)\n  converted_project Project?          @relation(\"ProposalConvertedProject\", fields: [converted_project_id], references: [id], onDelete: SetNull)\n  invoice           Invoice?          @relation(\"ProposalInvoice\", fields: [invoice_id], references: [id], onDelete: SetNull)\n  subscription      Subscription?     @relation(\"ProposalSubscription\", fields: [subscription_id], references: [id], onDelete: SetNull)\n  owner             Membership?       @relation(\"ProposalOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  current_version   ProposalVersion?  @relation(\"ProposalCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  sent_version      ProposalVersion?  @relation(\"ProposalSentVersion\", fields: [sent_version_id], references: [id], onDelete: SetNull)\n  accepted_version  ProposalVersion?  @relation(\"ProposalAcceptedVersion\", fields: [accepted_version_id], references: [id], onDelete: SetNull)\n\n  versions    ProposalVersion[]\n  deliveries  ProposalDelivery[]\n  events      ProposalEvent[]\n  comments    ProposalComment[]\n  acceptances ProposalAcceptance[]\n  contracts   Contract[]\n  projects    Project[]            @relation(\"ProjectSourceProposal\")\n\n  @@unique([organization_id, number])\n  @@index([organization_id, status])\n  @@index([company_id])\n  @@index([deal_id])\n  @@index([owner_membership_id])\n  @@index([valid_until])\n  @@map(\"proposals\")\n}\n\n/// 03 \"Proposal Versions\" — every revision. A version that was sent is immutable; acceptance\n/// is always bound to the exact version sent.\nmodel ProposalVersion {\n  id                 String                @id @default(uuid())\n  proposal_id        String\n  version_number     Int\n  status             ProposalVersionStatus @default(DRAFT)\n  parent_version_id  String?\n  change_summary     String?\n  /// Template version used at generation time.\n  template_version   Int?\n  /// Resolved dynamic variables at generation (03 \"Dynamic Proposal Content\").\n  variables          Json?\n  /// Structured commercial content not covered by sections: payment terms, validity, support options.\n  payment_terms      String?\n  validity_days      Int?\n  /// Milestones and timeline proposed (operational copies are created in 05 on conversion).\n  milestones         Json?\n  timeline           Json?\n  net_total          Decimal               @default(0) @db.Decimal(18, 2)\n  discount_total     Decimal               @default(0) @db.Decimal(18, 2)\n  tax_total          Decimal               @default(0) @db.Decimal(18, 2)\n  gross_total        Decimal               @default(0) @db.Decimal(18, 2)\n  recurring_monthly  Decimal               @default(0) @db.Decimal(18, 2)\n  recurring_annual   Decimal               @default(0) @db.Decimal(18, 2)\n  /// Generated PDF stored in 17 Documents; id only.\n  pdf_document_id    String?\n  /// Integrity hash of the rendered artifact.\n  content_hash       String?\n  is_ai_generated    Boolean               @default(false)\n  /// Model, prompt reference, sources used, review findings (03 \"AI Assistance\", \"Proposal Review\").\n  ai_metadata        Json?\n  locked_at          DateTime?\n  sent_at            DateTime?\n  created_by_user_id String?\n  created_at         DateTime              @default(now())\n  updated_at         DateTime              @updatedAt\n\n  proposal       Proposal          @relation(fields: [proposal_id], references: [id], onDelete: Cascade)\n  parent_version ProposalVersion?  @relation(\"ProposalVersionLineage\", fields: [parent_version_id], references: [id], onDelete: SetNull)\n  child_versions ProposalVersion[] @relation(\"ProposalVersionLineage\")\n\n  current_of         Proposal?          @relation(\"ProposalCurrentVersion\")\n  sent_of            Proposal?          @relation(\"ProposalSentVersion\")\n  accepted_of        Proposal?          @relation(\"ProposalAcceptedVersion\")\n  /// Contracts generated from this exact proposal version (04 §7, §55).\n  contracts          Contract[]\n  signature_requests SignatureRequest[]\n  projects           Project[]          @relation(\"ProjectSourceProposalVersion\")\n\n  sections         ProposalSection[]\n  line_items       ProposalLineItem[]\n  payment_schedule ProposalPaymentScheduleItem[]\n  approvals        ProposalApproval[]\n  deliveries       ProposalDelivery[]\n  events           ProposalEvent[]\n  comments         ProposalComment[]\n  acceptances      ProposalAcceptance[]\n  pdf_document     Document?                     @relation(\"ProposalVersionPdf\", fields: [pdf_document_id], references: [id], onDelete: SetNull)\n\n  @@unique([proposal_id, version_number])\n  @@index([proposal_id, status])\n  @@map(\"proposal_versions\")\n}\n\n/// Addressable content blocks of a version (03 \"AI Proposal Generation\" output structure).\nmodel ProposalSection {\n  id              String              @id @default(uuid())\n  version_id      String\n  type            ProposalSectionType\n  title           String\n  /// Markdown / rich text. Pricing and payment sections render from line items and schedule.\n  body            String?\n  sort_order      Int                 @default(0)\n  is_ai_generated Boolean             @default(false)\n  /// Hidden from the customer-facing render (internal notes inside a section).\n  is_internal     Boolean             @default(false)\n  created_at      DateTime            @default(now())\n  updated_at      DateTime            @updatedAt\n\n  version  ProposalVersion   @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  comments ProposalComment[]\n\n  @@index([version_id, sort_order])\n  @@map(\"proposal_sections\")\n}\n\n/// 03 \"Pricing & Quotation Builder\" — line items of a version. product_id references the\n/// Finance catalog (08); no FK until 08 exists.\nmodel ProposalLineItem {\n  id                   String   @id @default(uuid())\n  version_id           String\n  product_id           String?\n  /// Optional grouping label (package / phase).\n  group_name           String?\n  name                 String\n  description          String?\n  quantity             Decimal  @default(1) @db.Decimal(12, 3)\n  unit                 String?\n  unit_price           Decimal  @default(0) @db.Decimal(18, 2)\n  discount_percent     Decimal? @db.Decimal(5, 2)\n  discount_amount      Decimal  @default(0) @db.Decimal(18, 2)\n  tax_percent          Decimal? @db.Decimal(5, 2)\n  net_amount           Decimal  @default(0) @db.Decimal(18, 2)\n  tax_amount           Decimal  @default(0) @db.Decimal(18, 2)\n  gross_amount         Decimal  @default(0) @db.Decimal(18, 2)\n  is_recurring         Boolean  @default(false)\n  /// monthly | quarterly | annual | custom\n  billing_frequency    String?\n  /// Customer may choose this item (03 \"Approve specific optional items\").\n  is_optional          Boolean  @default(false)\n  /// Whether the customer selected the optional item on acceptance.\n  selected_by_customer Boolean?\n  sort_order           Int      @default(0)\n  created_at           DateTime @default(now())\n  updated_at           DateTime @updatedAt\n\n  version ProposalVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  product Product?        @relation(fields: [product_id], references: [id], onDelete: SetNull)\n\n  @@index([version_id, sort_order])\n  @@map(\"proposal_line_items\")\n}\n\n/// 03 \"Pricing & Quotation Builder\" — deposits, milestone payments, custom schedules.\nmodel ProposalPaymentScheduleItem {\n  id             String                 @id @default(uuid())\n  version_id     String\n  name           String\n  trigger        ProposalPaymentTrigger @default(ON_ACCEPTANCE)\n  /// Either a percentage of the gross total or a fixed amount.\n  percentage     Decimal?               @db.Decimal(5, 2)\n  amount         Decimal?               @db.Decimal(18, 2)\n  due_date       DateTime?              @db.Date\n  /// Milestone label this payment is tied to (ON_MILESTONE).\n  milestone_name String?\n  /// For RECURRING: monthly | quarterly | annual.\n  frequency      String?\n  sort_order     Int                    @default(0)\n\n  version  ProposalVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  invoices Invoice[]\n\n  @@index([version_id, sort_order])\n  @@map(\"proposal_payment_schedule_items\")\n}\n\n// --- Review, delivery, tracking, acceptance --------------------------------------\n\n/// 03 \"Proposal Review\" — internal approval bound to an exact version (approval rights: 01 §95).\nmodel ProposalApproval {\n  id                     String                   @id @default(uuid())\n  version_id             String\n  approver_membership_id String\n  step                   Int                      @default(1)\n  decision               ProposalApprovalDecision @default(PENDING)\n  /// 03 \"Proposal Review\" — the ProposalApprovalRule that requested this step; null = requested manually.\n  rule_id                String?\n  comment                String?\n  requested_at           DateTime                 @default(now())\n  decided_at             DateTime?\n\n  version  ProposalVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  approver Membership      @relation(\"ProposalApprover\", fields: [approver_membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([version_id, approver_membership_id, step])\n  @@index([approver_membership_id, decision])\n  @@map(\"proposal_approvals\")\n}\n\n/// 03 \"Proposal Review\" — approval rule: when the conditions match a proposal version (value, discount, margin, customer, type ...), the\n/// steps are requested in order. Mirrors ContractApprovalRule (04 §28). Evaluated when a version is submitted for review.\nmodel ProposalApprovalRule {\n  id              String   @id @default(uuid())\n  organization_id String\n  name            String\n  /// Conditions, e.g. [{ field: \"discount_percent\", operator: \">\", value: 10 }, { field: \"gross_total\", operator: \">=\", value: 100000 }].\n  conditions      Json\n  /// Ordered approval steps: [{ step, name, approver: { membership_id | role_id | team_id } }].\n  steps           Json\n  priority        Int      @default(100)\n  enabled         Boolean  @default(true)\n  created_at      DateTime @default(now())\n  updated_at      DateTime @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, enabled, priority])\n  @@map(\"proposal_approval_rules\")\n}\n\n/// Internal and customer comments on a proposal or a section. Customer authors are Customer Portal\n/// Users (01 §79) or the addressed contact; internal comments are never shown to customers.\nmodel ProposalComment {\n  id                   String    @id @default(uuid())\n  proposal_id          String\n  version_id           String?\n  section_id           String?\n  author_membership_id String?\n  author_user_id       String?\n  author_contact_id    String?\n  is_internal          Boolean   @default(true)\n  body                 String\n  resolved_at          DateTime?\n  created_at           DateTime  @default(now())\n  updated_at           DateTime  @updatedAt\n\n  proposal Proposal         @relation(fields: [proposal_id], references: [id], onDelete: Cascade)\n  version  ProposalVersion? @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  section  ProposalSection? @relation(fields: [section_id], references: [id], onDelete: Cascade)\n  author   Membership?      @relation(\"ProposalCommentAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([proposal_id, created_at])\n  @@index([section_id])\n  @@map(\"proposal_comments\")\n}\n\n/// 03 \"Customer Delivery\" — each send of a version through a channel. Emails go through 11.\nmodel ProposalDelivery {\n  id                   String                  @id @default(uuid())\n  proposal_id          String\n  version_id           String\n  channel              ProposalDeliveryChannel\n  status               ProposalDeliveryStatus  @default(QUEUED)\n  recipient_contact_id String?\n  recipient_email      String?\n  /// Communication record id (11); id only.\n  communication_id     String?\n  sent_by_user_id      String?\n  message              String?\n  sent_at              DateTime?\n  delivered_at         DateTime?\n  failed_reason        String?\n  created_at           DateTime                @default(now())\n\n  proposal      Proposal        @relation(fields: [proposal_id], references: [id], onDelete: Cascade)\n  version       ProposalVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  recipient     CrmContact?     @relation(fields: [recipient_contact_id], references: [id], onDelete: SetNull)\n  communication CommMessage?    @relation(fields: [communication_id], references: [id], onDelete: SetNull)\n\n  @@index([proposal_id, sent_at])\n  @@map(\"proposal_deliveries\")\n}\n\n/// 03 \"Proposal Tracking\" — append-only event log of customer activity and lifecycle changes.\nmodel ProposalEvent {\n  id               String            @id @default(uuid())\n  proposal_id      String\n  version_id       String?\n  type             ProposalEventType\n  /// Internal actor (user id) or customer actor (portal user id / contact id).\n  actor_user_id    String?\n  actor_contact_id String?\n  ip_address       String?\n  user_agent       String?\n  metadata         Json?\n  created_at       DateTime          @default(now())\n\n  proposal Proposal         @relation(fields: [proposal_id], references: [id], onDelete: Cascade)\n  version  ProposalVersion? @relation(fields: [version_id], references: [id], onDelete: Cascade)\n\n  @@index([proposal_id, created_at])\n  @@index([type, created_at])\n  @@map(\"proposal_events\")\n}\n\n/// 03 \"Customer Approval\" — the customer's decision on an exact version, with the evidence\n/// collected (name, contact, terms confirmation, selected optional items, signature reference).\nmodel ProposalAcceptance {\n  id                         String                   @id @default(uuid())\n  proposal_id                String\n  version_id                 String\n  decision                   ProposalCustomerDecision\n  /// Customer Portal User (01 §79) when accepted through the portal; id only.\n  customer_user_id           String?\n  contact_id                 String?\n  signer_name                String\n  signer_email               String\n  signer_title               String?\n  terms_accepted             Boolean                  @default(false)\n  /// Ids of optional line items the customer selected.\n  selected_optional_item_ids String[]                 @default([])\n  feedback                   String?\n  /// Signature request id from the in-house e-signature service (04 §33–38); id only.\n  signature_request_id       String?\n  signature_metadata         Json?\n  ip_address                 String?\n  user_agent                 String?\n  created_at                 DateTime                 @default(now())\n\n  proposal Proposal        @relation(fields: [proposal_id], references: [id], onDelete: Cascade)\n  version  ProposalVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  contact  CrmContact?     @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n\n  @@index([proposal_id, created_at])\n  @@index([version_id])\n  @@map(\"proposal_acceptances\")\n}\n\n// =====================================================================\n// 04 Contracts — docs/features/04-contracts.md (LOG-349)\n// Owns: contract types, templates and clause library, contract records, parties and signatories,\n// versions and sections, review, change requests, approval, in-house e-signature service\n// (also used by 03 Proposals), amendments/renewals lineage, obligations, termination.\n// Does not own: projects (05), documents storage (17), invoices (08), calendar events (19),\n// notifications (14), automation (20). Referenced by id only.\n// =====================================================================\n\n/// 04 §5 — contract lifecycle states.\nenum ContractStatus {\n  DRAFT\n  INTERNAL_REVIEW\n  CUSTOMER_REVIEW\n  APPROVAL_REQUIRED\n  READY_FOR_SIGNATURE\n  PARTIALLY_SIGNED\n  FULLY_SIGNED\n  ACTIVE\n  EXPIRING\n  RENEWED\n  SUPERSEDED\n  TERMINATED\n  EXPIRED\n  CANCELLED\n  ARCHIVED\n}\n\n/// 04 §19–20, §80 — version/document state, separate from contract lifecycle.\nenum ContractVersionStatus {\n  DRAFT\n  IN_REVIEW\n  APPROVED\n  LOCKED_FOR_SIGNATURE\n  SIGNED\n  SUPERSEDED\n}\n\n/// 04 §43, §46–48 — how a contract relates to its parent contract.\nenum ContractRelationKind {\n  STANDALONE\n  AMENDMENT\n  RENEWAL\n  SOW\n  CHANGE_ORDER\n  TERMINATION_AGREEMENT\n}\n\n/// 04 §3 — renewal behaviour.\nenum ContractRenewalType {\n  NONE\n  MANUAL\n  AUTOMATIC\n  EVERGREEN\n}\n\n/// 04 §4 — party type.\nenum ContractPartyType {\n  AGENCY\n  CUSTOMER\n  VENDOR\n  PARTNER\n  CONTRACTOR\n  EMPLOYEE\n  OTHER\n}\n\n/// 04 §8, §77 — template governance.\nenum ContractTemplateStatus {\n  DRAFT\n  PUBLISHED\n  DEPRECATED\n}\n\n/// 04 §11–12 — clause status.\nenum ContractClauseStatus {\n  DRAFT\n  ACTIVE\n  DEPRECATED\n}\n\n/// 04 §23 — review decision.\nenum ContractReviewDecision {\n  PENDING\n  APPROVED\n  REJECTED\n  CHANGES_REQUESTED\n}\n\n/// 04 §27–29 — approval decision.\nenum ContractApprovalDecision {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n/// 04 §26 — contract change request status.\nenum ContractChangeRequestStatus {\n  REQUESTED\n  UNDER_REVIEW\n  ACCEPTED\n  REJECTED\n  IMPLEMENTED\n  WITHDRAWN\n}\n\n/// 04 §49–50 — obligation types.\nenum ContractObligationType {\n  DELIVERABLE\n  PAYMENT\n  REPORTING\n  RENEWAL_NOTICE\n  SLA\n  SECURITY_REVIEW\n  CUSTOMER_APPROVAL\n  OTHER\n}\n\nenum ContractObligationStatus {\n  OPEN\n  IN_PROGRESS\n  FULFILLED\n  OVERDUE\n  WAIVED\n  CANCELLED\n}\n\n/// 04 §75 — AI-extracted obligations need review before acting.\nenum ExtractionReviewState {\n  PENDING_REVIEW\n  CONFIRMED\n  REJECTED\n}\n\n/// 04 §53 — termination type.\nenum ContractTerminationType {\n  FOR_CONVENIENCE\n  FOR_CAUSE\n  MUTUAL\n  EXPIRY\n  OTHER\n}\n\n/// 04 §74 — explainable risk level; not legal advice.\nenum ContractRiskLevel {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\n/// 04 §73 — what an AI contract review flagged.\nenum ContractAiFindingKind {\n  MISSING_CLAUSE\n  CONFLICTING_DATES\n  UNUSUAL_PAYMENT_TERMS\n  LIABILITY_DIFFERENCE\n  TERMINATION_DIFFERENCE\n  SCOPE_INCONSISTENCY\n  RENEWAL_PROVISION\n  NON_STANDARD_CLAUSE\n}\n\n/// 04 §73 — a human's handling of an AI finding. Findings are recommendations: OPEN until someone accepts or dismisses them.\nenum ContractAiFindingStatus {\n  OPEN\n  ACCEPTED\n  DISMISSED\n}\n\n/// What a signature request is bound to. The version relationship is immutable (04 §34).\nenum SignatureSubjectType {\n  CONTRACT_VERSION\n  PROPOSAL_VERSION\n}\n\n/// 04 §32 — signing order.\nenum SigningOrder {\n  SEQUENTIAL\n  PARALLEL\n}\n\n/// 04 §36 — how the signer provided the signature in the platform's own signing flow.\nenum SignatureType {\n  DRAWN\n  TYPED\n  UPLOADED\n}\n\n/// 04 §35 — signature request states.\nenum SignatureRequestStatus {\n  NOT_SENT\n  SENT\n  DELIVERED\n  VIEWED\n  PARTIALLY_SIGNED\n  FULLY_SIGNED\n  DECLINED\n  EXPIRED\n  CANCELLED\n  FAILED\n}\n\nenum SignerStatus {\n  PENDING\n  SENT\n  DELIVERED\n  VIEWED\n  SIGNED\n  DECLINED\n  BOUNCED\n}\n\n/// 04 §38 — provider events retained for the audit trail.\nenum SignatureEventType {\n  REQUEST_CREATED\n  SENT\n  DELIVERED\n  VIEWED\n  SIGNED\n  DECLINED\n  REMINDER_SENT\n  CANCELLED\n  EXPIRED\n  COMPLETED\n  FAILED\n}\n\n// --- Configuration: types, templates, clauses, approval rules ---------------------\n\n/// 04 §2 — configurable contract types with defaults.\nmodel ContractType {\n  id                     String              @id @default(uuid())\n  organization_id        String\n  name                   String\n  slug                   String\n  description            String?\n  default_template_id    String?\n  /// Required metadata keys for this type (04 §16 validation).\n  required_metadata      Json?\n  /// Default approval workflow steps when no ContractApprovalRule matches (04 §27).\n  approval_workflow      Json?\n  /// Signature requirements: required parties, signing order, internal/external first.\n  signature_requirements Json?\n  default_renewal_type   ContractRenewalType @default(NONE)\n  default_notice_days    Int?\n  /// Expiration reminder windows in days (04 §52), e.g. [180,120,90,60,30,14,7].\n  reminder_windows_days  Int[]               @default([90, 60, 30, 14, 7])\n  /// Retention in days after closeout (04 §84); null = organization default.\n  retention_days         Int?\n  sort_order             Int                 @default(0)\n  archived_at            DateTime?\n  created_at             DateTime            @default(now())\n  updated_at             DateTime            @updatedAt\n\n  organization     Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_template ContractTemplate?  @relation(\"ContractTypeDefaultTemplate\", fields: [default_template_id], references: [id], onDelete: SetNull)\n  templates        ContractTemplate[] @relation(\"ContractTemplateType\")\n  contracts        Contract[]\n\n  @@unique([organization_id, slug])\n  @@map(\"contract_types\")\n}\n\n/// 04 §8, §77 — reusable contractual structure. Content is versioned in ContractTemplateVersion;\n/// changing a template never modifies existing contracts.\nmodel ContractTemplate {\n  id                  String                 @id @default(uuid())\n  organization_id     String\n  type_id             String?\n  name                String\n  slug                String\n  description         String?\n  language            String                 @default(\"en\")\n  status              ContractTemplateStatus @default(DRAFT)\n  current_version_id  String?                @unique\n  owner_membership_id String?\n  effective_date      DateTime?              @db.Date\n  deprecated_at       DateTime?\n  created_at          DateTime               @default(now())\n  updated_at          DateTime               @updatedAt\n\n  organization      Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  type              ContractType?             @relation(\"ContractTemplateType\", fields: [type_id], references: [id], onDelete: SetNull)\n  current_version   ContractTemplateVersion?  @relation(\"ContractTemplateCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  versions          ContractTemplateVersion[]\n  default_for_types ContractType[]            @relation(\"ContractTypeDefaultTemplate\")\n  contracts         Contract[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, status])\n  @@map(\"contract_templates\")\n}\n\n/// 04 §8–10, §14 — one immutable template version: sections, variables, conditional clause rules,\n/// signature blocks, required fields, appendices.\nmodel ContractTemplateVersion {\n  id                 String    @id @default(uuid())\n  template_id        String\n  version_number     Int\n  change_summary     String?\n  /// Ordered sections: [{ key, title, body, clause_key?, conditions?, is_optional, sort_order }].\n  sections           Json\n  /// Variables with source mapping (04 §9): [{ key, label, source, required }].\n  variables          Json?\n  /// Deterministic conditional clause rules (04 §10).\n  conditional_rules  Json?\n  /// Signature blocks per party (04 §31).\n  signature_blocks   Json?\n  required_fields    String[]  @default([])\n  published_at       DateTime?\n  created_by_user_id String?\n  created_at         DateTime  @default(now())\n\n  template   ContractTemplate  @relation(fields: [template_id], references: [id], onDelete: Cascade)\n  current_of ContractTemplate? @relation(\"ContractTemplateCurrentVersion\")\n  versions   ContractVersion[]\n\n  @@unique([template_id, version_number])\n  @@map(\"contract_template_versions\")\n}\n\n/// 04 §11 — clause library entry. Text lives in ContractClauseVersion (04 §12).\nmodel ContractClause {\n  id                  String               @id @default(uuid())\n  organization_id     String\n  key                 String\n  name                String\n  /// payment | ip | confidentiality | privacy | liability | warranty | termination | renewal | sla | security | governing_law | other\n  category            String\n  description         String?\n  status              ContractClauseStatus @default(DRAFT)\n  /// Usage restrictions (04 §11): allowed contract types, jurisdictions, requires approval.\n  usage_restrictions  Json?\n  owner_membership_id String?\n  current_version_id  String?              @unique\n  effective_date      DateTime?            @db.Date\n  deprecated_at       DateTime?\n  created_at          DateTime             @default(now())\n  updated_at          DateTime             @updatedAt\n\n  organization    Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  current_version ContractClauseVersion?  @relation(\"ContractClauseCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  versions        ContractClauseVersion[]\n\n  @@unique([organization_id, key])\n  @@index([organization_id, category])\n  @@map(\"contract_clauses\")\n}\n\n/// 04 §12 — a generated contract keeps the exact clause version used.\nmodel ContractClauseVersion {\n  id                 String    @id @default(uuid())\n  clause_id          String\n  version_number     Int\n  text               String\n  change_summary     String?\n  effective_date     DateTime? @db.Date\n  deprecated_at      DateTime?\n  created_by_user_id String?\n  created_at         DateTime  @default(now())\n\n  clause     ContractClause    @relation(fields: [clause_id], references: [id], onDelete: Cascade)\n  current_of ContractClause?   @relation(\"ContractClauseCurrentVersion\")\n  sections   ContractSection[]\n\n  @@unique([clause_id, version_number])\n  @@map(\"contract_clause_versions\")\n}\n\n/// 04 §28 — approval requirements by value, type, liability, discount, payment terms, duration,\n/// customer category, risk, custom fields.\nmodel ContractApprovalRule {\n  id              String   @id @default(uuid())\n  organization_id String\n  name            String\n  /// Predicate on contract metadata.\n  conditions      Json\n  /// Ordered steps: [{ step, approver: { membership_id | role_slug | team_id }, required }].\n  steps           Json\n  priority        Int      @default(0)\n  enabled         Boolean  @default(true)\n  created_at      DateTime @default(now())\n  updated_at      DateTime @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, enabled])\n  @@map(\"contract_approval_rules\")\n}\n\n// --- Contract record ------------------------------------------------------------\n\n/// 04 §3 — the structured business record. Document content lives in versions.\nmodel Contract {\n  id                                 String                   @id @default(uuid())\n  organization_id                    String\n  branch_id                          String?\n  /// Organization numbering, e.g. CTR-2026-0001 (NumberSequence).\n  number                             String\n  title                              String\n  type_id                            String?\n  template_id                        String?\n  status                             ContractStatus           @default(DRAFT)\n  relation_kind                      ContractRelationKind     @default(STANDALONE)\n  /// Original / parent agreement for amendments, renewals, SOWs and change orders (04 §43–48).\n  parent_contract_id                 String?\n  /// Sequence inside the parent (Amendment 1, Amendment 2 …).\n  relation_sequence                  Int?\n  /// 04 §47 — the contract that replaced this one.\n  superseded_by_contract_id          String?                  @unique\n  owner_membership_id                String?\n  /// 04 §4 — primary customer (CRM Company, 02). Full party list in ContractParty.\n  primary_company_id                 String?\n  /// 04 §7, §55 — source proposal and exact version (03).\n  proposal_id                        String?\n  proposal_version_id                String?\n  /// 04 §43 — originating project change request (05); id only.\n  project_change_request_id          String?\n  currency                           String?\n  // 04 §51 — independently addressable dates.\n  draft_date                         DateTime?                @db.Date\n  approval_date                      DateTime?                @db.Date\n  signature_date                     DateTime?                @db.Date\n  effective_date                     DateTime?                @db.Date\n  start_date                         DateTime?                @db.Date\n  end_date                           DateTime?                @db.Date\n  renewal_date                       DateTime?                @db.Date\n  notice_deadline                    DateTime?                @db.Date\n  expiration_date                    DateTime?                @db.Date\n  termination_date                   DateTime?                @db.Date\n  renewal_type                       ContractRenewalType      @default(NONE)\n  renewal_term_months                Int?\n  notice_days                        Int?\n  // 04 §54 — contractual value context; Finance (08) is authoritative for actual billing.\n  total_value                        Decimal?                 @db.Decimal(18, 2)\n  one_time_value                     Decimal?                 @db.Decimal(18, 2)\n  recurring_value                    Decimal?                 @db.Decimal(18, 2)\n  /// monthly | quarterly | annual | milestone | custom\n  billing_frequency                  String?\n  payment_terms                      String?\n  /// 04 §54, 18 §6 — billing model agreed in the contract (08 BillingModel); seeds ProjectBillingSettings on project creation.\n  billing_model                      BillingModel?\n  /// 18 §6 — contract-level default billability for time logged under this contract; null = project type / organization default.\n  default_time_billable              Boolean?\n  default_time_non_billable_category TimeNonBillableCategory?\n  // 04 §74 — risk scoring.\n  risk_score                         Int?\n  risk_level                         ContractRiskLevel?\n  risk_factors                       Json?\n  /// 04 §61 — portal exposure.\n  customer_visible                   Boolean                  @default(false)\n  current_version_id                 String?                  @unique\n  signed_version_id                  String?                  @unique\n  /// Flags the contract as containing personal-data processing (drives DPA clause, 04 §10).\n  processes_personal_data            Boolean                  @default(false)\n  activated_at                       DateTime?\n  closed_at                          DateTime?\n  archived_at                        DateTime?\n  created_by_user_id                 String?\n  created_at                         DateTime                 @default(now())\n  updated_at                         DateTime                 @updatedAt\n\n  organization     Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch           Branch?           @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  type             ContractType?     @relation(fields: [type_id], references: [id], onDelete: SetNull)\n  template         ContractTemplate? @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  parent           Contract?         @relation(\"ContractLineage\", fields: [parent_contract_id], references: [id], onDelete: SetNull)\n  children         Contract[]        @relation(\"ContractLineage\")\n  superseded_by    Contract?         @relation(\"ContractSupersession\", fields: [superseded_by_contract_id], references: [id], onDelete: SetNull)\n  supersedes       Contract?         @relation(\"ContractSupersession\")\n  owner            Membership?       @relation(\"ContractOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  primary_company  CrmCompany?       @relation(\"ContractPrimaryCompany\", fields: [primary_company_id], references: [id], onDelete: SetNull)\n  proposal         Proposal?         @relation(fields: [proposal_id], references: [id], onDelete: SetNull)\n  proposal_version ProposalVersion?  @relation(fields: [proposal_version_id], references: [id], onDelete: SetNull)\n  current_version  ContractVersion?  @relation(\"ContractCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  signed_version   ContractVersion?  @relation(\"ContractSignedVersion\", fields: [signed_version_id], references: [id], onDelete: SetNull)\n\n  parties               ContractParty[]\n  versions              ContractVersion[]\n  projects              ContractProject[]\n  change_requests       ContractChangeRequest[]\n  obligations           ContractObligation[]\n  termination           ContractTermination?\n  signature_requests    SignatureRequest[]\n  invoices              Invoice[]\n  subscriptions         Subscription[]\n  ledger_records        LedgerRecord[]\n  employee_documents    EmployeeDocument[]      @relation(\"EmployeeDocumentContract\")\n  time_project_settings TimeProjectSettings[]\n\n  @@unique([organization_id, number])\n  @@index([organization_id, status])\n  @@index([primary_company_id])\n  @@index([parent_contract_id])\n  @@index([expiration_date])\n  @@index([renewal_date])\n  @@index([notice_deadline])\n  @@map(\"contracts\")\n}\n\n/// 04 §4 — a party to the contract. References a CRM Company (02) without duplicating it;\n/// the agency itself is a party of type AGENCY.\nmodel ContractParty {\n  id                  String            @id @default(uuid())\n  contract_id         String\n  party_type          ContractPartyType\n  company_id          String?\n  legal_name          String\n  address             Json?\n  registration_number String?\n  vat_number          String?\n  sort_order          Int               @default(0)\n  created_at          DateTime          @default(now())\n\n  contract    Contract            @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  company     CrmCompany?         @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  signatories ContractSignatory[]\n\n  @@index([contract_id])\n  @@index([company_id])\n  @@map(\"contract_parties\")\n}\n\n/// 04 §4, §31 — a signatory for a party; a party may have several. Internal signatories are Members,\n/// external ones are CRM Contacts or free-text.\nmodel ContractSignatory {\n  id            String   @id @default(uuid())\n  party_id      String\n  membership_id String?\n  contact_id    String?\n  name          String\n  title         String?\n  email         String\n  is_required   Boolean  @default(true)\n  sort_order    Int      @default(0)\n  created_at    DateTime @default(now())\n\n  party      ContractParty @relation(fields: [party_id], references: [id], onDelete: Cascade)\n  membership Membership?   @relation(fields: [membership_id], references: [id], onDelete: SetNull)\n  contact    CrmContact?   @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n  signers    Signer[]\n\n  @@index([party_id])\n  @@map(\"contract_signatories\")\n}\n\n/// 04 §56 — a contract can reference many projects (05).\nmodel ContractProject {\n  contract_id String\n  project_id  String\n  /// primary | sow | related\n  role        String   @default(\"primary\")\n  created_at  DateTime @default(now())\n\n  contract Contract @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  project  Project  @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@id([contract_id, project_id])\n  @@index([project_id])\n  @@map(\"contract_projects\")\n}\n\n// --- Versions ----------------------------------------------------------------------\n\n/// 04 §19–20 — every material draft change creates a version. Signed versions are immutable (04 §39).\nmodel ContractVersion {\n  id                  String                @id @default(uuid())\n  contract_id         String\n  version_number      Int\n  /// Display label, e.g. \"v0.3\", \"v1.0\", \"Amendment 1\" (04 §19).\n  label               String\n  parent_version_id   String?\n  status              ContractVersionStatus @default(DRAFT)\n  change_summary      String?\n  template_version_id String?\n  /// Resolved variables at generation (04 §9, §17).\n  variables           Json?\n  /// Rendered document in 17 Documents (draft artifact); id only.\n  document_id         String?\n  /// Final signed artifact in 17 Documents (04 §41); id only.\n  signed_document_id  String?\n  /// Integrity hash of the rendered / signed artifact (04 §17, §40).\n  content_hash        String?\n  signed_hash         String?\n  /// Whether the customer may see this version in the portal (04 §24, §61).\n  customer_visible    Boolean               @default(false)\n  locked_at           DateTime?\n  approved_at         DateTime?\n  signed_at           DateTime?\n  created_by_user_id  String?\n  created_at          DateTime              @default(now())\n  updated_at          DateTime              @updatedAt\n\n  contract         Contract                 @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  parent_version   ContractVersion?         @relation(\"ContractVersionLineage\", fields: [parent_version_id], references: [id], onDelete: SetNull)\n  child_versions   ContractVersion[]        @relation(\"ContractVersionLineage\")\n  template_version ContractTemplateVersion? @relation(fields: [template_version_id], references: [id], onDelete: SetNull)\n\n  current_of Contract? @relation(\"ContractCurrentVersion\")\n  signed_of  Contract? @relation(\"ContractSignedVersion\")\n\n  sections             ContractSection[]\n  reviews              ContractReview[]\n  comments             ContractComment[]\n  approvals            ContractApproval[]\n  signature_requests   SignatureRequest[]\n  change_requests_from ContractChangeRequest[] @relation(\"ChangeRequestRelatedVersion\")\n  change_requests_to   ContractChangeRequest[] @relation(\"ChangeRequestResultingVersion\")\n  document             Document?               @relation(\"ContractVersionDocument\", fields: [document_id], references: [id], onDelete: SetNull)\n  signed_document      Document?               @relation(\"ContractVersionSignedDocument\", fields: [signed_document_id], references: [id], onDelete: SetNull)\n\n  ai_findings ContractAiFinding[]\n\n  @@unique([contract_id, version_number])\n  @@index([contract_id, status])\n  @@map(\"contract_versions\")\n}\n\n/// 04 §14 — addressable section of a version; may embed an exact clause version (04 §12).\nmodel ContractSection {\n  id                String   @id @default(uuid())\n  version_id        String\n  /// Stable key within the contract (parties, definitions, scope, fees, ip, …).\n  key               String\n  title             String\n  body              String?\n  clause_version_id String?\n  /// Appendix / schedule marker.\n  is_appendix       Boolean  @default(false)\n  sort_order        Int      @default(0)\n  created_at        DateTime @default(now())\n  updated_at        DateTime @updatedAt\n\n  version         ContractVersion         @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  clause_version  ContractClauseVersion?  @relation(fields: [clause_version_id], references: [id], onDelete: SetNull)\n  comments        ContractComment[]\n  change_requests ContractChangeRequest[]\n  obligations     ContractObligation[]\n\n  ai_findings ContractAiFinding[]\n\n  @@unique([version_id, key])\n  @@index([version_id, sort_order])\n  @@map(\"contract_sections\")\n}\n\n// --- Review, comments, change requests, approval ----------------------------------\n\n/// 04 §23–24 — a review request references one exact version. Internal reviewers are Members;\n/// customer reviewers are Customer Portal Users (id only) or contacts.\nmodel ContractReview {\n  id                     String                 @id @default(uuid())\n  version_id             String\n  reviewer_membership_id String?\n  reviewer_user_id       String?\n  is_internal            Boolean                @default(true)\n  decision               ContractReviewDecision @default(PENDING)\n  comment                String?\n  requested_by_user_id   String?\n  requested_at           DateTime               @default(now())\n  due_at                 DateTime?\n  decided_at             DateTime?\n\n  version  ContractVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  reviewer Membership?     @relation(\"ContractReviewer\", fields: [reviewer_membership_id], references: [id], onDelete: Cascade)\n\n  @@index([version_id, decision])\n  @@index([reviewer_membership_id, decision])\n  @@map(\"contract_reviews\")\n}\n\n/// 04 §13, §23–24 — comments on a version or section; internal comments never reach the portal.\nmodel ContractComment {\n  id                   String    @id @default(uuid())\n  version_id           String\n  section_id           String?\n  author_membership_id String?\n  author_user_id       String?\n  is_internal          Boolean   @default(true)\n  /// Blocks signature until resolved (04 §30).\n  is_blocking          Boolean   @default(false)\n  body                 String\n  resolved_at          DateTime?\n  resolved_by_user_id  String?\n  created_at           DateTime  @default(now())\n  updated_at           DateTime  @updatedAt\n\n  version ContractVersion  @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  section ContractSection? @relation(fields: [section_id], references: [id], onDelete: Cascade)\n  author  Membership?      @relation(\"ContractCommentAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([version_id, created_at])\n  @@index([section_id])\n  @@map(\"contract_comments\")\n}\n\n/// 04 §73 — one finding of an AI contract review. Always an AI-generated recommendation pointing at a section; it never edits the contract text.\nmodel ContractAiFinding {\n  id                        String                  @id @default(uuid())\n  version_id                String\n  section_id                String?\n  kind                      ContractAiFindingKind\n  severity                  ContractRiskLevel\n  message                   String\n  recommendation            String?\n  status                    ContractAiFindingStatus @default(OPEN)\n  /// Model that produced the finding and the review run it belongs to (traceability).\n  model                     String?\n  review_run_id             String?\n  confidence                Decimal?                @db.Decimal(5, 4)\n  reviewed_by_membership_id String?\n  reviewed_at               DateTime?\n  resolution_note           String?\n  created_at                DateTime                @default(now())\n\n  version     ContractVersion  @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  section     ContractSection? @relation(fields: [section_id], references: [id], onDelete: SetNull)\n  reviewed_by Membership?      @relation(\"ContractAiFindingReviewer\", fields: [reviewed_by_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([version_id, status])\n  @@map(\"contract_ai_findings\")\n}\n\n/// 04 §26 — Contract Change Request: a request to change contract language. Never mutates the\n/// current version; an accepted request produces a new version or an amendment.\nmodel ContractChangeRequest {\n  id                        String                      @id @default(uuid())\n  contract_id               String\n  related_version_id        String?\n  resulting_version_id      String?\n  section_id                String?\n  requester_membership_id   String?\n  requester_user_id         String?\n  requester_contact_id      String?\n  requested_change          String\n  reason                    String?\n  impact                    String?\n  status                    ContractChangeRequestStatus @default(REQUESTED)\n  /// Linked Project Change Request (05 §45); id only.\n  project_change_request_id String?\n  decided_by_user_id        String?\n  decided_at                DateTime?\n  created_at                DateTime                    @default(now())\n  updated_at                DateTime                    @updatedAt\n\n  contract          Contract         @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  related_version   ContractVersion? @relation(\"ChangeRequestRelatedVersion\", fields: [related_version_id], references: [id], onDelete: SetNull)\n  resulting_version ContractVersion? @relation(\"ChangeRequestResultingVersion\", fields: [resulting_version_id], references: [id], onDelete: SetNull)\n  section           ContractSection? @relation(fields: [section_id], references: [id], onDelete: SetNull)\n\n  @@index([contract_id, status])\n  @@map(\"contract_change_requests\")\n}\n\n/// 04 §27–29 — business approval bound to an exact version. Approval of v1.0 does not approve v1.1.\nmodel ContractApproval {\n  id                     String                   @id @default(uuid())\n  version_id             String\n  step                   Int                      @default(1)\n  /// Role label for the step (account owner, finance, legal, executive, technical).\n  step_name              String?\n  approver_membership_id String\n  decision               ContractApprovalDecision @default(PENDING)\n  comment                String?\n  rule_id                String?\n  requested_at           DateTime                 @default(now())\n  decided_at             DateTime?\n\n  version  ContractVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  approver Membership      @relation(\"ContractApprover\", fields: [approver_membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([version_id, approver_membership_id, step])\n  @@index([approver_membership_id, decision])\n  @@map(\"contract_approvals\")\n}\n\n// --- E-signature (in-house signing service) (04 §30–42, §71, §78–79) -------------------\n\n/// 04 §34 — a signature request bound immutably to one subject version (contract or proposal).\n/// Provider-specific data stays in provider_* fields and metadata, never in core contract fields.\nmodel SignatureRequest {\n  id                            String                 @id @default(uuid())\n  organization_id               String\n  subject_type                  SignatureSubjectType\n  contract_id                   String?\n  contract_version_id           String?\n  proposal_version_id           String?\n  status                        SignatureRequestStatus @default(NOT_SENT)\n  signing_order                 SigningOrder           @default(SEQUENTIAL)\n  /// 04 §78 — package of document ids (17) in locked order: [{ document_id, title, sort_order }].\n  package_documents             Json?\n  /// 04 §37 — reminder settings: { frequency_days, max_reminders }.\n  reminder_settings             Json?\n  reminders_sent                Int                    @default(0)\n  /// Signed artifact (17) and the audit certificate (17) generated by the platform; ids only.\n  signed_document_id            String?\n  audit_certificate_document_id String?\n  signed_hash                   String?\n  message                       String?\n  created_by_user_id            String?\n  sent_at                       DateTime?\n  expires_at                    DateTime?\n  completed_at                  DateTime?\n  cancelled_at                  DateTime?\n  cancel_reason                 String?\n  metadata                      Json?\n  created_at                    DateTime               @default(now())\n  updated_at                    DateTime               @updatedAt\n\n  organization               Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  contract                   Contract?          @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  contract_version           ContractVersion?   @relation(fields: [contract_version_id], references: [id], onDelete: Cascade)\n  proposal_version           ProposalVersion?   @relation(fields: [proposal_version_id], references: [id], onDelete: Cascade)\n  signers                    Signer[]\n  events                     SignatureEvent[]\n  employee_documents         EmployeeDocument[] @relation(\"EmployeeDocumentSignatureRequest\")\n  signed_document            Document?          @relation(\"SignatureRequestSignedDocument\", fields: [signed_document_id], references: [id], onDelete: SetNull)\n  audit_certificate_document Document?          @relation(\"SignatureRequestAuditCertificate\", fields: [audit_certificate_document_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@index([contract_id])\n  @@index([contract_version_id])\n  @@index([proposal_version_id])\n  @@index([expires_at])\n  @@map(\"signature_requests\")\n}\n\n/// 04 §31–32, §36 — a signer on a request with mapped fields and signing position.\nmodel Signer {\n  id                    String         @id @default(uuid())\n  request_id            String\n  signatory_id          String?\n  name                  String\n  email                 String\n  title                 String?\n  /// Position in sequential signing; equal values sign in parallel.\n  order                 Int            @default(1)\n  status                SignerStatus   @default(PENDING)\n  /// Mapped fields (04 §31): [{ type: signature|date|initial|text, page, x, y, w, h, required }].\n  fields                Json?\n  /// Hash of the single-use signing link token (the raw token is only in the link sent to the signer).\n  access_token_hash     String?        @unique\n  auth_method           String?\n  /// Custom e-signature (04 §36): how the signature was given, the stored signature image (17, id only), the consent text version the signer accepted,\n  /// and when the signer's identity was verified (one-time code by email or SMS, auth_method).\n  signature_type        SignatureType?\n  signature_document_id String?\n  consent_text_version  String?\n  consent_accepted_at   DateTime?\n  identity_verified_at  DateTime?\n  ip_address            String?\n  user_agent            String?\n  sent_at               DateTime?\n  viewed_at             DateTime?\n  signed_at             DateTime?\n  declined_at           DateTime?\n  decline_reason        String?\n\n  request   SignatureRequest   @relation(fields: [request_id], references: [id], onDelete: Cascade)\n  signatory ContractSignatory? @relation(fields: [signatory_id], references: [id], onDelete: SetNull)\n  events    SignatureEvent[]\n\n  @@index([request_id, order])\n  @@index([email])\n  @@map(\"signers\")\n}\n\n/// 04 §38, §71 — provider and internal events; (provider, provider_event_id) is unique so duplicate\n/// callbacks are ignored.\nmodel SignatureEvent {\n  id          String             @id @default(uuid())\n  request_id  String\n  signer_id   String?\n  type        SignatureEventType\n  occurred_at DateTime           @default(now())\n  ip_address  String?\n  payload     Json?\n  created_at  DateTime           @default(now())\n\n  request SignatureRequest @relation(fields: [request_id], references: [id], onDelete: Cascade)\n  signer  Signer?          @relation(fields: [signer_id], references: [id], onDelete: SetNull)\n\n  @@index([request_id, occurred_at])\n  @@map(\"signature_events\")\n}\n\n// --- Obligations & termination ----------------------------------------------------\n\n/// 04 §49–50, §75 — operational obligations linked to a contract section; execution may create a\n/// Task (06) rather than duplicating task functionality.\nmodel ContractObligation {\n  id                        String                   @id @default(uuid())\n  contract_id               String\n  section_id                String?\n  type                      ContractObligationType   @default(OTHER)\n  title                     String\n  description               String?\n  /// Responsible side: a party of the contract and/or an internal Member.\n  responsible_party_id      String?\n  responsible_membership_id String?\n  due_date                  DateTime?                @db.Date\n  /// none | weekly | monthly | quarterly | annual\n  frequency                 String?\n  status                    ContractObligationStatus @default(OPEN)\n  reminder_days_before      Int?\n  /// Related Project (05) and Task (06); ids only.\n  project_id                String?\n  task_id                   String?\n  /// AI extraction provenance (04 §75).\n  is_ai_extracted           Boolean                  @default(false)\n  extraction_confidence     Decimal?                 @db.Decimal(5, 4)\n  review_state              ExtractionReviewState?\n  fulfilled_at              DateTime?\n  created_at                DateTime                 @default(now())\n  updated_at                DateTime                 @updatedAt\n\n  contract Contract         @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  section  ContractSection? @relation(fields: [section_id], references: [id], onDelete: SetNull)\n  task     Task?            @relation(fields: [task_id], references: [id], onDelete: SetNull)\n\n  @@index([contract_id, status])\n  @@index([due_date])\n  @@map(\"contract_obligations\")\n}\n\n/// 04 §53 — termination record. Never alters the signed document.\nmodel ContractTermination {\n  contract_id         String                  @id\n  type                ContractTerminationType @default(FOR_CONVENIENCE)\n  reason              String?\n  requesting_party_id String?\n  notice_date         DateTime?               @db.Date\n  effective_date      DateTime                @db.Date\n  approved_by_user_id String?\n  approved_at         DateTime?\n  /// Supporting document (17); id only.\n  document_id         String?\n  notes               String?\n  created_by_user_id  String?\n  created_at          DateTime                @default(now())\n\n  contract Contract  @relation(fields: [contract_id], references: [id], onDelete: Cascade)\n  document Document? @relation(fields: [document_id], references: [id], onDelete: SetNull)\n\n  @@map(\"contract_terminations\")\n}\n\n// =====================================================================\n// 05 Project Management — docs/features/05-project-management.md (LOG-405)\n// Owns: project types/statuses/templates, Project, membership and roles, branches, stakeholders,\n// objectives, workstreams, milestones, deliverables, acceptance criteria, dependencies, risks,\n// issues/blockers, decisions, status updates, project change requests, gates, reviews, allocation,\n// checklists, escalations, handovers, closeout, relationships, external references.\n// Does not own: Tasks (06), time entries (18), documents (17), messages (12), tickets (13),\n// invoices/expenses (08/09), calendar events (19), employees (10). Referenced by id only.\n// Project notes use the polymorphic notes table (crm_notes, entity_type PROJECT).\n// Project activity and change history (05 §42–43) are written to audit_events.\n// =====================================================================\n\n/// 05 §4 — semantic category of a configurable status.\nenum ProjectStatusCategory {\n  DRAFT\n  PLANNED\n  NOT_STARTED\n  IN_PROGRESS\n  ON_HOLD\n  BLOCKED\n  READY_FOR_COMPLETION\n  COMPLETED\n  CANCELLED\n  ARCHIVED\n}\n\n/// 05 §13\nenum ProjectHealth {\n  HEALTHY\n  AT_RISK\n  BLOCKED\n  CRITICAL\n  UNKNOWN\n}\n\n/// 05 §13–14 — how health / progress are determined.\nenum CalculationMode {\n  MANUAL\n  AUTOMATIC\n  HYBRID\n}\n\n/// 05 §80\nenum ProjectPriority {\n  CRITICAL\n  HIGH\n  MEDIUM\n  LOW\n}\n\n/// 05 §60, §111 — customer exposure of the project.\nenum ProjectVisibility {\n  INTERNAL\n  CUSTOMER_VISIBLE\n}\n\n/// 05 §19–20\nenum ProjectItemStatus {\n  PLANNED\n  IN_PROGRESS\n  AT_RISK\n  COMPLETED\n  CANCELLED\n}\n\n/// 05 §18 — deliverable lifecycle including customer acceptance (05 §47, 07 §7).\nenum DeliverableStatus {\n  PLANNED\n  IN_PROGRESS\n  READY_FOR_REVIEW\n  SUBMITTED\n  CHANGES_REQUESTED\n  ACCEPTED\n  REJECTED\n  CANCELLED\n}\n\n/// 05 §47\nenum AcceptanceStatus {\n  PENDING\n  PASSED\n  FAILED\n  WAIVED\n}\n\n/// 05 §21, §27–28 — what a dependency endpoint is.\nenum DependencyItemType {\n  PROJECT\n  WORKSTREAM\n  MILESTONE\n  DELIVERABLE\n  TASK\n  EXTERNAL\n}\n\n/// 05 §27\nenum DependencyType {\n  FINISH_TO_START\n  START_TO_START\n  FINISH_TO_FINISH\n  START_TO_FINISH\n  BLOCKS\n  RELATED\n}\n\nenum DependencyStatus {\n  OPEN\n  RESOLVED\n  CANCELLED\n}\n\n/// 05 §29\nenum RiskStatus {\n  OPEN\n  MONITORING\n  MITIGATED\n  ACCEPTED\n  RESOLVED\n  CLOSED\n}\n\n/// 05 §30–31 — a Project Issue is a delivery problem; a Blocker is an issue preventing progress.\nenum ProjectIssueKind {\n  ISSUE\n  BLOCKER\n}\n\nenum ProjectIssueStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n  CANCELLED\n}\n\nenum Severity {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\n/// 05 §45 — Project Change Request status (not a Contract Change Request, 04 §26).\nenum ProjectChangeRequestStatus {\n  REQUESTED\n  UNDER_REVIEW\n  ESTIMATING\n  AWAITING_APPROVAL\n  APPROVED\n  REJECTED\n  SCHEDULED\n  IMPLEMENTED\n  CANCELLED\n}\n\n/// 05 §46, §93 — approval and quality gates share one model.\nenum ProjectGateKind {\n  APPROVAL\n  QUALITY\n}\n\nenum ProjectGateStatus {\n  PENDING\n  PASSED\n  FAILED\n  WAIVED\n}\n\n/// 05 §48–49\nenum ProjectReviewType {\n  KICKOFF\n  MILESTONE\n  DELIVERY\n  QUALITY\n  CUSTOMER\n  POST_PROJECT\n  RETROSPECTIVE\n}\n\n/// 05 §105\nenum ProjectRelationType {\n  RELATED\n  DEPENDENCY\n  REPLACEMENT\n  FOLLOW_UP\n  MAINTENANCE_FOR\n  CONTINUATION_OF\n}\n\n/// 05 §101\nenum EscalationStatus {\n  OPEN\n  ACKNOWLEDGED\n  RESOLVED\n  CLOSED\n}\n\n/// 05 §72, §102\nenum HandoverStatus {\n  PLANNED\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\n// --- Configuration ----------------------------------------------------------------\n\n/// 05 §2 — organization-defined project types with defaults.\nmodel ProjectType {\n  id                                 String                   @id @default(uuid())\n  organization_id                    String\n  name                               String\n  slug                               String\n  description                        String?\n  default_template_id                String?\n  /// Workspace sections enabled by default (05 §11).\n  enabled_sections                   String[]                 @default([])\n  required_fields                    String[]                 @default([])\n  /// Health rules for AUTOMATIC/HYBRID mode (05 §13).\n  health_rules                       Json?\n  /// Completion checklist requirements (05 §71).\n  completion_requirements            Json?\n  is_default                         Boolean                  @default(false)\n  sort_order                         Int                      @default(0)\n  /// 18 §6 — default billability for time entries on projects of this type; null = organization default (TimeTrackingSettings). Copied into TimeProjectSettings when a project is created.\n  default_time_billable              Boolean?\n  /// 18 §6 — non-billable category applied when default_time_billable = false.\n  default_time_non_billable_category TimeNonBillableCategory?\n  archived_at                        DateTime?\n  created_at                         DateTime                 @default(now())\n  updated_at                         DateTime                 @updatedAt\n\n  organization     Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_template ProjectTemplate?  @relation(\"ProjectTypeDefaultTemplate\", fields: [default_template_id], references: [id], onDelete: SetNull)\n  templates        ProjectTemplate[] @relation(\"ProjectTemplateType\")\n  projects         Project[]\n  folder_templates FolderTemplate[]\n  automation_rules AutomationRule[]\n  task_statuses    TaskStatus[]\n\n  @@unique([organization_id, slug])\n  @@map(\"project_types\")\n}\n\n/// 05 §4 — configurable lifecycle statuses with allowed transitions.\nmodel ProjectStatus {\n  id                  String                @id @default(uuid())\n  organization_id     String\n  name                String\n  slug                String\n  category            ProjectStatusCategory\n  color               String?\n  sort_order          Int                   @default(0)\n  is_default          Boolean               @default(false)\n  /// Slugs of statuses this one may transition to; null = any.\n  allowed_transitions String[]              @default([])\n  archived_at         DateTime?\n  created_at          DateTime              @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  projects     Project[]\n\n  @@unique([organization_id, slug])\n  @@map(\"project_statuses\")\n}\n\n/// 05 §36–37 — templates with versions; updating a template never modifies existing projects.\nmodel ProjectTemplate {\n  id                 String    @id @default(uuid())\n  organization_id    String\n  type_id            String?\n  name               String\n  slug               String\n  description        String?\n  current_version_id String?   @unique\n  is_active          Boolean   @default(true)\n  deprecated_at      DateTime?\n  created_by_user_id String?\n  created_at         DateTime  @default(now())\n  updated_at         DateTime  @updatedAt\n\n  organization      Organization             @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  type              ProjectType?             @relation(\"ProjectTemplateType\", fields: [type_id], references: [id], onDelete: SetNull)\n  current_version   ProjectTemplateVersion?  @relation(\"ProjectTemplateCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  versions          ProjectTemplateVersion[]\n  default_for_types ProjectType[]            @relation(\"ProjectTypeDefaultTemplate\")\n  projects          Project[]\n\n  @@unique([organization_id, slug])\n  @@map(\"project_templates\")\n}\n\n/// 05 §37 — immutable template content: statuses, milestones, workstreams, task structures,\n/// dependencies, roles, required fields, standard documents, checklists, health rules, views.\nmodel ProjectTemplateVersion {\n  id                 String   @id @default(uuid())\n  template_id        String\n  version_number     Int\n  change_summary     String?\n  structure          Json\n  created_by_user_id String?\n  created_at         DateTime @default(now())\n\n  template   ProjectTemplate  @relation(fields: [template_id], references: [id], onDelete: Cascade)\n  current_of ProjectTemplate? @relation(\"ProjectTemplateCurrentVersion\")\n  projects   Project[]\n\n  @@unique([template_id, version_number])\n  @@map(\"project_template_versions\")\n}\n\n// --- Project ------------------------------------------------------------------------\n\n/// 05 §3, §5–7, §12–15, §80, §106–107, §117 — the project record.\nmodel Project {\n  id                  String            @id @default(uuid())\n  organization_id     String\n  /// Primary branch (01 §32). Participating branches in ProjectBranch.\n  branch_id           String?\n  parent_project_id   String?\n  name                String\n  /// Optional human project code (05 §6, §114); stable id is `id`.\n  code                String?\n  slug                String\n  description         String?\n  type_id             String?\n  status_id           String?\n  health              ProjectHealth     @default(UNKNOWN)\n  health_mode         CalculationMode   @default(HYBRID)\n  health_reason       String?\n  progress_percent    Int               @default(0)\n  progress_mode       CalculationMode   @default(AUTOMATIC)\n  priority            ProjectPriority   @default(MEDIUM)\n  visibility          ProjectVisibility @default(INTERNAL)\n  /// Customer (CRM Company, 02). Optional: internal projects have none (05 §3, §56).\n  company_id          String?\n  owner_membership_id String?\n  team_id             String?\n  template_id         String?\n  template_version_id String?\n  /// Source proposal and exact version (03), set when created from an accepted proposal (05 §57).\n  proposal_id         String?\n  proposal_version_id String?\n  // 05 §15 — dates.\n  planned_start       DateTime?         @db.Date\n  actual_start        DateTime?         @db.Date\n  target_completion   DateTime?         @db.Date\n  actual_completion   DateTime?         @db.Date\n  review_date         DateTime?         @db.Date\n  internal_deadline   DateTime?         @db.Date\n  customer_deadline   DateTime?         @db.Date\n  /// 05 §51 — planned budget context; actual financials live in 08/09.\n  budget_hours        Decimal?          @db.Decimal(12, 2)\n  budget_amount       Decimal?          @db.Decimal(18, 2)\n  currency            String?\n  icon                String?\n  color               String?\n  /// Messaging project channel (12 §26); id only.\n  channel_id          String?\n  /// Business Docs runbook page (15 §4); id only.\n  runbook_page_id     String?\n  completed_at        DateTime?\n  cancelled_at        DateTime?\n  archived_at         DateTime?\n  reopened_at         DateTime?\n  created_by_user_id  String?\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  organization     Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch           Branch?                 @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  parent           Project?                @relation(\"ProjectHierarchy\", fields: [parent_project_id], references: [id], onDelete: SetNull)\n  children         Project[]               @relation(\"ProjectHierarchy\")\n  type             ProjectType?            @relation(fields: [type_id], references: [id], onDelete: SetNull)\n  status           ProjectStatus?          @relation(fields: [status_id], references: [id], onDelete: SetNull)\n  company          CrmCompany?             @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  owner            Membership?             @relation(\"ProjectOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  team             Team?                   @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  template         ProjectTemplate?        @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  template_version ProjectTemplateVersion? @relation(fields: [template_version_id], references: [id], onDelete: SetNull)\n  proposal         Proposal?               @relation(\"ProjectSourceProposal\", fields: [proposal_id], references: [id], onDelete: SetNull)\n  proposal_version ProposalVersion?        @relation(\"ProjectSourceProposalVersion\", fields: [proposal_version_id], references: [id], onDelete: SetNull)\n\n  branches                       ProjectBranch[]\n  members                        ProjectMember[]\n  stakeholders                   ProjectStakeholder[]\n  objectives                     ProjectObjective[]\n  workstreams                    ProjectWorkstream[]\n  milestones                     ProjectMilestone[]\n  deliverables                   ProjectDeliverable[]\n  dependencies                   ProjectDependency[]\n  risks                          ProjectRisk[]\n  issues                         ProjectIssue[]\n  decisions                      ProjectDecision[]\n  status_updates                 ProjectStatusUpdate[]\n  change_requests                ProjectChangeRequest[]\n  gates                          ProjectGate[]\n  reviews                        ProjectReview[]\n  allocations                    ProjectAllocation[]\n  checklists                     ProjectChecklist[]\n  escalations                    ProjectEscalation[]\n  handovers                      ProjectHandover[]\n  closeout                       ProjectCloseout?\n  relations_from                 ProjectRelation[]             @relation(\"ProjectRelationSource\")\n  relations_to                   ProjectRelation[]             @relation(\"ProjectRelationTarget\")\n  external_refs                  ProjectExternalReference[]\n  contracts                      ContractProject[]\n  deals                          CrmDeal[]                     @relation(\"CrmDealProject\")\n  converted_from_proposals       Proposal[]                    @relation(\"ProposalConvertedProject\")\n  tasks                          Task[]\n  cycles                         Cycle[]\n  releases                       Release[]\n  invoices                       Invoice[]\n  subscriptions                  Subscription[]\n  billing_settings               ProjectBillingSettings?\n  ledger_records                 LedgerRecord[]\n  recurring_expenses             RecurringExpense[]\n  financial_period_summaries     FinancialPeriodSummary[]\n  ledger_profitability_snapshots LedgerProfitabilitySnapshot[]\n  performance_goals              PerformanceGoal[]\n  performance_feedback           PerformanceFeedback[]\n  comm_threads                   CommThread[]\n  comm_messages                  CommMessage[]\n  messaging_channels             Channel[]\n  channel                        Channel?                      @relation(\"ProjectPrimaryChannel\", fields: [channel_id], references: [id], onDelete: SetNull)\n  support_tickets                Ticket[]\n  wiki_spaces                    WikiSpace[]\n  runbook_page                   WikiPage?                     @relation(fields: [runbook_page_id], references: [id], onDelete: SetNull)\n  folders                        Folder[]\n  documents                      Document[]\n  vault_entries                  VaultEntry[]\n  time_settings                  TimeProjectSettings?\n  billing_rates                  BillingRate[]\n  time_entries                   TimeEntry[]\n  timers                         Timer[]\n  time_suggestions               TimeSuggestion[]\n  calendars                      Calendar[]\n  calendar_events                CalendarEvent[]\n  automation_rules               AutomationRule[]\n\n  @@unique([organization_id, slug])\n  @@unique([organization_id, code])\n  @@index([organization_id, status_id])\n  @@index([organization_id, health])\n  @@index([company_id])\n  @@index([owner_membership_id])\n  @@index([parent_project_id])\n  @@index([target_completion])\n  @@map(\"projects\")\n}\n\n/// 01 §32–33 — participating branches of a multi-branch project (primary is projects.branch_id).\nmodel ProjectBranch {\n  project_id String\n  branch_id  String\n  created_at DateTime @default(now())\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  branch  Branch  @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n\n  @@id([project_id, branch_id])\n  @@index([branch_id])\n  @@map(\"project_branches\")\n}\n\n/// 05 §8–9 — internal participants. role_id is a Role of type PROJECT (01 §45).\nmodel ProjectMember {\n  id                 String    @id @default(uuid())\n  project_id         String\n  membership_id      String\n  role_id            String?\n  /// Free-text role label when no Role is used (Developer, Designer, QA, …).\n  role_label         String?\n  allocation_percent Int?\n  is_active          Boolean   @default(true)\n  joined_at          DateTime  @default(now())\n  left_at            DateTime?\n  created_at         DateTime  @default(now())\n\n  project    Project    @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  role       Role?      @relation(fields: [role_id], references: [id], onDelete: SetNull)\n\n  @@unique([project_id, membership_id])\n  @@index([membership_id, is_active])\n  @@map(\"project_members\")\n}\n\n/// 05 §53 — external stakeholders: customer contacts (02), vendors, partners, consultants.\nmodel ProjectStakeholder {\n  id                 String   @id @default(uuid())\n  project_id         String\n  contact_id         String?\n  name               String\n  organization_name  String?\n  email              String?\n  role               String?\n  responsibility     String?\n  /// Whether the stakeholder sees the project in the Customer Portal (via 01 §79 identity).\n  portal_visible     Boolean  @default(false)\n  decision_authority Boolean  @default(false)\n  created_at         DateTime @default(now())\n\n  project Project     @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  contact CrmContact? @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n\n  @@index([project_id])\n  @@map(\"project_stakeholders\")\n}\n\n// --- Planning ----------------------------------------------------------------------\n\n/// 05 §17\nmodel ProjectObjective {\n  id                  String            @id @default(uuid())\n  project_id          String\n  name                String\n  description         String?\n  owner_membership_id String?\n  target_date         DateTime?         @db.Date\n  success_criteria    String?\n  status              ProjectItemStatus @default(PLANNED)\n  progress_percent    Int               @default(0)\n  sort_order          Int               @default(0)\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  project    Project            @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  milestones ProjectMilestone[]\n\n  @@index([project_id])\n  @@map(\"project_objectives\")\n}\n\n/// 05 §19\nmodel ProjectWorkstream {\n  id                  String            @id @default(uuid())\n  project_id          String\n  name                String\n  description         String?\n  owner_membership_id String?\n  status              ProjectItemStatus @default(PLANNED)\n  progress_percent    Int               @default(0)\n  planned_start       DateTime?         @db.Date\n  planned_end         DateTime?         @db.Date\n  actual_start        DateTime?         @db.Date\n  actual_end          DateTime?         @db.Date\n  color               String?\n  sort_order          Int               @default(0)\n  archived_at         DateTime?\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  project      Project              @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  milestones   ProjectMilestone[]\n  deliverables ProjectDeliverable[]\n  allocations  ProjectAllocation[]\n  tasks        Task[]\n  time_entries TimeEntry[]\n  timers       Timer[]\n\n  @@index([project_id])\n  @@map(\"project_workstreams\")\n}\n\n/// 05 §20 — major checkpoints. Task links come from Task Management (06).\nmodel ProjectMilestone {\n  id                     String            @id @default(uuid())\n  project_id             String\n  workstream_id          String?\n  objective_id           String?\n  name                   String\n  description            String?\n  owner_membership_id    String?\n  status                 ProjectItemStatus @default(PLANNED)\n  planned_date           DateTime?         @db.Date\n  actual_date            DateTime?         @db.Date\n  progress_percent       Int               @default(0)\n  /// Shown in the Customer Portal (05 §60) and projected onto the Calendar (19).\n  customer_visible       Boolean           @default(false)\n  /// Triggers milestone billing in 08 when completed.\n  is_billing_milestone   Boolean           @default(false)\n  /// Proposal milestone this was created from (03), stored as the proposal's milestone key.\n  proposal_milestone_key String?\n  notes                  String?\n  sort_order             Int               @default(0)\n  completed_at           DateTime?\n  created_at             DateTime          @default(now())\n  updated_at             DateTime          @updatedAt\n\n  project             Project                      @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  workstream          ProjectWorkstream?           @relation(fields: [workstream_id], references: [id], onDelete: SetNull)\n  objective           ProjectObjective?            @relation(fields: [objective_id], references: [id], onDelete: SetNull)\n  deliverables        ProjectDeliverable[]\n  acceptance_criteria ProjectAcceptanceCriterion[]\n  gates               ProjectGate[]\n  allocations         ProjectAllocation[]\n  tasks               Task[]\n  invoice_line_items  InvoiceLineItem[]\n  ledger_records      LedgerRecord[]\n  time_entries        TimeEntry[]\n  timers              Timer[]\n\n  @@index([project_id, planned_date])\n  @@index([workstream_id])\n  @@map(\"project_milestones\")\n}\n\n/// 05 §18 — tangible outputs. Files are Documents (17); commercial scope stays in 03/04.\nmodel ProjectDeliverable {\n  id                  String            @id @default(uuid())\n  project_id          String\n  milestone_id        String?\n  workstream_id       String?\n  name                String\n  description         String?\n  owner_membership_id String?\n  status              DeliverableStatus @default(PLANNED)\n  due_date            DateTime?         @db.Date\n  customer_visible    Boolean           @default(false)\n  /// Document ids (17) delivered.\n  document_ids        String[]          @default([])\n  /// Proposal line item / section reference (03) for commercial scope traceability.\n  proposal_reference  String?\n  submitted_at        DateTime?\n  accepted_at         DateTime?\n  /// Customer acceptance evidence: portal user id, contact id, comment (07 §7).\n  acceptance_record   Json?\n  sort_order          Int               @default(0)\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  project             Project                      @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  milestone           ProjectMilestone?            @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n  workstream          ProjectWorkstream?           @relation(fields: [workstream_id], references: [id], onDelete: SetNull)\n  acceptance_criteria ProjectAcceptanceCriterion[]\n  reviews             ProjectDeliverableReview[]\n\n  @@index([project_id, status])\n  @@index([milestone_id])\n  @@map(\"project_deliverables\")\n}\n\n/// 05 §47 — acceptance criteria on a deliverable or milestone. Contractual acceptance terms are 04.\nmodel ProjectAcceptanceCriterion {\n  id                     String           @id @default(uuid())\n  deliverable_id         String?\n  milestone_id           String?\n  requirement            String\n  expected_outcome       String?\n  verification_method    String?\n  status                 AcceptanceStatus @default(PENDING)\n  reviewer_membership_id String?\n  reviewed_at            DateTime?\n  sort_order             Int              @default(0)\n\n  deliverable ProjectDeliverable? @relation(fields: [deliverable_id], references: [id], onDelete: Cascade)\n  milestone   ProjectMilestone?   @relation(fields: [milestone_id], references: [id], onDelete: Cascade)\n\n  @@index([deliverable_id])\n  @@index([milestone_id])\n  @@map(\"project_acceptance_criteria\")\n}\n\n/// 05 §21, §27–28 — dependencies between tasks, milestones, workstreams, deliverables and projects.\n/// Endpoints are typed ids so Task (06) endpoints work without a FK.\nmodel ProjectDependency {\n  id                  String             @id @default(uuid())\n  project_id          String\n  source_type         DependencyItemType\n  source_id           String\n  target_type         DependencyItemType\n  target_id           String\n  type                DependencyType     @default(FINISH_TO_START)\n  status              DependencyStatus   @default(OPEN)\n  owner_membership_id String?\n  expected_resolution DateTime?          @db.Date\n  lag_days            Int?\n  notes               String?\n  resolved_at         DateTime?\n  created_at          DateTime           @default(now())\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, status])\n  @@index([source_type, source_id])\n  @@index([target_type, target_id])\n  @@map(\"project_dependencies\")\n}\n\n// --- Delivery visibility -------------------------------------------------------------\n\n/// 05 §29\nmodel ProjectRisk {\n  id                  String     @id @default(uuid())\n  project_id          String\n  title               String\n  description         String?\n  category            String?\n  /// 1–5 scales; severity derived or set.\n  probability         Int?\n  impact              Int?\n  severity            Severity   @default(MEDIUM)\n  status              RiskStatus @default(OPEN)\n  owner_membership_id String?\n  mitigation          String?\n  contingency         String?\n  due_date            DateTime?  @db.Date\n  milestone_id        String?\n  task_id             String?\n  resolved_at         DateTime?\n  created_at          DateTime   @default(now())\n  updated_at          DateTime   @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, status])\n  @@map(\"project_risks\")\n}\n\n/// 05 §30–31 — Project Issues and Blockers (kind). Distinct from Support tickets (13) and Tasks (06).\nmodel ProjectIssue {\n  id                  String              @id @default(uuid())\n  project_id          String\n  kind                ProjectIssueKind    @default(ISSUE)\n  title               String\n  description         String?\n  severity            Severity            @default(MEDIUM)\n  priority            ProjectPriority     @default(MEDIUM)\n  status              ProjectIssueStatus  @default(OPEN)\n  owner_membership_id String?\n  /// For blockers: what is blocked (typed id).\n  blocked_item_type   DependencyItemType?\n  blocked_item_id     String?\n  milestone_id        String?\n  task_id             String?\n  dependency_id       String?\n  /// Linked support ticket (13) when the issue originated from support; id only.\n  ticket_id           String?\n  identified_at       DateTime            @default(now())\n  target_resolution   DateTime?           @db.Date\n  resolution          String?\n  resolved_at         DateTime?\n  created_at          DateTime            @default(now())\n  updated_at          DateTime            @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  task    Task?   @relation(fields: [task_id], references: [id], onDelete: SetNull)\n  ticket  Ticket? @relation(fields: [ticket_id], references: [id], onDelete: SetNull)\n\n  @@index([project_id, kind, status])\n  @@map(\"project_issues\")\n}\n\n/// 05 §32 — decision records.\nmodel ProjectDecision {\n  id                           String   @id @default(uuid())\n  project_id                   String\n  title                        String\n  description                  String?\n  decided_at                   DateTime @default(now())\n  decision_maker_membership_id String?\n  /// Membership ids.\n  participants                 String[] @default([])\n  alternatives_considered      String?\n  selected_option              String?\n  reason                       String?\n  consequences                 String?\n  milestone_id                 String?\n  task_id                      String?\n  document_id                  String?\n  /// Source message permalink (12 §63) when converted from a conversation.\n  source_message_id            String?\n  created_at                   DateTime @default(now())\n\n  project        Project   @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  source_message Message?  @relation(\"ProjectDecisionSourceMessage\", fields: [source_message_id], references: [id], onDelete: SetNull)\n  document       Document? @relation(fields: [document_id], references: [id], onDelete: SetNull)\n\n  @@index([project_id, decided_at])\n  @@map(\"project_decisions\")\n}\n\n/// 05 §39 — structured status updates; customer-visible ones appear in the portal (07 §4).\nmodel ProjectStatusUpdate {\n  id                   String         @id @default(uuid())\n  project_id           String\n  period_start         DateTime?      @db.Date\n  period_end           DateTime?      @db.Date\n  summary              String\n  completed_work       String?\n  current_work         String?\n  upcoming_work        String?\n  progress_percent     Int?\n  health               ProjectHealth?\n  risks_summary        String?\n  blockers_summary     String?\n  decisions_summary    String?\n  required_actions     String?\n  author_membership_id String?\n  customer_visible     Boolean        @default(false)\n  published_at         DateTime?\n  is_ai_generated      Boolean        @default(false)\n  created_at           DateTime       @default(now())\n  updated_at           DateTime       @updatedAt\n\n  project  Project                      @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  comments ProjectStatusUpdateComment[]\n\n  @@index([project_id, published_at])\n  @@map(\"project_status_updates\")\n}\n\n/// 05 §45 — Project Change Request: changes affecting delivery. Commercial approval stays with\n/// 03/04 (proposal_id, contract_id); a Contract Change Request (04 §26) may be linked.\nmodel ProjectChangeRequest {\n  id                           String                     @id @default(uuid())\n  project_id                   String\n  number                       Int\n  title                        String\n  description                  String?\n  requester_membership_id      String?\n  requester_contact_id         String?\n  requested_at                 DateTime                   @default(now())\n  priority                     ProjectPriority            @default(MEDIUM)\n  status                       ProjectChangeRequestStatus @default(REQUESTED)\n  scope_impact                 String?\n  timeline_impact_days         Int?\n  resource_impact              String?\n  cost_impact_amount           Decimal?                   @db.Decimal(18, 2)\n  currency                     String?\n  customer_visible             Boolean                    @default(false)\n  approved_by_membership_id    String?\n  approved_by_customer_user_id String?\n  approved_at                  DateTime?\n  rejected_reason              String?\n  deliverable_id               String?\n  task_id                      String?\n  /// Commercial links (03, 04) and the contract change request this originated (04 §26, §43).\n  proposal_id                  String?\n  contract_id                  String?\n  contract_change_request_id   String?\n  implemented_at               DateTime?\n  created_at                   DateTime                   @default(now())\n  updated_at                   DateTime                   @updatedAt\n\n  project         Project  @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  task            Task?    @relation(fields: [task_id], references: [id], onDelete: SetNull)\n  support_tickets Ticket[]\n\n  @@unique([project_id, number])\n  @@index([project_id, status])\n  @@map(\"project_change_requests\")\n}\n\n/// 05 §46, §93 — approval gates (requirements, design, development, QA, security, customer\n/// acceptance, launch, handover) and quality gates (code review, QA, security review, documentation).\nmodel ProjectGate {\n  id                        String            @id @default(uuid())\n  project_id                String\n  kind                      ProjectGateKind   @default(APPROVAL)\n  name                      String\n  description               String?\n  milestone_id              String?\n  approver_membership_id    String?\n  /// Customer approval gates are decided by a Customer Portal User (01 §79); id only.\n  customer_approver_user_id String?\n  status                    ProjectGateStatus @default(PENDING)\n  blocks_completion         Boolean           @default(false)\n  decision_comment          String?\n  decided_at                DateTime?\n  sort_order                Int               @default(0)\n  created_at                DateTime          @default(now())\n  updated_at                DateTime          @updatedAt\n\n  project   Project           @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  milestone ProjectMilestone? @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n  approver  Membership?       @relation(\"ProjectGateApprover\", fields: [approver_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([project_id, status])\n  @@map(\"project_gates\")\n}\n\n/// 05 §48–49 — structured reviews and retrospectives. Actions may create Tasks (06).\nmodel ProjectReview {\n  id                        String            @id @default(uuid())\n  project_id                String\n  type                      ProjectReviewType\n  title                     String\n  held_at                   DateTime?\n  facilitator_membership_id String?\n  /// Membership ids.\n  participants              String[]          @default([])\n  findings                  String?\n  decisions                 String?\n  /// Retrospective fields (05 §49).\n  went_well                 String?\n  went_wrong                String?\n  root_causes               String?\n  lessons                   String?\n  /// Actions: [{ title, owner_membership_id, due_date, task_id? }].\n  actions                   Json?\n  milestone_id              String?\n  created_at                DateTime          @default(now())\n  updated_at                DateTime          @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, type])\n  @@map(\"project_reviews\")\n}\n\n// --- Resources ------------------------------------------------------------------------\n\n/// 05 §51 — planned allocation (the plan). Availability is 10; actuals are 18.\nmodel ProjectAllocation {\n  id                 String    @id @default(uuid())\n  project_id         String\n  membership_id      String?\n  team_id            String?\n  role_label         String?\n  workstream_id      String?\n  milestone_id       String?\n  planned_hours      Decimal?  @db.Decimal(10, 2)\n  allocation_percent Int?\n  start_date         DateTime? @db.Date\n  end_date           DateTime? @db.Date\n  notes              String?\n  created_at         DateTime  @default(now())\n  updated_at         DateTime  @updatedAt\n\n  project    Project            @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  membership Membership?        @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  team       Team?              @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  workstream ProjectWorkstream? @relation(fields: [workstream_id], references: [id], onDelete: SetNull)\n  milestone  ProjectMilestone?  @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n\n  @@index([project_id])\n  @@index([membership_id, start_date, end_date])\n  @@map(\"project_allocations\")\n}\n\n/// 05 §92 — reusable checklists (kickoff, discovery, development, QA, launch, handover, closeout).\nmodel ProjectChecklist {\n  id         String   @id @default(uuid())\n  project_id String\n  name       String\n  /// kickoff | discovery | development | qa | launch | handover | closeout | custom\n  phase      String?\n  sort_order Int      @default(0)\n  created_at DateTime @default(now())\n\n  project Project                @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  items   ProjectChecklistItem[]\n\n  @@index([project_id])\n  @@map(\"project_checklists\")\n}\n\nmodel ProjectChecklistItem {\n  id                         String    @id @default(uuid())\n  checklist_id               String\n  title                      String\n  is_required                Boolean   @default(false)\n  is_completed               Boolean   @default(false)\n  completed_by_membership_id String?\n  completed_at               DateTime?\n  /// Task created from this item (06).\n  task_id                    String?\n  sort_order                 Int       @default(0)\n\n  checklist ProjectChecklist @relation(fields: [checklist_id], references: [id], onDelete: Cascade)\n  task      Task?            @relation(fields: [task_id], references: [id], onDelete: SetNull)\n\n  @@index([checklist_id])\n  @@map(\"project_checklist_items\")\n}\n\n// --- Governance & closeout -------------------------------------------------------------\n\n/// 05 §101\nmodel ProjectEscalation {\n  id                         String           @id @default(uuid())\n  project_id                 String\n  issue_summary              String\n  /// blocker | delay | budget | scope | customer | resources | contract\n  category                   String?\n  severity                   Severity         @default(HIGH)\n  status                     EscalationStatus @default(OPEN)\n  owner_membership_id        String?\n  escalated_to_membership_id String?\n  escalated_at               DateTime         @default(now())\n  action_taken               String?\n  resolution                 String?\n  resolved_at                DateTime?\n  issue_id                   String?\n  created_at                 DateTime         @default(now())\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, status])\n  @@map(\"project_escalations\")\n}\n\n/// 05 §72, §102 — handovers between teams or to maintenance / support / customer success.\nmodel ProjectHandover {\n  id                        String         @id @default(uuid())\n  project_id                String\n  /// sales_to_delivery | delivery_to_support | development_to_qa | qa_to_customer | project_to_maintenance | custom\n  type                      String\n  from_team_id              String?\n  to_team_id                String?\n  new_owner_membership_id   String?\n  status                    HandoverStatus @default(PLANNED)\n  scheduled_at              DateTime?\n  completed_at              DateTime?\n  /// Checklist, documentation ids (17), open items, support references, contacts, notes.\n  details                   Json?\n  accepted_by_membership_id String?\n  accepted_at               DateTime?\n  created_at                DateTime       @default(now())\n  updated_at                DateTime       @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, status])\n  @@map(\"project_handovers\")\n}\n\n/// 05 §71, §103 — completion checklist state and closeout record.\nmodel ProjectCloseout {\n  project_id                      String    @id\n  /// Completion requirement results (05 §71): [{ key, label, required, satisfied, note }].\n  completion_checklist            Json?\n  final_status_summary            String?\n  outstanding_items               String?\n  lessons_learned                 String?\n  customer_outcome                String?\n  /// Financial review reference (08/09); id only.\n  financial_review_ref            String?\n  documentation_document_ids      String[]  @default([])\n  customer_acceptance_recorded_at DateTime?\n  closed_by_membership_id         String?\n  closed_at                       DateTime?\n  updated_at                      DateTime  @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@map(\"project_closeouts\")\n}\n\n/// 05 §105 — non-hierarchical relationships between projects (parent/child uses parent_project_id).\nmodel ProjectRelation {\n  id                String              @id @default(uuid())\n  source_project_id String\n  target_project_id String\n  type              ProjectRelationType @default(RELATED)\n  notes             String?\n  created_at        DateTime            @default(now())\n\n  source Project @relation(\"ProjectRelationSource\", fields: [source_project_id], references: [id], onDelete: Cascade)\n  target Project @relation(\"ProjectRelationTarget\", fields: [target_project_id], references: [id], onDelete: Cascade)\n\n  @@unique([source_project_id, target_project_id, type])\n  @@index([target_project_id])\n  @@map(\"project_relations\")\n}\n\n/// 05 §86 — references to external systems (GitHub, GitLab, Jira, Linear, deployment, cloud, docs).\nmodel ProjectExternalReference {\n  id          String   @id @default(uuid())\n  project_id  String\n  /// github | gitlab | jira | linear | notion | google_drive | microsoft_365 | deployment | cloud | other\n  system      String\n  label       String?\n  external_id String?\n  url         String?\n  metadata    Json?\n  created_at  DateTime @default(now())\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@index([project_id, system])\n  @@map(\"project_external_references\")\n}\n\n/// 05 §18, §47, 07 §7 — one customer (or internal) decision on a submitted deliverable: the queryable approval\n/// history behind \"approve / request revisions / reject with comments\". ProjectDeliverable.acceptance_record keeps\n/// only the final acceptance evidence.\nmodel ProjectDeliverableReview {\n  id                     String            @id @default(uuid())\n  organization_id        String\n  deliverable_id         String\n  /// Decision taken; the deliverable's status is set to this value.\n  decision               DeliverableStatus\n  comment                String?\n  /// Customer Portal User (01 §79) when decided through the portal.\n  reviewer_user_id       String?\n  reviewer_membership_id String?\n  /// Document version ids (17) that were reviewed, for traceability of which submission was decided.\n  document_version_ids   String[]          @default([])\n  decided_at             DateTime          @default(now())\n\n  organization Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  deliverable  ProjectDeliverable @relation(fields: [deliverable_id], references: [id], onDelete: Cascade)\n  reviewer     Membership?        @relation(\"ProjectDeliverableReviewer\", fields: [reviewer_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([deliverable_id, decided_at])\n  @@index([organization_id])\n  @@map(\"project_deliverable_reviews\")\n}\n\n/// 05 §39, 07 §4 — comments on a published status update by customers (Customer Portal Users, 01 §79) or members.\nmodel ProjectStatusUpdateComment {\n  id                   String    @id @default(uuid())\n  organization_id      String\n  status_update_id     String\n  author_membership_id String?\n  /// Customer Portal User (01 §79) when written from the portal.\n  author_user_id       String?\n  body                 String\n  edited_at            DateTime?\n  deleted_at           DateTime?\n  created_at           DateTime  @default(now())\n\n  organization  Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  status_update ProjectStatusUpdate @relation(fields: [status_update_id], references: [id], onDelete: Cascade)\n  author        Membership?         @relation(\"ProjectStatusUpdateCommentAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([status_update_id, created_at])\n  @@index([organization_id])\n  @@map(\"project_status_update_comments\")\n}\n\n// =====================================================================\n// 06 Task Management — docs/features/06-task-management.md (LOG-102)\n// Owns: the only Task entity, task statuses/workflows, task types, labels, cycles, dependencies,\n// assignees, watchers, checklists, comments, attachments, polymorphic links to other records,\n// Releases and deployments. \"Issue\" in the UI means Task.\n// Does not own: Projects/Milestones/Workstreams (05), time entries (18), documents (17),\n// conversations (12), tickets (13), recurrence schedules (20). Referenced by id only.\n// Task activity, version history and audit log are written to audit_events.\n// =====================================================================\n\n/// 06 §3 — semantic category of a configurable task status.\nenum TaskStatusCategory {\n  BACKLOG\n  TODO\n  IN_PROGRESS\n  IN_REVIEW\n  BLOCKED\n  DONE\n  CANCELLED\n}\n\n/// 06 §3\nenum TaskPriority {\n  NONE\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\n/// 06 §3 — task-to-task dependency kinds.\nenum TaskDependencyType {\n  BLOCKS\n  RELATED\n  DUPLICATE_OF\n}\n\n/// 06 §4 — cycles / sprints.\nenum CycleStatus {\n  PLANNED\n  ACTIVE\n  COMPLETED\n  CANCELLED\n}\n\n/// 06 §9\nenum ReleaseStatus {\n  PLANNED\n  IN_PROGRESS\n  RELEASED\n  CANCELLED\n}\n\nenum DeploymentStatus {\n  PENDING\n  IN_PROGRESS\n  SUCCEEDED\n  FAILED\n  ROLLED_BACK\n}\n\n/// 06 §7 — comment visibility.\nenum TaskCommentVisibility {\n  INTERNAL\n  CUSTOMER_VISIBLE\n}\n\n// --- Configuration ----------------------------------------------------------------\n\n/// 06 §3 — configurable statuses with workflow transitions. Scoped to a Team when team_id is set,\n/// otherwise organization-wide.\nmodel TaskStatus {\n  id                  String             @id @default(uuid())\n  organization_id     String\n  team_id             String?\n  /// 06 §3 — scope the workflow to a Project Type (05 §11) instead of / in addition to a Team; null = not type-specific.\n  project_type_id     String?\n  name                String\n  slug                String\n  category            TaskStatusCategory\n  color               String?\n  sort_order          Int                @default(0)\n  is_default          Boolean            @default(false)\n  /// Slugs this status may transition to; empty = any.\n  allowed_transitions String[]           @default([])\n  archived_at         DateTime?\n  created_at          DateTime           @default(now())\n\n  organization Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team         Team?               @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  tasks        Task[]\n  history_from TaskStatusHistory[] @relation(\"TaskStatusHistoryFrom\")\n  history_to   TaskStatusHistory[] @relation(\"TaskStatusHistoryTo\")\n  project_type ProjectType?        @relation(fields: [project_type_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, team_id, project_type_id, slug])\n  @@index([project_type_id])\n  @@index([organization_id, category])\n  @@map(\"task_statuses\")\n}\n\n/// 06 §3 — task types (task, bug, feature, improvement, chore, follow-up …).\nmodel TaskType {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  icon            String?\n  color           String?\n  is_default      Boolean   @default(false)\n  /// Default field values and checklist for tasks of this type (06 §3 templates).\n  template        Json?\n  sort_order      Int       @default(0)\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  tasks        Task[]\n\n  @@unique([organization_id, slug])\n  @@map(\"task_types\")\n}\n\n/// 06 §3 — Linear-style labels. Platform tags (02 §36) also apply to tasks.\nmodel TaskLabel {\n  id              String    @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  color           String?\n  /// Optional parent for label groups.\n  parent_label_id String?\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n\n  organization Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent       TaskLabel?            @relation(\"TaskLabelGroup\", fields: [parent_label_id], references: [id], onDelete: SetNull)\n  children     TaskLabel[]           @relation(\"TaskLabelGroup\")\n  assignments  TaskLabelAssignment[]\n\n  @@unique([organization_id, slug])\n  @@map(\"task_labels\")\n}\n\n/// 06 §4 — cycles / sprints, per team or project.\nmodel Cycle {\n  id              String      @id @default(uuid())\n  organization_id String\n  team_id         String?\n  project_id      String?\n  number          Int\n  name            String?\n  goal            String?\n  status          CycleStatus @default(PLANNED)\n  starts_at       DateTime    @db.Date\n  ends_at         DateTime    @db.Date\n  completed_at    DateTime?\n  created_at      DateTime    @default(now())\n  updated_at      DateTime    @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  project      Project?     @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  tasks        Task[]\n\n  @@unique([organization_id, team_id, number])\n  @@index([organization_id, status])\n  @@map(\"cycles\")\n}\n\n// --- Task ---------------------------------------------------------------------------\n\n/// 06 §1, §3, §6, §12 — the Task record (full-text search over title/description, inline editing). Work hierarchy: Organization → Team → Project → Workstream/Milestone →\n/// Task → Subtask. Project is optional for personal and CRM work.\nmodel Task {\n  id                         String                   @id @default(uuid())\n  organization_id            String\n  /// Sequential per organization; shown with the team key (e.g. ENG-123).\n  number                     Int\n  team_id                    String?\n  /// 06 §2 — project context consumed from 05 (project, workstream, milestone); all optional.\n  project_id                 String?\n  workstream_id              String?\n  milestone_id               String?\n  parent_task_id             String?\n  cycle_id                   String?\n  release_id                 String?\n  type_id                    String?\n  status_id                  String?\n  title                      String\n  /// Markdown body.\n  description                String?\n  priority                   TaskPriority             @default(NONE)\n  assignee_membership_id     String?\n  reporter_membership_id     String?\n  estimate_points            Decimal?                 @db.Decimal(6, 2)\n  estimate_hours             Decimal?                 @db.Decimal(8, 2)\n  start_date                 DateTime?                @db.Date\n  due_date                   DateTime?                @db.Date\n  completed_at               DateTime?\n  cancelled_at               DateTime?\n  /// Acceptance criteria as a checklist-like list: [{ text, done }].\n  acceptance_criteria        Json?\n  /// Visible in the Customer Portal (05 §60, 07 §4).\n  customer_visible           Boolean                  @default(false)\n  /// Recurring task instance: schedule rule lives in the Automation Engine (20); the template task is linked.\n  automation_rule_id         String?\n  recurring_template_task_id String?\n  is_template                Boolean                  @default(false)\n  /// Lexicographic rank for manual ordering in boards/backlog.\n  rank                       String?\n  /// Duplicate detection target (06 §3).\n  duplicate_of_task_id       String?\n  blocked                    Boolean                  @default(false)\n  /// 06 §3, §10 — why the task is blocked (shown in workload bottleneck detection).\n  blocked_reason             String?\n  /// 06 §3, §11 — cached actual effort rolled up from approved time entries (18 §8); 18 is the source of truth.\n  actual_hours               Decimal?                 @db.Decimal(8, 2)\n  /// 06 §3 — task created by cloning this task (clone lineage).\n  cloned_from_task_id        String?\n  archived_at                DateTime?\n  created_by_user_id         String?\n  created_at                 DateTime                 @default(now())\n  updated_at                 DateTime                 @updatedAt\n  /// 06 §6 — Postgres full-text search vector over title + description; maintained by a database trigger (see migration). Not set by the API.\n  search_vector              Unsupported(\"tsvector\")?\n\n  organization        Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team                Team?              @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  project             Project?           @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  workstream          ProjectWorkstream? @relation(fields: [workstream_id], references: [id], onDelete: SetNull)\n  milestone           ProjectMilestone?  @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n  parent              Task?              @relation(\"TaskHierarchy\", fields: [parent_task_id], references: [id], onDelete: SetNull)\n  subtasks            Task[]             @relation(\"TaskHierarchy\")\n  cycle               Cycle?             @relation(fields: [cycle_id], references: [id], onDelete: SetNull)\n  release             Release?           @relation(fields: [release_id], references: [id], onDelete: SetNull)\n  type                TaskType?          @relation(fields: [type_id], references: [id], onDelete: SetNull)\n  status              TaskStatus?        @relation(fields: [status_id], references: [id], onDelete: SetNull)\n  assignee            Membership?        @relation(\"TaskAssignee\", fields: [assignee_membership_id], references: [id], onDelete: SetNull)\n  reporter            Membership?        @relation(\"TaskReporter\", fields: [reporter_membership_id], references: [id], onDelete: SetNull)\n  recurring_template  Task?              @relation(\"TaskRecurringTemplate\", fields: [recurring_template_task_id], references: [id], onDelete: SetNull)\n  recurring_instances Task[]             @relation(\"TaskRecurringTemplate\")\n  duplicate_of        Task?              @relation(\"TaskDuplicate\", fields: [duplicate_of_task_id], references: [id], onDelete: SetNull)\n  duplicates          Task[]             @relation(\"TaskDuplicate\")\n\n  assignees         TaskAssignee[]\n  labels            TaskLabelAssignment[]\n  dependencies_from TaskDependency[]      @relation(\"TaskDependencySource\")\n  dependencies_to   TaskDependency[]      @relation(\"TaskDependencyTarget\")\n  checklist_items   TaskChecklistItem[]\n  comments          TaskComment[]\n  attachments       TaskAttachment[]\n  links             TaskLink[]\n  watchers          TaskWatcher[]\n  status_history    TaskStatusHistory[]\n\n  // Back-links from other modules' records that reference this task\n  project_issues           ProjectIssue[]\n  project_change_requests  ProjectChangeRequest[]\n  project_checklist_items  ProjectChecklistItem[]\n  contract_obligations     ContractObligation[]\n  ticket_links             TicketTaskLink[]\n  wiki_checklist_run_items WikiChecklistRunItem[]\n  form_submissions         FormSubmission[]\n  time_entries             TimeEntry[]\n  timers                   Timer[]\n  time_suggestions         TimeSuggestion[]\n  automation_rule          AutomationRule?        @relation(\"TaskAutomationRule\", fields: [automation_rule_id], references: [id], onDelete: SetNull)\n\n  @@unique([organization_id, number])\n  @@index([organization_id, status_id])\n  @@index([project_id, status_id])\n  @@index([search_vector], type: Gin)\n  @@index([assignee_membership_id, status_id])\n  @@index([team_id, cycle_id])\n  @@index([parent_task_id])\n  @@index([milestone_id])\n  @@index([due_date])\n  @@map(\"tasks\")\n}\n\n/// 06 §3 — additional assignees beyond the primary assignee.\nmodel TaskAssignee {\n  task_id       String\n  membership_id String\n  assigned_at   DateTime @default(now())\n\n  task       Task       @relation(fields: [task_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([task_id, membership_id])\n  @@index([membership_id])\n  @@map(\"task_assignees\")\n}\n\nmodel TaskLabelAssignment {\n  task_id  String\n  label_id String\n\n  task  Task      @relation(fields: [task_id], references: [id], onDelete: Cascade)\n  label TaskLabel @relation(fields: [label_id], references: [id], onDelete: Cascade)\n\n  @@id([task_id, label_id])\n  @@index([label_id])\n  @@map(\"task_label_assignments\")\n}\n\n/// 06 §3 — blocks / related / duplicates between tasks, including cross-project links.\nmodel TaskDependency {\n  id                 String             @id @default(uuid())\n  source_task_id     String\n  target_task_id     String\n  type               TaskDependencyType @default(BLOCKS)\n  created_by_user_id String?\n  created_at         DateTime           @default(now())\n\n  source Task @relation(\"TaskDependencySource\", fields: [source_task_id], references: [id], onDelete: Cascade)\n  target Task @relation(\"TaskDependencyTarget\", fields: [target_task_id], references: [id], onDelete: Cascade)\n\n  @@unique([source_task_id, target_task_id, type])\n  @@index([target_task_id])\n  @@map(\"task_dependencies\")\n}\n\n/// 06 §3 — checklists inside a task.\nmodel TaskChecklistItem {\n  id                         String    @id @default(uuid())\n  task_id                    String\n  title                      String\n  is_completed               Boolean   @default(false)\n  completed_by_membership_id String?\n  completed_at               DateTime?\n  sort_order                 Int       @default(0)\n\n  task Task @relation(fields: [task_id], references: [id], onDelete: Cascade)\n\n  @@index([task_id])\n  @@map(\"task_checklist_items\")\n}\n\n/// 06 §7 — comments with threads, mentions and reactions. Customer-visible comments surface in 07.\nmodel TaskComment {\n  id                   String                @id @default(uuid())\n  task_id              String\n  parent_comment_id    String?\n  author_membership_id String?\n  /// Customer Portal User (01 §79) when written from the portal; id only.\n  author_user_id       String?\n  visibility           TaskCommentVisibility @default(INTERNAL)\n  body                 String\n  /// Membership ids mentioned.\n  mentions             String[]              @default([])\n  /// { emoji: [membership_id, …] }\n  reactions            Json?\n  edited_at            DateTime?\n  deleted_at           DateTime?\n  created_at           DateTime              @default(now())\n  updated_at           DateTime              @updatedAt\n\n  task    Task          @relation(fields: [task_id], references: [id], onDelete: Cascade)\n  parent  TaskComment?  @relation(\"TaskCommentThread\", fields: [parent_comment_id], references: [id], onDelete: Cascade)\n  replies TaskComment[] @relation(\"TaskCommentThread\")\n  author  Membership?   @relation(\"TaskCommentAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([task_id, created_at])\n  @@index([parent_comment_id])\n  @@map(\"task_comments\")\n}\n\n/// 06 §8 — attachments are Documents (17 §2).\nmodel TaskAttachment {\n  id               String   @id @default(uuid())\n  task_id          String\n  document_id      String\n  added_by_user_id String?\n  created_at       DateTime @default(now())\n\n  task     Task     @relation(fields: [task_id], references: [id], onDelete: Cascade)\n  document Document @relation(fields: [document_id], references: [id], onDelete: Cascade)\n\n  @@unique([task_id, document_id])\n  @@map(\"task_attachments\")\n}\n\n/// 06 §13 — polymorphic link from a task to the record it originated from or serves:\n/// CRM records (02 §14), tickets (13 §4), project change requests (05), customer requests (07),\n/// contract obligations (04 §49), employee onboarding (10).\nmodel TaskLink {\n  id                 String           @id @default(uuid())\n  task_id            String\n  entity_type        RecordEntityType\n  entity_id          String\n  /// origin | related | blocks | fixes\n  relation           String           @default(\"related\")\n  created_by_user_id String?\n  created_at         DateTime         @default(now())\n\n  task Task @relation(fields: [task_id], references: [id], onDelete: Cascade)\n\n  @@unique([task_id, entity_type, entity_id])\n  @@index([entity_type, entity_id])\n  @@map(\"task_links\")\n}\n\n/// 06 §4, §11 — status transition log per task; source for lead time, cycle time, throughput and\n/// time-in-status metrics. Full field-level history stays in audit_events.\nmodel TaskStatusHistory {\n  id                       String              @id @default(uuid())\n  task_id                  String\n  from_status_id           String?\n  to_status_id             String?\n  /// Category snapshot of the target status (statuses can be renamed/deleted later).\n  to_category              TaskStatusCategory?\n  changed_by_membership_id String?\n  /// Seconds spent in the previous status.\n  seconds_in_previous      Int?\n  changed_at               DateTime            @default(now())\n\n  task        Task        @relation(fields: [task_id], references: [id], onDelete: Cascade)\n  from_status TaskStatus? @relation(\"TaskStatusHistoryFrom\", fields: [from_status_id], references: [id], onDelete: SetNull)\n  to_status   TaskStatus? @relation(\"TaskStatusHistoryTo\", fields: [to_status_id], references: [id], onDelete: SetNull)\n\n  @@index([task_id, changed_at])\n  @@index([to_status_id, changed_at])\n  @@map(\"task_status_history\")\n}\n\n/// Members following a task for notifications (14).\nmodel TaskWatcher {\n  task_id       String\n  membership_id String\n  created_at    DateTime @default(now())\n\n  task       Task       @relation(fields: [task_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([task_id, membership_id])\n  @@index([membership_id])\n  @@map(\"task_watchers\")\n}\n\n// --- Releases -----------------------------------------------------------------------\n\n/// 06 §9 — a shippable set of tasks. A Release may map to a Project Milestone (05).\nmodel Release {\n  id                   String        @id @default(uuid())\n  organization_id      String\n  team_id              String?\n  project_id           String?\n  milestone_id         String?\n  name                 String\n  version              String?\n  status               ReleaseStatus @default(PLANNED)\n  target_date          DateTime?     @db.Date\n  released_at          DateTime?\n  /// Release notes (markdown), publishable to the portal (07) and knowledge base (13 §6).\n  notes                String?\n  notes_document_id    String?\n  customer_visible     Boolean       @default(false)\n  /// Customers affected, derived from linked tickets (13 §4); CRM company ids.\n  affected_company_ids String[]      @default([])\n  created_by_user_id   String?\n  created_at           DateTime      @default(now())\n  updated_at           DateTime      @updatedAt\n\n  organization   Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team           Team?               @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  project        Project?            @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  tasks          Task[]\n  deployments    ReleaseDeployment[]\n  notes_document Document?           @relation(\"ReleaseNotesDocument\", fields: [notes_document_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@index([project_id])\n  @@map(\"releases\")\n}\n\n/// 06 §9 — deployment status per environment.\nmodel ReleaseDeployment {\n  id                  String           @id @default(uuid())\n  release_id          String\n  /// development | staging | production | custom\n  environment         String\n  status              DeploymentStatus @default(PENDING)\n  url                 String?\n  deployed_by_user_id String?\n  deployed_at         DateTime?\n  /// External reference (CI run, GitHub deployment id, …).\n  external_ref        String?\n  notes               String?\n  created_at          DateTime         @default(now())\n\n  release Release @relation(fields: [release_id], references: [id], onDelete: Cascade)\n\n  @@index([release_id, environment])\n  @@map(\"release_deployments\")\n}\n\n// =====================================================================\n// 07 Customer Portal — docs/features/07-customer-portal.md (LOG-103)\n// The portal is a surface; identity is 01 §79, requests are 13, billing is 08, documents are 17.\n// Its only schema footprint is per-organization portal configuration.\n// =====================================================================\n\n/// 07 §14, §18 — portal branding, white-label and feature toggles per organization.\nmodel CustomerPortalSettings {\n  organization_id                  String   @id\n  enabled                          Boolean  @default(true)\n  /// Custom domain for the portal (white-label); verified through OrganizationDomain.\n  custom_domain                    String?  @unique\n  /// Branding overrides on top of organization branding (01 §15).\n  branding                         Json?\n  /// Feature toggles: { projects, requests, conversations, documents, proposals, contracts, billing, calendar, vault, ai }.\n  features                         Json?\n  /// Default customer role slug assigned to invited portal users (01 §79).\n  default_role_slug                String   @default(\"customer-viewer\")\n  /// 07 §2 — agency approval policy for customer profile edits; false = changes apply immediately (PortalProfileChangeStatus.AUTO_APPLIED).\n  profile_changes_require_approval Boolean  @default(true)\n  /// Embedded widget configuration (support chat, request form) for customer sites (13 §5).\n  widget_settings                  Json?\n  welcome_message                  String?\n  support_email                    String?\n  updated_at                       DateTime @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"customer_portal_settings\")\n}\n\n/// 07 §2 — review state of a customer-submitted profile change.\nenum PortalProfileChangeStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  AUTO_APPLIED\n}\n\n/// 07 §2 — a customer portal user edits company information or contact details; the write goes to the\n/// CRM Company/Contact (02) subject to the agency approval policy. Holds the proposed diff until reviewed.\nmodel CustomerPortalProfileChangeRequest {\n  id                        String                    @id @default(uuid())\n  organization_id           String\n  company_id                String\n  /// CRM contact being edited, when the change targets a contact rather than the company.\n  contact_id                String?\n  requested_by_user_id      String\n  /// { field: { from, to } } for the Company or Contact record.\n  changes                   Json\n  status                    PortalProfileChangeStatus @default(PENDING)\n  reviewed_by_membership_id String?\n  reviewed_at               DateTime?\n  review_note               String?\n  created_at                DateTime                  @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  company      CrmCompany   @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  contact      CrmContact?  @relation(fields: [contact_id], references: [id], onDelete: Cascade)\n  requested_by User         @relation(\"PortalProfileChangeRequester\", fields: [requested_by_user_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, status])\n  @@index([company_id])\n  @@map(\"customer_portal_profile_change_requests\")\n}\n\n// =====================================================================\n// 08 Financial Management & Payment Providers — docs/features/08-financial-management-stripe-integration.md (LOG-104)\n// Owns: billing profiles and payment methods, the platform products & services catalog, prices,\n// tax rates, coupons, invoices and line items, payments, allocations, refunds, credit notes,\n// subscriptions, dunning, project billing settings, provider webhook idempotency.\n// Boundary: 08 bills and collects; 09 owns the ledger. Every invoice/payment here produces an income\n// record in 09. Quotes are Proposals (03). PDFs are Documents (17). Emails go through 11.\n// =====================================================================\n\n/// 08 \"Products & Services\"\nenum ProductType {\n  SERVICE\n  PACKAGE\n  DEVELOPMENT_HOURS\n  MAINTENANCE_PLAN\n  SUPPORT_PLAN\n  SUBSCRIPTION\n  LICENSE\n  OTHER\n}\n\n/// 08 — one-time vs recurring price.\nenum PriceType {\n  ONE_TIME\n  RECURRING\n}\n\n/// 08 \"Subscription Management\" / \"Recurring Billing\"\nenum BillingInterval {\n  DAY\n  WEEK\n  MONTH\n  QUARTER\n  YEAR\n}\n\n/// 08 \"Taxes & Discounts\"\nenum TaxBehavior {\n  INCLUSIVE\n  EXCLUSIVE\n}\n\nenum DiscountType {\n  PERCENTAGE\n  FIXED\n}\n\nenum CouponDuration {\n  ONCE\n  REPEATING\n  FOREVER\n}\n\n/// 08 \"Invoicing\" — invoice statuses.\nenum InvoiceStatus {\n  DRAFT\n  SCHEDULED\n  OPEN\n  PENDING\n  PAID\n  PARTIALLY_PAID\n  OVERDUE\n  REFUNDED\n  CANCELLED\n  VOID\n}\n\n/// 08 \"Project Billing\"\nenum BillingModel {\n  FIXED_PRICE\n  MILESTONE\n  TIME_AND_MATERIALS\n  RETAINER\n  RECURRING\n  MAINTENANCE\n}\n\n/// 08 \"Payment Providers\" — online providers have an adapter and a PaymentProviderConnection; MANUAL and BANK are\n/// recorded by hand and never have a connection. Adding a provider = a new value here + an adapter (08 spec).\nenum PaymentProvider {\n  STRIPE\n  VIVA_WALLET\n  PAYPAL\n  MOLLIE\n  ADYEN\n  MANUAL\n  BANK\n}\n\n/// 08 \"Payment Providers\"\nenum PaymentProviderConnectionStatus {\n  PENDING\n  ACTIVE\n  ERROR\n  DISCONNECTED\n}\n\n/// 08 \"Payment Providers\" — platform record types mirrored at a provider (PaymentProviderObject.object_type).\nenum ProviderObjectType {\n  CUSTOMER\n  PRODUCT\n  PRICE\n  TAX_RATE\n  COUPON\n}\n\nenum PaymentMethodType {\n  CARD\n  BANK_TRANSFER\n  SEPA_DEBIT\n  CASH\n  CHECK\n  WALLET\n  OTHER\n}\n\nenum PaymentStatus {\n  PENDING\n  PROCESSING\n  SUCCEEDED\n  FAILED\n  CANCELLED\n  REFUNDED\n  PARTIALLY_REFUNDED\n}\n\nenum RefundStatus {\n  PENDING\n  SUCCEEDED\n  FAILED\n  CANCELLED\n}\n\nenum CreditNoteStatus {\n  DRAFT\n  ISSUED\n  APPLIED\n  VOID\n}\n\n/// 08 \"Subscription Management\"\nenum SubscriptionStatus {\n  INCOMPLETE\n  TRIALING\n  ACTIVE\n  PAST_DUE\n  PAUSED\n  CANCELLED\n  EXPIRED\n}\n\nenum CollectionMethod {\n  CHARGE_AUTOMATICALLY\n  SEND_INVOICE\n}\n\n/// 08 \"Recurring Billing\" — dunning step actions.\nenum DunningAction {\n  REMINDER\n  RETRY_PAYMENT\n  NOTIFY_OWNER\n  PAUSE_SUBSCRIPTION\n  CANCEL_SUBSCRIPTION\n  MARK_UNCOLLECTIBLE\n}\n\n// --- Customer billing --------------------------------------------------------------\n\n/// 08 \"Customer Billing\" — billing profile of a Customer (CRM Company, 02). The customer record at each connected\n/// provider is a PaymentProviderObject (object_type CUSTOMER, local_id = this id).\nmodel BillingProfile {\n  id                               String   @id @default(uuid())\n  organization_id                  String\n  company_id                       String\n  legal_name                       String\n  billing_email                    String?\n  /// CRM contact ids with the BILLING role (02 §3).\n  billing_contact_ids              String[] @default([])\n  billing_address                  Json?\n  shipping_address                 Json?\n  tax_id                           String?\n  vat_number                       String?\n  tax_exempt                       Boolean  @default(false)\n  currency                         String\n  /// Net payment terms in days (e.g. 14, 30).\n  payment_terms_days               Int      @default(14)\n  /// 08 \"Recurring Billing\" — dunning policy applied to this customer's invoices; null = organization default policy.\n  dunning_policy_id                String?\n  default_payment_method_id        String?  @unique\n  /// 08 \"Payment Providers\" — connection used for this customer's invoices and subscriptions; null = organization routing.\n  preferred_provider_connection_id String?\n  /// Customer-specific pricing: { product_id: unit_amount } or coupon reference (08 \"Taxes & Discounts\").\n  custom_pricing                   Json?\n  notes                            String?\n  created_at                       DateTime @default(now())\n  updated_at                       DateTime @updatedAt\n\n  organization                  Organization               @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  company                       CrmCompany                 @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  default_payment_method        PaymentMethod?             @relation(\"BillingProfileDefaultMethod\", fields: [default_payment_method_id], references: [id], onDelete: SetNull)\n  payment_methods               PaymentMethod[]\n  invoices                      Invoice[]\n  payments                      Payment[]\n  subscriptions                 Subscription[]\n  credit_notes                  CreditNote[]\n  dunning_policy                DunningPolicy?             @relation(fields: [dunning_policy_id], references: [id], onDelete: SetNull)\n  preferred_provider_connection PaymentProviderConnection? @relation(\"BillingProfilePreferredProvider\", fields: [preferred_provider_connection_id], references: [id], onDelete: SetNull)\n\n  @@unique([organization_id, company_id])\n  @@map(\"billing_profiles\")\n}\n\n/// 08 \"Customer Billing\" — stored payment methods; card data never stored, only provider tokens.\n/// A saved method belongs to one provider connection and can only be charged through it.\nmodel PaymentMethod {\n  id                     String            @id @default(uuid())\n  billing_profile_id     String\n  type                   PaymentMethodType\n  provider               PaymentProvider\n  /// 08 \"Payment Providers\" — connection that holds the token; null for MANUAL / BANK methods.\n  provider_connection_id String?\n  /// Provider token: Stripe payment method, Viva Wallet card token, PayPal vault id, Mollie mandate …\n  provider_method_id     String?\n  brand                  String?\n  last4                  String?\n  exp_month              Int?\n  exp_year               Int?\n  /// Bank details for transfers (IBAN masked, bank name) when provider is BANK.\n  /// Encrypted at the application layer (envelope encryption with the organization VaultKey, 17 §12); never returned in list endpoints.\n  bank_details           Json?\n  is_default             Boolean           @default(false)\n  disabled_at            DateTime?\n  created_at             DateTime          @default(now())\n\n  billing_profile     BillingProfile             @relation(fields: [billing_profile_id], references: [id], onDelete: Cascade)\n  provider_connection PaymentProviderConnection? @relation(fields: [provider_connection_id], references: [id], onDelete: SetNull)\n  default_for         BillingProfile?            @relation(\"BillingProfileDefaultMethod\")\n  payments            Payment[]\n\n  @@unique([provider_connection_id, provider_method_id])\n  @@index([billing_profile_id])\n  @@map(\"payment_methods\")\n}\n\n// --- Catalog --------------------------------------------------------------------------\n\n/// 08 \"Products & Services\" — the platform catalog used by 02 deal line items, 03 proposals and 18 rates.\nmodel Product {\n  id                  String      @id @default(uuid())\n  organization_id     String\n  name                String\n  slug                String\n  type                ProductType @default(SERVICE)\n  description         String?\n  /// Unit label (hour, month, project, seat).\n  unit                String?\n  default_tax_rate_id String?\n  is_active           Boolean     @default(true)\n  archived_at         DateTime?\n  created_at          DateTime    @default(now())\n  updated_at          DateTime    @updatedAt\n\n  organization        Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_tax_rate    TaxRate?           @relation(fields: [default_tax_rate_id], references: [id], onDelete: SetNull)\n  prices              Price[]\n  invoice_line_items  InvoiceLineItem[]\n  subscription_items  SubscriptionItem[]\n  deal_line_items     CrmDealLineItem[]\n  proposal_line_items ProposalLineItem[]\n  billing_rates       BillingRate[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, is_active])\n  @@map(\"products\")\n}\n\n/// 08 — a price of a product: one-time or recurring, per currency.\nmodel Price {\n  id             String           @id @default(uuid())\n  product_id     String\n  name           String?\n  currency       String\n  unit_amount    Decimal          @db.Decimal(18, 2)\n  type           PriceType        @default(ONE_TIME)\n  interval       BillingInterval?\n  interval_count Int?\n  trial_days     Int?\n  /// Setup fee charged on first subscription invoice.\n  setup_fee      Decimal?         @db.Decimal(18, 2)\n  is_active      Boolean          @default(true)\n  created_at     DateTime         @default(now())\n  updated_at     DateTime         @updatedAt\n\n  product            Product            @relation(fields: [product_id], references: [id], onDelete: Cascade)\n  invoice_line_items InvoiceLineItem[]\n  subscription_items SubscriptionItem[]\n\n  @@index([product_id, is_active])\n  @@map(\"prices\")\n}\n\n/// 08 \"Taxes & Discounts\" — tax rates incl. VAT and regional rules.\nmodel TaxRate {\n  id              String      @id @default(uuid())\n  organization_id String\n  name            String\n  percentage      Decimal     @db.Decimal(5, 2)\n  country         String?\n  region          String?\n  behavior        TaxBehavior @default(EXCLUSIVE)\n  is_default      Boolean     @default(false)\n  is_active       Boolean     @default(true)\n  created_at      DateTime    @default(now())\n\n  organization                    Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  products                        Product[]\n  line_items                      InvoiceLineItem[]\n  ledger_settings_income_default  LedgerSettings[]        @relation(\"LedgerSettingsDefaultIncomeTaxRate\")\n  ledger_settings_expense_default LedgerSettings[]        @relation(\"LedgerSettingsDefaultExpenseTaxRate\")\n  ledger_categories               LedgerCategory[]\n  ledger_supplier_profiles        LedgerSupplierProfile[]\n  ledger_records                  LedgerRecord[]\n  recurring_expenses              RecurringExpense[]\n\n  @@index([organization_id, is_active])\n  @@map(\"tax_rates\")\n}\n\n/// 08 \"Taxes & Discounts\" — percentage or fixed discounts, reusable as coupons.\nmodel Coupon {\n  id              String         @id @default(uuid())\n  organization_id String\n  name            String\n  code            String?\n  type            DiscountType\n  value           Decimal        @db.Decimal(18, 2)\n  currency        String?\n  duration        CouponDuration @default(ONCE)\n  duration_months Int?\n  max_redemptions Int?\n  redemptions     Int            @default(0)\n  valid_from      DateTime?\n  valid_until     DateTime?\n  is_active       Boolean        @default(true)\n  created_at      DateTime       @default(now())\n\n  organization  Organization   @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  invoices      Invoice[]\n  subscriptions Subscription[]\n\n  @@unique([organization_id, code])\n  @@map(\"coupons\")\n}\n\n// --- Invoicing ----------------------------------------------------------------------\n\n/// 08 \"Invoicing\" — invoice templates: layout, branding and default texts. Organization branding (01 §15) is the fallback.\nmodel InvoiceTemplate {\n  id                   String    @id @default(uuid())\n  organization_id      String\n  name                 String\n  is_default           Boolean   @default(false)\n  /// Layout key or structure (sections, column visibility, colors).\n  layout               Json?\n  /// Branding overrides: logo_url, primary_color, font.\n  branding             Json?\n  locale               String?\n  default_notes        String?\n  default_footer       String?\n  payment_instructions String?\n  /// Default payment terms in days applied to invoices created with this template.\n  payment_terms_days   Int?\n  archived_at          DateTime?\n  created_at           DateTime  @default(now())\n  updated_at           DateTime  @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  invoices     Invoice[]\n\n  @@unique([organization_id, name])\n  @@map(\"invoice_templates\")\n}\n\n/// 08 \"Invoicing\" — the invoice. Numbering via NumberSequence (INV-2026-0001).\nmodel Invoice {\n  id                                String              @id @default(uuid())\n  organization_id                   String\n  branch_id                         String?\n  number                            String\n  status                            InvoiceStatus       @default(DRAFT)\n  billing_profile_id                String\n  company_id                        String\n  /// Origins (ids with relations where the module exists).\n  project_id                        String?\n  proposal_id                       String?\n  /// 08 \"Proposals & Quotations\" — accepted proposal version (03) this invoice was generated from; permanent link.\n  proposal_version_id               String?\n  /// 08 \"Proposals & Quotations\" — the accepted proposal's payment schedule item (03: deposit, milestone, instalment) this invoice realises; permanent link.\n  proposal_payment_schedule_item_id String?\n  contract_id                       String?\n  subscription_id                   String?\n  /// Revision lineage (08 \"Invoice revisions\").\n  revises_invoice_id                String?             @unique\n  billing_model                     BillingModel?\n  currency                          String\n  issue_date                        DateTime?           @db.Date\n  due_date                          DateTime?           @db.Date\n  /// For recurring/period invoices.\n  period_start                      DateTime?           @db.Date\n  period_end                        DateTime?           @db.Date\n  subtotal                          Decimal             @default(0) @db.Decimal(18, 2)\n  discount_total                    Decimal             @default(0) @db.Decimal(18, 2)\n  tax_total                         Decimal             @default(0) @db.Decimal(18, 2)\n  total                             Decimal             @default(0) @db.Decimal(18, 2)\n  amount_paid                       Decimal             @default(0) @db.Decimal(18, 2)\n  amount_due                        Decimal             @default(0) @db.Decimal(18, 2)\n  coupon_id                         String?\n  collection_method                 CollectionMethod    @default(SEND_INVOICE)\n  /// Accepted payment method types for this invoice.\n  accepted_methods                  PaymentMethodType[] @default([CARD, BANK_TRANSFER])\n  notes                             String?\n  payment_instructions              String?\n  footer                            String?\n  /// Template / branding override; organization branding (01 §15) is the fallback.\n  template_id                       String?\n  /// Generated PDF (17); id only.\n  pdf_document_id                   String?\n  /// 08 \"Payment Providers\" — connection that collects this invoice; null = paid outside a provider (bank transfer, cash).\n  /// Fixed when the invoice is finalized or when the customer starts an online payment (08 routing rules).\n  provider_connection_id            String?\n  /// Invoice object at the provider when it has one (e.g. Stripe invoice); null when the platform issues the invoice itself.\n  provider_invoice_id               String?\n  /// Payment page for the customer: the provider's hosted page or the portal (07) pay link.\n  hosted_invoice_url                String?\n  is_recurring                      Boolean             @default(false)\n  scheduled_send_at                 DateTime?\n  sent_at                           DateTime?\n  paid_at                           DateTime?\n  voided_at                         DateTime?\n  cancelled_at                      DateTime?\n  last_reminder_at                  DateTime?\n  reminder_count                    Int                 @default(0)\n  /// 08 \"Invoicing\" — explicit invoice approval (01 §95); must differ from created_by_user_id (separation of duties, 01 §96). Null = not approved / not required.\n  approved_by_user_id               String?\n  approved_at                       DateTime?\n  created_by_user_id                String?\n  created_at                        DateTime            @default(now())\n  updated_at                        DateTime            @updatedAt\n\n  organization        Organization               @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  provider_connection PaymentProviderConnection? @relation(fields: [provider_connection_id], references: [id], onDelete: SetNull)\n  branch              Branch?                    @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  billing_profile     BillingProfile             @relation(fields: [billing_profile_id], references: [id], onDelete: Restrict)\n  company             CrmCompany                 @relation(fields: [company_id], references: [id], onDelete: Restrict)\n  project             Project?                   @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  contract            Contract?                  @relation(fields: [contract_id], references: [id], onDelete: SetNull)\n  subscription        Subscription?              @relation(fields: [subscription_id], references: [id], onDelete: SetNull)\n  coupon              Coupon?                    @relation(fields: [coupon_id], references: [id], onDelete: SetNull)\n  template            InvoiceTemplate?           @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  revises             Invoice?                   @relation(\"InvoiceRevision\", fields: [revises_invoice_id], references: [id], onDelete: SetNull)\n  revised_by          Invoice?                   @relation(\"InvoiceRevision\")\n\n  line_items                     InvoiceLineItem[]\n  allocations                    PaymentAllocation[]\n  credit_notes                   CreditNote[]\n  reminders                      InvoiceReminder[]\n  proposals                      Proposal[]                   @relation(\"ProposalInvoice\")\n  ledger_record                  LedgerRecord?\n  pdf_document                   Document?                    @relation(\"InvoicePdf\", fields: [pdf_document_id], references: [id], onDelete: SetNull)\n  time_entries                   TimeEntry[]\n  proposal_payment_schedule_item ProposalPaymentScheduleItem? @relation(fields: [proposal_payment_schedule_item_id], references: [id], onDelete: SetNull)\n\n  @@unique([provider_connection_id, provider_invoice_id])\n  @@unique([organization_id, number])\n  @@index([organization_id, status])\n  @@index([company_id, status])\n  @@index([due_date])\n  @@index([project_id])\n  @@index([proposal_payment_schedule_item_id])\n  @@map(\"invoices\")\n}\n\n/// 08 \"Invoicing\" — line items; milestone and time entries link project billing (05 §20, 18 §7).\nmodel InvoiceLineItem {\n  id                String    @id @default(uuid())\n  invoice_id        String\n  product_id        String?\n  price_id          String?\n  description       String\n  quantity          Decimal   @default(1) @db.Decimal(12, 3)\n  unit              String?\n  unit_amount       Decimal   @default(0) @db.Decimal(18, 2)\n  discount_amount   Decimal   @default(0) @db.Decimal(18, 2)\n  tax_rate_id       String?\n  tax_percent       Decimal?  @db.Decimal(5, 2)\n  net_amount        Decimal   @default(0) @db.Decimal(18, 2)\n  tax_amount        Decimal   @default(0) @db.Decimal(18, 2)\n  gross_amount      Decimal   @default(0) @db.Decimal(18, 2)\n  milestone_id      String?\n  /// 08 \"Project Billing\" — write-off (negative) or write-up (positive) applied at invoicing time on top of billable time.\n  adjustment_amount Decimal   @default(0) @db.Decimal(18, 2)\n  adjustment_reason String?\n  period_start      DateTime? @db.Date\n  period_end        DateTime? @db.Date\n  sort_order        Int       @default(0)\n\n  invoice                Invoice               @relation(fields: [invoice_id], references: [id], onDelete: Cascade)\n  product                Product?              @relation(fields: [product_id], references: [id], onDelete: SetNull)\n  price                  Price?                @relation(fields: [price_id], references: [id], onDelete: SetNull)\n  tax_rate               TaxRate?              @relation(fields: [tax_rate_id], references: [id], onDelete: SetNull)\n  milestone              ProjectMilestone?     @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n  time_entries           TimeEntry[]\n  time_entry_adjustments TimeEntryAdjustment[]\n\n  @@index([invoice_id, sort_order])\n  @@map(\"invoice_line_items\")\n}\n\n/// 08 \"Automation\" — reminder / dunning actions sent for an invoice. Delivery is 11/14.\nmodel InvoiceReminder {\n  id                   String        @id @default(uuid())\n  invoice_id           String\n  action               DunningAction @default(REMINDER)\n  /// 08 \"Automation\" — 20 AutomationRun / ScheduledJobRun that produced this reminder (null = sent manually); ids only.\n  automation_run_id    String?\n  scheduled_job_run_id String?\n  /// Days relative to due date (negative = before).\n  offset_days          Int?\n  communication_id     String?\n  sent_at              DateTime      @default(now())\n\n  invoice       Invoice      @relation(fields: [invoice_id], references: [id], onDelete: Cascade)\n  communication CommMessage? @relation(fields: [communication_id], references: [id], onDelete: SetNull)\n\n  @@index([invoice_id, sent_at])\n  @@map(\"invoice_reminders\")\n}\n\n// --- Payments -------------------------------------------------------------------------\n\n/// 08 \"Payments\" — a payment received (online or manually recorded). Allocations split it across invoices.\nmodel Payment {\n  id                     String            @id @default(uuid())\n  organization_id        String\n  billing_profile_id     String?\n  payment_method_id      String?\n  provider               PaymentProvider\n  /// 08 \"Payment Providers\" — connection that processed the payment; null for MANUAL / BANK.\n  provider_connection_id String?\n  /// Provider transaction id (Stripe payment intent, Viva Wallet transaction id, PayPal capture id …).\n  provider_payment_id    String?\n  /// Hosted checkout that started the payment (Stripe Checkout session, Viva Wallet order code, PayPal order id).\n  provider_checkout_id   String?\n  method_type            PaymentMethodType @default(CARD)\n  status                 PaymentStatus     @default(PENDING)\n  currency               String\n  amount                 Decimal           @db.Decimal(18, 2)\n  fee_amount             Decimal           @default(0) @db.Decimal(18, 2)\n  /// 08 \"Payments\" — tax / VAT portion of the amount, for the ledger (09 VAT management).\n  tax_amount             Decimal           @default(0) @db.Decimal(18, 2)\n  net_amount             Decimal?          @db.Decimal(18, 2)\n  refunded_amount        Decimal           @default(0) @db.Decimal(18, 2)\n  /// deposit | milestone | invoice | subscription | one_time\n  kind                   String?\n  reference              String?\n  failure_code           String?\n  failure_message        String?\n  /// Receipt document (17); id only.\n  receipt_document_id    String?\n  received_at            DateTime?\n  recorded_by_user_id    String?\n  metadata               Json?\n  created_at             DateTime          @default(now())\n  updated_at             DateTime          @updatedAt\n\n  organization         Organization               @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  billing_profile      BillingProfile?            @relation(fields: [billing_profile_id], references: [id], onDelete: SetNull)\n  payment_method       PaymentMethod?             @relation(fields: [payment_method_id], references: [id], onDelete: SetNull)\n  provider_connection  PaymentProviderConnection? @relation(fields: [provider_connection_id], references: [id], onDelete: SetNull)\n  allocations          PaymentAllocation[]\n  refunds              Refund[]\n  origin_ledger_record LedgerRecord?              @relation(\"LedgerRecordOriginPayment\")\n  ledger_settlements   LedgerSettlement[]\n  receipt_document     Document?                  @relation(\"PaymentReceipt\", fields: [receipt_document_id], references: [id], onDelete: SetNull)\n\n  @@unique([provider_connection_id, provider_payment_id])\n  @@index([provider_connection_id, provider_checkout_id])\n  @@index([organization_id, status])\n  @@index([billing_profile_id])\n  @@index([received_at])\n  @@map(\"payments\")\n}\n\n/// Partial and multi-invoice payments (08 \"Partial payments\").\nmodel PaymentAllocation {\n  id         String   @id @default(uuid())\n  payment_id String\n  invoice_id String\n  amount     Decimal  @db.Decimal(18, 2)\n  created_at DateTime @default(now())\n\n  payment Payment @relation(fields: [payment_id], references: [id], onDelete: Cascade)\n  invoice Invoice @relation(fields: [invoice_id], references: [id], onDelete: Cascade)\n\n  @@unique([payment_id, invoice_id])\n  @@index([invoice_id])\n  @@map(\"payment_allocations\")\n}\n\n/// 08 \"Payments\" — refunds against a payment.\nmodel Refund {\n  id                   String       @id @default(uuid())\n  payment_id           String\n  provider_refund_id   String?\n  status               RefundStatus @default(PENDING)\n  amount               Decimal      @db.Decimal(18, 2)\n  reason               String?\n  requested_by_user_id String?\n  processed_at         DateTime?\n  created_at           DateTime     @default(now())\n\n  payment            Payment            @relation(fields: [payment_id], references: [id], onDelete: Cascade)\n  ledger_settlements LedgerSettlement[]\n\n  @@unique([payment_id, provider_refund_id])\n  @@index([payment_id])\n  @@map(\"refunds\")\n}\n\n/// 08 \"Invoicing\" — credit notes issued against an invoice. Numbered via NumberSequence.\nmodel CreditNote {\n  id                      String           @id @default(uuid())\n  organization_id         String\n  billing_profile_id      String\n  invoice_id              String?\n  number                  String\n  status                  CreditNoteStatus @default(DRAFT)\n  currency                String\n  subtotal                Decimal          @default(0) @db.Decimal(18, 2)\n  tax_total               Decimal          @default(0) @db.Decimal(18, 2)\n  total                   Decimal          @default(0) @db.Decimal(18, 2)\n  reason                  String?\n  /// Line items mirrored from the invoice: [{ description, quantity, unit_amount, tax_percent, amount }].\n  lines                   Json?\n  pdf_document_id         String?\n  provider_connection_id  String?\n  provider_credit_note_id String?\n  issued_at               DateTime?\n  applied_at              DateTime?\n  voided_at               DateTime?\n  created_by_user_id      String?\n  created_at              DateTime         @default(now())\n\n  organization        Organization               @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  provider_connection PaymentProviderConnection? @relation(fields: [provider_connection_id], references: [id], onDelete: SetNull)\n  billing_profile     BillingProfile             @relation(fields: [billing_profile_id], references: [id], onDelete: Restrict)\n  invoice             Invoice?                   @relation(fields: [invoice_id], references: [id], onDelete: SetNull)\n  pdf_document        Document?                  @relation(\"CreditNotePdf\", fields: [pdf_document_id], references: [id], onDelete: SetNull)\n\n  @@unique([provider_connection_id, provider_credit_note_id])\n  @@unique([organization_id, number])\n  @@index([invoice_id])\n  @@map(\"credit_notes\")\n}\n\n// --- Subscriptions ------------------------------------------------------------------------\n\n/// 08 \"Subscription Management\" — multiple active subscriptions per customer.\nmodel Subscription {\n  id                       String             @id @default(uuid())\n  organization_id          String\n  billing_profile_id       String\n  company_id               String\n  project_id               String?\n  contract_id              String?\n  /// 08 \"Proposals & Quotations\" — accepted proposal version (03) that created this subscription; permanent link.\n  proposal_version_id      String?\n  status                   SubscriptionStatus @default(INCOMPLETE)\n  currency                 String\n  interval                 BillingInterval    @default(MONTH)\n  interval_count           Int                @default(1)\n  collection_method        CollectionMethod   @default(CHARGE_AUTOMATICALLY)\n  coupon_id                String?\n  trial_start              DateTime?\n  trial_end                DateTime?\n  current_period_start     DateTime?\n  current_period_end       DateTime?\n  started_at               DateTime?\n  /// Scheduled cancellation at period end (08 \"Scheduled cancellations\").\n  cancel_at                DateTime?\n  cancel_at_period_end     Boolean            @default(false)\n  cancelled_at             DateTime?\n  cancellation_reason      String?\n  paused_at                DateTime?\n  resume_at                DateTime?\n  ended_at                 DateTime?\n  /// 08 \"Payment Providers\" — connection that charges this subscription.\n  provider_connection_id   String?\n  /// Subscription object at the provider (Stripe, PayPal, Mollie). Null when the platform runs the schedule itself\n  /// (providers without native subscriptions, e.g. Viva Wallet recurring card tokens): 20 creates each invoice and\n  /// charges the saved PaymentMethod.\n  provider_subscription_id String?\n  /// 08 \"Subscription Management\" — one-time setup fee charged on the first invoice; overrides Price.setup_fee for custom (proposal-derived) items.\n  setup_fee                Decimal?           @db.Decimal(18, 2)\n  setup_fee_invoiced_at    DateTime?\n  /// Snapshot of recurring total per period.\n  period_amount            Decimal            @default(0) @db.Decimal(18, 2)\n  metadata                 Json?\n  created_by_user_id       String?\n  created_at               DateTime           @default(now())\n  updated_at               DateTime           @updatedAt\n\n  organization        Organization               @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  provider_connection PaymentProviderConnection? @relation(fields: [provider_connection_id], references: [id], onDelete: SetNull)\n  billing_profile     BillingProfile             @relation(fields: [billing_profile_id], references: [id], onDelete: Restrict)\n  company             CrmCompany                 @relation(fields: [company_id], references: [id], onDelete: Restrict)\n  project             Project?                   @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  contract            Contract?                  @relation(fields: [contract_id], references: [id], onDelete: SetNull)\n  coupon              Coupon?                    @relation(fields: [coupon_id], references: [id], onDelete: SetNull)\n  items               SubscriptionItem[]\n  invoices            Invoice[]\n  proposals           Proposal[]                 @relation(\"ProposalSubscription\")\n  ledger_records      LedgerRecord[]\n\n  @@unique([provider_connection_id, provider_subscription_id])\n  @@index([organization_id, status])\n  @@index([company_id, status])\n  @@index([current_period_end])\n  @@map(\"subscriptions\")\n}\n\n/// 08 — plan lines of a subscription (upgrades/downgrades change items, history in audit_events).\nmodel SubscriptionItem {\n  id               String   @id @default(uuid())\n  subscription_id  String\n  product_id       String?\n  price_id         String?\n  description      String?\n  quantity         Decimal  @default(1) @db.Decimal(12, 3)\n  unit_amount      Decimal  @db.Decimal(18, 2)\n  provider_item_id String?\n  created_at       DateTime @default(now())\n  updated_at       DateTime @updatedAt\n\n  subscription Subscription @relation(fields: [subscription_id], references: [id], onDelete: Cascade)\n  product      Product?     @relation(fields: [product_id], references: [id], onDelete: SetNull)\n  price        Price?       @relation(fields: [price_id], references: [id], onDelete: SetNull)\n\n  @@unique([subscription_id, provider_item_id])\n  @@index([subscription_id])\n  @@map(\"subscription_items\")\n}\n\n/// 08 \"Recurring Billing\" — dunning policy; steps are scheduled by the Automation Engine (20).\nmodel DunningPolicy {\n  id                  String   @id @default(uuid())\n  organization_id     String\n  name                String\n  is_default          Boolean  @default(false)\n  /// [{ offset_days, action: DunningAction, template_key? }], offset relative to due date.\n  steps               Json\n  max_payment_retries Int      @default(3)\n  created_at          DateTime @default(now())\n  updated_at          DateTime @updatedAt\n\n  organization     Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  billing_profiles BillingProfile[]\n\n  @@unique([organization_id, name])\n  @@map(\"dunning_policies\")\n}\n\n/// 08 \"Project Billing\" — how a project is billed (05 §63 consumes the result).\nmodel ProjectBillingSettings {\n  project_id              String           @id\n  billing_model           BillingModel     @default(FIXED_PRICE)\n  currency                String?\n  /// Fixed price / retainer amount per period.\n  fixed_amount            Decimal?         @db.Decimal(18, 2)\n  retainer_interval       BillingInterval?\n  /// Default hourly rate for time and materials; overrides catalog/employee rates.\n  hourly_rate             Decimal?         @db.Decimal(18, 2)\n  /// Default product used for T&M lines.\n  default_product_id      String?\n  /// Create an invoice automatically when a billing milestone completes (05 §20).\n  auto_invoice_milestones Boolean          @default(false)\n  /// Automatically bill approved billable time at period end.\n  auto_invoice_time       Boolean          @default(false)\n  billing_interval        BillingInterval?\n  billing_day             Int?\n  /// Budget alert threshold (percent of budget_amount in 05).\n  budget_alert_percent    Int?\n  updated_at              DateTime         @updatedAt\n\n  project Project @relation(fields: [project_id], references: [id], onDelete: Cascade)\n\n  @@map(\"project_billing_settings\")\n}\n\n/// 08 \"Payment Providers\" — one connected payment provider account of an organization. An organization can connect\n/// several providers (Stripe, Viva Wallet, PayPal …) and several accounts of the same provider (per country, per\n/// branch, test and live). Resolves incoming provider webhooks (ProviderWebhookEvent) to an organization and holds the\n/// per-tenant provider identity; secrets live behind credentials_ref (envelope encryption, 17 §12), never in plain text.\nmodel PaymentProviderConnection {\n  id                        String                          @id @default(uuid())\n  organization_id           String\n  provider                  PaymentProvider\n  /// Label shown to admins and, when several are offered, to customers at checkout (\"Stripe EU\", \"Viva Wallet GR\").\n  display_name              String\n  status                    PaymentProviderConnectionStatus @default(PENDING)\n  /// Provider-side account identifier (Stripe acct_…, Viva Wallet merchant id, PayPal merchant id).\n  provider_account_id       String?\n  /// live | test\n  mode                      String                          @default(\"live\")\n  /// 01 §157 — the organization's own credentials for this provider account (API keys, webhook signing secret). Secrets never live on this row.\n  integration_connection_id String?\n  /// Non-secret provider options (statement descriptor, automatic tax, Viva Wallet source code, checkout branding).\n  config                    Json?\n  /// What the adapter supports for this account, refreshed on connect and on health checks:\n  /// { recurring, saved_methods, refunds, partial_refunds, provider_invoices, provider_subscriptions, payouts }.\n  capabilities              Json?\n  /// Routing (08 \"Payment Providers\"): currencies and method types this connection collects; empty = everything the\n  /// provider supports. Lower priority wins among matching connections; is_default breaks the remaining tie.\n  currencies                String[]                        @default([])\n  method_types              PaymentMethodType[]             @default([])\n  priority                  Int                             @default(100)\n  /// At most one default per organization and mode (enforced by the service).\n  is_default                Boolean                         @default(false)\n  /// 01 §34 — limit the connection to one branch; null = whole organization.\n  branch_id                 String?\n  /// 09 — ledger payment method that payouts and fees of this connection are booked against.\n  ledger_payment_method_id  String?\n  connected_by_user_id      String?\n  connected_at              DateTime?\n  disconnected_at           DateTime?\n  last_checked_at           DateTime?\n  last_error                String?\n  created_at                DateTime                        @default(now())\n  updated_at                DateTime                        @updatedAt\n\n  organization           Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  integration_connection IntegrationConnection?  @relation(fields: [integration_connection_id], references: [id], onDelete: SetNull)\n  branch                 Branch?                 @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  ledger_payment_method  LedgerPaymentMethod?    @relation(fields: [ledger_payment_method_id], references: [id], onDelete: SetNull)\n  provider_objects       PaymentProviderObject[]\n  payment_methods        PaymentMethod[]\n  payments               Payment[]\n  invoices               Invoice[]\n  credit_notes           CreditNote[]\n  subscriptions          Subscription[]\n  preferred_by_profiles  BillingProfile[]        @relation(\"BillingProfilePreferredProvider\")\n  webhook_events         ProviderWebhookEvent[]\n\n  @@unique([provider, provider_account_id, mode])\n  @@index([organization_id, provider])\n  @@index([organization_id, status])\n  @@index([integration_connection_id])\n  @@map(\"payment_provider_connections\")\n}\n\n/// 08 \"Payment Providers\" — the copy of a platform billing record at one provider connection (customer, product,\n/// price, tax rate, coupon). One row per record and connection, so the same product or customer can be synced to\n/// Stripe and Viva Wallet at once. local_id is the id of the BillingProfile / Product / Price / TaxRate / Coupon\n/// named by object_type.\nmodel PaymentProviderObject {\n  id                     String             @id @default(uuid())\n  organization_id        String\n  provider_connection_id String\n  object_type            ProviderObjectType\n  local_id               String\n  provider_object_id     String\n  last_synced_at         DateTime?\n  last_error             String?\n  metadata               Json?\n  created_at             DateTime           @default(now())\n  updated_at             DateTime           @updatedAt\n\n  organization        Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  provider_connection PaymentProviderConnection @relation(fields: [provider_connection_id], references: [id], onDelete: Cascade)\n\n  @@unique([provider_connection_id, object_type, local_id], map: \"payment_provider_objects_connection_local_key\")\n  @@unique([provider_connection_id, object_type, provider_object_id], map: \"payment_provider_objects_connection_remote_key\")\n  @@index([organization_id, object_type, local_id])\n  @@map(\"payment_provider_objects\")\n}\n\n/// Idempotent processing of provider webhooks (payment providers, email/SMS providers; signature providers also use SignatureEvent).\nmodel ProviderWebhookEvent {\n  id                     String    @id @default(uuid())\n  organization_id        String?\n  /// 08 \"Payment Providers\" — payment connection the webhook was verified against; null for non-payment providers.\n  provider_connection_id String?\n  provider               String\n  provider_event_id      String\n  event_type             String\n  payload                Json\n  received_at            DateTime  @default(now())\n  processed_at           DateTime?\n  error                  String?\n\n  organization         Organization?              @relation(fields: [organization_id], references: [id], onDelete: SetNull)\n  provider_connection  PaymentProviderConnection? @relation(fields: [provider_connection_id], references: [id], onDelete: SetNull)\n  comm_delivery_events CommDeliveryEvent[]\n\n  @@unique([provider, provider_event_id])\n  @@index([provider, processed_at])\n  @@map(\"provider_webhook_events\")\n}\n\n// =====================================================================\n// 09 Income & Expense Management — docs/features/09-income-expense-management.md (LOG-105)\n// Owns: the agency ledger — income/expense records (LedgerRecord), settlements against them,\n// ledger categories/subcategories, custom payment methods, supplier ledger profiles, supplier\n// invoice intake (AI/OCR import jobs), recurring expenses, payroll schedules and entries, financial\n// periods, stored period summaries (P&L / VAT / dashboard), project & customer profitability\n// snapshots, AI insights and per-organization ledger settings.\n// Does not own: customer invoices, payments, subscriptions, tax rates (08 — every 08 invoice/payment\n// creates or updates an income record here), customers/vendors (02 CRM companies, type VENDOR = supplier),\n// employees, departments and compensation terms (10), time entries and cost-rate snapshots (18),\n// files (17 Documents, id only), recurrence/job scheduling (20), reminders (14), cost centers\n// (01 §34 — Branch.cost_center_code; ledger records carry branch_id). Change history → audit_events.\n// =====================================================================\n\n/// 09 \"Financial Records\" — income or expense.\nenum LedgerRecordType {\n  INCOME\n  EXPENSE\n}\n\n/// 09 \"Financial Records\", \"Audit Trail\" — record lifecycle. Records are never hard-deleted; VOIDED keeps\n/// the audit history. PENDING_REVIEW is used for imported records awaiting verification and for manual\n/// entries above the approval threshold (LedgerSettings). Voiding or cancelling an 08 invoice voids its\n/// synced record (void_reason = INVOICE_VOIDED); an invoice revision (08 Invoice.revises_invoice_id) creates a\n/// new record for the new invoice row and voids the old one (void_reason = INVOICE_REVISED).\nenum LedgerRecordStatus {\n  DRAFT\n  PENDING_REVIEW\n  POSTED\n  VOIDED\n}\n\n/// 09 \"Manual Financial Entries\", \"Income Management\", \"Automation\" — how a record came into the ledger\n/// (filter \"Manual / Imported\").\nenum LedgerRecordSource {\n  MANUAL\n  INVOICE_SYNC\n  PAYMENT_SYNC\n  SUBSCRIPTION_SYNC\n  SUPPLIER_INVOICE_IMPORT\n  RECURRING_EXPENSE\n  PAYROLL\n  API\n}\n\n/// 09 \"Payment & Settlement Tracking\" — payment status of a ledger record.\nenum LedgerPaymentStatus {\n  UNPAID\n  PARTIALLY_PAID\n  PAID\n  OVERDUE\n  CANCELLED\n  REFUNDED\n}\n\n/// 09 \"VAT Management\" — VAT classification of a record (VAT-exempt, multiple/custom rates).\nenum LedgerVatTreatment {\n  STANDARD\n  REDUCED\n  ZERO_RATED\n  EXEMPT\n  REVERSE_CHARGE\n  OUT_OF_SCOPE\n}\n\n/// 09 \"Payment & Settlement Tracking\" — kinds of settlement lines against a record.\nenum LedgerSettlementKind {\n  PAYMENT\n  REFUND\n  WRITE_OFF\n  ADJUSTMENT\n}\n\n/// 09 \"Attachments & Documentation\"\nenum LedgerAttachmentKind {\n  INVOICE\n  RECEIPT\n  PAYMENT_CONFIRMATION\n  CONTRACT\n  EXPENSE_DOCUMENTATION\n  OTHER\n}\n\n/// 09 \"Financial Categories\" — income vs expense category trees.\nenum LedgerCategoryKind {\n  INCOME\n  EXPENSE\n}\n\n/// 09 \"Profit & Loss\" — P&L line a category rolls up into.\nenum LedgerPlLine {\n  REVENUE\n  COST_OF_OPERATIONS\n  EMPLOYEE_EXPENSES\n  OFFICE_EXPENSES\n  SOFTWARE_EXPENSES\n  MARKETING_EXPENSES\n  PROFESSIONAL_EXPENSES\n  OTHER_OPERATING_EXPENSES\n}\n\n/// 09 \"Invoice Upload & Automatic Processing\" — lifecycle of an AI/OCR import job.\nenum LedgerImportStatus {\n  UPLOADED\n  PROCESSING\n  PENDING_REVIEW\n  APPROVED\n  REJECTED\n  DUPLICATE\n  FAILED\n}\n\n/// 09 \"Recurring Expenses\"\nenum RecurringExpenseStatus {\n  ACTIVE\n  PAUSED\n  ENDED\n  CANCELLED\n}\n\n/// 09 \"Employee Payments & Payroll Expenses\" — kinds of employee-related expense.\nenum PayrollEntryKind {\n  SALARY\n  MONTHLY_PAYMENT\n  HOURLY_PAYMENT\n  BONUS\n  COMMISSION\n  OVERTIME\n  EMPLOYER_COST\n  BENEFIT\n  REIMBURSEMENT\n  OTHER\n}\n\n/// 09 \"Employee Payments & Payroll Expenses\"\nenum PayrollEntryStatus {\n  DRAFT\n  APPROVED\n  POSTED\n  CANCELLED\n}\n\n/// 09 \"Financial Periods\"\nenum FinancialPeriodType {\n  DAY\n  WEEK\n  MONTH\n  QUARTER\n  YEAR\n  CUSTOM\n}\n\n/// 09 \"Financial Periods\" — closed periods reject new postings; locked periods also reject edits.\nenum FinancialPeriodStatus {\n  OPEN\n  CLOSED\n  LOCKED\n}\n\n/// 09 \"Financial Dashboard\" — accrual-based vs actual cash view.\nenum LedgerReportBasis {\n  ACCRUAL\n  CASH\n}\n\n/// 09 \"Project Profitability\" — subject of a profitability snapshot (05 §63, 02 §19).\nenum LedgerProfitabilityScope {\n  PROJECT\n  CUSTOMER\n}\n\n/// 09 \"AI Financial Assistant\" — kinds of stored AI findings.\nenum LedgerInsightKind {\n  UNUSUAL_EXPENSE\n  DUPLICATE_SUSPECTED\n  MISSING_RECORD\n  CATEGORY_SUGGESTION\n  RECURRING_COST_DETECTED\n  FORECAST\n  MONTHLY_SUMMARY\n  OTHER\n}\n\nenum LedgerInsightStatus {\n  OPEN\n  ACCEPTED\n  DISMISSED\n}\n\n// --- Configuration ----------------------------------------------------------------\n\n/// 09 \"VAT Management\", \"Automation\", \"Audit Trail\" — per-organization ledger settings: VAT defaults,\n/// approval thresholds (separation of duties, 01), sync and AI toggles.\nmodel LedgerSettings {\n  organization_id                String      @id\n  /// Reporting currency; falls back to Organization.default_currency (01 §14).\n  reporting_currency             String?\n  /// 09 \"VAT Management\" — default VAT rates (08 tax_rates) for new income / expense records.\n  default_income_tax_rate_id     String?\n  default_expense_tax_rate_id    String?\n  default_pricing_mode           TaxBehavior @default(EXCLUSIVE)\n  /// 09 \"Financial Periods\" — first month of the fiscal year (1–12).\n  fiscal_year_start_month        Int         @default(1)\n  /// 09 \"Audit Trail\" — manual records with gross amount above this need approval by a second member.\n  approval_threshold_amount      Decimal?    @db.Decimal(18, 2)\n  require_approval_for_imports   Boolean     @default(true)\n  /// 09 \"Automation\" toggles.\n  auto_sync_invoices             Boolean     @default(true)\n  auto_sync_payments             Boolean     @default(true)\n  auto_sync_subscriptions        Boolean     @default(true)\n  auto_categorize_suppliers      Boolean     @default(true)\n  duplicate_detection_enabled    Boolean     @default(true)\n  /// Days before a due date to remind administrators (delivered by 14).\n  upcoming_expense_reminder_days Int         @default(7)\n  overdue_check_enabled          Boolean     @default(true)\n  monthly_summary_enabled        Boolean     @default(true)\n  /// 09 \"AI Financial Assistant\"\n  ai_enabled                     Boolean     @default(true)\n  ai_auto_categorize             Boolean     @default(true)\n  updated_at                     DateTime    @updatedAt\n\n  organization             Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_income_tax_rate  TaxRate?     @relation(\"LedgerSettingsDefaultIncomeTaxRate\", fields: [default_income_tax_rate_id], references: [id], onDelete: SetNull)\n  default_expense_tax_rate TaxRate?     @relation(\"LedgerSettingsDefaultExpenseTaxRate\", fields: [default_expense_tax_rate_id], references: [id], onDelete: SetNull)\n\n  @@map(\"ledger_settings\")\n}\n\n/// 09 \"Financial Categories\" — income/expense categories and subcategories (parent_category_id), configurable\n/// by administrators. `system_key` marks seeded defaults; `pl_line` maps the category onto the P&L overview.\nmodel LedgerCategory {\n  id                    String              @id @default(uuid())\n  organization_id       String\n  parent_category_id    String?\n  kind                  LedgerCategoryKind\n  name                  String\n  slug                  String\n  description           String?\n  color                 String?\n  icon                  String?\n  /// Stable key for seeded categories (e.g. office.rent); null for custom ones.\n  system_key            String?\n  /// 09 \"Profit & Loss\" — P&L line this category rolls up into. Inherited from the parent when null.\n  pl_line               LedgerPlLine?\n  /// 09 \"VAT Management\" — default VAT rate (08 tax_rates) applied to new records in this category.\n  default_tax_rate_id   String?\n  default_vat_treatment LedgerVatTreatment?\n  /// 09 \"Financial Dashboard\" — counts toward \"operating expenses\".\n  is_operating          Boolean             @default(true)\n  sort_order            Int                 @default(0)\n  archived_at           DateTime?\n  created_at            DateTime            @default(now())\n  updated_at            DateTime            @updatedAt\n\n  organization     Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent           LedgerCategory?  @relation(\"LedgerCategoryHierarchy\", fields: [parent_category_id], references: [id], onDelete: Restrict)\n  children         LedgerCategory[] @relation(\"LedgerCategoryHierarchy\")\n  default_tax_rate TaxRate?         @relation(fields: [default_tax_rate_id], references: [id], onDelete: SetNull)\n\n  records                 LedgerRecord[]          @relation(\"LedgerRecordCategory\")\n  subcategory_records     LedgerRecord[]          @relation(\"LedgerRecordSubcategory\")\n  recurring_expenses      RecurringExpense[]      @relation(\"RecurringExpenseCategory\")\n  recurring_subcategories RecurringExpense[]      @relation(\"RecurringExpenseSubcategory\")\n  supplier_defaults       LedgerSupplierProfile[]\n  payroll_schedules       PayrollSchedule[]\n  import_suggestions      LedgerInvoiceImport[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, kind])\n  @@index([parent_category_id])\n  @@map(\"ledger_categories\")\n}\n\n/// 09 \"Financial Categories\" — custom payment methods (bank account X, cash, company card, Stripe, Viva Wallet …),\n/// classified by the platform PaymentMethodType (08).\nmodel LedgerPaymentMethod {\n  id              String            @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  type            PaymentMethodType @default(BANK_TRANSFER)\n  /// Masked account details / card label shown in lists.\n  details         Json?\n  is_default      Boolean           @default(false)\n  sort_order      Int               @default(0)\n  archived_at     DateTime?\n  created_at      DateTime          @default(now())\n  updated_at      DateTime          @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  provider_connections PaymentProviderConnection[]\n  records              LedgerRecord[]\n  settlements          LedgerSettlement[]\n  recurring_expenses   RecurringExpense[]\n  payroll_schedules    PayrollSchedule[]\n  payroll_entries      PayrollEntry[]\n\n  @@unique([organization_id, slug])\n  @@map(\"ledger_payment_methods\")\n}\n\n/// 09 \"Expense Management\", \"Automation\" (auto-categorizing known suppliers) — ledger defaults for a supplier.\n/// Suppliers ARE CRM companies of type VENDOR (02 §2a); this profile only adds ledger behaviour, like\n/// BillingProfile (08) does for customers.\nmodel LedgerSupplierProfile {\n  id                    String              @id @default(uuid())\n  organization_id       String\n  company_id            String              @unique\n  default_category_id   String?\n  default_tax_rate_id   String?\n  default_vat_treatment LedgerVatTreatment?\n  default_pricing_mode  TaxBehavior?\n  /// Default payment terms in days (due date = invoice date + N).\n  payment_terms_days    Int?\n  /// Supplier names / VAT numbers / IBANs as they appear on uploaded invoices, used by OCR matching.\n  matching_aliases      String[]            @default([])\n  vat_number            String?\n  /// Supplier's bank details for paying their invoices (IBAN masked in the UI).\n  /// Encrypted at the application layer (envelope encryption with the organization VaultKey, 17 §12); never returned in list endpoints.\n  bank_details          Json?\n  notes                 String?\n  created_at            DateTime            @default(now())\n  updated_at            DateTime            @updatedAt\n\n  organization     Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  company          CrmCompany      @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  default_category LedgerCategory? @relation(fields: [default_category_id], references: [id], onDelete: SetNull)\n  default_tax_rate TaxRate?        @relation(fields: [default_tax_rate_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id])\n  @@map(\"ledger_supplier_profiles\")\n}\n\n// --- Ledger records -----------------------------------------------------------------\n\n/// 09 \"Income & Expense Management\", \"Financial Records\", \"Income Management\", \"Expense Management\", \"Search & Filtering\" — the standardized income/expense record. Income records are created and kept in\n/// sync by 08 invoices/payments/subscriptions (source INVOICE_SYNC / PAYMENT_SYNC / SUBSCRIPTION_SYNC); expenses\n/// come from manual entry, supplier invoice imports, recurring expenses and payroll. Numbered via\n/// NumberSequence (03) — e.g. INC-2026-0001 / EXP-2026-0001. Snapshot columns keep records historically\n/// consistent when categories or suppliers change later (09 \"Financial Periods\").\nmodel LedgerRecord {\n  id                        String              @id @default(uuid())\n  organization_id           String\n  /// Cost center / branch context (01 §34).\n  branch_id                 String?\n  number                    String\n  type                      LedgerRecordType\n  status                    LedgerRecordStatus  @default(POSTED)\n  source                    LedgerRecordSource  @default(MANUAL)\n  /// 09 \"Manual Financial Entries\" — clearly identifies manually created records.\n  is_manual                 Boolean             @default(true)\n  category_id               String?\n  subcategory_id            String?\n  /// Snapshot \"Category / Subcategory\" at posting time.\n  category_path_snapshot    String?\n  description               String\n  /// External reference: supplier invoice number, bank reference, receipt number …\n  reference_number          String?\n  transaction_date          DateTime            @db.Date\n  due_date                  DateTime?           @db.Date\n  /// Date fully paid (cash basis). Partial payments live in LedgerSettlement.\n  payment_date              DateTime?           @db.Date\n  /// Accounting period the record is posted to (set on posting; defaults to the period containing transaction_date).\n  period_id                 String?\n  // 09 \"VAT Management\" — amounts\n  currency                  String\n  /// FX rate to the reporting currency at transaction date; 1 when same currency.\n  fx_rate                   Decimal?            @db.Decimal(18, 6)\n  net_amount                Decimal             @default(0) @db.Decimal(18, 2)\n  vat_percent               Decimal             @default(0) @db.Decimal(5, 2)\n  vat_amount                Decimal             @default(0) @db.Decimal(18, 2)\n  gross_amount              Decimal             @default(0) @db.Decimal(18, 2)\n  /// Gross amount converted to the reporting currency.\n  reporting_gross_amount    Decimal?            @db.Decimal(18, 2)\n  /// 08 tax_rates reference the percentage was taken from; vat_percent is the snapshot.\n  tax_rate_id               String?\n  vat_treatment             LedgerVatTreatment  @default(STANDARD)\n  /// VAT-inclusive vs VAT-exclusive entry (09 \"VAT Management\").\n  pricing_mode              TaxBehavior         @default(EXCLUSIVE)\n  /// True when an authorized user overrode the auto-calculated VAT/gross/net.\n  amounts_overridden        Boolean             @default(false)\n  // 09 \"Payment & Settlement Tracking\"\n  payment_status            LedgerPaymentStatus @default(UNPAID)\n  payment_method_id         String?\n  amount_paid               Decimal             @default(0) @db.Decimal(18, 2)\n  amount_remaining          Decimal             @default(0) @db.Decimal(18, 2)\n  // 09 \"Income Management\" / \"Expense Management\" — counterparty and links\n  /// Customer or supplier (CRM company, 02 §2a).\n  company_id                String?\n  /// Snapshot of the counterparty name at posting time.\n  counterparty_name         String?\n  project_id                String?\n  milestone_id              String?\n  /// 08 invoice that produced this income record: exactly one record per invoice row; a revised invoice is a\n  /// new row and therefore a new record (the superseded record is VOIDED, see LedgerRecordStatus).\n  invoice_id                String?             @unique\n  /// 08 payment that produced this income record when it is not allocated to an invoice (one-off provider/bank/cash payment).\n  origin_payment_id         String?             @unique\n  subscription_id           String?\n  contract_id               String?\n  /// 10 Employee — related employee (employee expenses, payroll); id only.\n  employee_id               String?\n  /// Department = Team of kind DEPARTMENT (01 §43).\n  department_id             String?\n  recurring_expense_id      String?\n  /// 1-based occurrence number within the recurring expense.\n  recurrence_sequence       Int?\n  /// 20 AutomationRule / ScheduledJob that generated the record; id only.\n  automation_run_id         String?\n  notes                     String?\n  /// Line items (description, quantity, unit_price, net, vat, gross) copied from an import or entered manually.\n  line_items                Json?\n  /// 09 \"AI Financial Assistant\" — category suggestion, confidence, anomaly reasons.\n  ai_suggestions            Json?\n  flagged_unusual           Boolean             @default(false)\n  metadata                  Json?\n  // 09 \"Audit Trail\" — actors and lifecycle\n  created_by_membership_id  String?\n  approved_by_membership_id String?\n  approved_at               DateTime?\n  posted_at                 DateTime?\n  voided_at                 DateTime?\n  void_reason               String?\n  /// Soft delete where deletion is permitted; audit history is preserved.\n  deleted_at                DateTime?\n  created_at                DateTime            @default(now())\n  updated_at                DateTime            @updatedAt\n\n  organization      Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch            Branch?              @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  category          LedgerCategory?      @relation(\"LedgerRecordCategory\", fields: [category_id], references: [id], onDelete: SetNull)\n  subcategory       LedgerCategory?      @relation(\"LedgerRecordSubcategory\", fields: [subcategory_id], references: [id], onDelete: SetNull)\n  period            FinancialPeriod?     @relation(fields: [period_id], references: [id], onDelete: SetNull)\n  tax_rate          TaxRate?             @relation(fields: [tax_rate_id], references: [id], onDelete: SetNull)\n  payment_method    LedgerPaymentMethod? @relation(fields: [payment_method_id], references: [id], onDelete: SetNull)\n  company           CrmCompany?          @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  project           Project?             @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  milestone         ProjectMilestone?    @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n  invoice           Invoice?             @relation(fields: [invoice_id], references: [id], onDelete: SetNull)\n  origin_payment    Payment?             @relation(\"LedgerRecordOriginPayment\", fields: [origin_payment_id], references: [id], onDelete: SetNull)\n  subscription      Subscription?        @relation(fields: [subscription_id], references: [id], onDelete: SetNull)\n  contract          Contract?            @relation(fields: [contract_id], references: [id], onDelete: SetNull)\n  recurring_expense RecurringExpense?    @relation(fields: [recurring_expense_id], references: [id], onDelete: SetNull)\n  created_by        Membership?          @relation(\"LedgerRecordCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  approved_by       Membership?          @relation(\"LedgerRecordApprover\", fields: [approved_by_membership_id], references: [id], onDelete: SetNull)\n\n  settlements       LedgerSettlement[]\n  attachments       LedgerAttachment[]\n  import            LedgerInvoiceImport?  @relation(\"LedgerImportRecord\")\n  duplicate_imports LedgerInvoiceImport[] @relation(\"LedgerImportDuplicateRecord\")\n  payroll_entry     PayrollEntry?\n  insights          LedgerInsight[]\n\n  department Team? @relation(\"LedgerRecordDepartment\", fields: [department_id], references: [id], onDelete: SetNull)\n\n  @@unique([organization_id, number])\n  @@index([organization_id, type, transaction_date])\n  @@index([organization_id, status])\n  @@index([organization_id, payment_status])\n  @@index([organization_id, due_date])\n  @@index([organization_id, payment_date])\n  @@index([category_id])\n  @@index([subcategory_id])\n  @@index([company_id])\n  @@index([project_id])\n  @@index([period_id])\n  @@index([employee_id])\n  @@index([recurring_expense_id])\n  @@index([branch_id])\n  @@map(\"ledger_records\")\n}\n\n/// 09 \"Payment & Settlement Tracking\" — one payment/refund/write-off against a record; multiple settlements\n/// per record are allowed. For income synced from 08, settlements mirror PaymentAllocation / Refund.\nmodel LedgerSettlement {\n  id                        String               @id @default(uuid())\n  record_id                 String\n  kind                      LedgerSettlementKind @default(PAYMENT)\n  /// Positive amount; REFUND/WRITE_OFF reduce amount_paid by kind.\n  amount                    Decimal              @db.Decimal(18, 2)\n  currency                  String\n  settled_on                DateTime             @db.Date\n  payment_method_id         String?\n  /// Bank / provider reference (\"Payment reference\").\n  reference                 String?\n  /// 08 payment this settlement mirrors (allocation of a customer payment).\n  payment_id                String?\n  /// 08 refund this settlement mirrors.\n  refund_id                 String?\n  /// 17 Document — payment confirmation; id only.\n  document_id               String?\n  notes                     String?\n  recorded_by_membership_id String?\n  created_at                DateTime             @default(now())\n  updated_at                DateTime             @updatedAt\n\n  record         LedgerRecord         @relation(fields: [record_id], references: [id], onDelete: Cascade)\n  payment_method LedgerPaymentMethod? @relation(fields: [payment_method_id], references: [id], onDelete: SetNull)\n  payment        Payment?             @relation(fields: [payment_id], references: [id], onDelete: SetNull)\n  refund         Refund?              @relation(fields: [refund_id], references: [id], onDelete: SetNull)\n  recorded_by    Membership?          @relation(\"LedgerSettlementRecorder\", fields: [recorded_by_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([record_id, settled_on])\n  @@index([payment_id])\n  @@index([refund_id])\n  @@map(\"ledger_settlements\")\n}\n\n/// 09 \"Attachments & Documentation\" — supporting documents of a record. Files are Documents (17); the\n/// original uploaded supplier invoice is flagged is_original and kept for auditing.\nmodel LedgerAttachment {\n  id                     String               @id @default(uuid())\n  record_id              String\n  /// 17 Document; id only.\n  document_id            String\n  kind                   LedgerAttachmentKind @default(OTHER)\n  /// The original uploaded document the record was created from (09 \"Invoice Upload & Automatic Processing\").\n  is_original            Boolean              @default(false)\n  title                  String?\n  added_by_membership_id String?\n  created_at             DateTime             @default(now())\n\n  record LedgerRecord @relation(fields: [record_id], references: [id], onDelete: Cascade)\n\n  @@unique([record_id, document_id])\n  @@index([document_id])\n  @@map(\"ledger_attachments\")\n}\n\n// --- Supplier invoice intake (AI/OCR) ---------------------------------------------------\n\n/// 09 \"Invoice Upload & Automatic Processing\" — an uploaded supplier invoice / receipt and its AI/OCR extraction.\n/// Extracted values are editable during review; on approval a LedgerRecord is created and linked.\n/// Duplicate detection uses file_hash plus supplier + invoice number + amount (09 \"Automation\").\nmodel LedgerInvoiceImport {\n  id                        String             @id @default(uuid())\n  organization_id           String\n  /// 17 Document — the uploaded file; id only.\n  document_id               String\n  file_name                 String?\n  /// SHA-256 of the uploaded file for exact-duplicate detection.\n  file_hash                 String?\n  status                    LedgerImportStatus @default(UPLOADED)\n  /// Expected record type; defaults to EXPENSE for supplier invoices, INCOME for external income documents.\n  record_type               LedgerRecordType   @default(EXPENSE)\n  uploaded_by_membership_id String?\n  // Extraction results (09 \"Invoice Upload & Automatic Processing\" list)\n  /// Full raw extraction payload from the AI/OCR provider.\n  extraction_raw            Json?\n  /// Extraction provider / model identifier.\n  extraction_provider       String?\n  /// Overall confidence 0–100.\n  confidence                Decimal?           @db.Decimal(5, 2)\n  /// Per-field confidences: { field: 0–100 }.\n  field_confidence          Json?\n  supplier_name             String?\n  supplier_vat_number       String?\n  customer_name             String?\n  /// CRM company matched from supplier/customer data (02 §2a); confirmed in review.\n  matched_company_id        String?\n  suggested_category_id     String?\n  invoice_number            String?\n  invoice_date              DateTime?          @db.Date\n  due_date                  DateTime?          @db.Date\n  description               String?\n  currency                  String?\n  net_amount                Decimal?           @db.Decimal(18, 2)\n  vat_percent               Decimal?           @db.Decimal(5, 2)\n  vat_amount                Decimal?           @db.Decimal(18, 2)\n  gross_amount              Decimal?           @db.Decimal(18, 2)\n  /// Payment information printed on the document: { iban, bank, reference, terms, method }.\n  payment_info              Json?\n  // Review and outcome\n  /// Record created on approval.\n  ledger_record_id          String?            @unique\n  duplicate_of_record_id    String?\n  duplicate_of_import_id    String?\n  reviewed_by_membership_id String?\n  reviewed_at               DateTime?\n  review_notes              String?\n  error                     String?\n  processing_started_at     DateTime?\n  processed_at              DateTime?\n  created_at                DateTime           @default(now())\n  updated_at                DateTime           @updatedAt\n\n  organization        Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  matched_company     CrmCompany?               @relation(fields: [matched_company_id], references: [id], onDelete: SetNull)\n  suggested_category  LedgerCategory?           @relation(fields: [suggested_category_id], references: [id], onDelete: SetNull)\n  ledger_record       LedgerRecord?             @relation(\"LedgerImportRecord\", fields: [ledger_record_id], references: [id], onDelete: SetNull)\n  duplicate_of_record LedgerRecord?             @relation(\"LedgerImportDuplicateRecord\", fields: [duplicate_of_record_id], references: [id], onDelete: SetNull)\n  duplicate_of_import LedgerInvoiceImport?      @relation(\"LedgerImportDuplicateImport\", fields: [duplicate_of_import_id], references: [id], onDelete: SetNull)\n  duplicates          LedgerInvoiceImport[]     @relation(\"LedgerImportDuplicateImport\")\n  uploaded_by         Membership?               @relation(\"LedgerImportUploader\", fields: [uploaded_by_membership_id], references: [id], onDelete: SetNull)\n  reviewed_by         Membership?               @relation(\"LedgerImportReviewer\", fields: [reviewed_by_membership_id], references: [id], onDelete: SetNull)\n  lines               LedgerInvoiceImportLine[]\n\n  @@index([organization_id, status])\n  @@index([organization_id, file_hash])\n  @@index([organization_id, supplier_vat_number, invoice_number])\n  @@index([matched_company_id])\n  @@index([document_id])\n  @@map(\"ledger_invoice_imports\")\n}\n\n/// 09 \"Invoice Upload & Automatic Processing\" — extracted line items (quantities, unit prices), editable in review.\nmodel LedgerInvoiceImportLine {\n  id           String   @id @default(uuid())\n  import_id    String\n  description  String\n  quantity     Decimal  @default(1) @db.Decimal(12, 3)\n  unit_price   Decimal  @default(0) @db.Decimal(18, 2)\n  net_amount   Decimal  @default(0) @db.Decimal(18, 2)\n  vat_percent  Decimal? @db.Decimal(5, 2)\n  vat_amount   Decimal  @default(0) @db.Decimal(18, 2)\n  gross_amount Decimal  @default(0) @db.Decimal(18, 2)\n  confidence   Decimal? @db.Decimal(5, 2)\n  sort_order   Int      @default(0)\n\n  import LedgerInvoiceImport @relation(fields: [import_id], references: [id], onDelete: Cascade)\n\n  @@index([import_id, sort_order])\n  @@map(\"ledger_invoice_import_lines\")\n}\n\n// --- Recurring expenses -----------------------------------------------------------------\n\n/// 09 \"Recurring Expenses\" — template that generates expense records on a schedule (run by 20). Generated\n/// records stay individually editable; editing the template never rewrites past records.\nmodel RecurringExpense {\n  id                       String                 @id @default(uuid())\n  organization_id          String\n  branch_id                String?\n  name                     String\n  description              String?\n  status                   RecurringExpenseStatus @default(ACTIVE)\n  category_id              String?\n  subcategory_id           String?\n  /// Supplier (CRM company, 02 §2a).\n  company_id               String?\n  project_id               String?\n  /// Department = Team of kind DEPARTMENT (01 §43).\n  department_id            String?\n  payment_method_id        String?\n  currency                 String\n  expected_net_amount      Decimal                @db.Decimal(18, 2)\n  vat_percent              Decimal                @default(0) @db.Decimal(5, 2)\n  expected_vat_amount      Decimal                @default(0) @db.Decimal(18, 2)\n  expected_gross_amount    Decimal                @default(0) @db.Decimal(18, 2)\n  tax_rate_id              String?\n  vat_treatment            LedgerVatTreatment     @default(STANDARD)\n  pricing_mode             TaxBehavior            @default(EXCLUSIVE)\n  // Schedule\n  /// MONTH / QUARTER / YEAR, or WEEK/DAY with interval_count for custom recurrence (08 BillingInterval).\n  interval                 BillingInterval        @default(MONTH)\n  interval_count           Int                    @default(1)\n  /// iCalendar RRULE for custom recurrences that interval + interval_count cannot express.\n  custom_rrule             String?\n  start_date               DateTime               @db.Date\n  end_date                 DateTime?              @db.Date\n  /// Day of month the expense falls on (1–31, clamped), when interval is MONTH/QUARTER/YEAR.\n  day_of_month             Int?\n  /// Days after the occurrence date that the generated record is due.\n  due_days                 Int?\n  next_occurrence_date     DateTime?              @db.Date\n  last_generated_at        DateTime?\n  occurrences_generated    Int                    @default(0)\n  /// Generate records automatically (true) or only remind (false).\n  auto_generate            Boolean                @default(true)\n  /// Days before the occurrence to send an upcoming-expense reminder (14); null = organization default.\n  reminder_days_before     Int?\n  /// 20 ScheduledJob registered for this template; id only.\n  scheduled_job_id         String?\n  notes                    String?\n  created_by_membership_id String?\n  paused_at                DateTime?\n  ended_at                 DateTime?\n  created_at               DateTime               @default(now())\n  updated_at               DateTime               @updatedAt\n\n  organization   Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch         Branch?              @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  category       LedgerCategory?      @relation(\"RecurringExpenseCategory\", fields: [category_id], references: [id], onDelete: SetNull)\n  subcategory    LedgerCategory?      @relation(\"RecurringExpenseSubcategory\", fields: [subcategory_id], references: [id], onDelete: SetNull)\n  company        CrmCompany?          @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  project        Project?             @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  payment_method LedgerPaymentMethod? @relation(fields: [payment_method_id], references: [id], onDelete: SetNull)\n  tax_rate       TaxRate?             @relation(fields: [tax_rate_id], references: [id], onDelete: SetNull)\n  records        LedgerRecord[]\n\n  department Team? @relation(\"RecurringExpenseDepartment\", fields: [department_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@index([organization_id, next_occurrence_date])\n  @@index([company_id])\n  @@index([category_id])\n  @@map(\"recurring_expenses\")\n}\n\n// --- Payroll & employee costs -----------------------------------------------------------\n\n/// 09 \"Employee Payments & Payroll Expenses\" — recurring monthly employee payment template (base payment and\n/// employer costs), so the same expense is not recreated by hand each month. Compensation terms themselves\n/// are owned by 10 \"Compensation\" (01 §81); this stores the amounts to post, not the contract.\nmodel PayrollSchedule {\n  id                       String                 @id @default(uuid())\n  organization_id          String\n  /// 10 Employee; id only.\n  employee_id              String\n  /// Department = Team of kind DEPARTMENT (01 §43).\n  department_id            String?\n  kind                     PayrollEntryKind       @default(SALARY)\n  category_id              String?\n  payment_method_id        String?\n  currency                 String\n  /// Employee's base payment per occurrence.\n  base_amount              Decimal                @db.Decimal(18, 2)\n  /// Additional employer-related costs per occurrence (social contributions, insurance, benefits).\n  employer_cost_amount     Decimal                @default(0) @db.Decimal(18, 2)\n  interval                 BillingInterval        @default(MONTH)\n  interval_count           Int                    @default(1)\n  /// Day of month the payment is made.\n  payment_day              Int?\n  start_date               DateTime               @db.Date\n  end_date                 DateTime?              @db.Date\n  next_occurrence_date     DateTime?              @db.Date\n  last_generated_at        DateTime?\n  auto_generate            Boolean                @default(true)\n  status                   RecurringExpenseStatus @default(ACTIVE)\n  /// 20 ScheduledJob; id only.\n  scheduled_job_id         String?\n  notes                    String?\n  created_by_membership_id String?\n  created_at               DateTime               @default(now())\n  updated_at               DateTime               @updatedAt\n\n  organization   Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  category       LedgerCategory?      @relation(fields: [category_id], references: [id], onDelete: SetNull)\n  payment_method LedgerPaymentMethod? @relation(fields: [payment_method_id], references: [id], onDelete: SetNull)\n  entries        PayrollEntry[]\n\n  department Team? @relation(\"PayrollScheduleDepartment\", fields: [department_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@index([organization_id, employee_id])\n  @@index([next_occurrence_date])\n  @@map(\"payroll_schedules\")\n}\n\n/// 09 \"Employee Payments & Payroll Expenses\" — one employee payment / employee cost for an accounting period.\n/// Posting creates the linked expense LedgerRecord (source PAYROLL) so payroll is included in all reporting.\nmodel PayrollEntry {\n  id                        String             @id @default(uuid())\n  organization_id           String\n  /// 10 Employee; id only.\n  employee_id               String\n  /// Snapshot of the employee's display name at posting time.\n  employee_name_snapshot    String?\n  /// Department = Team of kind DEPARTMENT (01 §43).\n  department_id             String?\n  schedule_id               String?\n  period_id                 String?\n  /// Accounting period covered by the payment.\n  period_start              DateTime           @db.Date\n  period_end                DateTime           @db.Date\n  kind                      PayrollEntryKind   @default(SALARY)\n  status                    PayrollEntryStatus @default(DRAFT)\n  currency                  String\n  /// Employee's base payment (net of employer costs).\n  base_amount               Decimal            @db.Decimal(18, 2)\n  /// Employer-related costs on top of the base payment.\n  employer_cost_amount      Decimal            @default(0) @db.Decimal(18, 2)\n  total_amount              Decimal            @default(0) @db.Decimal(18, 2)\n  /// Hourly payments: hours × rate = base_amount.\n  hours                     Decimal?           @db.Decimal(8, 2)\n  hourly_rate               Decimal?           @db.Decimal(18, 2)\n  /// Breakdown of components: [{ kind, label, amount }].\n  breakdown                 Json?\n  description               String?\n  payment_date              DateTime?          @db.Date\n  payment_method_id         String?\n  /// 17 Document — payslip / payment confirmation; id only.\n  document_id               String?\n  /// Expense record created on posting.\n  ledger_record_id          String?            @unique\n  notes                     String?\n  created_by_membership_id  String?\n  approved_by_membership_id String?\n  approved_at               DateTime?\n  posted_at                 DateTime?\n  cancelled_at              DateTime?\n  created_at                DateTime           @default(now())\n  updated_at                DateTime           @updatedAt\n\n  organization   Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  schedule       PayrollSchedule?     @relation(fields: [schedule_id], references: [id], onDelete: SetNull)\n  period         FinancialPeriod?     @relation(fields: [period_id], references: [id], onDelete: SetNull)\n  payment_method LedgerPaymentMethod? @relation(fields: [payment_method_id], references: [id], onDelete: SetNull)\n  ledger_record  LedgerRecord?        @relation(fields: [ledger_record_id], references: [id], onDelete: SetNull)\n  approved_by    Membership?          @relation(\"PayrollEntryApprover\", fields: [approved_by_membership_id], references: [id], onDelete: SetNull)\n\n  department Team? @relation(\"PayrollEntryDepartment\", fields: [department_id], references: [id], onDelete: SetNull)\n\n  @@unique([schedule_id, period_start])\n  @@index([organization_id, employee_id, period_start])\n  @@index([organization_id, status])\n  @@index([period_id])\n  @@map(\"payroll_entries\")\n}\n\n// --- Periods, reports and profitability --------------------------------------------------\n\n/// 09 \"Financial Periods\" — accounting periods (month/quarter/year/custom) that records and payroll entries post to.\n/// Closing a period freezes its summaries; locking prevents edits of posted records.\nmodel FinancialPeriod {\n  id                      String                @id @default(uuid())\n  organization_id         String\n  type                    FinancialPeriodType\n  name                    String\n  fiscal_year             Int?\n  start_date              DateTime              @db.Date\n  end_date                DateTime              @db.Date\n  status                  FinancialPeriodStatus @default(OPEN)\n  closed_by_membership_id String?\n  closed_at               DateTime?\n  locked_at               DateTime?\n  notes                   String?\n  created_at              DateTime              @default(now())\n  updated_at              DateTime              @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  closed_by    Membership?  @relation(\"FinancialPeriodCloser\", fields: [closed_by_membership_id], references: [id], onDelete: SetNull)\n\n  records                 LedgerRecord[]\n  payroll_entries         PayrollEntry[]\n  summaries               FinancialPeriodSummary[]\n  profitability_snapshots LedgerProfitabilitySnapshot[]\n\n  @@unique([organization_id, type, start_date, end_date])\n  @@index([organization_id, status])\n  @@index([organization_id, start_date, end_date])\n  @@map(\"financial_periods\")\n}\n\n/// 09 \"Financial Dashboard\", \"Profit & Loss\", \"VAT Management\" (reporting), \"Automation\" (monthly financial\n/// summaries) — stored totals for a period, per basis (accrual vs cash) and optional scope (branch, project,\n/// customer). `scope_key` is \"org\", \"branch:<id>\", \"project:<id>\" or \"company:<id>\" to keep the unique key non-null.\n/// One row per period x basis: ACCRUAL and CASH are both materialized when a period closes; for open periods the\n/// row is recomputed on demand and refreshed.\nmodel FinancialPeriodSummary {\n  id                   String            @id @default(uuid())\n  organization_id      String\n  period_id            String\n  basis                LedgerReportBasis @default(ACCRUAL)\n  scope_key            String            @default(\"org\")\n  branch_id            String?\n  project_id           String?\n  company_id           String?\n  currency             String\n  // 09 \"Financial Dashboard\" totals\n  total_income         Decimal           @default(0) @db.Decimal(18, 2)\n  total_expenses       Decimal           @default(0) @db.Decimal(18, 2)\n  net_profit           Decimal           @default(0) @db.Decimal(18, 2)\n  gross_income         Decimal           @default(0) @db.Decimal(18, 2)\n  outstanding_income   Decimal           @default(0) @db.Decimal(18, 2)\n  paid_income          Decimal           @default(0) @db.Decimal(18, 2)\n  outstanding_expenses Decimal           @default(0) @db.Decimal(18, 2)\n  paid_expenses        Decimal           @default(0) @db.Decimal(18, 2)\n  vat_collected        Decimal           @default(0) @db.Decimal(18, 2)\n  vat_paid             Decimal           @default(0) @db.Decimal(18, 2)\n  net_vat              Decimal           @default(0) @db.Decimal(18, 2)\n  recurring_expenses   Decimal           @default(0) @db.Decimal(18, 2)\n  payroll_expenses     Decimal           @default(0) @db.Decimal(18, 2)\n  operating_expenses   Decimal           @default(0) @db.Decimal(18, 2)\n  /// [{ category_id, name, amount }]\n  income_by_category   Json?\n  expenses_by_category Json?\n  /// 09 \"Profit & Loss\" — { pl_line: amount } incl. REVENUE … OTHER_OPERATING_EXPENSES, total_expenses, net_operating_result.\n  pl_lines             Json?\n  /// 09 \"VAT Management\" — VAT by category and by counterparty: { by_category: [...], by_company: [...] }.\n  vat_breakdown        Json?\n  /// Cash-flow / trend series inside the period (daily or monthly buckets).\n  trend                Json?\n  /// 09 \"AI Financial Assistant\" — generated management summary for the period.\n  ai_summary           String?\n  generated_at         DateTime          @default(now())\n  /// True once the period is closed; the summary is no longer recalculated.\n  is_final             Boolean           @default(false)\n  created_at           DateTime          @default(now())\n  updated_at           DateTime          @updatedAt\n\n  organization Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  period       FinancialPeriod @relation(fields: [period_id], references: [id], onDelete: Cascade)\n  branch       Branch?         @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n  project      Project?        @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  company      CrmCompany?     @relation(fields: [company_id], references: [id], onDelete: Cascade)\n\n  @@unique([period_id, basis, scope_key])\n  @@index([organization_id, period_id])\n  @@index([project_id])\n  @@index([company_id])\n  @@map(\"financial_period_summaries\")\n}\n\n/// 09 \"Project Profitability\" — stored profitability per project or customer and period. Employee cost comes\n/// from approved time entries and cost-rate snapshots (18 §7). Consumed by 05 §63 and 02 §19; the calculation\n/// is owned here. `subject_id` is the project or company id (unique key); the relation columns mirror it.\nmodel LedgerProfitabilitySnapshot {\n  id                  String                   @id @default(uuid())\n  organization_id     String\n  scope               LedgerProfitabilityScope\n  subject_id          String\n  project_id          String?\n  company_id          String?\n  period_id           String\n  currency            String\n  revenue             Decimal                  @default(0) @db.Decimal(18, 2)\n  payments_received   Decimal                  @default(0) @db.Decimal(18, 2)\n  outstanding_revenue Decimal                  @default(0) @db.Decimal(18, 2)\n  direct_expenses     Decimal                  @default(0) @db.Decimal(18, 2)\n  /// From 18 time entries × cost-rate snapshots.\n  employee_costs      Decimal                  @default(0) @db.Decimal(18, 2)\n  other_expenses      Decimal                  @default(0) @db.Decimal(18, 2)\n  total_cost          Decimal                  @default(0) @db.Decimal(18, 2)\n  gross_profit        Decimal                  @default(0) @db.Decimal(18, 2)\n  margin_percent      Decimal?                 @db.Decimal(5, 2)\n  /// Hours and cost per employee, expenses per category, etc.\n  details             Json?\n  calculated_at       DateTime                 @default(now())\n  created_at          DateTime                 @default(now())\n  updated_at          DateTime                 @updatedAt\n\n  organization Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  project      Project?        @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  company      CrmCompany?     @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  period       FinancialPeriod @relation(fields: [period_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, scope, subject_id, period_id])\n  @@index([project_id])\n  @@index([company_id])\n  @@index([period_id])\n  @@map(\"ledger_profitability_snapshots\")\n}\n\n// --- AI insights ----------------------------------------------------------------------\n\n/// 09 \"AI Financial Assistant\" — stored AI findings surfaced to administrators: unusual/unusually high expenses,\n/// suspected duplicates, missing records, category suggestions, detected recurring costs, forecasts and\n/// monthly summaries. Accepting a CATEGORY_SUGGESTION applies it to the record.\nmodel LedgerInsight {\n  id                        String              @id @default(uuid())\n  organization_id           String\n  kind                      LedgerInsightKind\n  status                    LedgerInsightStatus @default(OPEN)\n  /// 0–100\n  confidence                Decimal?            @db.Decimal(5, 2)\n  /// low | medium | high\n  severity                  String?\n  title                     String\n  body                      String?\n  record_id                 String?\n  /// Structured payload: suggested category_id, compared records, forecast series, period ids …\n  data                      Json?\n  /// Period the insight refers to (forecasts, summaries); id only to keep the unique key simple.\n  period_id                 String?\n  resolved_by_membership_id String?\n  resolved_at               DateTime?\n  expires_at                DateTime?\n  created_at                DateTime            @default(now())\n  updated_at                DateTime            @updatedAt\n\n  organization Organization  @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  record       LedgerRecord? @relation(fields: [record_id], references: [id], onDelete: Cascade)\n  resolved_by  Membership?   @relation(\"LedgerInsightResolver\", fields: [resolved_by_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status, kind])\n  @@index([record_id])\n  @@map(\"ledger_insights\")\n}\n\n// =====================================================================\n// 10 Employee Management System — docs/features/10-employee-management-system.md (LOG-107)\n// Owns: the Employee (HR) record and everything HR: employment details and position history, compensation\n// history, skills/certifications/training/languages, working schedules and availability, leave types/policies/\n// balances/requests, attendance (clock in/out, breaks, summaries), capacity snapshots, performance reviews/goals/\n// feedback/improvement plans, employee documents, visibility-restricted HR notes, self-service change requests.\n// Does not own: identity and login (01 User), Membership/Teams/Departments (Team kind DEPARTMENT)/Branches/branch\n// holidays (01), project membership and planned allocation (05), onboarding tasks (06, linked via TaskLink EMPLOYEE),\n// payroll expense records (09), file storage (17 Document — id only), time entries/utilization actuals (18),\n// calendar events (19 — id only), leave/onboarding workflows (20), notifications (14).\n// Activity and change history is written to audit_events (01).\n// =====================================================================\n\n/// 10 \"Employee Profiles\" — lifecycle state of the employment relationship.\nenum EmploymentStatus {\n  ONBOARDING\n  ACTIVE\n  ON_LEAVE\n  SUSPENDED\n  OFFBOARDING\n  TERMINATED\n}\n\n/// 10 \"Compensation\", \"Employee Profiles\" — employment type.\nenum EmploymentType {\n  FULL_TIME\n  PART_TIME\n  CONTRACTOR\n  INTERN\n}\n\n/// 10 \"Compensation\" — pay type.\nenum EmployeePayType {\n  MONTHLY_SALARY\n  HOURLY\n  DAILY\n  PER_PROJECT\n}\n\n/// 10 \"Compensation\" — employer-side cost and variable pay components on top of base compensation.\nenum CompensationComponentKind {\n  SOCIAL_CONTRIBUTION\n  INSURANCE\n  BENEFIT\n  ALLOWANCE\n  BONUS\n  COMMISSION\n  OTHER\n}\n\n/// 10 \"Compensation\" — how often a compensation component applies.\nenum CompensationFrequency {\n  MONTHLY\n  ANNUAL\n  PER_PAYMENT\n  ONE_OFF\n}\n\n/// 10 \"Roles & Responsibilities\" — seniority level.\nenum EmployeeSeniorityLevel {\n  INTERN\n  JUNIOR\n  MID\n  SENIOR\n  LEAD\n  PRINCIPAL\n  MANAGER\n  DIRECTOR\n  EXECUTIVE\n}\n\n/// 10 \"Roles & Responsibilities\", \"Organization Structure\" — why a position record was created.\nenum EmployeePositionChangeReason {\n  HIRE\n  PROMOTION\n  DEMOTION\n  TRANSFER\n  TITLE_CHANGE\n  MANAGER_CHANGE\n  TYPE_CHANGE\n  REHIRE\n  OTHER\n}\n\n/// 10 \"Attendance & Working Hours\" — default or actual place of work.\nenum EmployeeWorkLocation {\n  OFFICE\n  REMOTE\n  HYBRID\n  CLIENT_SITE\n  TRAVEL\n}\n\n/// 10 \"Employee Availability\" — real-time availability states.\nenum EmployeeAvailabilityStatus {\n  AVAILABLE\n  BUSY\n  ON_LEAVE\n  VACATION\n  SICK_LEAVE\n  PUBLIC_HOLIDAY\n  REMOTE\n  IN_OFFICE\n  TRAINING\n  BUSINESS_TRAVEL\n}\n\n/// 10 \"Employee Availability\" — where an availability entry came from.\nenum EmployeeAvailabilitySource {\n  MANUAL\n  LEAVE\n  HOLIDAY\n  ATTENDANCE\n  CALENDAR\n  SYSTEM\n}\n\n/// 10 \"Attendance & Working Hours\" — schedule model.\nenum EmployeeScheduleType {\n  FIXED\n  FLEXIBLE\n  SHIFT\n}\n\n/// 10 \"Leave Management\" — semantic category of a configurable leave type.\nenum LeaveCategory {\n  VACATION\n  SICK\n  PERSONAL\n  MATERNITY\n  PATERNITY\n  PARENTAL\n  UNPAID\n  PUBLIC_HOLIDAY\n  COMPANY_HOLIDAY\n  TIME_OFF\n  OTHER\n}\n\n/// 10 \"Leave Management\" — how balances accrue under a policy.\nenum LeaveAccrualMethod {\n  NONE\n  ANNUAL_UPFRONT\n  MONTHLY\n  PER_HOURS_WORKED\n}\n\n/// 10 \"Leave Management\" — request lifecycle (approval workflow, 01 §95, 20).\nenum LeaveRequestStatus {\n  DRAFT\n  PENDING\n  APPROVED\n  REJECTED\n  CANCELLED\n  WITHDRAWN\n}\n\n/// 10 \"Leave Management\" — half-day leave.\nenum LeaveDayPart {\n  FULL_DAY\n  FIRST_HALF\n  SECOND_HALF\n}\n\n/// 10 \"Leave Management\" — approval step decision.\nenum LeaveApprovalDecision {\n  PENDING\n  APPROVED\n  REJECTED\n  SKIPPED\n}\n\n/// 10 \"Leave Management\" — balance ledger movements.\nenum LeaveBalanceTransactionType {\n  ACCRUAL\n  USAGE\n  REVERSAL\n  ADJUSTMENT\n  CARRY_OVER\n  EXPIRY\n}\n\n/// 10 \"Leave Management\" — public vs company holidays (branch holidays live in 01 §122).\nenum CompanyHolidayKind {\n  PUBLIC\n  COMPANY\n}\n\n/// 10 \"Attendance & Working Hours\" — state of a daily attendance record.\nenum AttendanceStatus {\n  CLOCKED_IN\n  COMPLETED\n  ABSENT\n  ON_LEAVE\n  HOLIDAY\n  EXCUSED\n}\n\n/// 10 \"Attendance & Working Hours\" — how a clock event was captured.\nenum AttendanceSource {\n  WEB\n  MOBILE\n  MANUAL\n  IMPORT\n  SYSTEM\n}\n\n/// 10 \"Attendance & Working Hours\"\nenum AttendanceBreakKind {\n  PAID\n  UNPAID\n}\n\n/// 10 \"Attendance & Working Hours\", \"Capacity & Workload\" — summary / capacity period granularity.\nenum EmployeePeriodType {\n  DAY\n  WEEK\n  MONTH\n}\n\n/// 10 \"Capacity & Workload\" — classification of a capacity period.\nenum EmployeeCapacityStatus {\n  UNDERUTILIZED\n  BALANCED\n  OVERLOADED\n}\n\n/// 10 \"Performance Management\" — review kinds; ongoing tracking, not only annual.\nenum PerformanceReviewType {\n  ANNUAL\n  SEMI_ANNUAL\n  QUARTERLY\n  PROBATION\n  PROJECT\n  ONE_ON_ONE\n  AD_HOC\n}\n\n/// 10 \"Performance Management\"\nenum PerformanceReviewCycleStatus {\n  PLANNED\n  ACTIVE\n  COMPLETED\n  CANCELLED\n}\n\n/// 10 \"Performance Management\" — review lifecycle.\nenum PerformanceReviewStatus {\n  DRAFT\n  SELF_ASSESSMENT\n  MANAGER_ASSESSMENT\n  SUBMITTED\n  COMPLETED\n  ACKNOWLEDGED\n  CANCELLED\n}\n\n/// 10 \"Performance Management\" — goals and objectives.\nenum PerformanceGoalKind {\n  GOAL\n  OBJECTIVE\n  KEY_RESULT\n}\n\n/// 10 \"Performance Management\"\nenum PerformanceGoalStatus {\n  NOT_STARTED\n  IN_PROGRESS\n  AT_RISK\n  ACHIEVED\n  PARTIALLY_ACHIEVED\n  MISSED\n  CANCELLED\n}\n\n/// 10 \"Performance Management\" — feedback, achievements, recognition and performance notes.\nenum PerformanceFeedbackKind {\n  MANAGER_FEEDBACK\n  EMPLOYEE_FEEDBACK\n  PEER_FEEDBACK\n  PERFORMANCE_NOTE\n  ACHIEVEMENT\n  RECOGNITION\n}\n\n/// 10 \"Performance Management\" — who may read a feedback entry.\nenum PerformanceFeedbackVisibility {\n  MANAGERS_ONLY\n  EMPLOYEE_VISIBLE\n  PUBLIC\n}\n\n/// 10 \"Performance Management\" — improvement plans.\nenum PerformanceImprovementPlanStatus {\n  DRAFT\n  ACTIVE\n  COMPLETED_SUCCESSFUL\n  COMPLETED_UNSUCCESSFUL\n  CANCELLED\n}\n\n/// 10 \"Performance Management\"\nenum PerformanceImprovementItemStatus {\n  OPEN\n  MET\n  NOT_MET\n}\n\n/// 10 \"Skills Management\" — skill catalogue categories.\nenum SkillCategory {\n  TECHNICAL\n  PROGRAMMING_LANGUAGE\n  FRAMEWORK\n  PLATFORM\n  TOOL\n  DOMAIN\n  SOFT_SKILL\n  OTHER\n}\n\n/// 10 \"Skills Management\" — proficiency.\nenum SkillProficiency {\n  BEGINNER\n  INTERMEDIATE\n  ADVANCED\n  EXPERT\n}\n\n/// 10 \"Employee Profiles\" — spoken language proficiency.\nenum LanguageProficiency {\n  BASIC\n  CONVERSATIONAL\n  PROFESSIONAL\n  FLUENT\n  NATIVE\n}\n\n/// 10 \"Skills Management\" — professional training.\nenum EmployeeTrainingStatus {\n  PLANNED\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\n/// 10 \"Employee Documents\" — document categories (storage is 17).\nenum EmployeeDocumentCategory {\n  EMPLOYMENT_CONTRACT\n  NDA\n  CERTIFICATION\n  IDENTIFICATION\n  SIGNED_AGREEMENT\n  HR_FORM\n  RESUME\n  OTHER\n}\n\n/// 10 \"Employee Documents\" — covers \"document requests\" (Notifications) and verification.\nenum EmployeeDocumentStatus {\n  REQUESTED\n  UPLOADED\n  VERIFIED\n  REJECTED\n  EXPIRED\n  ARCHIVED\n}\n\n/// 10 \"Internal Notes\" — note categories.\nenum HrNoteCategory {\n  PERFORMANCE_OBSERVATION\n  MEETING\n  HR_COMMENT\n  WARNING\n  OTHER\n}\n\n/// 10 \"Internal Notes\" — role-based visibility.\nenum HrNoteVisibility {\n  HR_ONLY\n  HR_AND_MANAGERS\n  EMPLOYEE_VISIBLE\n}\n\n/// 10 \"Internal Notes\" — warning severity.\nenum HrNoteSeverity {\n  INFO\n  MINOR\n  MAJOR\n  FINAL\n}\n\n/// 10 \"Employee Self-Service\" — profile change requests.\nenum EmployeeChangeRequestStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  CANCELLED\n}\n\n/// 10 \"Leave Management\" — who approves leave by default (01 §95; workflow in 20).\nenum LeaveApproverStrategy {\n  DIRECT_MANAGER\n  HR\n  MANAGER_THEN_HR\n  CUSTOM\n}\n\n// --- Settings -------------------------------------------------------------------------\n\n/// 10 \"Employee Self-Service\", \"Attendance & Working Hours\", \"Capacity & Workload\", \"Leave Management\" —\n/// organization-wide HR configuration (one row per organization).\nmodel EmployeeHrSettings {\n  organization_id                      String                @id\n  /// Default weekly capacity when an employee has no work schedule.\n  default_weekly_hours                 Decimal               @default(40) @db.Decimal(5, 2)\n  /// [{ weekday, start, end, break_minutes }] default schedule template; falls back to Organization.business_hours.\n  default_schedule                     Json?\n  /// 10 \"Leave Management\" — default approval chain.\n  leave_approver_strategy              LeaveApproverStrategy @default(DIRECT_MANAGER)\n  /// Flag overlapping leave in the same team above this share of members (conflict detection).\n  leave_conflict_threshold_percent     Decimal?              @db.Decimal(5, 2)\n  /// 10 \"Attendance & Working Hours\"\n  attendance_required                  Boolean               @default(false)\n  allowed_clock_sources                AttendanceSource[]    @default([WEB, MOBILE])\n  late_tolerance_minutes               Int                   @default(0)\n  /// Minutes worked beyond the scheduled day that count as overtime.\n  overtime_threshold_minutes           Int                   @default(0)\n  overtime_requires_approval           Boolean               @default(true)\n  /// Pre-fill 18 Time Tracking daily total from attendance (never replaces time entries).\n  prefill_time_entries_from_attendance Boolean               @default(false)\n  /// 10 \"Capacity & Workload\" — utilization thresholds.\n  target_utilization_percent           Decimal               @default(80) @db.Decimal(5, 2)\n  overload_threshold_percent           Decimal               @default(100) @db.Decimal(5, 2)\n  underutilized_threshold_percent      Decimal               @default(60) @db.Decimal(5, 2)\n  /// 10 \"Employee Self-Service\" — employee-editable profile fields and whether edits need approval.\n  self_service_editable_fields         String[]              @default([])\n  profile_changes_require_approval     Boolean               @default(false)\n  /// 10 \"Employee Directory\" — fields shown in the directory.\n  directory_visible_fields             String[]              @default([])\n  /// 10 \"Notifications\" — anniversary / birthday events emitted to 14.\n  notify_birthdays                     Boolean               @default(true)\n  notify_anniversaries                 Boolean               @default(true)\n  updated_at                           DateTime              @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"employee_hr_settings\")\n}\n\n// --- Employee ---------------------------------------------------------------------------\n\n/// 10 \"Employee Profiles\", \"Organization Structure\", \"Roles & Responsibilities\", \"Employee Availability\",\n/// \"Employee Directory\" — the HR record, 1:1 with a Membership (01 §80–81). Identity (name used for login, photo,\n/// locale) stays on User; secondary branches and teams come from MembershipBranch / TeamMembership (01 §35).\n/// Compensation, personal identifiers and bank details are field-level permissioned (01 §60).\nmodel Employee {\n  id                         String                     @id @default(uuid())\n  organization_id            String\n  membership_id              String                     @unique\n  /// Human-readable Employee ID, e.g. EMP-0042 (NumberSequence, 03).\n  employee_number            String\n  // Personal information (10 \"Employee Profiles\")\n  legal_first_name           String?\n  legal_last_name            String?\n  preferred_name             String?\n  date_of_birth              DateTime?                  @db.Date\n  gender                     String?\n  nationality                String?\n  /// Sensitive identifiers (01 §60).\n  national_id_number         String?\n  tax_id                     String?\n  social_security_number     String?\n  /// Sensitive; consumed by 09 payroll.\n  /// Encrypted at the application layer (envelope encryption with the organization VaultKey, 17 §12); never returned in list endpoints.\n  bank_details               Json?\n  // Contact information\n  work_email                 String?\n  work_phone                 String?\n  personal_email             String?\n  personal_phone             String?\n  address                    Json?\n  /// 17 Document — profile photo override; falls back to User.profile_photo_url.\n  photo_document_id          String?\n  /// 17 Document — resume / CV.\n  resume_document_id         String?\n  // Employment details — current values; history in EmployeePosition\n  job_title                  String?\n  /// Position within the structure (e.g. \"Frontend Engineer II\").\n  position                   String?\n  /// Functional role label (10 \"Roles & Responsibilities\").\n  role                       String?\n  seniority_level            EmployeeSeniorityLevel?\n  /// Team of kind DEPARTMENT (01 §43).\n  department_team_id         String?\n  primary_branch_id          String?\n  manager_employee_id        String?\n  employment_status          EmploymentStatus           @default(ONBOARDING)\n  employment_status_since    DateTime?                  @db.Date\n  employment_type            EmploymentType             @default(FULL_TIME)\n  work_location              EmployeeWorkLocation       @default(OFFICE)\n  hire_date                  DateTime?                  @db.Date\n  probation_end_date         DateTime?                  @db.Date\n  /// Fixed-term contract end.\n  contract_end_date          DateTime?                  @db.Date\n  notice_period_days         Int?\n  termination_date           DateTime?                  @db.Date\n  termination_reason         String?\n  /// 10 \"Roles & Responsibilities\" / \"Employee Profiles\" — free-form lists; structured skills in EmployeeSkill.\n  responsibilities           String[]                   @default([])\n  areas_of_expertise         String[]                   @default([])\n  technical_stack            String[]                   @default([])\n  bio                        String?\n  // Availability (10 \"Employee Availability\") — denormalized current state\n  availability_status        EmployeeAvailabilityStatus @default(AVAILABLE)\n  availability_note          String?\n  availability_updated_at    DateTime?\n  // Capacity (10 \"Capacity & Workload\")\n  /// Overrides the active work schedule / HR settings default.\n  weekly_capacity_hours      Decimal?                   @db.Decimal(5, 2)\n  target_utilization_percent Decimal?                   @db.Decimal(5, 2)\n  timezone                   String?\n  // Lifecycle\n  /// Onboarding tasks are Tasks linked via TaskLink(EMPLOYEE) (06 §13); workflows in 20.\n  onboarding_completed_at    DateTime?\n  offboarding_completed_at   DateTime?\n  /// 10 \"Employee Directory\" — hide from the directory (e.g. silent contractors).\n  directory_visible          Boolean                    @default(true)\n  archived_at                DateTime?\n  created_by_user_id         String?\n  created_at                 DateTime                   @default(now())\n  updated_at                 DateTime                   @updatedAt\n\n  organization   Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership     Membership   @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  department     Team?        @relation(\"EmployeeDepartment\", fields: [department_team_id], references: [id], onDelete: SetNull)\n  primary_branch Branch?      @relation(\"EmployeePrimaryBranch\", fields: [primary_branch_id], references: [id], onDelete: SetNull)\n  manager        Employee?    @relation(\"EmployeeManager\", fields: [manager_employee_id], references: [id], onDelete: SetNull)\n  direct_reports Employee[]   @relation(\"EmployeeManager\")\n\n  emergency_contacts      EmployeeEmergencyContact[]\n  positions               EmployeePosition[]             @relation(\"EmployeePositionEmployee\")\n  managed_positions       EmployeePosition[]             @relation(\"EmployeePositionManager\")\n  compensations           EmployeeCompensation[]\n  skills                  EmployeeSkill[]\n  certifications          EmployeeCertification[]\n  trainings               EmployeeTraining[]\n  languages               EmployeeLanguage[]\n  work_schedules          EmployeeWorkSchedule[]\n  availability_entries    EmployeeAvailabilityEntry[]\n  leave_policies          EmployeeLeavePolicy[]\n  leave_balances          LeaveBalance[]\n  leave_requests          LeaveRequest[]                 @relation(\"LeaveRequestEmployee\")\n  covered_leave_requests  LeaveRequest[]                 @relation(\"LeaveRequestCover\")\n  attendance_records      AttendanceRecord[]\n  attendance_summaries    AttendanceSummary[]\n  capacity_periods        EmployeeCapacityPeriod[]\n  performance_reviews     PerformanceReview[]\n  performance_goals       PerformanceGoal[]\n  performance_feedback    PerformanceFeedback[]\n  improvement_plans       PerformanceImprovementPlan[]\n  documents               EmployeeDocument[]\n  hr_notes                EmployeeHrNote[]\n  profile_change_requests EmployeeProfileChangeRequest[]\n\n  @@unique([organization_id, employee_number])\n  @@index([organization_id, employment_status])\n  @@index([organization_id, department_team_id])\n  @@index([organization_id, primary_branch_id])\n  @@index([organization_id, availability_status])\n  @@index([manager_employee_id])\n  @@index([hire_date])\n  @@index([date_of_birth])\n  @@map(\"employees\")\n}\n\n/// 10 \"Employee Profiles\" — emergency contacts.\nmodel EmployeeEmergencyContact {\n  id           String   @id @default(uuid())\n  employee_id  String\n  name         String\n  relationship String?\n  phone        String\n  email        String?\n  address      Json?\n  is_primary   Boolean  @default(false)\n  sort_order   Int      @default(0)\n  created_at   DateTime @default(now())\n  updated_at   DateTime @updatedAt\n\n  employee Employee @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n\n  @@index([employee_id])\n  @@map(\"employee_emergency_contacts\")\n}\n\n/// 10 \"Roles & Responsibilities\", \"Organization Structure\" — effective-dated position history (title, department,\n/// branch, manager, seniority, employment type). The current row is mirrored onto Employee.\nmodel EmployeePosition {\n  id                  String                       @id @default(uuid())\n  employee_id         String\n  job_title           String\n  position            String?\n  role                String?\n  seniority_level     EmployeeSeniorityLevel?\n  employment_type     EmploymentType\n  /// Team of kind DEPARTMENT (01 §43).\n  department_team_id  String?\n  branch_id           String?\n  manager_employee_id String?\n  effective_from      DateTime                     @db.Date\n  effective_to        DateTime?                    @db.Date\n  reason              EmployeePositionChangeReason @default(HIRE)\n  note                String?\n  created_by_user_id  String?\n  created_at          DateTime                     @default(now())\n\n  employee   Employee  @relation(\"EmployeePositionEmployee\", fields: [employee_id], references: [id], onDelete: Cascade)\n  manager    Employee? @relation(\"EmployeePositionManager\", fields: [manager_employee_id], references: [id], onDelete: SetNull)\n  department Team?     @relation(\"EmployeePositionDepartment\", fields: [department_team_id], references: [id], onDelete: SetNull)\n  branch     Branch?   @relation(\"EmployeePositionBranch\", fields: [branch_id], references: [id], onDelete: SetNull)\n\n  @@index([employee_id, effective_from])\n  @@index([department_team_id])\n  @@map(\"employee_positions\")\n}\n\n// --- Compensation -----------------------------------------------------------------------\n\n/// 10 \"Compensation\" — effective-dated compensation record (01 §81 source of truth; 01 §60 field-level permission).\n/// cost_rate_hourly is consumed by 18 Time Tracking; billing_rate_default by 08 and 18. 09 creates payroll\n/// expense records from this data; the expense itself is never stored here.\nmodel EmployeeCompensation {\n  id                        String          @id @default(uuid())\n  employee_id               String\n  effective_from            DateTime        @db.Date\n  effective_to              DateTime?       @db.Date\n  employment_type           EmploymentType\n  pay_type                  EmployeePayType\n  /// Base amount per pay type unit (month, hour, day or project).\n  base_amount               Decimal         @db.Decimal(18, 2)\n  currency                  String\n  /// Sum of employer cost components per month (denormalized from components).\n  employer_cost_monthly     Decimal?        @db.Decimal(18, 2)\n  /// Total monthly employer cost (base + employer costs), used for cost-rate derivation.\n  total_cost_monthly        Decimal?        @db.Decimal(18, 2)\n  /// Hourly cost rate for project costing (18 §7 snapshots this).\n  cost_rate_hourly          Decimal?        @db.Decimal(18, 2)\n  /// Default hourly billing rate (08 catalog / project overrides take precedence).\n  billing_rate_default      Decimal?        @db.Decimal(18, 2)\n  billing_currency          String?\n  /// Contracted hours used when deriving the cost rate for salaried staff.\n  contracted_weekly_hours   Decimal?        @db.Decimal(5, 2)\n  /// Bonus / commission scheme summary (details in components).\n  bonus_scheme              String?\n  commission_scheme         String?\n  reason                    String?\n  notes                     String?\n  approved_by_membership_id String?\n  approved_at               DateTime?\n  created_by_user_id        String?\n  created_at                DateTime        @default(now())\n  updated_at                DateTime        @updatedAt\n\n  employee   Employee                        @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  components EmployeeCompensationComponent[]\n\n  @@index([employee_id, effective_from])\n  @@map(\"employee_compensations\")\n}\n\n/// 10 \"Compensation\" — employer costs (social contributions, insurance, benefits), allowances and bonus /\n/// commission scheme lines. Either a fixed amount or a percentage of base.\nmodel EmployeeCompensationComponent {\n  id               String                    @id @default(uuid())\n  compensation_id  String\n  kind             CompensationComponentKind\n  name             String\n  amount           Decimal?                  @db.Decimal(18, 2)\n  /// Percentage of base compensation when amount is null.\n  percent_of_base  Decimal?                  @db.Decimal(5, 2)\n  currency         String?\n  frequency        CompensationFrequency     @default(MONTHLY)\n  /// Scheme rules for bonus / commission (targets, tiers, triggers).\n  rule             Json?\n  /// Whether the component is paid to the employee (true) or an employer-only cost (false).\n  paid_to_employee Boolean                   @default(false)\n  sort_order       Int                       @default(0)\n  created_at       DateTime                  @default(now())\n\n  compensation EmployeeCompensation @relation(fields: [compensation_id], references: [id], onDelete: Cascade)\n\n  @@index([compensation_id])\n  @@map(\"employee_compensation_components\")\n}\n\n// --- Skills -----------------------------------------------------------------------------\n\n/// 10 \"Skills Management\" — organization skill catalogue (technical skills, languages, frameworks, platforms,\n/// specializations). Searchable for project staffing.\nmodel Skill {\n  id              String        @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String\n  category        SkillCategory @default(TECHNICAL)\n  description     String?\n  parent_skill_id String?\n  archived_at     DateTime?\n  created_at      DateTime      @default(now())\n  updated_at      DateTime      @updatedAt\n\n  organization   Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent         Skill?                  @relation(\"SkillHierarchy\", fields: [parent_skill_id], references: [id], onDelete: SetNull)\n  children       Skill[]                 @relation(\"SkillHierarchy\")\n  employees      EmployeeSkill[]\n  certifications EmployeeCertification[]\n  trainings      EmployeeTraining[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, category])\n  @@map(\"skills\")\n}\n\n/// 10 \"Skills Management\", \"Roles & Responsibilities\" — skill per employee with proficiency, experience and\n/// primary/secondary flag.\nmodel EmployeeSkill {\n  id                        String           @id @default(uuid())\n  employee_id               String\n  skill_id                  String\n  proficiency               SkillProficiency @default(INTERMEDIATE)\n  years_experience          Decimal?         @db.Decimal(4, 1)\n  /// Primary skills vs secondary skills (10 \"Roles & Responsibilities\").\n  is_primary                Boolean          @default(false)\n  last_used_on              DateTime?        @db.Date\n  /// Verified by a manager / HR.\n  verified_by_membership_id String?\n  verified_at               DateTime?\n  notes                     String?\n  created_at                DateTime         @default(now())\n  updated_at                DateTime         @updatedAt\n\n  employee Employee @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  skill    Skill    @relation(fields: [skill_id], references: [id], onDelete: Cascade)\n\n  @@unique([employee_id, skill_id])\n  @@index([skill_id, proficiency])\n  @@map(\"employee_skills\")\n}\n\n/// 10 \"Skills Management\", \"Employee Profiles\" — certifications; the certificate file is a 17 Document.\nmodel EmployeeCertification {\n  id             String    @id @default(uuid())\n  employee_id    String\n  skill_id       String?\n  name           String\n  issuer         String?\n  credential_id  String?\n  credential_url String?\n  issued_on      DateTime? @db.Date\n  expires_on     DateTime? @db.Date\n  /// 17 Document — certificate file.\n  document_id    String?\n  notes          String?\n  created_at     DateTime  @default(now())\n  updated_at     DateTime  @updatedAt\n\n  employee Employee @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  skill    Skill?   @relation(fields: [skill_id], references: [id], onDelete: SetNull)\n\n  @@index([employee_id])\n  @@index([expires_on])\n  @@map(\"employee_certifications\")\n}\n\n/// 10 \"Skills Management\" — professional training records.\nmodel EmployeeTraining {\n  id           String                 @id @default(uuid())\n  employee_id  String\n  skill_id     String?\n  title        String\n  provider     String?\n  /// course | workshop | conference | certification_prep | on_the_job | other\n  kind         String?\n  status       EmployeeTrainingStatus @default(PLANNED)\n  start_date   DateTime?              @db.Date\n  end_date     DateTime?              @db.Date\n  hours        Decimal?               @db.Decimal(8, 2)\n  cost         Decimal?               @db.Decimal(18, 2)\n  currency     String?\n  completed_at DateTime?\n  /// 17 Document — completion certificate / material.\n  document_id  String?\n  notes        String?\n  created_at   DateTime               @default(now())\n  updated_at   DateTime               @updatedAt\n\n  employee Employee @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  skill    Skill?   @relation(fields: [skill_id], references: [id], onDelete: SetNull)\n\n  @@index([employee_id, status])\n  @@map(\"employee_trainings\")\n}\n\n/// 10 \"Employee Profiles\" — spoken languages.\nmodel EmployeeLanguage {\n  id          String              @id @default(uuid())\n  employee_id String\n  /// ISO 639-1 code.\n  language    String\n  proficiency LanguageProficiency @default(PROFESSIONAL)\n  is_primary  Boolean             @default(false)\n  created_at  DateTime            @default(now())\n\n  employee Employee @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n\n  @@unique([employee_id, language])\n  @@map(\"employee_languages\")\n}\n\n// --- Working hours & availability -----------------------------------------------------------\n\n/// 10 \"Attendance & Working Hours\", \"Capacity & Workload\" — effective-dated working schedule (fixed, flexible or\n/// shift). Defines expected hours and therefore capacity. Branch business hours (01 §121) are the fallback.\nmodel EmployeeWorkSchedule {\n  id             String               @id @default(uuid())\n  employee_id    String\n  name           String?\n  schedule_type  EmployeeScheduleType @default(FIXED)\n  effective_from DateTime             @db.Date\n  effective_to   DateTime?            @db.Date\n  timezone       String?\n  weekly_hours   Decimal              @db.Decimal(5, 2)\n  /// Flexible schedules: core hours everyone must be reachable, e.g. { start: \"10:00\", end: \"15:00\" }.\n  core_hours     Json?\n  work_location  EmployeeWorkLocation @default(OFFICE)\n  created_at     DateTime             @default(now())\n  updated_at     DateTime             @updatedAt\n\n  employee Employee                  @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  days     EmployeeWorkScheduleDay[]\n\n  @@index([employee_id, effective_from])\n  @@map(\"employee_work_schedules\")\n}\n\n/// 10 \"Attendance & Working Hours\" — one row per working weekday of a schedule.\nmodel EmployeeWorkScheduleDay {\n  id            String                @id @default(uuid())\n  schedule_id   String\n  /// 0 = Sunday … 6 = Saturday.\n  weekday       Int\n  /// \"09:00\" local time; null for flexible days.\n  starts_at     String?\n  ends_at       String?\n  break_minutes Int                   @default(0)\n  hours         Decimal               @db.Decimal(4, 2)\n  work_location EmployeeWorkLocation?\n\n  schedule EmployeeWorkSchedule @relation(fields: [schedule_id], references: [id], onDelete: Cascade)\n\n  @@unique([schedule_id, weekday])\n  @@map(\"employee_work_schedule_days\")\n}\n\n/// 10 \"Employee Availability\" — time-boxed availability states (remote day, training, business travel, busy,\n/// leave projection). Approved leave and holidays create entries with source LEAVE / HOLIDAY; the current state is\n/// mirrored onto Employee.availability_status. Projected onto 19 Calendar as read-only items.\nmodel EmployeeAvailabilityEntry {\n  id                 String                     @id @default(uuid())\n  organization_id    String\n  employee_id        String\n  status             EmployeeAvailabilityStatus\n  starts_at          DateTime\n  ends_at            DateTime\n  all_day            Boolean                    @default(true)\n  source             EmployeeAvailabilitySource @default(MANUAL)\n  leave_request_id   String?\n  /// 19 CalendarEvent — the projected or originating event.\n  calendar_event_id  String?\n  note               String?\n  created_by_user_id String?\n  created_at         DateTime                   @default(now())\n  updated_at         DateTime                   @updatedAt\n\n  organization  Organization  @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee      Employee      @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  leave_request LeaveRequest? @relation(fields: [leave_request_id], references: [id], onDelete: Cascade)\n\n  @@index([employee_id, starts_at, ends_at])\n  @@index([organization_id, status, starts_at])\n  @@map(\"employee_availability_entries\")\n}\n\n// --- Leave ------------------------------------------------------------------------------\n\n/// 10 \"Leave Management\" — configurable leave types (vacation, sick, personal, maternity, paternity, unpaid, …).\nmodel LeaveType {\n  id                    String           @id @default(uuid())\n  organization_id       String\n  name                  String\n  code                  String\n  category              LeaveCategory\n  color                 String?\n  is_paid               Boolean          @default(true)\n  requires_approval     Boolean          @default(true)\n  /// e.g. doctor's note for sick leave beyond N days.\n  requires_attachment   Boolean          @default(false)\n  attachment_after_days Int?\n  allows_half_day       Boolean          @default(true)\n  /// Whether requests deduct from a LeaveBalance (false for unpaid / unlimited types).\n  deducts_balance       Boolean          @default(true)\n  min_notice_days       Int?\n  max_consecutive_days  Int?\n  /// Employment types the type applies to; empty = all.\n  applies_to_types      EmploymentType[] @default([])\n  sort_order            Int              @default(0)\n  archived_at           DateTime?\n  created_at            DateTime         @default(now())\n  updated_at            DateTime         @updatedAt\n\n  organization Organization   @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  policies     LeavePolicy[]\n  balances     LeaveBalance[]\n  requests     LeaveRequest[]\n\n  @@unique([organization_id, code])\n  @@index([organization_id, category])\n  @@map(\"leave_types\")\n}\n\n/// 10 \"Leave Management\" — entitlement and accrual rules for a leave type, optionally restricted to a branch\n/// (local law) or employment types. Assigned to employees through EmployeeLeavePolicy; is_default applies to all.\nmodel LeavePolicy {\n  id                            String             @id @default(uuid())\n  organization_id               String\n  leave_type_id                 String\n  branch_id                     String?\n  name                          String\n  accrual_method                LeaveAccrualMethod @default(ANNUAL_UPFRONT)\n  annual_entitlement_days       Decimal            @db.Decimal(6, 2)\n  /// Days accrued per month / per 100 hours worked, depending on accrual_method.\n  accrual_rate                  Decimal?           @db.Decimal(6, 2)\n  prorate_first_year            Boolean            @default(true)\n  /// Extra days per completed year of service, capped by max_entitlement_days.\n  seniority_bonus_days_per_year Decimal?           @db.Decimal(6, 2)\n  max_entitlement_days          Decimal?           @db.Decimal(6, 2)\n  carry_over_max_days           Decimal?           @db.Decimal(6, 2)\n  /// Months after period end before carried-over days expire.\n  carry_over_expiry_months      Int?\n  allow_negative_balance        Boolean            @default(false)\n  max_negative_days             Decimal?           @db.Decimal(6, 2)\n  /// Balance period start (month 1–12, day); default calendar year.\n  period_start_month            Int                @default(1)\n  period_start_day              Int                @default(1)\n  applies_to_types              EmploymentType[]   @default([])\n  is_default                    Boolean            @default(false)\n  effective_from                DateTime?          @db.Date\n  effective_to                  DateTime?          @db.Date\n  archived_at                   DateTime?\n  created_at                    DateTime           @default(now())\n  updated_at                    DateTime           @updatedAt\n\n  organization Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  leave_type   LeaveType             @relation(fields: [leave_type_id], references: [id], onDelete: Cascade)\n  branch       Branch?               @relation(\"LeavePolicyBranch\", fields: [branch_id], references: [id], onDelete: SetNull)\n  assignments  EmployeeLeavePolicy[]\n\n  @@index([organization_id, leave_type_id])\n  @@index([branch_id])\n  @@map(\"leave_policies\")\n}\n\n/// 10 \"Leave Management\" — explicit policy assignment per employee (overrides defaults).\nmodel EmployeeLeavePolicy {\n  id              String    @id @default(uuid())\n  employee_id     String\n  leave_policy_id String\n  effective_from  DateTime  @db.Date\n  effective_to    DateTime? @db.Date\n  created_at      DateTime  @default(now())\n\n  employee Employee    @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  policy   LeavePolicy @relation(fields: [leave_policy_id], references: [id], onDelete: Cascade)\n\n  @@unique([employee_id, leave_policy_id, effective_from])\n  @@index([leave_policy_id])\n  @@map(\"employee_leave_policies\")\n}\n\n/// 10 \"Leave Management\" — balance per employee, leave type and balance period.\n/// available = entitled + accrued + carried_over + adjusted − used − pending.\nmodel LeaveBalance {\n  id                    String    @id @default(uuid())\n  organization_id       String\n  employee_id           String\n  leave_type_id         String\n  period_start          DateTime  @db.Date\n  period_end            DateTime  @db.Date\n  entitled_days         Decimal   @default(0) @db.Decimal(6, 2)\n  accrued_days          Decimal   @default(0) @db.Decimal(6, 2)\n  carried_over_days     Decimal   @default(0) @db.Decimal(6, 2)\n  adjusted_days         Decimal   @default(0) @db.Decimal(6, 2)\n  used_days             Decimal   @default(0) @db.Decimal(6, 2)\n  /// Days in PENDING requests (reserved).\n  pending_days          Decimal   @default(0) @db.Decimal(6, 2)\n  /// When carried-over days expire.\n  carry_over_expires_on DateTime? @db.Date\n  last_accrued_at       DateTime?\n  created_at            DateTime  @default(now())\n  updated_at            DateTime  @updatedAt\n\n  organization Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee     Employee                  @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  leave_type   LeaveType                 @relation(fields: [leave_type_id], references: [id], onDelete: Cascade)\n  transactions LeaveBalanceTransaction[]\n\n  @@unique([employee_id, leave_type_id, period_start])\n  @@index([organization_id, period_start])\n  @@map(\"leave_balances\")\n}\n\n/// 10 \"Leave Management\" — ledger of balance movements (accruals, usage, adjustments, carry-over, expiry).\nmodel LeaveBalanceTransaction {\n  id                       String                      @id @default(uuid())\n  leave_balance_id         String\n  leave_request_id         String?\n  type                     LeaveBalanceTransactionType\n  /// Signed: positive adds to the balance, negative consumes it.\n  days                     Decimal                     @db.Decimal(6, 2)\n  effective_on             DateTime                    @db.Date\n  reason                   String?\n  created_by_membership_id String?\n  created_at               DateTime                    @default(now())\n\n  balance       LeaveBalance  @relation(fields: [leave_balance_id], references: [id], onDelete: Cascade)\n  leave_request LeaveRequest? @relation(fields: [leave_request_id], references: [id], onDelete: SetNull)\n\n  @@index([leave_balance_id, effective_on])\n  @@index([leave_request_id])\n  @@map(\"leave_balance_transactions\")\n}\n\n/// 10 \"Leave Management\" — a leave / time-off request with approval workflow (01 §95 approval right; 20 workflow),\n/// half-day support, conflict detection and calendar projection (19).\nmodel LeaveRequest {\n  id                             String             @id @default(uuid())\n  organization_id                String\n  employee_id                    String\n  leave_type_id                  String\n  status                         LeaveRequestStatus @default(DRAFT)\n  start_date                     DateTime           @db.Date\n  end_date                       DateTime           @db.Date\n  start_day_part                 LeaveDayPart       @default(FULL_DAY)\n  end_day_part                   LeaveDayPart       @default(FULL_DAY)\n  /// Working days requested, excluding weekends and holidays (see days).\n  total_days                     Decimal            @db.Decimal(6, 2)\n  total_hours                    Decimal?           @db.Decimal(8, 2)\n  reason                         String?\n  /// 17 Document — e.g. medical certificate.\n  attachment_document_id         String?\n  /// Colleague covering during the absence.\n  covering_employee_id           String?\n  /// Membership expected to decide next (derived from LeaveApproverStrategy / workflow).\n  current_approver_membership_id String?\n  submitted_at                   DateTime?\n  decided_at                     DateTime?\n  decided_by_membership_id       String?\n  decision_note                  String?\n  cancelled_at                   DateTime?\n  cancellation_reason            String?\n  /// Conflict detection snapshot: overlapping team leave, project deadlines, insufficient balance.\n  conflicts                      Json?\n  has_conflicts                  Boolean            @default(false)\n  /// 19 CalendarEvent created for approved leave.\n  calendar_event_id              String?\n  /// 20 AutomationRun driving the approval workflow.\n  automation_run_id              String?\n  created_at                     DateTime           @default(now())\n  updated_at                     DateTime           @updatedAt\n\n  organization      Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee          Employee     @relation(\"LeaveRequestEmployee\", fields: [employee_id], references: [id], onDelete: Cascade)\n  leave_type        LeaveType    @relation(fields: [leave_type_id], references: [id], onDelete: Restrict)\n  covering_employee Employee?    @relation(\"LeaveRequestCover\", fields: [covering_employee_id], references: [id], onDelete: SetNull)\n  decided_by        Membership?  @relation(\"LeaveRequestDecider\", fields: [decided_by_membership_id], references: [id], onDelete: SetNull)\n\n  days                 LeaveRequestDay[]\n  approvals            LeaveRequestApproval[]\n  balance_transactions LeaveBalanceTransaction[]\n  availability_entries EmployeeAvailabilityEntry[]\n\n  @@index([organization_id, status])\n  @@index([employee_id, start_date])\n  @@index([organization_id, start_date, end_date])\n  @@index([current_approver_membership_id, status])\n  @@map(\"leave_requests\")\n}\n\n/// 10 \"Leave Management\" — per-day breakdown of a request (half days, hours) for the leave calendar, team\n/// availability and capacity.\nmodel LeaveRequestDay {\n  id               String       @id @default(uuid())\n  leave_request_id String\n  date             DateTime     @db.Date\n  day_part         LeaveDayPart @default(FULL_DAY)\n  hours            Decimal?     @db.Decimal(5, 2)\n\n  leave_request LeaveRequest @relation(fields: [leave_request_id], references: [id], onDelete: Cascade)\n\n  @@unique([leave_request_id, date])\n  @@index([date])\n  @@map(\"leave_request_days\")\n}\n\n/// 10 \"Leave Management\" — approval steps (manager, HR, custom chain from 20).\nmodel LeaveRequestApproval {\n  id                     String                @id @default(uuid())\n  leave_request_id       String\n  step                   Int                   @default(1)\n  approver_membership_id String\n  decision               LeaveApprovalDecision @default(PENDING)\n  decided_at             DateTime?\n  comment                String?\n  created_at             DateTime              @default(now())\n\n  leave_request LeaveRequest @relation(fields: [leave_request_id], references: [id], onDelete: Cascade)\n  approver      Membership   @relation(\"LeaveRequestApprover\", fields: [approver_membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([leave_request_id, step, approver_membership_id])\n  @@index([approver_membership_id, decision])\n  @@map(\"leave_request_approvals\")\n}\n\n/// 10 \"Leave Management\" — organization-wide public and company holidays. Branch-specific holidays are\n/// BranchHoliday (01 §122); both reduce capacity and are projected onto the leave calendar.\nmodel CompanyHoliday {\n  id                    String             @id @default(uuid())\n  organization_id       String\n  name                  String\n  date                  DateTime           @db.Date\n  kind                  CompanyHolidayKind @default(COMPANY)\n  is_half_day           Boolean            @default(false)\n  recurring             Boolean            @default(false)\n  /// Restrict to these branches; empty = whole organization.\n  applies_to_branch_ids String[]           @default([])\n  created_at            DateTime           @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, date, name])\n  @@index([organization_id, date])\n  @@map(\"company_holidays\")\n}\n\n// --- Attendance -------------------------------------------------------------------------\n\n/// 10 \"Attendance & Working Hours\" — one record per employee per calendar day aggregating clock sessions,\n/// breaks, overtime and lateness against the work schedule. Presence only; work effort is 18 Time Tracking.\nmodel AttendanceRecord {\n  id                                 String               @id @default(uuid())\n  organization_id                    String\n  employee_id                        String\n  date                               DateTime             @db.Date\n  status                             AttendanceStatus     @default(CLOCKED_IN)\n  work_location                      EmployeeWorkLocation @default(OFFICE)\n  /// First clock-in / last clock-out of the day (denormalized from sessions).\n  first_clock_in_at                  DateTime?\n  last_clock_out_at                  DateTime?\n  scheduled_minutes                  Int                  @default(0)\n  worked_minutes                     Int                  @default(0)\n  break_minutes                      Int                  @default(0)\n  overtime_minutes                   Int                  @default(0)\n  late_minutes                       Int                  @default(0)\n  early_leave_minutes                Int                  @default(0)\n  overtime_approved                  Boolean              @default(false)\n  overtime_approved_by_membership_id String?\n  overtime_approved_at               DateTime?\n  /// 18 TimeEntry pre-filled from this record, if enabled.\n  prefilled_time_entry_id            String?\n  note                               String?\n  /// Manual correction audit (full history in audit_events).\n  edited_by_membership_id            String?\n  edited_at                          DateTime?\n  created_at                         DateTime             @default(now())\n  updated_at                         DateTime             @updatedAt\n\n  organization Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee     Employee            @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  sessions     AttendanceSession[]\n\n  @@unique([employee_id, date])\n  @@index([organization_id, date])\n  @@index([organization_id, status])\n  @@map(\"attendance_records\")\n}\n\n/// 10 \"Attendance & Working Hours\" — a clock-in / clock-out pair; several per day are allowed.\nmodel AttendanceSession {\n  id                   String               @id @default(uuid())\n  attendance_record_id String\n  clock_in_at          DateTime\n  clock_out_at         DateTime?\n  work_location        EmployeeWorkLocation @default(OFFICE)\n  clock_in_source      AttendanceSource     @default(WEB)\n  clock_out_source     AttendanceSource?\n  /// { lat, lng, accuracy } / ip captured at clock-in / out.\n  clock_in_meta        Json?\n  clock_out_meta       Json?\n  note                 String?\n  created_at           DateTime             @default(now())\n  updated_at           DateTime             @updatedAt\n\n  record AttendanceRecord  @relation(fields: [attendance_record_id], references: [id], onDelete: Cascade)\n  breaks AttendanceBreak[]\n\n  @@index([attendance_record_id, clock_in_at])\n  @@map(\"attendance_sessions\")\n}\n\n/// 10 \"Attendance & Working Hours\" — breaks inside a session.\nmodel AttendanceBreak {\n  id         String              @id @default(uuid())\n  session_id String\n  kind       AttendanceBreakKind @default(UNPAID)\n  started_at DateTime\n  ended_at   DateTime?\n  note       String?\n\n  session AttendanceSession @relation(fields: [session_id], references: [id], onDelete: Cascade)\n\n  @@index([session_id])\n  @@map(\"attendance_breaks\")\n}\n\n/// 10 \"Attendance & Working Hours\", \"Dashboards & Reporting\" — materialized weekly / monthly attendance summary\n/// per employee (recomputed by a scheduled job, 20).\nmodel AttendanceSummary {\n  id                String             @id @default(uuid())\n  organization_id   String\n  employee_id       String\n  period_type       EmployeePeriodType\n  period_start      DateTime           @db.Date\n  period_end        DateTime           @db.Date\n  scheduled_minutes Int                @default(0)\n  worked_minutes    Int                @default(0)\n  break_minutes     Int                @default(0)\n  overtime_minutes  Int                @default(0)\n  days_present      Int                @default(0)\n  days_remote       Int                @default(0)\n  days_absent       Int                @default(0)\n  days_on_leave     Int                @default(0)\n  days_holiday      Int                @default(0)\n  late_count        Int                @default(0)\n  computed_at       DateTime           @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee     Employee     @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n\n  @@unique([employee_id, period_type, period_start])\n  @@index([organization_id, period_type, period_start])\n  @@map(\"attendance_summaries\")\n}\n\n// --- Capacity -------------------------------------------------------------------------\n\n/// 10 \"Capacity & Workload\" — materialized capacity per employee and period: expected hours from the work\n/// schedule minus leave and holidays (owned here), with snapshots of planned hours (05 §51 allocation) and logged\n/// hours / utilization (18) for dashboards and the AI workforce assistant. 05 and 18 remain the sources.\nmodel EmployeeCapacityPeriod {\n  id                  String                 @id @default(uuid())\n  organization_id     String\n  employee_id         String\n  period_type         EmployeePeriodType\n  period_start        DateTime               @db.Date\n  period_end          DateTime               @db.Date\n  scheduled_hours     Decimal                @default(0) @db.Decimal(8, 2)\n  leave_hours         Decimal                @default(0) @db.Decimal(8, 2)\n  holiday_hours       Decimal                @default(0) @db.Decimal(8, 2)\n  /// scheduled − leave − holiday.\n  available_hours     Decimal                @default(0) @db.Decimal(8, 2)\n  /// Snapshot from 05 ProjectAllocation (+ task estimates, 06).\n  planned_hours       Decimal                @default(0) @db.Decimal(8, 2)\n  /// Snapshot from 18 TimeEntry actuals.\n  logged_hours        Decimal                @default(0) @db.Decimal(8, 2)\n  /// planned / available.\n  allocation_percent  Decimal?               @db.Decimal(5, 2)\n  /// logged / available (computed by 18, mirrored here).\n  utilization_percent Decimal?               @db.Decimal(5, 2)\n  status              EmployeeCapacityStatus @default(BALANCED)\n  /// Per-project breakdown [{ project_id, planned_hours, logged_hours }].\n  breakdown           Json?\n  computed_at         DateTime               @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee     Employee     @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n\n  @@unique([employee_id, period_type, period_start])\n  @@index([organization_id, period_type, period_start, status])\n  @@map(\"employee_capacity_periods\")\n}\n\n// --- Performance ------------------------------------------------------------------------\n\n/// 10 \"Performance Management\" — a review cycle (e.g. \"H1 2026\") grouping reviews with a shared template.\nmodel PerformanceReviewCycle {\n  id                 String                       @id @default(uuid())\n  organization_id    String\n  name               String\n  type               PerformanceReviewType        @default(ANNUAL)\n  status             PerformanceReviewCycleStatus @default(PLANNED)\n  period_start       DateTime                     @db.Date\n  period_end         DateTime                     @db.Date\n  due_date           DateTime?                    @db.Date\n  /// Rating scale, competencies and questions: { scale_max, competencies: [...], questions: [...] }.\n  template           Json?\n  created_by_user_id String?\n  created_at         DateTime                     @default(now())\n  updated_at         DateTime                     @updatedAt\n\n  organization Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  reviews      PerformanceReview[]\n\n  @@index([organization_id, status])\n  @@map(\"performance_review_cycles\")\n}\n\n/// 10 \"Performance Management\" — a performance review (self assessment + manager assessment + ratings).\nmodel PerformanceReview {\n  id                     String                  @id @default(uuid())\n  organization_id        String\n  employee_id            String\n  cycle_id               String?\n  reviewer_membership_id String?\n  type                   PerformanceReviewType   @default(ANNUAL)\n  status                 PerformanceReviewStatus @default(DRAFT)\n  title                  String?\n  period_start           DateTime                @db.Date\n  period_end             DateTime                @db.Date\n  due_date               DateTime?               @db.Date\n  /// Markdown.\n  self_assessment        String?\n  self_submitted_at      DateTime?\n  manager_assessment     String?\n  manager_submitted_at   DateTime?\n  /// Per competency ratings [{ key, label, rating, comment }].\n  ratings                Json?\n  overall_rating         Decimal?                @db.Decimal(4, 2)\n  rating_scale_max       Int                     @default(5)\n  strengths              String?\n  improvement_areas      String?\n  summary                String?\n  /// Employee response after reading the review.\n  employee_comment       String?\n  completed_at           DateTime?\n  acknowledged_at        DateTime?\n  next_review_date       DateTime?               @db.Date\n  /// 19 CalendarEvent — review meeting.\n  meeting_event_id       String?\n  /// 17 Document — exported / signed review.\n  document_id            String?\n  created_by_user_id     String?\n  created_at             DateTime                @default(now())\n  updated_at             DateTime                @updatedAt\n\n  organization Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee     Employee                @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  cycle        PerformanceReviewCycle? @relation(fields: [cycle_id], references: [id], onDelete: SetNull)\n  reviewer     Membership?             @relation(\"PerformanceReviewer\", fields: [reviewer_membership_id], references: [id], onDelete: SetNull)\n\n  goals             PerformanceGoal[]\n  feedback          PerformanceFeedback[]\n  improvement_plans PerformanceImprovementPlan[]\n\n  @@index([organization_id, status])\n  @@index([employee_id, period_start])\n  @@index([reviewer_membership_id, status])\n  @@index([cycle_id])\n  @@map(\"performance_reviews\")\n}\n\n/// 10 \"Performance Management\" — goals, objectives and key results (objective → key results via parent_goal_id),\n/// optionally tied to a review or a Project (05).\nmodel PerformanceGoal {\n  id                       String                @id @default(uuid())\n  organization_id          String\n  employee_id              String\n  review_id                String?\n  parent_goal_id           String?\n  project_id               String?\n  kind                     PerformanceGoalKind   @default(GOAL)\n  title                    String\n  description              String?\n  status                   PerformanceGoalStatus @default(NOT_STARTED)\n  /// Weight among sibling goals.\n  weight_percent           Decimal?              @db.Decimal(5, 2)\n  target_value             Decimal?              @db.Decimal(18, 2)\n  current_value            Decimal?              @db.Decimal(18, 2)\n  unit                     String?\n  progress_percent         Decimal               @default(0) @db.Decimal(5, 2)\n  start_date               DateTime?             @db.Date\n  due_date                 DateTime?             @db.Date\n  completed_at             DateTime?\n  /// Employee-visible by default; managers may keep draft goals private.\n  employee_visible         Boolean               @default(true)\n  created_by_membership_id String?\n  created_at               DateTime              @default(now())\n  updated_at               DateTime              @updatedAt\n\n  organization Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee     Employee                @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  review       PerformanceReview?      @relation(fields: [review_id], references: [id], onDelete: SetNull)\n  parent       PerformanceGoal?        @relation(\"PerformanceGoalHierarchy\", fields: [parent_goal_id], references: [id], onDelete: SetNull)\n  children     PerformanceGoal[]       @relation(\"PerformanceGoalHierarchy\")\n  project      Project?                @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  updates      PerformanceGoalUpdate[]\n  feedback     PerformanceFeedback[]\n\n  @@index([organization_id, status])\n  @@index([employee_id, status])\n  @@index([review_id])\n  @@index([parent_goal_id])\n  @@index([project_id])\n  @@map(\"performance_goals\")\n}\n\n/// 10 \"Performance Management\" — progress check-ins on a goal (ongoing tracking).\nmodel PerformanceGoalUpdate {\n  id                   String                 @id @default(uuid())\n  goal_id              String\n  author_membership_id String?\n  progress_percent     Decimal?               @db.Decimal(5, 2)\n  current_value        Decimal?               @db.Decimal(18, 2)\n  status               PerformanceGoalStatus?\n  note                 String?\n  created_at           DateTime               @default(now())\n\n  goal PerformanceGoal @relation(fields: [goal_id], references: [id], onDelete: Cascade)\n\n  @@index([goal_id, created_at])\n  @@map(\"performance_goal_updates\")\n}\n\n/// 10 \"Performance Management\" — manager feedback, employee (upward / self) feedback, peer feedback, performance\n/// notes, achievements and recognition history. Continuous, not only inside reviews.\nmodel PerformanceFeedback {\n  id                   String                        @id @default(uuid())\n  organization_id      String\n  employee_id          String\n  author_membership_id String?\n  review_id            String?\n  goal_id              String?\n  project_id           String?\n  kind                 PerformanceFeedbackKind\n  visibility           PerformanceFeedbackVisibility @default(MANAGERS_ONLY)\n  title                String?\n  /// Markdown.\n  body                 String\n  rating               Decimal?                      @db.Decimal(4, 2)\n  occurred_on          DateTime?                     @db.Date\n  is_anonymous         Boolean                       @default(false)\n  edited_at            DateTime?\n  deleted_at           DateTime?\n  created_at           DateTime                      @default(now())\n  updated_at           DateTime                      @updatedAt\n\n  organization Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee     Employee           @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  author       Membership?        @relation(\"PerformanceFeedbackAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n  review       PerformanceReview? @relation(fields: [review_id], references: [id], onDelete: SetNull)\n  goal         PerformanceGoal?   @relation(fields: [goal_id], references: [id], onDelete: SetNull)\n  project      Project?           @relation(fields: [project_id], references: [id], onDelete: SetNull)\n\n  @@index([employee_id, kind, created_at])\n  @@index([organization_id, kind])\n  @@index([review_id])\n  @@map(\"performance_feedback\")\n}\n\n/// 10 \"Performance Management\" — improvement plans (PIP) with check-ins and measurable items.\nmodel PerformanceImprovementPlan {\n  id                      String                           @id @default(uuid())\n  organization_id         String\n  employee_id             String\n  review_id               String?\n  status                  PerformanceImprovementPlanStatus @default(DRAFT)\n  title                   String\n  /// Why the plan was opened.\n  reason                  String?\n  /// Expected outcomes and support offered (markdown).\n  objectives              String?\n  start_date              DateTime                         @db.Date\n  end_date                DateTime                         @db.Date\n  check_in_frequency_days Int?\n  next_check_in_on        DateTime?                        @db.Date\n  manager_membership_id   String?\n  hr_membership_id        String?\n  outcome_note            String?\n  closed_at               DateTime?\n  /// 17 Document — signed plan.\n  document_id             String?\n  created_by_user_id      String?\n  created_at              DateTime                         @default(now())\n  updated_at              DateTime                         @updatedAt\n\n  organization Organization                     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee     Employee                         @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  review       PerformanceReview?               @relation(fields: [review_id], references: [id], onDelete: SetNull)\n  items        PerformanceImprovementPlanItem[]\n\n  @@index([organization_id, status])\n  @@index([employee_id, status])\n  @@map(\"performance_improvement_plans\")\n}\n\n/// 10 \"Performance Management\" — measurable items of an improvement plan.\nmodel PerformanceImprovementPlanItem {\n  id           String                           @id @default(uuid())\n  plan_id      String\n  title        String\n  description  String?\n  due_date     DateTime?                        @db.Date\n  status       PerformanceImprovementItemStatus @default(OPEN)\n  evaluated_at DateTime?\n  note         String?\n  sort_order   Int                              @default(0)\n  created_at   DateTime                         @default(now())\n\n  plan PerformanceImprovementPlan @relation(fields: [plan_id], references: [id], onDelete: Cascade)\n\n  @@index([plan_id])\n  @@map(\"performance_improvement_plan_items\")\n}\n\n// --- Documents & notes --------------------------------------------------------------------\n\n/// 10 \"Employee Documents\" — HR document index per employee (contracts, NDAs, IDs, signed agreements, HR forms).\n/// The file is a 17 Document (employee scope, 17 §3); employment / contractor agreements may also be a Contract\n/// (04) and signed through SignatureRequest (04). A row with status REQUESTED and no document_id is a document\n/// request (\"Notifications\" → document requests).\nmodel EmployeeDocument {\n  id                         String                   @id @default(uuid())\n  organization_id            String\n  employee_id                String\n  category                   EmployeeDocumentCategory @default(OTHER)\n  title                      String\n  description                String?\n  status                     EmployeeDocumentStatus   @default(UPLOADED)\n  /// 17 Document — the stored file; null while REQUESTED.\n  document_id                String?\n  contract_id                String?\n  signature_request_id       String?\n  requested_by_membership_id String?\n  requested_at               DateTime?\n  due_date                   DateTime?                @db.Date\n  uploaded_by_user_id        String?\n  uploaded_at                DateTime?\n  verified_by_membership_id  String?\n  verified_at                DateTime?\n  rejection_reason           String?\n  valid_from                 DateTime?                @db.Date\n  expires_on                 DateTime?                @db.Date\n  /// Visible to the employee in self-service (\"Access HR documents\", \"Download employment documents\").\n  employee_visible           Boolean                  @default(true)\n  /// Restricted to HR / explicit grants (01 §60).\n  is_confidential            Boolean                  @default(false)\n  note                       String?\n  created_at                 DateTime                 @default(now())\n  updated_at                 DateTime                 @updatedAt\n\n  organization      Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee          Employee          @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  contract          Contract?         @relation(\"EmployeeDocumentContract\", fields: [contract_id], references: [id], onDelete: SetNull)\n  signature_request SignatureRequest? @relation(\"EmployeeDocumentSignatureRequest\", fields: [signature_request_id], references: [id], onDelete: SetNull)\n\n  @@index([employee_id, category])\n  @@index([organization_id, status])\n  @@index([document_id])\n  @@index([expires_on])\n  @@map(\"employee_documents\")\n}\n\n/// 10 \"Internal Notes\" — private HR notes (performance observations, meeting notes, HR comments, warnings) with\n/// role-based visibility (01 §60). Kept separate from crm_notes so they never surface in generic note feeds,\n/// search or exports, and so warnings can carry severity and employee acknowledgement.\nmodel EmployeeHrNote {\n  id                           String            @id @default(uuid())\n  organization_id              String\n  employee_id                  String\n  author_membership_id         String?\n  category                     HrNoteCategory    @default(HR_COMMENT)\n  visibility                   HrNoteVisibility  @default(HR_AND_MANAGERS)\n  /// Additional memberships allowed to read beyond the visibility rule.\n  restricted_to_membership_ids String[]          @default([])\n  /// Warning severity; null for non-warnings.\n  severity                     HrNoteSeverity?\n  title                        String?\n  /// Markdown body.\n  body                         String\n  occurred_on                  DateTime?         @db.Date\n  /// Employee acknowledgement (EMPLOYEE_VISIBLE warnings).\n  requires_acknowledgement     Boolean           @default(false)\n  acknowledged_at              DateTime?\n  /// Related record (review, leave request, project …).\n  related_entity_type          RecordEntityType?\n  related_entity_id            String?\n  /// 17 Document ids attached (signed warning letter, meeting minutes).\n  attachment_document_ids      String[]          @default([])\n  pinned                       Boolean           @default(false)\n  edited_at                    DateTime?\n  /// Previous bodies for edit history.\n  edit_history                 Json?\n  deleted_at                   DateTime?\n  created_at                   DateTime          @default(now())\n  updated_at                   DateTime          @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee     Employee     @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n  author       Membership?  @relation(\"EmployeeHrNoteAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([employee_id, created_at])\n  @@index([organization_id, category])\n  @@index([related_entity_type, related_entity_id])\n  @@map(\"employee_hr_notes\")\n}\n\n// --- Self-service -------------------------------------------------------------------------\n\n/// 10 \"Employee Self-Service\" — profile changes submitted by the employee that need HR approval\n/// (EmployeeHrSettings.profile_changes_require_approval). Direct edits of allowed fields skip this table.\nmodel EmployeeProfileChangeRequest {\n  id                       String                      @id @default(uuid())\n  organization_id          String\n  employee_id              String\n  status                   EmployeeChangeRequestStatus @default(PENDING)\n  /// { field: { from, to } } for Employee / emergency contact / bank detail fields.\n  changes                  Json\n  employee_note            String?\n  submitted_by_user_id     String?\n  decided_by_membership_id String?\n  decided_at               DateTime?\n  decision_note            String?\n  created_at               DateTime                    @default(now())\n  updated_at               DateTime                    @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  employee     Employee     @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, status])\n  @@index([employee_id, status])\n  @@map(\"employee_profile_change_requests\")\n}\n\n// =====================================================================\n// 11 Communication Center — docs/features/11-communication-center.md (LOG-106)\n// Owns: outbound email & SMS messages (CommMessage) with recipients, attachments, threads and\n// provider delivery events; sender domains/identities, provider accounts and signatures; templates\n// with versions and translations; campaigns (audiences, recipients, runs, approvals, tracked links);\n// recipient lists, segments (saved filters over CRM), consent, suppression; daily stats; AI drafts.\n// Does not own: contacts/companies (02), notification events/preferences/inbox (14 — 11 is only the\n// email/SMS delivery channel, referenced by plain id), internal chat (12), inbound conversations\n// and tickets (13), automation rules/jobs (20), attachments as files (17). Referenced by id only.\n// Activity, review notes and change history go to audit_events / crm_notes (COMM_MESSAGE, CAMPAIGN).\n// =====================================================================\n\n/// 11 \"Email Management\", \"SMS Management\" — delivery channel of a message, template or campaign.\nenum CommChannel {\n  EMAIL\n  SMS\n}\n\n/// 11 \"Communication History\", \"Notification Delivery Provider\" — why a message exists. Notification and\n/// transactional sends are logged separately from customer communications and campaigns.\nenum CommMessageKind {\n  CUSTOMER\n  CAMPAIGN\n  TRANSACTIONAL\n  NOTIFICATION\n  INTERNAL\n}\n\n/// 11 \"Communication History\" — who or what originated the send (\"Automation source\", \"User who sent\").\nenum CommMessageSource {\n  MANUAL\n  CAMPAIGN\n  AUTOMATION\n  MODULE\n  NOTIFICATION\n  API\n}\n\n/// 11 \"Scheduling\", \"Delivery Tracking\" — lifecycle of a single outbound message.\nenum CommMessageStatus {\n  DRAFT\n  SCHEDULED\n  QUEUED\n  SENDING\n  SENT\n  DELIVERED\n  FAILED\n  BOUNCED\n  CANCELLED\n}\n\n/// 11 \"Delivery Tracking\" — provider delivery events for email (delivered/opened/clicked/replied/bounced/\n/// failed/unsubscribed/complained) and SMS (queued/sent/delivered/failed/read).\nenum CommDeliveryEventType {\n  QUEUED\n  SENT\n  DEFERRED\n  DELIVERED\n  OPENED\n  CLICKED\n  REPLIED\n  READ\n  BOUNCED\n  COMPLAINED\n  FAILED\n  UNSUBSCRIBED\n}\n\n/// 11 \"Recipients\" — bounce handling.\nenum CommBounceType {\n  HARD\n  SOFT\n}\n\n/// 11 \"Recipients\" — who a message recipient / list member is.\nenum CommRecipientKind {\n  CRM_CONTACT\n  MEMBERSHIP\n  PORTAL_USER\n  EXTERNAL\n}\n\n/// 11 \"Email Management\" — to / cc / bcc.\nenum CommRecipientRole {\n  TO\n  CC\n  BCC\n}\n\n/// 11 \"Delivery Tracking\" — per-recipient status.\nenum CommRecipientStatus {\n  PENDING\n  EXCLUDED\n  QUEUED\n  SENT\n  DELIVERED\n  OPENED\n  CLICKED\n  REPLIED\n  BOUNCED\n  FAILED\n  UNSUBSCRIBED\n}\n\n/// 11 \"Communication Templates\" — template categories listed in the spec.\nenum CommTemplateCategory {\n  PROJECT_UPDATE\n  MILESTONE_COMPLETION\n  INVOICE_NOTIFICATION\n  PAYMENT_CONFIRMATION\n  PAYMENT_REMINDER\n  SUBSCRIPTION_RENEWAL\n  WELCOME\n  CUSTOMER_ONBOARDING\n  MEETING_REMINDER\n  MAINTENANCE_ANNOUNCEMENT\n  SERVICE_INTERRUPTION\n  SUPPORT_RESPONSE\n  MARKETING_CAMPAIGN\n  HOLIDAY_GREETING\n  /// 11 \"Customer Communication\", \"Automation\" — remaining communication topics named by the spec.\n  DEVELOPMENT_UPDATE\n  FEATURE_RELEASE\n  BUG_FIX\n  DOWNTIME_NOTIFICATION\n  MEETING_INVITATION\n  APPROVAL_REQUEST\n  FEEDBACK_REQUEST\n  CONTRACT_RENEWAL\n  CONTRACT_EXPIRATION_REMINDER\n  PROJECT_CREATED\n  PROJECT_COMPLETED\n  FAILED_PAYMENT\n  CUSTOMER_FOLLOW_UP\n  GENERAL_ANNOUNCEMENT\n  NOTIFICATION\n  OTHER\n}\n\n/// 11 \"Communication Templates\", \"Notification Delivery Provider\" — what a template is used for.\nenum CommTemplateKind {\n  COMMUNICATION\n  CAMPAIGN\n  NOTIFICATION\n  SYSTEM\n}\n\nenum CommTemplateStatus {\n  DRAFT\n  ACTIVE\n  ARCHIVED\n}\n\n/// 11 \"Communication Templates\" — version lifecycle.\nenum CommTemplateVersionStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\n/// 11 \"Email Management\" — supported providers for email and SMS delivery.\nenum CommProviderKind {\n  RESEND\n  SENDGRID\n  POSTMARK\n  MAILGUN\n  AWS_SES\n  SMTP\n  TWILIO\n  VONAGE\n  MESSAGEBIRD\n  CUSTOM\n}\n\nenum CommProviderAccountStatus {\n  ACTIVE\n  DISABLED\n  ERROR\n}\n\n/// 11 \"Email Management\" — sending domain (DKIM / SPF / DMARC / return-path) verification.\nenum CommSenderDomainStatus {\n  PENDING\n  VERIFIED\n  FAILED\n  DISABLED\n}\n\n/// 11 \"Email Management\", \"SMS Management\" — a from-address or sender number must be verified before use.\nenum CommSenderIdentityStatus {\n  PENDING_VERIFICATION\n  VERIFIED\n  FAILED\n  DISABLED\n}\n\n/// 11 \"Marketing Campaigns\", \"Internal Collaboration\", \"Scheduling\" — campaign lifecycle.\nenum CampaignStatus {\n  DRAFT\n  PENDING_APPROVAL\n  APPROVED\n  SCHEDULED\n  SENDING\n  PAUSED\n  COMPLETED\n  CANCELLED\n  FAILED\n}\n\n/// 11 \"Internal Collaboration\" — approve campaigns.\nenum CampaignApprovalDecision {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n/// 11 \"Marketing Campaigns\" — include or exclude an audience source.\nenum CampaignAudienceMode {\n  INCLUDE\n  EXCLUDE\n}\n\n/// 11 \"Scheduling\" — recurring campaign runs.\nenum CampaignRunStatus {\n  PENDING\n  RUNNING\n  COMPLETED\n  FAILED\n  CANCELLED\n}\n\n/// 11 \"Customer Segmentation\" — the CRM record type a segment filters.\nenum SegmentEntityType {\n  CRM_CONTACT\n  CRM_COMPANY\n  MEMBERSHIP\n}\n\n/// 11 \"Recipients\" — consent / opt-in state per channel.\nenum CommConsentStatus {\n  UNKNOWN\n  PENDING_DOUBLE_OPT_IN\n  OPTED_IN\n  OPTED_OUT\n}\n\n/// 11 \"Recipients\" — where consent evidence came from.\nenum CommConsentSource {\n  FORM\n  IMPORT\n  MANUAL\n  DOUBLE_OPT_IN\n  UNSUBSCRIBE_LINK\n  PORTAL\n  API\n}\n\n/// 11 \"Recipients\" — why an address is suppressed.\nenum CommSuppressionReason {\n  UNSUBSCRIBE\n  HARD_BOUNCE\n  SOFT_BOUNCE\n  COMPLAINT\n  INVALID_ADDRESS\n  CONSENT_WITHDRAWN\n  MANUAL\n}\n\n/// 11 \"AI Communication Assistant\" — what the assistant was asked to do.\nenum CommAiTaskKind {\n  WRITE_EMAIL\n  WRITE_SMS\n  PERSONALIZE\n  PROJECT_UPDATE\n  PAYMENT_REMINDER\n  CAMPAIGN\n  SUMMARIZE\n  TRANSLATE\n  IMPROVE_TONE\n  SUBJECT_LINES\n  GENERATE_TEMPLATE\n  AUTO_REPLY\n  EXECUTIVE_SUMMARY\n}\n\n// --- Providers & sender identities -------------------------------------------------\n\n/// 11 \"Email Management\", \"SMS Management\" — a configured delivery provider account (API key stored\n/// encrypted / as a secret reference). One default per channel per organization.\nmodel CommProviderAccount {\n  id                        String                    @id @default(uuid())\n  organization_id           String\n  channel                   CommChannel\n  provider                  CommProviderKind\n  name                      String\n  status                    CommProviderAccountStatus @default(ACTIVE)\n  is_default                Boolean                   @default(false)\n  /// 01 §157 — the organization's own credentials (API key, webhook secret) for this provider. Secrets never live on this row.\n  integration_connection_id String?\n  /// Provider-specific settings (region, SMTP host/port, messaging service sid, tracking options…).\n  settings                  Json?\n  last_error                String?\n  last_used_at              DateTime?\n  created_by_user_id        String?\n  created_at                DateTime                  @default(now())\n  updated_at                DateTime                  @updatedAt\n\n  organization           Organization           @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  integration_connection IntegrationConnection? @relation(fields: [integration_connection_id], references: [id], onDelete: SetNull)\n  sender_domains         CommSenderDomain[]\n  sender_identities      CommSenderIdentity[]\n  messages               CommMessage[]\n\n  @@index([organization_id, channel, status])\n  @@index([integration_connection_id])\n  @@map(\"comm_provider_accounts\")\n}\n\n/// 11 \"Email Management\" — a sending domain with DNS verification (SPF / DKIM / DMARC / return-path).\n/// Distinct from organization_domains (01 §70), which are login domains.\nmodel CommSenderDomain {\n  id                  String                 @id @default(uuid())\n  organization_id     String\n  provider_account_id String?\n  domain              String\n  status              CommSenderDomainStatus @default(PENDING)\n  /// Provider-side domain id.\n  provider_domain_id  String?\n  /// DNS records to publish: [{ type, name, value, verified }].\n  dns_records         Json?\n  spf_verified_at     DateTime?\n  dkim_verified_at    DateTime?\n  dmarc_verified_at   DateTime?\n  verified_at         DateTime?\n  last_checked_at     DateTime?\n  failure_reason      String?\n  /// Subdomain used for link/open tracking, if any.\n  tracking_domain     String?\n  created_at          DateTime               @default(now())\n  updated_at          DateTime               @updatedAt\n\n  organization     Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  provider_account CommProviderAccount? @relation(fields: [provider_account_id], references: [id], onDelete: SetNull)\n  identities       CommSenderIdentity[]\n\n  @@unique([organization_id, domain])\n  @@index([organization_id, status])\n  @@map(\"comm_sender_domains\")\n}\n\n/// 11 \"Email Management\", \"SMS Management\" — a verified from-address (email) or sender number / alphanumeric\n/// sender id (SMS). May be scoped to a Branch (01 §120 branding). One default per channel.\nmodel CommSenderIdentity {\n  id                   String                   @id @default(uuid())\n  organization_id      String\n  branch_id            String?\n  channel              CommChannel\n  provider_account_id  String?\n  sender_domain_id     String?\n  /// Email address or E.164 number / alphanumeric sender id.\n  address              String\n  display_name         String?\n  reply_to_address     String?\n  status               CommSenderIdentityStatus @default(PENDING_VERIFICATION)\n  is_default           Boolean                  @default(false)\n  /// Provider-side identity id (verified sender, messaging service, phone number sid …).\n  provider_identity_id String?\n  verified_at          DateTime?\n  failure_reason       String?\n  /// Membership whose personal mailbox this identity represents, if not shared.\n  membership_id        String?\n  created_at           DateTime                 @default(now())\n  updated_at           DateTime                 @updatedAt\n\n  organization     Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch           Branch?              @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  provider_account CommProviderAccount? @relation(fields: [provider_account_id], references: [id], onDelete: SetNull)\n  sender_domain    CommSenderDomain?    @relation(fields: [sender_domain_id], references: [id], onDelete: SetNull)\n  membership       Membership?          @relation(\"CommSenderIdentityMembership\", fields: [membership_id], references: [id], onDelete: SetNull)\n  messages         CommMessage[]\n  campaigns        Campaign[]\n  templates        CommTemplate[]\n\n  @@unique([organization_id, channel, address])\n  @@index([organization_id, channel, status])\n  @@index([branch_id])\n  @@map(\"comm_sender_identities\")\n}\n\n/// 11 \"Email Management\" — email signatures; organization-wide when membership_id is null, personal otherwise.\nmodel CommSignature {\n  id              String   @id @default(uuid())\n  organization_id String\n  membership_id   String?\n  name            String\n  body_html       String\n  body_text       String?\n  is_default      Boolean  @default(false)\n  created_at      DateTime @default(now())\n  updated_at      DateTime @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership   Membership?  @relation(\"CommSignatureMembership\", fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, membership_id])\n  @@map(\"comm_signatures\")\n}\n\n// --- Templates ----------------------------------------------------------------------\n\n/// 11 \"Communication Templates\" — reusable email / SMS template. Content lives in versions; the published\n/// version is pointed to by current_version_id. Variables resolve against CRM (02), project (05) and\n/// billing (08) data; branding comes from 01 §15 / §120. Kind NOTIFICATION templates are used by 14.\nmodel CommTemplate {\n  id                         String               @id @default(uuid())\n  organization_id            String\n  branch_id                  String?\n  name                       String\n  slug                       String\n  description                String?\n  channel                    CommChannel\n  kind                       CommTemplateKind     @default(COMMUNICATION)\n  category                   CommTemplateCategory @default(OTHER)\n  status                     CommTemplateStatus   @default(DRAFT)\n  /// Default language (BCP-47); other languages live in CommTemplateTranslation.\n  language                   String               @default(\"en\")\n  /// Published version; null while only drafts exist.\n  current_version_id         String?              @unique\n  default_sender_identity_id String?\n  /// 14 NotificationEventType key this template renders (kind NOTIFICATION); id only.\n  notification_event_type_id String?\n  /// Built-in templates shipped by the platform; editable copies are created per organization.\n  is_system                  Boolean              @default(false)\n  /// Apply organization/branch branded layout (header, footer, colors) around the body.\n  use_branded_layout         Boolean              @default(true)\n  /// Declared variables: [{ key, label, source: crm|project|billing|custom, required, sample }].\n  variables                  Json?\n  /// AI-generated template (11 \"AI Communication Assistant\").\n  ai_generation_id           String?\n  usage_count                Int                  @default(0)\n  last_used_at               DateTime?\n  archived_at                DateTime?\n  created_by_membership_id   String?\n  created_at                 DateTime             @default(now())\n  updated_at                 DateTime             @updatedAt\n\n  organization            Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch                  Branch?               @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  current_version         CommTemplateVersion?  @relation(\"CommTemplateCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  default_sender_identity CommSenderIdentity?   @relation(fields: [default_sender_identity_id], references: [id], onDelete: SetNull)\n  created_by              Membership?           @relation(\"CommTemplateCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  versions                CommTemplateVersion[] @relation(\"CommTemplateVersions\")\n  messages                CommMessage[]\n  campaigns               Campaign[]\n  ai_generations          CommAiGeneration[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, channel, status])\n  @@index([organization_id, kind, category])\n  @@map(\"comm_templates\")\n}\n\n/// 11 \"Communication Templates\" — immutable content snapshot per version: subject, preheader, HTML body,\n/// plain-text body, editor design JSON. Conditional content uses template syntax inside the body.\nmodel CommTemplateVersion {\n  id                       String                    @id @default(uuid())\n  template_id              String\n  version                  Int\n  status                   CommTemplateVersionStatus @default(DRAFT)\n  subject                  String?\n  preheader                String?\n  /// Rich HTML email body (templating syntax for variables and conditionals). Null for SMS.\n  body_html                String?\n  /// Plain-text body (email fallback / SMS content).\n  body_text                String?\n  /// Visual editor document (blocks) used to regenerate body_html.\n  design                   Json?\n  /// Variables used by this version (derived at save time).\n  variables                Json?\n  /// Document ids (17) of attachments bundled with the template; ids only.\n  attachment_document_ids  String[]                  @default([])\n  change_note              String?\n  published_at             DateTime?\n  created_by_membership_id String?\n  created_at               DateTime                  @default(now())\n  updated_at               DateTime                  @updatedAt\n\n  template     CommTemplate              @relation(\"CommTemplateVersions\", fields: [template_id], references: [id], onDelete: Cascade)\n  current_of   CommTemplate?             @relation(\"CommTemplateCurrentVersion\")\n  created_by   Membership?               @relation(\"CommTemplateVersionCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  translations CommTemplateTranslation[]\n  messages     CommMessage[]\n  campaigns    Campaign[]\n\n  @@unique([template_id, version])\n  @@index([template_id, status])\n  @@map(\"comm_template_versions\")\n}\n\n/// 11 \"Communication Templates\" — multiple languages: a localized subject/body for a template version,\n/// selected by recipient language (02 CrmContact.language, 01 §128 defaults).\nmodel CommTemplateTranslation {\n  id                        String    @id @default(uuid())\n  version_id                String\n  /// BCP-47 language tag.\n  language                  String\n  subject                   String?\n  preheader                 String?\n  body_html                 String?\n  body_text                 String?\n  /// Machine-translated by the AI assistant and not yet reviewed.\n  is_machine_translated     Boolean   @default(false)\n  reviewed_by_membership_id String?\n  reviewed_at               DateTime?\n  created_at                DateTime  @default(now())\n  updated_at                DateTime  @updatedAt\n\n  version CommTemplateVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n\n  @@unique([version_id, language])\n  @@map(\"comm_template_translations\")\n}\n\n// --- Messages -----------------------------------------------------------------------\n\n/// 11 \"Email Management\", \"Conversation threads\" — groups outbound emails and their inbound replies\n/// (captured by 13 and linked by support_conversation_id) under one subject for a contact / project.\nmodel CommThread {\n  id                      String      @id @default(uuid())\n  organization_id         String\n  subject                 String?\n  channel                 CommChannel @default(EMAIL)\n  contact_id              String?\n  company_id              String?\n  project_id              String?\n  /// 13 SupportConversation holding inbound replies; id only.\n  support_conversation_id String?\n  /// Provider / RFC 5322 thread identifiers for reply matching.\n  provider_thread_id      String?\n  message_count           Int         @default(0)\n  last_message_at         DateTime?\n  archived_at             DateTime?\n  created_at              DateTime    @default(now())\n  updated_at              DateTime    @updatedAt\n\n  organization Organization  @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  contact      CrmContact?   @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n  company      CrmCompany?   @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  project      Project?      @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  messages     CommMessage[]\n\n  @@index([organization_id, last_message_at])\n  @@index([contact_id])\n  @@index([company_id])\n  @@index([project_id])\n  @@map(\"comm_threads\")\n}\n\n/// 11 \"Email Management\", \"SMS Management\", \"Communication History\", \"Scheduling\", \"Delivery Tracking\" —\n/// one outbound email or SMS to one primary recipient (cc/bcc in CommMessageRecipient). Campaign sends\n/// create one CommMessage per recipient. Transactional sends from 03/04/08/13 and notification sends\n/// from 14 are the same table with kind TRANSACTIONAL / NOTIFICATION so history and analytics are\n/// complete, while UI history views filter by kind. Internal notes: crm_notes (COMM_MESSAGE).\nmodel CommMessage {\n  id                     String            @id @default(uuid())\n  organization_id        String\n  branch_id              String?\n  channel                CommChannel\n  kind                   CommMessageKind   @default(CUSTOMER)\n  source                 CommMessageSource @default(MANUAL)\n  status                 CommMessageStatus @default(DRAFT)\n  thread_id              String?\n  /// Reply chain inside a thread.\n  in_reply_to_message_id String?\n\n  // Content (\"Rich HTML emails\", \"Plain text emails\", \"Personalized messages\")\n  template_id         String?\n  /// 11 \"Communication History\" — topic of the message; copied from the template, or set directly for template-less sends so history can be filtered by topic.\n  category            CommTemplateCategory?\n  template_version_id String?\n  subject             String?\n  preheader           String?\n  body_html           String?\n  body_text           String?\n  /// Variable values used to render the template (snapshot for audit / resend).\n  render_context      Json?\n  language            String?\n  signature_id        String?\n  /// Branded layout applied (01 §15 / §120 snapshot at send time).\n  branding_snapshot   Json?\n\n  // Sender (\"User who sent the communication\", ownership)\n  sender_identity_id    String?\n  from_address          String?\n  from_name             String?\n  reply_to_address      String?\n  sent_by_membership_id String?\n  owner_membership_id   String?\n\n  // Primary recipient (cc/bcc and extra recipients in CommMessageRecipient)\n  recipient_kind          CommRecipientKind @default(CRM_CONTACT)\n  /// Email address or E.164 phone number.\n  to_address              String\n  to_name                 String?\n  recipient_contact_id    String?\n  recipient_membership_id String?\n  /// Customer Portal User (01 §79); id only.\n  recipient_user_id       String?\n  company_id              String?\n  project_id              String?\n\n  // Origin (\"Automation source\", campaigns, modules, notifications)\n  campaign_id              String?\n  campaign_run_id          String?\n  /// 11 \"Automation\" — 20 AutomationRule / AutomationRun that triggered this send; ids only.\n  automation_rule_id       String?\n  automation_run_id        String?\n  /// 14 Notification / NotificationDelivery this message delivers (kind NOTIFICATION); ids only.\n  notification_id          String?\n  notification_delivery_id String?\n  /// Record that caused a transactional send (PROPOSAL 03, CONTRACT 04, INVOICE 08, TICKET 13 …).\n  source_entity_type       RecordEntityType?\n  source_entity_id         String?\n  ai_generation_id         String?\n\n  // Scheduling & queue (\"Scheduled sending\", \"Delay sending\", \"Time-zone aware delivery\", \"Queue management\")\n  scheduled_at      DateTime?\n  /// IANA timezone the schedule was expressed in.\n  schedule_timezone String?\n  /// 20 ScheduledJob backing the schedule; id only.\n  scheduled_job_id  String?\n  priority          Int       @default(0)\n  attempt_count     Int       @default(0)\n  next_attempt_at   DateTime?\n  last_error        String?\n\n  // Provider & delivery (\"Delivery Tracking\")\n  provider_account_id String?\n  provider            CommProviderKind?\n  provider_message_id String?\n  queued_at           DateTime?\n  sent_at             DateTime?\n  delivered_at        DateTime?\n  first_opened_at     DateTime?\n  last_opened_at      DateTime?\n  first_clicked_at    DateTime?\n  replied_at          DateTime?\n  read_at             DateTime?\n  bounced_at          DateTime?\n  bounce_type         CommBounceType?\n  complained_at       DateTime?\n  unsubscribed_at     DateTime?\n  failed_at           DateTime?\n  failure_reason      String?\n  cancelled_at        DateTime?\n  open_count          Int                      @default(0)\n  click_count         Int                      @default(0)\n  /// SMS: number of 160/70-char segments billed.\n  sms_segment_count   Int?\n  /// Provider cost for the send, if reported.\n  cost                Decimal?                 @db.Decimal(18, 4)\n  cost_currency       String?\n  tracking_enabled    Boolean                  @default(true)\n  /// Token embedded in the unsubscribe link / List-Unsubscribe header.\n  unsubscribe_token   String?                  @unique\n  is_test             Boolean                  @default(false)\n  /// Raw provider headers / metadata (Message-ID, X-headers …).\n  provider_metadata   Json?\n  /// 11 \"Communication History\" — Postgres full-text search vector over subject + body; maintained by a database trigger (see migration). Not set by the API.\n  search_vector       Unsupported(\"tsvector\")?\n\n  archived_at        DateTime?\n  deleted_at         DateTime?\n  created_by_user_id String?\n  created_at         DateTime  @default(now())\n  updated_at         DateTime  @updatedAt\n\n  organization         Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch               Branch?              @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  thread               CommThread?          @relation(fields: [thread_id], references: [id], onDelete: SetNull)\n  in_reply_to          CommMessage?         @relation(\"CommMessageReplyChain\", fields: [in_reply_to_message_id], references: [id], onDelete: SetNull)\n  replies              CommMessage[]        @relation(\"CommMessageReplyChain\")\n  template             CommTemplate?        @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  template_version     CommTemplateVersion? @relation(fields: [template_version_id], references: [id], onDelete: SetNull)\n  sender_identity      CommSenderIdentity?  @relation(fields: [sender_identity_id], references: [id], onDelete: SetNull)\n  sent_by              Membership?          @relation(\"CommMessageSender\", fields: [sent_by_membership_id], references: [id], onDelete: SetNull)\n  owner                Membership?          @relation(\"CommMessageOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  recipient_contact    CrmContact?          @relation(\"CommMessageRecipientContact\", fields: [recipient_contact_id], references: [id], onDelete: SetNull)\n  recipient_membership Membership?          @relation(\"CommMessageRecipientMembership\", fields: [recipient_membership_id], references: [id], onDelete: SetNull)\n  company              CrmCompany?          @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  project              Project?             @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  campaign             Campaign?            @relation(fields: [campaign_id], references: [id], onDelete: SetNull)\n  campaign_run         CampaignRun?         @relation(fields: [campaign_run_id], references: [id], onDelete: SetNull)\n  provider_account     CommProviderAccount? @relation(fields: [provider_account_id], references: [id], onDelete: SetNull)\n  ai_generation        CommAiGeneration?    @relation(\"CommAiGenerationMessage\", fields: [ai_generation_id], references: [id], onDelete: SetNull)\n\n  recipients          CommMessageRecipient[]\n  attachments         CommMessageAttachment[]\n  links               CommMessageLink[]\n  delivery_events     CommDeliveryEvent[]\n  tracked_links       CommTrackedLink[]\n  campaign_recipient  CampaignRecipient?\n  suppressions        CommSuppression[]\n  proposal_deliveries ProposalDelivery[]\n  invoice_reminders   InvoiceReminder[]\n\n  @@unique([provider, provider_message_id])\n  @@index([organization_id, status, scheduled_at])\n  @@index([search_vector], type: Gin)\n  @@index([organization_id, channel, kind, created_at])\n  @@index([organization_id, status, next_attempt_at])\n  @@index([recipient_contact_id, created_at])\n  @@index([company_id, created_at])\n  @@index([project_id, created_at])\n  @@index([campaign_id, status])\n  @@index([thread_id, created_at])\n  @@index([sent_by_membership_id])\n  @@index([source_entity_type, source_entity_id])\n  @@index([notification_delivery_id])\n  @@index([to_address])\n  @@map(\"comm_messages\")\n}\n\n/// 11 \"Email Management\" — every recipient of a message (the primary TO is duplicated here so\n/// per-recipient delivery status is uniform), plus cc / bcc.\nmodel CommMessageRecipient {\n  id                    String              @id @default(uuid())\n  message_id            String\n  role                  CommRecipientRole   @default(TO)\n  kind                  CommRecipientKind   @default(CRM_CONTACT)\n  address               String\n  name                  String?\n  contact_id            String?\n  membership_id         String?\n  /// Customer Portal User (01 §79); id only.\n  user_id               String?\n  status                CommRecipientStatus @default(PENDING)\n  provider_recipient_id String?\n  delivered_at          DateTime?\n  opened_at             DateTime?\n  clicked_at            DateTime?\n  bounced_at            DateTime?\n  failed_at             DateTime?\n  failure_reason        String?\n  created_at            DateTime            @default(now())\n  updated_at            DateTime            @updatedAt\n\n  message         CommMessage         @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  contact         CrmContact?         @relation(\"CommMessageRecipientsContact\", fields: [contact_id], references: [id], onDelete: SetNull)\n  membership      Membership?         @relation(\"CommMessageRecipientsMembership\", fields: [membership_id], references: [id], onDelete: SetNull)\n  delivery_events CommDeliveryEvent[]\n\n  @@unique([message_id, role, address])\n  @@index([contact_id])\n  @@index([membership_id])\n  @@index([address])\n  @@map(\"comm_message_recipients\")\n}\n\n/// 11 \"Email Management\" — file attachments and inline images. Files are Documents (17); id only.\nmodel CommMessageAttachment {\n  id          String   @id @default(uuid())\n  message_id  String\n  /// 17 Document; id only.\n  document_id String?\n  filename    String\n  mimetype    String?\n  size        Int?\n  /// Direct URL when the file is not a Document (e.g. generated invoice PDF from 08).\n  url         String?\n  /// Inline image referenced from body_html via cid:.\n  is_inline   Boolean  @default(false)\n  content_id  String?\n  created_at  DateTime @default(now())\n\n  message CommMessage @relation(fields: [message_id], references: [id], onDelete: Cascade)\n\n  @@index([message_id])\n  @@index([document_id])\n  @@map(\"comm_message_attachments\")\n}\n\n/// 11 \"Customer Communication\", \"Communication History\" — polymorphic link from a message to the records it\n/// concerns (CRM_COMPANY / CRM_CONTACT / PROJECT / INVOICE / PROPOSAL / CONTRACT / TICKET / TASK …) so it\n/// appears in the Customer 360 timeline (02 §18) and project history (05).\nmodel CommMessageLink {\n  id          String           @id @default(uuid())\n  message_id  String\n  entity_type RecordEntityType\n  entity_id   String\n  /// about | triggered_by | related\n  relation    String           @default(\"related\")\n  created_at  DateTime         @default(now())\n\n  message CommMessage @relation(fields: [message_id], references: [id], onDelete: Cascade)\n\n  @@unique([message_id, entity_type, entity_id])\n  @@index([entity_type, entity_id])\n  @@map(\"comm_message_links\")\n}\n\n/// 11 \"Delivery Tracking\" — append-only provider events (webhooks and sync). Idempotent through\n/// provider_webhook_events (08) and the (provider, provider_event_id) unique.\nmodel CommDeliveryEvent {\n  id                        String                @id @default(uuid())\n  organization_id           String\n  message_id                String\n  recipient_id              String?\n  type                      CommDeliveryEventType\n  occurred_at               DateTime\n  provider                  CommProviderKind?\n  provider_event_id         String?\n  /// 08 ProviderWebhookEvent that carried this event.\n  provider_webhook_event_id String?\n  tracked_link_id           String?\n  /// Click: target URL.\n  url                       String?\n  user_agent                String?\n  ip_address                String?\n  /// Bounce / failure details.\n  bounce_type               CommBounceType?\n  bounce_code               String?\n  reason                    String?\n  payload                   Json?\n  created_at                DateTime              @default(now())\n\n  organization           Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  message                CommMessage           @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  recipient              CommMessageRecipient? @relation(fields: [recipient_id], references: [id], onDelete: SetNull)\n  provider_webhook_event ProviderWebhookEvent? @relation(fields: [provider_webhook_event_id], references: [id], onDelete: SetNull)\n  tracked_link           CommTrackedLink?      @relation(fields: [tracked_link_id], references: [id], onDelete: SetNull)\n\n  @@unique([provider, provider_event_id])\n  @@index([message_id, occurred_at])\n  @@index([organization_id, type, occurred_at])\n  @@index([recipient_id])\n  @@map(\"comm_delivery_events\")\n}\n\n/// 11 \"Delivery Tracking\", \"Analytics & Reporting\" — rewritten links for click tracking, per message\n/// (one-off sends) or per campaign (shared across its messages).\nmodel CommTrackedLink {\n  id                 String    @id @default(uuid())\n  organization_id    String\n  message_id         String?\n  campaign_id        String?\n  token              String    @unique\n  original_url       String\n  label              String?\n  click_count        Int       @default(0)\n  unique_click_count Int       @default(0)\n  first_clicked_at   DateTime?\n  last_clicked_at    DateTime?\n  created_at         DateTime  @default(now())\n\n  organization Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  message      CommMessage?        @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  campaign     Campaign?           @relation(fields: [campaign_id], references: [id], onDelete: Cascade)\n  events       CommDeliveryEvent[]\n\n  @@index([message_id])\n  @@index([campaign_id])\n  @@map(\"comm_tracked_links\")\n}\n\n// --- Recipients, segments, consent & suppression ------------------------------------\n\n/// 11 \"Recipients\" — a static recipient list of CRM contacts and/or members. Dynamic audiences are Segments.\nmodel CommRecipientList {\n  id                       String       @id @default(uuid())\n  organization_id          String\n  name                     String\n  description              String?\n  /// Restricts the list to recipients reachable on this channel; null = both.\n  channel                  CommChannel?\n  member_count             Int          @default(0)\n  created_by_membership_id String?\n  archived_at              DateTime?\n  created_at               DateTime     @default(now())\n  updated_at               DateTime     @updatedAt\n\n  organization Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  created_by   Membership?               @relation(\"CommRecipientListCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  members      CommRecipientListMember[]\n  audiences    CampaignAudience[]\n\n  @@unique([organization_id, name])\n  @@map(\"comm_recipient_lists\")\n}\n\n/// 11 \"Recipients\" — list membership: a CRM contact, a member, or an external address.\nmodel CommRecipientListMember {\n  id                     String            @id @default(uuid())\n  list_id                String\n  kind                   CommRecipientKind @default(CRM_CONTACT)\n  contact_id             String?\n  membership_id          String?\n  /// External address when kind = EXTERNAL, or an override address for a contact.\n  address                String?\n  name                   String?\n  added_by_membership_id String?\n  created_at             DateTime          @default(now())\n\n  list       CommRecipientList @relation(fields: [list_id], references: [id], onDelete: Cascade)\n  contact    CrmContact?       @relation(\"CommRecipientListMemberContact\", fields: [contact_id], references: [id], onDelete: Cascade)\n  membership Membership?       @relation(\"CommRecipientListMemberMembership\", fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([list_id, contact_id])\n  @@unique([list_id, membership_id])\n  @@unique([list_id, address])\n  @@index([contact_id])\n  @@map(\"comm_recipient_list_members\")\n}\n\n/// 11 \"Customer Segmentation\" — a saved filter over CRM companies/contacts (02 §29 saved views, §24 custom\n/// fields, §36 tags) combined with billing state (08) and project state (05). Evaluated at send time.\nmodel Segment {\n  id                       String            @id @default(uuid())\n  organization_id          String\n  name                     String\n  description              String?\n  entity_type              SegmentEntityType @default(CRM_CONTACT)\n  /// Optional 02 SavedView whose filter this segment was created from.\n  saved_view_id            String?\n  /// Filter tree: { and: [ { field, op, value }, { or: [...] } ] } over CRM fields, custom fields, tags,\n  /// subscription plan / billing status / outstanding invoices (08), active projects (05), last activity.\n  definition               Json\n  /// Restricts to recipients reachable on this channel; null = both.\n  channel                  CommChannel?\n  /// Exclude contacts without OPTED_IN consent on the campaign channel (default on for marketing).\n  require_consent          Boolean           @default(true)\n  last_evaluated_at        DateTime?\n  last_count               Int?\n  created_by_membership_id String?\n  archived_at              DateTime?\n  created_at               DateTime          @default(now())\n  updated_at               DateTime          @updatedAt\n\n  organization Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  saved_view   SavedView?         @relation(fields: [saved_view_id], references: [id], onDelete: SetNull)\n  created_by   Membership?        @relation(\"SegmentCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  audiences    CampaignAudience[]\n\n  @@unique([organization_id, name])\n  @@index([organization_id, entity_type])\n  @@map(\"segments\")\n}\n\n/// 11 \"Recipients\" — consent / opt-in / unsubscribe state per CRM contact and channel, with evidence.\n/// Source of truth for marketing sends; CrmContact.consent (02) is a denormalized summary.\nmodel CommConsent {\n  id                       String            @id @default(uuid())\n  organization_id          String\n  contact_id               String\n  channel                  CommChannel\n  status                   CommConsentStatus @default(UNKNOWN)\n  source                   CommConsentSource @default(MANUAL)\n  /// Marketing vs transactional scope; transactional messages never require consent.\n  marketing_opted_in       Boolean           @default(false)\n  consented_at             DateTime?\n  withdrawn_at             DateTime?\n  /// Double opt-in confirmation token and its expiry.\n  confirmation_token       String?           @unique\n  confirmation_expires_at  DateTime?\n  confirmed_at             DateTime?\n  /// Evidence: ip, user agent, form id, imported file, consent text version …\n  evidence                 Json?\n  notes                    String?\n  updated_by_membership_id String?\n  created_at               DateTime          @default(now())\n  updated_at               DateTime          @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  contact      CrmContact   @relation(\"CommConsentContact\", fields: [contact_id], references: [id], onDelete: Cascade)\n\n  @@unique([contact_id, channel])\n  @@index([organization_id, channel, status])\n  @@map(\"comm_consents\")\n}\n\n/// 11 \"Recipients\", \"Delivery Tracking\" — suppression list: addresses that must not be contacted on a channel\n/// (unsubscribes, hard bounces, complaints, manual). Checked before every non-transactional send.\nmodel CommSuppression {\n  id                       String                @id @default(uuid())\n  organization_id          String\n  channel                  CommChannel\n  /// Normalized email (lower-case) or E.164 number.\n  address                  String\n  reason                   CommSuppressionReason\n  contact_id               String?\n  /// Message / campaign that produced the bounce, complaint or unsubscribe.\n  source_message_id        String?\n  campaign_id              String?\n  /// Soft bounces expire; hard suppressions have no expiry.\n  expires_at               DateTime?\n  /// Marketing-only suppression (transactional still allowed) vs all sends.\n  blocks_transactional     Boolean               @default(false)\n  notes                    String?\n  created_by_membership_id String?\n  removed_at               DateTime?\n  removed_by_membership_id String?\n  created_at               DateTime              @default(now())\n  updated_at               DateTime              @updatedAt\n\n  organization   Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  contact        CrmContact?  @relation(\"CommSuppressionContact\", fields: [contact_id], references: [id], onDelete: SetNull)\n  source_message CommMessage? @relation(fields: [source_message_id], references: [id], onDelete: SetNull)\n  campaign       Campaign?    @relation(fields: [campaign_id], references: [id], onDelete: SetNull)\n\n  @@unique([organization_id, channel, address])\n  @@index([organization_id, reason])\n  @@index([contact_id])\n  @@map(\"comm_suppressions\")\n}\n\n// --- Campaigns ----------------------------------------------------------------------\n\n/// 11 \"Marketing Campaigns\", \"Scheduling\", \"Internal Collaboration\", \"Analytics & Reporting\" — a bulk email\n/// or SMS send to an audience built from lists and segments. Campaign templates are campaigns with\n/// is_template = true; duplication records duplicated_from_campaign_id. Recurring campaigns carry an\n/// RRULE and are triggered by a 20 ScheduledJob; each occurrence is a CampaignRun.\nmodel Campaign {\n  id                          String         @id @default(uuid())\n  organization_id             String\n  branch_id                   String?\n  name                        String\n  description                 String?\n  channel                     CommChannel\n  status                      CampaignStatus @default(DRAFT)\n  /// Promotional announcement, product launch, newsletter, … free-form tag; platform tags also apply.\n  campaign_type               String?\n  is_template                 Boolean        @default(false)\n  duplicated_from_campaign_id String?\n\n  // Content (template or inline)\n  template_id             String?\n  template_version_id     String?\n  subject                 String?\n  preheader               String?\n  body_html               String?\n  body_text               String?\n  sender_identity_id      String?\n  from_name               String?\n  reply_to_address        String?\n  /// Attachment Document ids (17); ids only.\n  attachment_document_ids String[] @default([])\n  tracking_enabled        Boolean  @default(true)\n  /// UTM parameters appended to tracked links.\n  utm                     Json?\n  language                String?\n  /// Only send to recipients with OPTED_IN consent on the channel.\n  require_consent         Boolean  @default(true)\n\n  // Scheduling\n  scheduled_at               DateTime?\n  schedule_timezone          String?\n  /// Deliver at scheduled local time in each recipient's timezone.\n  send_in_recipient_timezone Boolean   @default(false)\n  /// RFC 5545 RRULE for recurring campaigns; null = one-off.\n  recurrence_rule            String?\n  recurrence_ends_at         DateTime?\n  next_run_at                DateTime?\n  /// 20 ScheduledJob driving the schedule; id only.\n  scheduled_job_id           String?\n  /// Max messages per hour (throttling); null = provider default.\n  send_rate_per_hour         Int?\n\n  // Lifecycle\n  owner_membership_id       String?\n  submitted_for_approval_at DateTime?\n  approved_at               DateTime?\n  approved_by_membership_id String?\n  started_at                DateTime?\n  paused_at                 DateTime?\n  completed_at              DateTime?\n  cancelled_at              DateTime?\n  failure_reason            String?\n\n  // Aggregated performance (\"Campaign performance\"), refreshed from delivery events\n  audience_count     Int       @default(0)\n  excluded_count     Int       @default(0)\n  sent_count         Int       @default(0)\n  delivered_count    Int       @default(0)\n  opened_count       Int       @default(0)\n  clicked_count      Int       @default(0)\n  replied_count      Int       @default(0)\n  bounced_count      Int       @default(0)\n  failed_count       Int       @default(0)\n  complained_count   Int       @default(0)\n  unsubscribed_count Int       @default(0)\n  stats_refreshed_at DateTime?\n\n  ai_generation_id         String?\n  archived_at              DateTime?\n  created_by_membership_id String?\n  created_at               DateTime  @default(now())\n  updated_at               DateTime  @updatedAt\n\n  organization     Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch           Branch?              @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  duplicated_from  Campaign?            @relation(\"CampaignDuplicate\", fields: [duplicated_from_campaign_id], references: [id], onDelete: SetNull)\n  duplicates       Campaign[]           @relation(\"CampaignDuplicate\")\n  template         CommTemplate?        @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  template_version CommTemplateVersion? @relation(fields: [template_version_id], references: [id], onDelete: SetNull)\n  sender_identity  CommSenderIdentity?  @relation(fields: [sender_identity_id], references: [id], onDelete: SetNull)\n  owner            Membership?          @relation(\"CampaignOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  approved_by      Membership?          @relation(\"CampaignApprover\", fields: [approved_by_membership_id], references: [id], onDelete: SetNull)\n  created_by       Membership?          @relation(\"CampaignCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  ai_generation    CommAiGeneration?    @relation(\"CommAiGenerationCampaign\", fields: [ai_generation_id], references: [id], onDelete: SetNull)\n\n  audiences     CampaignAudience[]\n  recipients    CampaignRecipient[]\n  runs          CampaignRun[]\n  approvals     CampaignApproval[]\n  messages      CommMessage[]\n  tracked_links CommTrackedLink[]\n  suppressions  CommSuppression[]\n  daily_stats   CommDailyStat[]\n\n  @@index([organization_id, status])\n  @@index([organization_id, channel, scheduled_at])\n  @@index([organization_id, is_template])\n  @@index([next_run_at])\n  @@index([owner_membership_id])\n  @@map(\"campaigns\")\n}\n\n/// 11 \"Marketing Campaigns\", \"Customer Segmentation\" — audience sources of a campaign: recipient lists and\n/// segments, included or excluded. Resolved into CampaignRecipient rows when the campaign is scheduled.\nmodel CampaignAudience {\n  id          String               @id @default(uuid())\n  campaign_id String\n  mode        CampaignAudienceMode @default(INCLUDE)\n  list_id     String?\n  segment_id  String?\n  sort_order  Int                  @default(0)\n  created_at  DateTime             @default(now())\n\n  campaign Campaign           @relation(fields: [campaign_id], references: [id], onDelete: Cascade)\n  list     CommRecipientList? @relation(fields: [list_id], references: [id], onDelete: Cascade)\n  segment  Segment?           @relation(fields: [segment_id], references: [id], onDelete: Cascade)\n\n  @@unique([campaign_id, list_id])\n  @@unique([campaign_id, segment_id])\n  @@index([segment_id])\n  @@map(\"campaign_audiences\")\n}\n\n/// 11 \"Marketing Campaigns\", \"Delivery Tracking\" — resolved audience: one row per recipient per campaign\n/// (per run for recurring campaigns). Links to the CommMessage created for the send.\nmodel CampaignRecipient {\n  id               String              @id @default(uuid())\n  campaign_id      String\n  run_id           String?\n  kind             CommRecipientKind   @default(CRM_CONTACT)\n  address          String\n  name             String?\n  contact_id       String?\n  membership_id    String?\n  status           CommRecipientStatus @default(PENDING)\n  /// Why the recipient was excluded (suppressed, no consent, invalid address, duplicate …).\n  exclusion_reason String?\n  message_id       String?             @unique\n  /// Personalization values resolved for this recipient.\n  render_context   Json?\n  /// Local send time when send_in_recipient_timezone is on.\n  scheduled_at     DateTime?\n  sent_at          DateTime?\n  created_at       DateTime            @default(now())\n  updated_at       DateTime            @updatedAt\n\n  campaign   Campaign     @relation(fields: [campaign_id], references: [id], onDelete: Cascade)\n  run        CampaignRun? @relation(fields: [run_id], references: [id], onDelete: Cascade)\n  contact    CrmContact?  @relation(\"CampaignRecipientContact\", fields: [contact_id], references: [id], onDelete: SetNull)\n  membership Membership?  @relation(\"CampaignRecipientMembership\", fields: [membership_id], references: [id], onDelete: SetNull)\n  message    CommMessage? @relation(fields: [message_id], references: [id], onDelete: SetNull)\n\n  @@unique([campaign_id, run_id, address])\n  @@index([campaign_id, status])\n  @@index([contact_id])\n  @@index([run_id])\n  @@map(\"campaign_recipients\")\n}\n\n/// 11 \"Scheduling\" — one execution of a campaign (recurring campaigns have many; one-off campaigns one).\nmodel CampaignRun {\n  id              String            @id @default(uuid())\n  campaign_id     String\n  run_number      Int\n  status          CampaignRunStatus @default(PENDING)\n  scheduled_for   DateTime\n  started_at      DateTime?\n  completed_at    DateTime?\n  audience_count  Int               @default(0)\n  sent_count      Int               @default(0)\n  delivered_count Int               @default(0)\n  failed_count    Int               @default(0)\n  failure_reason  String?\n  created_at      DateTime          @default(now())\n  updated_at      DateTime          @updatedAt\n\n  campaign   Campaign            @relation(fields: [campaign_id], references: [id], onDelete: Cascade)\n  recipients CampaignRecipient[]\n  messages   CommMessage[]\n\n  @@unique([campaign_id, run_number])\n  @@index([campaign_id, status])\n  @@index([scheduled_for])\n  @@map(\"campaign_runs\")\n}\n\n/// 11 \"Internal Collaboration\" — campaign review / approval by a member before sending.\nmodel CampaignApproval {\n  id                     String                   @id @default(uuid())\n  campaign_id            String\n  approver_membership_id String\n  decision               CampaignApprovalDecision @default(PENDING)\n  comment                String?\n  requested_at           DateTime                 @default(now())\n  decided_at             DateTime?\n\n  campaign Campaign   @relation(fields: [campaign_id], references: [id], onDelete: Cascade)\n  approver Membership @relation(\"CampaignApprovalApprover\", fields: [approver_membership_id], references: [id], onDelete: Cascade)\n\n  @@index([campaign_id, decision])\n  @@index([approver_membership_id, decision])\n  @@map(\"campaign_approvals\")\n}\n\n// --- Analytics & AI -----------------------------------------------------------------\n\n/// 11 \"Analytics & Reporting\" — daily rollup per organization / channel / kind (and per campaign) used for\n/// sent counts, open / click / reply / bounce / delivery rates and exports. Rebuilt from delivery events.\nmodel CommDailyStat {\n  id                   String          @id @default(uuid())\n  organization_id      String\n  date                 DateTime        @db.Date\n  channel              CommChannel\n  kind                 CommMessageKind\n  campaign_id          String?\n  sent_count           Int             @default(0)\n  delivered_count      Int             @default(0)\n  opened_count         Int             @default(0)\n  unique_opened_count  Int             @default(0)\n  clicked_count        Int             @default(0)\n  unique_clicked_count Int             @default(0)\n  replied_count        Int             @default(0)\n  bounced_count        Int             @default(0)\n  failed_count         Int             @default(0)\n  complained_count     Int             @default(0)\n  unsubscribed_count   Int             @default(0)\n  cost                 Decimal?        @db.Decimal(18, 4)\n  updated_at           DateTime        @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  campaign     Campaign?    @relation(fields: [campaign_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, date, channel, kind, campaign_id])\n  @@index([organization_id, date])\n  @@map(\"comm_daily_stats\")\n}\n\n/// 11 \"AI Communication Assistant\" — a request to the assistant and its output (draft, rewrite, translation,\n/// subject lines, summary). Linked to the message / template / campaign it produced or edited.\nmodel CommAiGeneration {\n  id                         String         @id @default(uuid())\n  organization_id            String\n  requested_by_membership_id String?\n  task                       CommAiTaskKind\n  channel                    CommChannel?\n  /// User instructions.\n  prompt                     String?\n  /// Context passed to the model: contact / project / invoice summaries, source text, target language, tone.\n  input                      Json?\n  /// Generated result (text, or structured for subject lines / campaigns).\n  output                     Json?\n  model                      String?\n  input_tokens               Int?\n  output_tokens              Int?\n  /// Whether the user kept the result.\n  accepted                   Boolean?\n  template_id                String?\n  created_at                 DateTime       @default(now())\n\n  organization Organization  @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  requested_by Membership?   @relation(\"CommAiGenerationRequester\", fields: [requested_by_membership_id], references: [id], onDelete: SetNull)\n  template     CommTemplate? @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  messages     CommMessage[] @relation(\"CommAiGenerationMessage\")\n  campaigns    Campaign[]    @relation(\"CommAiGenerationCampaign\")\n\n  @@index([organization_id, task, created_at])\n  @@index([requested_by_membership_id])\n  @@map(\"comm_ai_generations\")\n}\n\n// =====================================================================\n// 12 Messaging & Team Communication — docs/features/12-messaging-team-communication.md (LOG-313)\n// Owns: channels (public/private/direct/group DM/project/customer/announcement/record conversations),\n// channel membership & roles, messages, threads, edits/versions, reactions, mentions, attachment links,\n// link previews, record shares, presence, read state, saved messages, reminders, pins, drafts, keywords,\n// per-user channel sections, per-channel notification settings, moderation, retention, exports,\n// integrations/bots, messaging webhooks, calls, channel templates and usage stats.\n// Does not own: identity/Teams/guests/portal users (01), attachments as files (17 Document — id only),\n// notification channels, global preferences, DND and the inbox (14), outbound email/SMS (11),\n// support conversations/tickets (13), automation rules and the event bus (20), calendar events (19).\n// Channel/member/moderation history is written to audit_events (12 §51).\n// =====================================================================\n\n/// 12 §2, §5, §6, §25 — kinds of conversation. DMs are channels of kind DIRECT / GROUP_DIRECT;\n/// RECORD is the contextual conversation attached to a business record (12 §25).\nenum ChannelKind {\n  PUBLIC\n  PRIVATE\n  DIRECT\n  GROUP_DIRECT\n  PROJECT\n  CUSTOMER\n  ANNOUNCEMENT\n  RECORD\n}\n\n/// 12 §7, §34 — discoverability of a channel inside its scope.\nenum ChannelVisibility {\n  DISCOVERABLE\n  HIDDEN\n}\n\n/// 12 §6, §8 — lifecycle status; ARCHIVED channels are read-only (12 §8, §95).\nenum ChannelStatus {\n  ACTIVE\n  ARCHIVED\n  DELETED\n}\n\n/// 12 §7, §29, §49 — who may post.\nenum ChannelPostingPolicy {\n  ALL_MEMBERS\n  INTERNAL_MEMBERS_ONLY\n  ADMINS_ONLY\n  OWNERS_ONLY\n}\n\n/// 12 §9 — membership roles.\nenum ChannelMemberRole {\n  OWNER\n  ADMIN\n  MEMBER\n  GUEST\n  EXTERNAL\n  READ_ONLY\n}\n\n/// 12 §9, §93 — how a member entered the channel.\nenum ChannelMembershipSource {\n  MANUAL\n  TEAM\n  ROLE\n  PROJECT\n  CUSTOMER\n  ORGANIZATION_DEFAULT\n  TEMPLATE\n  JOINED\n  INTEGRATION\n}\n\n/// 12 §82 — guest types; access may expire (access_expires_at on the member).\nenum ChannelGuestKind {\n  SINGLE_CHANNEL\n  MULTI_CHANNEL\n  CUSTOMER\n  PARTNER\n  TEMPORARY\n}\n\n/// 12 §17, §79 — per-channel / per-conversation notification level layered on 14 §6.\nenum ChannelNotificationLevel {\n  ALL_MESSAGES\n  MENTIONS_AND_DIRECT\n  DIRECT_ONLY\n  NOTHING\n  CUSTOM\n}\n\n/// 12 §90 — optional channel digest instead of real-time notifications.\nenum ChannelDigestFrequency {\n  NONE\n  HOURLY\n  DAILY\n  WEEKLY\n}\n\n/// 12 §10, §38, §45, §91 — origin of a message.\nenum MessageKind {\n  USER\n  SYSTEM\n  INTEGRATION\n  VOICE\n}\n\n/// 12 §28, §57 — internal vs customer-visible messages inside customer-facing channels.\nenum MessageVisibility {\n  INTERNAL\n  EXTERNAL\n}\n\n/// 12 §75 — delivery states. Drafts live in message_drafts; DELETED is a soft delete (12 §13).\nenum MessageDeliveryStatus {\n  SCHEDULED\n  SENDING\n  SENT\n  DELIVERED\n  FAILED\n  RETRYING\n  DELETED\n}\n\n/// 12 §15 — mention targets. CHANNEL = @channel/@here broadcast, EVERYONE = organization-wide,\n/// CHANNEL_LINK = a #channel reference.\nenum MessageMentionKind {\n  MEMBER\n  EXTERNAL_USER\n  TEAM\n  ROLE\n  CHANNEL\n  EVERYONE\n  CHANNEL_LINK\n}\n\n/// 12 §22, §45 — attachment categories.\nenum MessageAttachmentKind {\n  IMAGE\n  PDF\n  DOCUMENT\n  SPREADSHEET\n  PRESENTATION\n  VIDEO\n  AUDIO\n  VOICE_MESSAGE\n  ARCHIVE\n  OTHER\n}\n\n/// 12 §23 — link preview resolution state.\nenum MessageLinkPreviewStatus {\n  PENDING\n  RESOLVED\n  FAILED\n  BLOCKED\n}\n\n/// 12 §4 — presence states; custom status is text/emoji on the same record.\nenum MessagingPresenceState {\n  ACTIVE\n  AWAY\n  DO_NOT_DISTURB\n  OFFLINE\n}\n\n/// 12 §21 — reminder lifecycle.\nenum MessageReminderStatus {\n  PENDING\n  TRIGGERED\n  COMPLETED\n  SNOOZED\n  CANCELLED\n}\n\n/// 12 §54 — where a retention policy applies.\nenum MessagingRetentionScope {\n  ORGANIZATION\n  BRANCH\n  TEAM\n  CHANNEL_KIND\n  CHANNEL\n}\n\n/// 12 §54 — what happens after the retention period.\nenum MessagingRetentionAction {\n  UNLIMITED\n  ARCHIVE\n  DELETE\n}\n\n/// 12 §55 — export job lifecycle.\nenum MessagingExportStatus {\n  PENDING\n  RUNNING\n  COMPLETED\n  FAILED\n  EXPIRED\n}\n\n/// 12 §55 — export formats.\nenum MessagingExportFormat {\n  JSON\n  CSV\n  HTML\n}\n\n/// 12 §49, §64 — report lifecycle.\nenum MessageReportStatus {\n  OPEN\n  UNDER_REVIEW\n  ACTIONED\n  DISMISSED\n}\n\n/// 12 §49–50 — moderation restriction kinds.\nenum ChannelRestrictionKind {\n  MUTED\n  BANNED\n}\n\n/// 12 §37–38 — integration / bot sources. Inbound webhooks and bots post messages; external\n/// providers are controlled event sources.\nenum MessagingIntegrationKind {\n  INBOUND_WEBHOOK\n  BOT\n  GITHUB\n  GITLAB\n  JIRA\n  LINEAR\n  GOOGLE_DRIVE\n  NOTION\n  MICROSOFT_365\n  GOOGLE_WORKSPACE\n  SLACK\n  DISCORD\n  CUSTOM\n}\n\n/// 12 §37, §50 — integration status.\nenum MessagingIntegrationStatus {\n  ACTIVE\n  DISABLED\n  ERROR\n}\n\n/// 12 §44 — call kinds.\nenum ChannelCallKind {\n  VOICE\n  VIDEO\n  HUDDLE\n}\n\n/// 12 §44 — call lifecycle.\nenum ChannelCallStatus {\n  RINGING\n  IN_PROGRESS\n  ENDED\n  MISSED\n  CANCELLED\n  FAILED\n}\n\n/// 12 §93 — when a channel template is applied automatically.\nenum ChannelTemplateTrigger {\n  MANUAL\n  PROJECT_CREATED\n  CUSTOMER_CREATED\n}\n\n// --- Organization settings ---------------------------------------------------------\n\n/// 12 §13, §14, §43, §53, §80, §85, §94 — organization-wide messaging configuration (one row per\n/// organization). Global notification channels/DND/digest live in 14 §6; branding comes from 01 §15.\nmodel MessagingSettings {\n  organization_id                      String                   @id\n  /// 12 §13 — deletion policy.\n  allow_delete_own_messages            Boolean                  @default(true)\n  /// 12 §13 — minutes after sending during which the author may delete; null = any time.\n  delete_own_time_limit_minutes        Int?\n  allow_admin_delete_messages          Boolean                  @default(true)\n  /// 12 §13 — edit window in minutes; null = unlimited.\n  edit_time_limit_minutes              Int?\n  /// 12 §13 — keep message_versions on edit.\n  preserve_edit_history                Boolean                  @default(true)\n  /// 12 §14, §80 — allowed reaction emoji; empty = all.\n  allowed_reactions                    String[]                 @default([])\n  /// 12 §80 — custom emoji definitions [{ name, url }].\n  custom_emoji                         Json?\n  /// 12 §43, §53 — read receipts per conversation kind.\n  read_receipts_direct                 Boolean                  @default(true)\n  read_receipts_group                  Boolean                  @default(true)\n  read_receipts_customer               Boolean                  @default(false)\n  /// 12 §4, §53 — presence visibility: everyone | members | nobody.\n  presence_visibility                  String                   @default(\"everyone\")\n  /// 12 §80 — default per-channel notification level for new members.\n  default_notification_level           ChannelNotificationLevel @default(MENTIONS_AND_DIRECT)\n  /// 12 §80 — default channel slugs every new member joins (12 §9 organization-wide channels).\n  default_channel_ids                  String[]                 @default([])\n  /// 12 §80, §94 — naming rules: { prefix_rules: {PROJECT: \"project-\", CUSTOMER: \"customer-\"}, pattern, lowercase }.\n  channel_naming_rules                 Json?\n  /// 12 §80 — file limits: { max_file_size_bytes, allowed_mime_types[], blocked_extensions[] } (12 §69, §85).\n  file_policy                          Json?\n  /// 12 §27, §80 — external participants allowed at all.\n  external_access_enabled              Boolean                  @default(false)\n  /// 12 §82 — guest access and default guest expiry days.\n  guest_access_enabled                 Boolean                  @default(false)\n  guest_default_expiry_days            Int?\n  /// 12 §15, §80 — who may use @channel / @everyone: everyone | admins | owners.\n  broadcast_mention_policy             String                   @default(\"admins\")\n  /// 12 §29, §80 — who may create announcement channels / post announcements.\n  announcement_policy                  String                   @default(\"admins\")\n  /// 12 §26 — offer / auto-create a project channel on project creation (12 §93).\n  auto_create_project_channels         Boolean                  @default(false)\n  /// 12 §45, §71 — voice messages enabled.\n  voice_messages_enabled               Boolean                  @default(true)\n  /// 12 §44 — calls enabled and provider: internal | google_meet | zoom | teams | custom.\n  calls_enabled                        Boolean                  @default(false)\n  call_provider                        String?\n  /// 12 §69 — rate limits: { messages_per_minute, uploads_per_hour, api_requests_per_minute, integration_events_per_minute }.\n  rate_limits                          Json?\n  /// 12 §85 — sensitive content controls: { external_sharing_warning, prevent_external_forwarding, restricted_file_types[], dlp_provider }.\n  sensitive_content_controls           Json?\n  /// 12 §50 — admins may search private messages/DMs under policy.\n  admin_private_message_access_enabled Boolean                  @default(false)\n  /// 12 §87 — notification previews may include message text (user may further restrict).\n  notification_previews_include_text   Boolean                  @default(true)\n  /// 12 §33, §80 — default sidebar sections for new members [{ name, channel_ids[] }].\n  default_sections                     Json?\n  created_at                           DateTime                 @default(now())\n  updated_at                           DateTime                 @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"messaging_settings\")\n}\n\n/// 12 §54 — message retention policy. Scope precedence: CHANNEL > CHANNEL_KIND > TEAM > BRANCH > ORGANIZATION.\nmodel MessagingRetentionPolicy {\n  id                     String                   @id @default(uuid())\n  organization_id        String\n  name                   String\n  scope                  MessagingRetentionScope  @default(ORGANIZATION)\n  branch_id              String?\n  team_id                String?\n  /// Set when scope = CHANNEL_KIND.\n  channel_kind           ChannelKind?\n  action                 MessagingRetentionAction @default(UNLIMITED)\n  /// Days after creation before `action` applies; null for UNLIMITED.\n  retention_days         Int?\n  /// 12 §54 — the policy also applies to attachments (17 Documents are notified), reactions and metadata.\n  applies_to_attachments Boolean                  @default(true)\n  applies_to_reactions   Boolean                  @default(true)\n  applies_to_metadata    Boolean                  @default(false)\n  is_default             Boolean                  @default(false)\n  created_by_user_id     String?\n  last_applied_at        DateTime?\n  created_at             DateTime                 @default(now())\n  updated_at             DateTime                 @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch       Branch?      @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  channels     Channel[]\n\n  @@index([organization_id, scope])\n  @@index([branch_id])\n  @@index([team_id])\n  @@map(\"messaging_retention_policies\")\n}\n\n/// 12 §93 — templates for recurring communication spaces (new project channel, customer onboarding).\nmodel ChannelTemplate {\n  id                  String                 @id @default(uuid())\n  organization_id     String\n  name                String\n  description         String?\n  channel_kind        ChannelKind            @default(PROJECT)\n  trigger             ChannelTemplateTrigger @default(MANUAL)\n  /// 12 §94 — slug pattern, e.g. \"project-{project.slug}\" / \"customer-{company.slug}\".\n  name_pattern        String?\n  default_description String?\n  default_purpose     String?\n  default_topic       String?\n  posting_policy      ChannelPostingPolicy   @default(ALL_MEMBERS)\n  visibility          ChannelVisibility      @default(DISCOVERABLE)\n  external_access     Boolean                @default(false)\n  /// 12 §93 — required members: { roles: [PROJECT_MANAGER, ACCOUNT_MANAGER, ASSIGNED_EMPLOYEES, STAKEHOLDERS, CUSTOMER], team_ids[], membership_ids[] }.\n  member_rules        Json?\n  /// 12 §93 — messages posted and pinned on creation [{ body, pin: true }] (project overview, dashboard links, onboarding docs).\n  pinned_content      Json?\n  /// 12 §93 — standard discussion sections / threads to seed [{ title }].\n  discussion_sections Json?\n  /// 12 §95 — auto-archive rule: { after_project_completed_days, after_inactive_days }.\n  archive_rule        Json?\n  retention_policy_id String?\n  is_active           Boolean                @default(true)\n  created_by_user_id  String?\n  created_at          DateTime               @default(now())\n  updated_at          DateTime               @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  channels     Channel[]\n\n  @@unique([organization_id, name])\n  @@index([organization_id, trigger])\n  @@map(\"channel_templates\")\n}\n\n// --- Channels --------------------------------------------------------------------\n\n/// 12 §5–8, §25–29, §48 — every conversation: channels, DMs (DIRECT/GROUP_DIRECT), project and\n/// customer channels, announcement channels and record conversations (RECORD, entity_type/entity_id).\n/// Custom fields via custom_field_values, tags via taggings (RecordEntityType.CHANNEL).\nmodel Channel {\n  id                         String                    @id @default(uuid())\n  organization_id            String\n  kind                       ChannelKind\n  visibility                 ChannelVisibility         @default(DISCOVERABLE)\n  status                     ChannelStatus             @default(ACTIVE)\n  /// 12 §7, §94 — unique handle (#general); null for DMs and record conversations.\n  slug                       String?\n  /// 12 §7 — channel name; null for DMs (derived from participants).\n  name                       String?\n  display_name               String?\n  description                String?\n  purpose                    String?\n  /// 12 §48 — short current focus.\n  topic                      String?\n  icon_url                   String?\n  /// Emoji or icon key shown before the name.\n  icon                       String?\n  color                      String?\n  owner_membership_id        String?\n  created_by_membership_id   String?\n  /// 12 §3, §7 — Team / Branch scope.\n  team_id                    String?\n  /// 12 §9 — automatic membership rules (team / role based): { team_ids: string[], role_ids: string[], sync: boolean }. Members added by these rules get source TEAM / ROLE.\n  membership_rules           Json?\n  branch_id                  String?\n  /// 12 §7, §26 — associated project (PROJECT channels; also set on RECORD conversations of project items).\n  project_id                 String?\n  /// 12 §7, §27 — associated customer (CRM company) for CUSTOMER channels.\n  company_id                 String?\n  /// 12 §7, §25 — associated business record for RECORD conversations (task, deal, ticket (13), proposal …).\n  entity_type                RecordEntityType?\n  entity_id                  String?\n  /// 12 §7, §29, §49 — posting permissions.\n  posting_policy             ChannelPostingPolicy      @default(ALL_MEMBERS)\n  /// 12 §7, §27 — external participants (portal users / guests) may be added.\n  external_access_enabled    Boolean                   @default(false)\n  /// 12 §43 — read receipts for this conversation (null = organization default by kind).\n  read_receipts_enabled      Boolean?\n  /// 12 §7, §17 — default notification level for new members (null = organization default).\n  default_notification_level ChannelNotificationLevel?\n  /// 12 §9 — every new organization member is auto-joined (organization-wide channel).\n  auto_join                  Boolean                   @default(false)\n  /// 12 §29 — announcement messages in this channel require acknowledgement by default.\n  require_acknowledgement    Boolean                   @default(false)\n  /// 12 §85 — confidential label shown in the UI.\n  is_confidential            Boolean                   @default(false)\n  /// 12 §5 — stable key for DM de-duplication: sorted participant ids joined with \":\".\n  dm_key                     String?\n  /// 12 §54 — explicit retention policy; null = inherited.\n  retention_policy_id        String?\n  /// 12 §93 — template this channel was created from.\n  template_id                String?\n  /// 12 §2 — temporary conversations expire (12 §95 auto-archive).\n  expires_at                 DateTime?\n  auto_archive_at            DateTime?\n  archived_at                DateTime?\n  archived_by_user_id        String?\n  /// 12 §95 — reason: manual | project_completed | customer_inactive | expired | retention.\n  archive_reason             String?\n  deleted_at                 DateTime?\n  deleted_by_user_id         String?\n  /// Denormalized counters (12 §34, §77, §102).\n  member_count               Int                       @default(0)\n  message_count              Int                       @default(0)\n  last_message_at            DateTime?\n  /// 12 §37, §103 — integration ids connected to this channel (12 Integrations), plus misc settings.\n  settings                   Json?\n  created_at                 DateTime                  @default(now())\n  updated_at                 DateTime                  @updatedAt\n\n  organization     Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner            Membership?               @relation(\"ChannelOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  created_by       Membership?               @relation(\"ChannelCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  team             Team?                     @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  branch           Branch?                   @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  project          Project?                  @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  company          CrmCompany?               @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  retention_policy MessagingRetentionPolicy? @relation(fields: [retention_policy_id], references: [id], onDelete: SetNull)\n  template         ChannelTemplate?          @relation(fields: [template_id], references: [id], onDelete: SetNull)\n\n  members              ChannelMember[]\n  messages             Message[]\n  pins                 ChannelPin[]\n  read_states          ChannelReadState[]\n  drafts               MessageDraft[]\n  section_items        ChannelSectionItem[]\n  restrictions         ChannelMemberRestriction[]\n  calls                ChannelCall[]\n  attachments          MessageAttachment[]\n  mentions_in_messages MessageMention[]           @relation(\"MessageMentionChannel\")\n  integrations         MessagingIntegration[]     @relation(\"IntegrationDefaultChannel\")\n  webhooks             OutboundWebhook[]          @relation(\"WebhookChannelFilter\")\n  usage_stats          MessagingUsageDaily[]\n  primary_for_projects Project[]                  @relation(\"ProjectPrimaryChannel\")\n\n  @@unique([organization_id, slug])\n  @@unique([organization_id, dm_key])\n  @@unique([organization_id, entity_type, entity_id])\n  @@index([organization_id, kind, status])\n  @@index([organization_id, status, last_message_at])\n  @@index([project_id])\n  @@index([company_id])\n  @@index([team_id])\n  @@index([branch_id])\n  @@index([owner_membership_id])\n  @@index([auto_archive_at])\n  @@map(\"channels\")\n}\n\n/// 12 §9, §27, §82–83 — a participant of a channel: an internal Member (membership_id) or an external\n/// participant (external_user_id — Customer Portal User 01 §79 or guest 01 §77–78). Exactly one is set.\n/// Favorites, mute and last-viewed live here; notification settings in channel_notification_settings.\nmodel ChannelMember {\n  id                 String                  @id @default(uuid())\n  channel_id         String\n  membership_id      String?\n  external_user_id   String?\n  role               ChannelMemberRole       @default(MEMBER)\n  source             ChannelMembershipSource @default(MANUAL)\n  /// 12 §82 — set for guests / external participants.\n  guest_kind         ChannelGuestKind?\n  /// 12 §82 — guest access expires automatically.\n  access_expires_at  DateTime?\n  /// 12 §83 — identity marker shown next to external users (\"ACME Corp — Guest\").\n  external_label     String?\n  invited_by_user_id String?\n  joined_at          DateTime                @default(now())\n  left_at            DateTime?\n  removed_at         DateTime?\n  removed_by_user_id String?\n  /// 12 §33 — favorites and recently viewed.\n  is_favorite        Boolean                 @default(false)\n  last_viewed_at     DateTime?\n  /// 12 §17 — mute until (null = not muted; far future = indefinitely).\n  muted_until        DateTime?\n  /// 12 §93 — membership is required by the template / rule and cannot be left.\n  is_required        Boolean                 @default(false)\n  created_at         DateTime                @default(now())\n  updated_at         DateTime                @updatedAt\n\n  channel               Channel                     @relation(fields: [channel_id], references: [id], onDelete: Cascade)\n  membership            Membership?                 @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  external_user         User?                       @relation(\"ChannelExternalMember\", fields: [external_user_id], references: [id], onDelete: Cascade)\n  notification_settings ChannelNotificationSetting?\n\n  @@unique([channel_id, membership_id])\n  @@unique([channel_id, external_user_id])\n  @@index([membership_id, left_at])\n  @@index([external_user_id])\n  @@index([channel_id, role])\n  @@index([access_expires_at])\n  @@map(\"channel_members\")\n}\n\n/// 12 §17, §79, §90 — per-channel / per-conversation notification settings layered on the global\n/// preferences of 14 §6 (DND, quiet hours and delivery channels are evaluated by 14).\nmodel ChannelNotificationSetting {\n  channel_member_id          String                    @id\n  /// null = inherit channel default, then organization default.\n  level                      ChannelNotificationLevel?\n  notify_thread_replies      Boolean                   @default(true)\n  notify_reactions           Boolean                   @default(false)\n  notify_keywords            Boolean                   @default(true)\n  desktop_enabled            Boolean                   @default(true)\n  mobile_enabled             Boolean                   @default(true)\n  email_enabled              Boolean                   @default(false)\n  /// Sound key or null for silent.\n  sound                      String?\n  /// 12 §17 — per-channel schedule override: { days: [1..7], start: \"09:00\", end: \"18:00\", timezone }.\n  schedule                   Json?\n  digest_frequency           ChannelDigestFrequency    @default(NONE)\n  /// 12 §79 — notify immediately for customer (EXTERNAL) messages even when muted.\n  priority_customer_messages Boolean                   @default(false)\n  updated_at                 DateTime                  @updatedAt\n\n  channel_member ChannelMember @relation(fields: [channel_member_id], references: [id], onDelete: Cascade)\n\n  @@map(\"channel_notification_settings\")\n}\n\n/// 12 §49–50 — moderation restrictions: mute or ban a participant in one channel (channel_id set)\n/// or across the whole organization (channel_id null). Target is a Member or an external user.\nmodel ChannelMemberRestriction {\n  id                 String                 @id @default(uuid())\n  organization_id    String\n  channel_id         String?\n  membership_id      String?\n  external_user_id   String?\n  kind               ChannelRestrictionKind\n  reason             String?\n  /// null = until lifted.\n  expires_at         DateTime?\n  created_by_user_id String?\n  lifted_at          DateTime?\n  lifted_by_user_id  String?\n  created_at         DateTime               @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  channel      Channel?     @relation(fields: [channel_id], references: [id], onDelete: Cascade)\n  membership   Membership?  @relation(\"ChannelRestrictionTarget\", fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, kind, lifted_at])\n  @@index([channel_id, membership_id])\n  @@index([membership_id])\n  @@index([external_user_id])\n  @@map(\"channel_member_restrictions\")\n}\n\n// --- Messages --------------------------------------------------------------------\n\n/// 12 §10–13, §28, §29, §38, §75, §91 — the message. Thread replies set parent_message_id (root only,\n/// one level). Author is a Member, an external User, or an integration/bot (12 §38); SYSTEM messages\n/// have no author. Permalink = /messaging/c/{channel_id}/m/{id} (12 §65).\nmodel Message {\n  id                        String                   @id @default(uuid())\n  organization_id           String\n  channel_id                String\n  kind                      MessageKind              @default(USER)\n  visibility                MessageVisibility        @default(INTERNAL)\n  status                    MessageDeliveryStatus    @default(SENT)\n  author_membership_id      String?\n  /// 12 §27 — external participant author (Customer Portal User / guest).\n  author_user_id            String?\n  /// 12 §38 — integration or bot that posted the message.\n  integration_id            String?\n  /// 12 §11, §35 — markdown source.\n  body                      String\n  /// Structured rich-text document (editor JSON) when available.\n  body_rich                 Json?\n  /// Plain text rendering for search and notification previews (12 §30, §87).\n  body_plain                String?\n  /// 12 §12 — thread root; null for top-level messages.\n  parent_message_id         String?\n  reply_count               Int                      @default(0)\n  last_reply_at             DateTime?\n  /// 12 §11 — quoted message.\n  quoted_message_id         String?\n  /// 12 §11, §64 — forwarded / shared from another message.\n  forwarded_from_message_id String?\n  /// 12 §11 — scheduled messages: send at this time (status SCHEDULED until sent).\n  scheduled_for             DateTime?\n  sent_at                   DateTime?\n  /// 12 §29 — important styling and acknowledgement tracking for announcements.\n  is_announcement           Boolean                  @default(false)\n  requires_acknowledgement  Boolean                  @default(false)\n  /// 12 §13 — edit state; versions in message_versions when the organization preserves history.\n  is_edited                 Boolean                  @default(false)\n  edited_at                 DateTime?\n  deleted_at                DateTime?\n  deleted_by_user_id        String?\n  /// 12 §13, §49 — self | admin | retention | moderation.\n  delete_reason             String?\n  /// 12 §47 — denormalized pin state (source of truth: channel_pins).\n  pinned_at                 DateTime?\n  /// 12 §91 — system event key (member_joined, member_left, channel_renamed, channel_archived, integration_connected, project_linked, customer_added, call_started …).\n  system_event              String?\n  /// 12 §38 — external source shown on integration messages (e.g. \"GitHub\") and the provider event id for idempotency.\n  integration_source        String?\n  external_event_id         String?\n  /// 12 §39, §76 — client-generated idempotency key.\n  client_message_id         String?\n  /// 12 §30 — search facets.\n  has_attachments           Boolean                  @default(false)\n  has_links                 Boolean                  @default(false)\n  has_record_shares         Boolean                  @default(false)\n  reaction_count            Int                      @default(0)\n  /// 12 §10 — free-form metadata (integration payload, formatting hints, failure reason).\n  metadata                  Json?\n  created_at                DateTime                 @default(now())\n  updated_at                DateTime                 @updatedAt\n  /// 12 §30 — Postgres full-text search vector over body_plain; maintained by a database trigger (see migration). Not set by the API.\n  search_vector             Unsupported(\"tsvector\")?\n\n  organization   Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  channel        Channel               @relation(fields: [channel_id], references: [id], onDelete: Cascade)\n  author         Membership?           @relation(\"MessageAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n  author_user    User?                 @relation(\"MessageExternalAuthor\", fields: [author_user_id], references: [id], onDelete: SetNull)\n  integration    MessagingIntegration? @relation(fields: [integration_id], references: [id], onDelete: SetNull)\n  parent         Message?              @relation(\"MessageThread\", fields: [parent_message_id], references: [id], onDelete: Cascade)\n  replies        Message[]             @relation(\"MessageThread\")\n  quoted         Message?              @relation(\"MessageQuote\", fields: [quoted_message_id], references: [id], onDelete: SetNull)\n  quoted_by      Message[]             @relation(\"MessageQuote\")\n  forwarded_from Message?              @relation(\"MessageForward\", fields: [forwarded_from_message_id], references: [id], onDelete: SetNull)\n  forwards       Message[]             @relation(\"MessageForward\")\n\n  versions          MessageVersion[]\n  reactions         MessageReaction[]\n  mentions          MessageMention[]\n  attachments       MessageAttachment[]\n  link_previews     MessageLinkPreview[]\n  record_shares     MessageRecordShare[]\n  acknowledgements  MessageAcknowledgement[]\n  read_receipts     MessageReadReceipt[]\n  thread_followers  MessageThreadFollower[]\n  pins              ChannelPin[]\n  saved_by          SavedMessage[]\n  reminders         MessageReminder[]\n  reports           MessageReport[]\n  drafts_replying   MessageDraft[]           @relation(\"DraftThreadRoot\")\n  last_read_in      ChannelReadState[]       @relation(\"ReadStateLastMessage\")\n  unread_from_in    ChannelReadState[]       @relation(\"ReadStateUnreadFrom\")\n  calls             ChannelCall[]\n  project_decisions ProjectDecision[]        @relation(\"ProjectDecisionSourceMessage\")\n\n  @@unique([channel_id, client_message_id])\n  @@unique([integration_id, external_event_id])\n  @@index([search_vector], type: Gin)\n  @@index([channel_id, created_at])\n  @@index([channel_id, parent_message_id, created_at])\n  @@index([parent_message_id])\n  @@index([organization_id, author_membership_id, created_at])\n  @@index([organization_id, status, scheduled_for])\n  @@index([organization_id, kind])\n  @@index([author_user_id])\n  @@map(\"messages\")\n}\n\n/// 12 §13 — edit history (previous bodies) when the organization preserves it.\nmodel MessageVersion {\n  id                String   @id @default(uuid())\n  message_id        String\n  version           Int\n  body              String\n  body_rich         Json?\n  edited_by_user_id String?\n  /// When this version was superseded.\n  created_at        DateTime @default(now())\n\n  message Message @relation(fields: [message_id], references: [id], onDelete: Cascade)\n\n  @@unique([message_id, version])\n  @@map(\"message_versions\")\n}\n\n/// 12 §14 — emoji reactions; one per (message, emoji, reactor). Reactor is a Member or an external user.\nmodel MessageReaction {\n  id               String   @id @default(uuid())\n  message_id       String\n  /// Unicode emoji or custom emoji name (12 §80).\n  emoji            String\n  membership_id    String?\n  /// External participant reactor (01 §79); id only.\n  external_user_id String?\n  created_at       DateTime @default(now())\n\n  message    Message     @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  membership Membership? @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([message_id, emoji, membership_id])\n  @@unique([message_id, emoji, external_user_id])\n  @@index([membership_id])\n  @@map(\"message_reactions\")\n}\n\n/// 12 §15 — mentions extracted from a message; drives notifications (14) and mention counts (12 §19).\nmodel MessageMention {\n  id                   String             @id @default(uuid())\n  message_id           String\n  kind                 MessageMentionKind\n  membership_id        String?\n  /// External participant mentioned (01 §79); id only.\n  external_user_id     String?\n  team_id              String?\n  role_id              String?\n  /// CHANNEL_LINK target (#channel).\n  mentioned_channel_id String?\n  created_at           DateTime           @default(now())\n\n  message           Message     @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  membership        Membership? @relation(\"MessageMentionMember\", fields: [membership_id], references: [id], onDelete: Cascade)\n  team              Team?       @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  role              Role?       @relation(fields: [role_id], references: [id], onDelete: Cascade)\n  mentioned_channel Channel?    @relation(\"MessageMentionChannel\", fields: [mentioned_channel_id], references: [id], onDelete: Cascade)\n\n  @@index([message_id])\n  @@index([membership_id, created_at])\n  @@index([team_id])\n  @@index([role_id])\n  @@index([external_user_id])\n  @@map(\"message_mentions\")\n}\n\n/// 12 §22, §45 — link between a message and a Document (17). File bytes, versions and access\n/// permissions are owned by 17; metadata is denormalized here for listing \"files in channel\".\n/// Vault entries (17 §12) cannot be attached.\nmodel MessageAttachment {\n  id                  String                @id @default(uuid())\n  message_id          String\n  channel_id          String\n  /// 17 Document — the stored file.\n  document_id         String\n  kind                MessageAttachmentKind @default(OTHER)\n  file_name           String\n  mime_type           String?\n  size_bytes          Int?\n  /// 12 §45 — voice message / audio duration.\n  duration_seconds    Int?\n  /// 12 §22 — preview data: { thumbnail_url, width, height, waveform[] }.\n  preview             Json?\n  uploaded_by_user_id String?\n  sort_order          Int                   @default(0)\n  created_at          DateTime              @default(now())\n\n  message Message @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  channel Channel @relation(fields: [channel_id], references: [id], onDelete: Cascade)\n\n  @@unique([message_id, document_id])\n  @@index([channel_id, created_at])\n  @@index([channel_id, kind])\n  @@index([document_id])\n  @@map(\"message_attachments\")\n}\n\n/// 12 §23 — unfurled link previews. Internal application links resolve to a record (entity_type/entity_id)\n/// and are rendered with a permission check at view time.\nmodel MessageLinkPreview {\n  id          String                   @id @default(uuid())\n  message_id  String\n  url         String\n  domain      String?\n  title       String?\n  description String?\n  image_url   String?\n  status      MessageLinkPreviewStatus @default(PENDING)\n  /// Internal link target (12 §23 — projects, tasks, customers, contacts, deals, proposals, contracts, invoices, payments, tickets, documents).\n  entity_type RecordEntityType?\n  entity_id   String?\n  fetched_at  DateTime?\n  sort_order  Int                      @default(0)\n  created_at  DateTime                 @default(now())\n\n  message Message @relation(fields: [message_id], references: [id], onDelete: Cascade)\n\n  @@unique([message_id, url])\n  @@index([entity_type, entity_id])\n  @@map(\"message_link_previews\")\n}\n\n/// 12 §24, §58–60 — a business record shared into a conversation with a preview snapshot.\n/// Record access is re-checked when rendered; the snapshot is only a display cache.\nmodel MessageRecordShare {\n  id                String           @id @default(uuid())\n  message_id        String\n  entity_type       RecordEntityType\n  entity_id         String\n  /// 12 §24 — { name, status, owner, summary, metadata } captured at share time.\n  snapshot          Json?\n  snapshot_at       DateTime?\n  shared_by_user_id String?\n  sort_order        Int              @default(0)\n  created_at        DateTime         @default(now())\n\n  message Message @relation(fields: [message_id], references: [id], onDelete: Cascade)\n\n  @@unique([message_id, entity_type, entity_id])\n  @@index([entity_type, entity_id])\n  @@map(\"message_record_shares\")\n}\n\n/// 12 §29 — acknowledgement of an announcement that requires it.\nmodel MessageAcknowledgement {\n  message_id      String\n  membership_id   String\n  acknowledged_at DateTime @default(now())\n\n  message    Message    @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([message_id, membership_id])\n  @@index([membership_id])\n  @@map(\"message_acknowledgements\")\n}\n\n// --- Read state, threads, personal items ----------------------------------------------\n\n/// 12 §19, §43 — per-participant read position in a channel (unread state for channels, read state for DMs).\n/// Participant is a Member or an external user (id only).\nmodel ChannelReadState {\n  id                    String    @id @default(uuid())\n  channel_id            String\n  membership_id         String?\n  external_user_id      String?\n  last_read_message_id  String?\n  last_read_at          DateTime?\n  /// 12 §19 — \"mark unread\" from this message onward.\n  marked_unread_from_id String?\n  /// Denormalized counters, recomputed on write.\n  unread_count          Int       @default(0)\n  mention_count         Int       @default(0)\n  updated_at            DateTime  @updatedAt\n\n  channel            Channel     @relation(fields: [channel_id], references: [id], onDelete: Cascade)\n  membership         Membership? @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  last_read_message  Message?    @relation(\"ReadStateLastMessage\", fields: [last_read_message_id], references: [id], onDelete: SetNull)\n  marked_unread_from Message?    @relation(\"ReadStateUnreadFrom\", fields: [marked_unread_from_id], references: [id], onDelete: SetNull)\n\n  @@unique([channel_id, membership_id])\n  @@unique([channel_id, external_user_id])\n  @@index([membership_id, unread_count])\n  @@map(\"channel_read_states\")\n}\n\n/// 12 §43 — per-message read receipts for DMs, group conversations and (when configured) customer conversations.\nmodel MessageReadReceipt {\n  message_id    String\n  /// Member id or external user id (one participant id; both kinds share the key space).\n  reader_id     String\n  membership_id String?\n  read_at       DateTime @default(now())\n\n  message    Message     @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  membership Membership? @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([message_id, reader_id])\n  @@index([membership_id, read_at])\n  @@map(\"message_read_receipts\")\n}\n\n/// 12 §12, §88 — members following a thread (root message) without subscribing to the channel.\nmodel MessageThreadFollower {\n  root_message_id String\n  membership_id   String\n  /// Follow without notifications.\n  muted           Boolean   @default(false)\n  /// 12 §88 — mark thread read.\n  last_read_at    DateTime?\n  /// auto (replied/mentioned) | manual\n  source          String    @default(\"auto\")\n  created_at      DateTime  @default(now())\n\n  root_message Message    @relation(fields: [root_message_id], references: [id], onDelete: Cascade)\n  membership   Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([root_message_id, membership_id])\n  @@index([membership_id, created_at])\n  @@map(\"message_thread_followers\")\n}\n\n/// 12 §47 — pinned messages per channel.\nmodel ChannelPin {\n  id                      String   @id @default(uuid())\n  channel_id              String\n  message_id              String\n  pinned_by_membership_id String?\n  sort_order              Int      @default(0)\n  created_at              DateTime @default(now())\n\n  channel   Channel     @relation(fields: [channel_id], references: [id], onDelete: Cascade)\n  message   Message     @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  pinned_by Membership? @relation(\"ChannelPinner\", fields: [pinned_by_membership_id], references: [id], onDelete: SetNull)\n\n  @@unique([channel_id, message_id])\n  @@index([pinned_by_membership_id])\n  @@map(\"channel_pins\")\n}\n\n/// 12 §20 — personal saved/bookmarked messages with an optional note.\nmodel SavedMessage {\n  id            String   @id @default(uuid())\n  membership_id String\n  message_id    String\n  note          String?\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  message    Message    @relation(fields: [message_id], references: [id], onDelete: Cascade)\n\n  @@unique([membership_id, message_id])\n  @@index([membership_id, created_at])\n  @@map(\"saved_messages\")\n}\n\n/// 12 §20–21 — \"remind me\" on a message; triggers a notification (14) linking back to the message.\nmodel MessageReminder {\n  id              String                @id @default(uuid())\n  organization_id String\n  membership_id   String\n  message_id      String\n  remind_at       DateTime\n  /// later_today | tomorrow | next_week | custom\n  preset          String?\n  note            String?\n  status          MessageReminderStatus @default(PENDING)\n  triggered_at    DateTime?\n  completed_at    DateTime?\n  /// 14 Notification id emitted when triggered; id only.\n  notification_id String?\n  created_at      DateTime              @default(now())\n  updated_at      DateTime              @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership   Membership   @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  message      Message      @relation(fields: [message_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, status, remind_at])\n  @@index([membership_id, status])\n  @@index([message_id])\n  @@map(\"message_reminders\")\n}\n\n/// 12 §46, §74 — unsent messages, private to the author, one per channel (+ thread) per author.\nmodel MessageDraft {\n  id                      String    @id @default(uuid())\n  channel_id              String\n  membership_id           String\n  /// Draft reply inside a thread.\n  thread_root_message_id  String?\n  body                    String\n  body_rich               Json?\n  /// 17 Document ids already uploaded for this draft.\n  attachment_document_ids String[]  @default([])\n  /// Draft of a scheduled message (12 §11).\n  scheduled_for           DateTime?\n  created_at              DateTime  @default(now())\n  updated_at              DateTime  @updatedAt\n\n  channel     Channel    @relation(fields: [channel_id], references: [id], onDelete: Cascade)\n  membership  Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  thread_root Message?   @relation(\"DraftThreadRoot\", fields: [thread_root_message_id], references: [id], onDelete: Cascade)\n\n  @@unique([channel_id, membership_id, thread_root_message_id])\n  @@index([membership_id, updated_at])\n  @@map(\"message_drafts\")\n}\n\n/// 12 §32, §79 — keyword subscriptions; matches in authorized conversations notify the member (14).\nmodel MessagingKeyword {\n  id               String    @id @default(uuid())\n  organization_id  String\n  membership_id    String\n  keyword          String\n  match_whole_word Boolean   @default(true)\n  case_sensitive   Boolean   @default(false)\n  /// 12 §32 — temporarily disabled.\n  is_enabled       Boolean   @default(true)\n  disabled_until   DateTime?\n  created_at       DateTime  @default(now())\n  updated_at       DateTime  @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership   Membership   @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([membership_id, keyword])\n  @@index([organization_id, is_enabled])\n  @@map(\"messaging_keywords\")\n}\n\n/// 12 §33, §72 — a member's custom sidebar sections (My Projects, Sales, …). Built-in groups\n/// (favorites, DMs, channels, projects, customers, archived, unread) are computed, not stored.\nmodel ChannelSection {\n  id              String   @id @default(uuid())\n  organization_id String\n  membership_id   String\n  name            String\n  icon            String?\n  sort_order      Int      @default(0)\n  is_collapsed    Boolean  @default(false)\n  created_at      DateTime @default(now())\n  updated_at      DateTime @updatedAt\n\n  organization Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership   Membership           @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  items        ChannelSectionItem[]\n\n  @@unique([membership_id, name])\n  @@index([membership_id, sort_order])\n  @@map(\"channel_sections\")\n}\n\n/// 12 §33 — a channel placed in a member's custom section.\nmodel ChannelSectionItem {\n  section_id String\n  channel_id String\n  sort_order Int      @default(0)\n  created_at DateTime @default(now())\n\n  section ChannelSection @relation(fields: [section_id], references: [id], onDelete: Cascade)\n  channel Channel        @relation(fields: [channel_id], references: [id], onDelete: Cascade)\n\n  @@id([section_id, channel_id])\n  @@index([channel_id])\n  @@map(\"channel_section_items\")\n}\n\n// --- Presence & member settings ---------------------------------------------------------\n\n/// 12 §4, §41 — presence and custom status, one row per Member. Visibility follows organization\n/// privacy settings (messaging_settings.presence_visibility) and the member's own override.\nmodel MessagingPresence {\n  membership_id      String                  @id\n  organization_id    String\n  state              MessagingPresenceState  @default(OFFLINE)\n  /// Manually chosen state (Away / Do Not Disturb) that overrides automatic detection until cleared.\n  manual_state       MessagingPresenceState?\n  manual_state_until DateTime?\n  /// 12 §4 — custom status.\n  status_text        String?\n  status_emoji       String?\n  status_starts_at   DateTime?\n  status_ends_at     DateTime?\n  /// 12 §4 — automatic expiration of the custom status.\n  status_expires_at  DateTime?\n  last_seen_at       DateTime?\n  /// Number of live connections (websocket sessions) currently open.\n  active_connections Int                     @default(0)\n  /// 12 §53 — member hides presence from others.\n  presence_hidden    Boolean                 @default(false)\n  updated_at         DateTime                @updatedAt\n\n  membership   Membership   @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, state])\n  @@map(\"messaging_presence\")\n}\n\n/// 12 §17, §43, §53, §73, §87 — messaging-specific per-member defaults. Global notification\n/// preferences, DND and digests are 14 §6 (NotificationPreference); only messaging-local settings live here.\nmodel MessagingMemberSettings {\n  membership_id                   String                    @id\n  /// 12 §17 — default level applied to channels the member joins.\n  default_channel_level           ChannelNotificationLevel?\n  default_dm_level                ChannelNotificationLevel?\n  /// 12 §87 — include message text in notification previews.\n  notification_previews_with_text Boolean                   @default(true)\n  notification_sound              String?\n  /// 12 §43, §53 — send read receipts to others.\n  share_read_receipts             Boolean                   @default(true)\n  /// 12 §41 — show typing indicator to others.\n  share_typing_indicator          Boolean                   @default(true)\n  /// 12 §73 — keyboard shortcut overrides { action: keys }.\n  keyboard_shortcuts              Json?\n  /// 12 §72 — sidebar layout preferences (collapsed built-in groups, sort mode, theme density).\n  sidebar_preferences             Json?\n  /// 12 §11 — send on Enter vs Cmd+Enter, markdown mode, emoji skin tone.\n  composer_preferences            Json?\n  updated_at                      DateTime                  @updatedAt\n\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@map(\"messaging_member_settings\")\n}\n\n// --- Moderation ----------------------------------------------------------------------\n\n/// 12 §49–50, §64, §69 — a message reported by a participant or flagged by spam detection.\nmodel MessageReport {\n  id                     String              @id @default(uuid())\n  organization_id        String\n  message_id             String\n  reporter_membership_id String?\n  /// External participant reporter; id only.\n  reporter_user_id       String?\n  /// spam | abuse | sensitive_data | off_topic | other | automated\n  reason                 String\n  details                String?\n  status                 MessageReportStatus @default(OPEN)\n  reviewed_by_user_id    String?\n  reviewed_at            DateTime?\n  /// none | message_deleted | member_muted | member_banned | member_removed | warning\n  action_taken           String?\n  resolution_note        String?\n  created_at             DateTime            @default(now())\n  updated_at             DateTime            @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  message      Message      @relation(fields: [message_id], references: [id], onDelete: Cascade)\n  reporter     Membership?  @relation(\"MessageReportReporter\", fields: [reporter_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status, created_at])\n  @@index([message_id])\n  @@index([reporter_membership_id])\n  @@map(\"message_reports\")\n}\n\n// --- Retention & export ----------------------------------------------------------------\n\n/// 12 §55, §106 — administrator export of messaging data; the produced file is a Document (17).\nmodel MessagingExportJob {\n  id                         String                @id @default(uuid())\n  organization_id            String\n  requested_by_membership_id String?\n  status                     MessagingExportStatus @default(PENDING)\n  format                     MessagingExportFormat @default(JSON)\n  /// 12 §55 — scope: { branch_id, team_id, channel_ids[], channel_kinds[], membership_id, date_from, date_to, include_attachments_metadata, include_reactions, include_threads }.\n  filters                    Json\n  started_at                 DateTime?\n  completed_at               DateTime?\n  /// 17 Document holding the export archive; id only.\n  result_document_id         String?\n  /// Download link expiry.\n  expires_at                 DateTime?\n  message_count              Int?\n  channel_count              Int?\n  error                      String?\n  created_at                 DateTime              @default(now())\n  updated_at                 DateTime              @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  requested_by Membership?  @relation(\"MessagingExportRequester\", fields: [requested_by_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status, created_at])\n  @@index([requested_by_membership_id])\n  @@map(\"messaging_export_jobs\")\n}\n\n// --- Integrations, bots & webhooks -----------------------------------------------------\n\n/// 12 §37–38, §50, §61, §92 — an integration or bot allowed to post into channels. Inbound webhook\n/// integrations authenticate with a hashed token; provider integrations hold their config. Internal\n/// module events (finance, CRM, projects …) arrive through 20 Automation \"post message\" actions.\nmodel MessagingIntegration {\n  id                    String                     @id @default(uuid())\n  organization_id       String\n  kind                  MessagingIntegrationKind\n  status                MessagingIntegrationStatus @default(ACTIVE)\n  name                  String\n  description           String?\n  /// Bot identity shown on messages (12 §38 — clearly marked as external source).\n  bot_display_name      String?\n  bot_avatar_url        String?\n  /// Default target channel; integrations may also target channels per event.\n  default_channel_id    String?\n  /// Channel ids this integration may post to; empty = default channel only.\n  allowed_channel_ids   String[]                   @default([])\n  /// Inbound webhook token hash (never plain text); provider credentials are stored in config encrypted.\n  inbound_token_hash    String?\n  /// Provider configuration: repositories, projects, event filters, mapping rules.\n  config                Json?\n  /// 12 §92 — subscribed event keys (github.pull_request.opened, finance.invoice.paid …).\n  subscribed_events     String[]                   @default([])\n  /// 12 §69 — integration rate limit (events per minute); null = organization default.\n  rate_limit_per_minute Int?\n  /// 20 OutboundWebhook / AutomationRule backing this integration when managed by the Automation Engine; id only.\n  automation_rule_id    String?\n  created_by_user_id    String?\n  last_event_at         DateTime?\n  last_error            String?\n  last_error_at         DateTime?\n  disconnected_at       DateTime?\n  created_at            DateTime                   @default(now())\n  updated_at            DateTime                   @updatedAt\n\n  organization    Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_channel Channel?     @relation(\"IntegrationDefaultChannel\", fields: [default_channel_id], references: [id], onDelete: SetNull)\n  messages        Message[]\n\n  @@unique([organization_id, name])\n  @@index([organization_id, kind, status])\n  @@index([default_channel_id])\n  @@map(\"messaging_integrations\")\n}\n\n// --- Calls -------------------------------------------------------------------------\n\n/// 12 §5, §44 — voice/video calls and huddles started from a conversation. Media is provided by an\n/// external provider or 19 Calendar meeting links; messaging keeps history and participants.\nmodel ChannelCall {\n  id                       String            @id @default(uuid())\n  organization_id          String\n  channel_id               String\n  kind                     ChannelCallKind   @default(VOICE)\n  status                   ChannelCallStatus @default(RINGING)\n  started_by_membership_id String?\n  title                    String?\n  /// Provider: internal | google_meet | zoom | teams | custom.\n  provider                 String?\n  meeting_url              String?\n  external_ref             String?\n  /// 19 CalendarEvent when scheduled as a meeting; id only.\n  calendar_event_id        String?\n  /// System message announcing the call (12 §91).\n  message_id               String?\n  screen_sharing_used      Boolean           @default(false)\n  started_at               DateTime          @default(now())\n  ended_at                 DateTime?\n  duration_seconds         Int?\n  /// 17 Document holding the recording, if any; id only.\n  recording_document_id    String?\n  participant_count        Int               @default(0)\n  created_at               DateTime          @default(now())\n  updated_at               DateTime          @updatedAt\n\n  organization Organization             @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  channel      Channel                  @relation(fields: [channel_id], references: [id], onDelete: Cascade)\n  started_by   Membership?              @relation(\"ChannelCallStarter\", fields: [started_by_membership_id], references: [id], onDelete: SetNull)\n  message      Message?                 @relation(fields: [message_id], references: [id], onDelete: SetNull)\n  participants ChannelCallParticipant[]\n\n  @@index([organization_id, status])\n  @@index([channel_id, started_at])\n  @@index([started_by_membership_id])\n  @@map(\"channel_calls\")\n}\n\n/// 12 §44 — call participants (Members or external users).\nmodel ChannelCallParticipant {\n  id               String    @id @default(uuid())\n  call_id          String\n  membership_id    String?\n  /// External participant (01 §79); id only.\n  external_user_id String?\n  invited_at       DateTime  @default(now())\n  joined_at        DateTime?\n  left_at          DateTime?\n  /// invited | joined | declined | missed | left\n  state            String    @default(\"invited\")\n\n  call       ChannelCall @relation(fields: [call_id], references: [id], onDelete: Cascade)\n  membership Membership? @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([call_id, membership_id])\n  @@unique([call_id, external_user_id])\n  @@index([membership_id, joined_at])\n  @@map(\"channel_call_participants\")\n}\n\n// --- Analytics -----------------------------------------------------------------------\n\n/// 12 §66, §104 — daily usage aggregates per organization (channel_id null) and per channel.\n/// Usage-oriented, never per-employee productivity scoring.\nmodel MessagingUsageDaily {\n  id                      String   @id @default(uuid())\n  organization_id         String\n  channel_id              String?\n  date                    DateTime @db.Date\n  messages_count          Int      @default(0)\n  direct_messages_count   Int      @default(0)\n  threads_count           Int      @default(0)\n  thread_replies_count    Int      @default(0)\n  reactions_count         Int      @default(0)\n  files_count             Int      @default(0)\n  files_bytes             BigInt   @default(0)\n  active_members_count    Int      @default(0)\n  active_channels_count   Int      @default(0)\n  external_messages_count Int      @default(0)\n  mentions_count          Int      @default(0)\n  /// 12 §66 — average time to first reply in seconds, where appropriate.\n  avg_response_seconds    Int?\n  /// 12 §66 — total unread volume snapshot at end of day.\n  unread_snapshot         Int?\n  created_at              DateTime @default(now())\n  updated_at              DateTime @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  channel      Channel?     @relation(fields: [channel_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, channel_id, date])\n  @@index([organization_id, date])\n  @@map(\"messaging_usage_daily\")\n}\n\n// =====================================================================\n// 13 Customer Support & Communication Hub — docs/features/13-customer-support-communication-hub.md (LOG-342)\n// Owns: support inboxes and channels (live chat, email, widget, portal, forms), support Conversations and\n// their messages, Tickets (statuses, categories, relations, followers, attachments), SLA policies/timers,\n// ticket status history, ticket↔task links, CSAT, canned responses, the customer-facing knowledge base,\n// AI agent sessions/suggestions and support incidents. Every portal request (07) is a Ticket here.\n// Does not own: Tasks (06), Projects/Change Requests (05), CRM companies/contacts and the Customer 360\n// timeline (02, derived from audit_events + these tables), internal chat (12), outbound email/SMS (11),\n// notifications (14), documents (17), time on tickets (18), the automation rules engine and scheduled\n// jobs (20 — referenced by plain ids), internal knowledge (15). Tags, custom fields, saved views → 02.\n// =====================================================================\n\n/// 13 §1, §5 — channel through which a customer conversation arrives.\nenum SupportChannelType {\n  LIVE_CHAT\n  EMAIL\n  WIDGET\n  PORTAL\n  FORM\n  API\n  PHONE\n}\n\n/// 13 §1 — conversation status (Open, Pending, Snoozed, Resolved).\nenum SupportConversationStatus {\n  OPEN\n  PENDING\n  SNOOZED\n  RESOLVED\n}\n\n/// 13 §1, §2 — who wrote a message: customer, agent (public reply), private internal note, the AI agent, or system.\nenum SupportMessageKind {\n  CUSTOMER\n  AGENT\n  INTERNAL_NOTE\n  AI_AGENT\n  SYSTEM\n}\n\n/// 13 §1, §10 — outbound delivery state of an agent reply sent through 11 (email) or the widget.\nenum SupportMessageDeliveryStatus {\n  PENDING\n  SENT\n  DELIVERED\n  FAILED\n  BOUNCED\n}\n\n/// 13 §1 — role of an internal participant on a conversation.\nenum SupportParticipantRole {\n  ASSIGNEE\n  COLLABORATOR\n  MENTIONED\n}\n\n/// 13 §2 — priority levels (Low, Normal, High, Urgent). Also used for conversation prioritization (§1).\nenum TicketPriority {\n  LOW\n  NORMAL\n  HIGH\n  URGENT\n}\n\n/// 13 §2, §13 — semantic category of a configurable ticket status.\nenum TicketStatusCategory {\n  NEW\n  OPEN\n  PENDING_CUSTOMER\n  ON_HOLD\n  RESOLVED\n  CLOSED\n}\n\n/// 13 §3, §5 — request/issue type (portal request types + AI issue types).\nenum TicketType {\n  QUESTION\n  BUG\n  FEATURE_REQUEST\n  CHANGE_REQUEST\n  BILLING\n  ACCOUNT\n  INCIDENT\n  OTHER\n}\n\n/// 13 §2 — where the ticket was created from.\nenum TicketSource {\n  CONVERSATION\n  EMAIL\n  LIVE_CHAT\n  WIDGET\n  PORTAL\n  FORM\n  AI_AGENT\n  MANUAL\n  API\n}\n\n/// 13 §2, §3 — relationships between tickets (related, duplicate, blocks, same incident).\nenum TicketRelationType {\n  RELATED\n  DUPLICATE_OF\n  BLOCKS\n  SAME_INCIDENT\n}\n\n/// 13 §4 — how a ticket is tied to a Task (06): converted (task created from the ticket) or linked to an existing task.\nenum TicketTaskLinkKind {\n  CONVERTED\n  LINKED\n}\n\n/// 13 §2 — SLA metrics tracked per ticket.\nenum SlaMetric {\n  FIRST_RESPONSE\n  NEXT_RESPONSE\n  RESOLUTION\n}\n\n/// 13 §2, §7 — lifecycle of one SLA timer.\nenum SlaTimerStatus {\n  RUNNING\n  PAUSED\n  MET\n  BREACHED\n  CANCELLED\n}\n\n/// 13 §3 — detected customer sentiment.\nenum SupportSentiment {\n  POSITIVE\n  NEUTRAL\n  NEGATIVE\n  FRUSTRATED\n}\n\n/// 13 §6 — article lifecycle.\nenum KnowledgeArticleStatus {\n  DRAFT\n  IN_REVIEW\n  PUBLISHED\n  ARCHIVED\n}\n\n/// 13 §6 — public (help center, no login), customers (portal users only), internal (agents only).\nenum KnowledgeVisibility {\n  PUBLIC\n  CUSTOMERS\n  INTERNAL\n}\n\n/// 13 §1 — who may use a canned response.\nenum SupportCannedResponseScope {\n  PERSONAL\n  TEAM\n  ORGANIZATION\n}\n\n/// 13 §3 — AI agent session lifecycle (automated first-line support with human handover).\nenum SupportAiSessionStatus {\n  ACTIVE\n  RESOLVED_BY_AI\n  HANDED_OVER\n  ABANDONED\n  FAILED\n}\n\n/// 13 §3 — kinds of AI output that wait for (or bypass) human approval.\nenum SupportAiSuggestionKind {\n  CLASSIFICATION\n  PRIORITY\n  ASSIGNMENT\n  REPLY\n  REWRITE\n  SUMMARY\n  TRANSLATION\n  ARTICLE_RECOMMENDATION\n  FOLLOW_UP_QUESTION\n  TROUBLESHOOTING\n  ACTION_ITEMS\n  DUPLICATE_TICKET\n  TASK_CREATION\n  KNOWLEDGE_GAP\n  ARTICLE_DRAFT\n  INCIDENT_GROUPING\n  FEEDBACK_EXTRACTION\n}\n\n/// 13 §3 — approval state of an AI suggestion.\nenum SupportAiSuggestionStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n  AUTO_APPLIED\n  EXPIRED\n}\n\n/// 13 §3, §9 — grouped incident / recurring problem status.\nenum SupportIncidentStatus {\n  DETECTED\n  CONFIRMED\n  RESOLVED\n  DISMISSED\n}\n\n// --- Settings ----------------------------------------------------------------------\n\n/// 13 §2, §3, §7 — per-organization support configuration: ticket numbering, auto-close / inactivity\n/// periods, CSAT, AI thresholds and approval requirements. Rules themselves live in 20.\nmodel SupportSettings {\n  organization_id            String   @id\n  /// Prefix for ticket references (e.g. \"SUP\"); the counter is number_sequences (03) with key \"ticket\".\n  ticket_prefix              String   @default(\"SUP\")\n  default_sla_policy_id      String?\n  default_inbox_id           String?\n  /// 13 §7 — auto-close resolved tickets after N days (null = never); registered as a scheduled job (20).\n  auto_close_after_days      Int?\n  /// 13 §7 — flag a ticket as inactive after N hours without a reply (null = off).\n  inactivity_after_hours     Int?\n  /// 13 §7 — customer may reopen a resolved ticket within N days (null = always).\n  reopen_window_days         Int?\n  /// 13 §9 — request a CSAT rating when a ticket is resolved.\n  csat_enabled               Boolean  @default(true)\n  csat_delay_minutes         Int      @default(0)\n  /// 13 §3 — AI agent enabled for customer-facing channels.\n  ai_agent_enabled           Boolean  @default(false)\n  /// 13 §3 — AI model through the shared AI layer (Product_Specification §6); JEV by default.\n  ai_model                   String   @default(\"jev\")\n  /// 13 §3 — minimum confidence (0–1) to auto-apply classification / assignment / task creation.\n  ai_auto_classify_threshold Decimal? @db.Decimal(5, 4)\n  ai_auto_assign_threshold   Decimal? @db.Decimal(5, 4)\n  ai_auto_task_threshold     Decimal? @db.Decimal(5, 4)\n  /// 13 §3, §4 — require human approval before AI creates tasks / sends replies.\n  ai_require_task_approval   Boolean  @default(true)\n  ai_require_reply_approval  Boolean  @default(true)\n  /// 13 §3 — AI agent hands over to a human after N unresolved turns or on these intents.\n  ai_handover_after_turns    Int?\n  ai_escalation_intents      String[] @default([])\n  /// 13 §4 — default project / task type used when converting tickets (06 TaskType id).\n  default_task_type_id       String?\n  /// 13 §4 — ticket priority → task priority mapping, e.g. { URGENT: \"URGENT\", HIGH: \"HIGH\" }.\n  task_priority_mapping      Json?\n  /// 13 §4 — task status category → ticket status slug mapping for bidirectional sync.\n  task_status_sync_mapping   Json?\n  /// 13 §1 — default agent signature (markdown).\n  default_signature          String?\n  updated_at                 DateTime @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"support_settings\")\n}\n\n// --- Inboxes & channels ------------------------------------------------------------\n\n/// 13 §1 — team / shared inbox. Conversations and tickets are routed into an inbox; an inbox can\n/// belong to a Team (01 §42) and to a Branch for branch-level support (01 §38).\nmodel SupportInbox {\n  id                             String    @id @default(uuid())\n  organization_id                String\n  team_id                        String?\n  branch_id                      String?\n  name                           String\n  slug                           String\n  description                    String?\n  color                          String?\n  is_default                     Boolean   @default(false)\n  /// 13 §2 — default assignee for new conversations/tickets in this inbox.\n  default_assignee_membership_id String?\n  default_sla_policy_id          String?\n  /// 13 §2 — routing strategy: manual | round_robin | load_balanced; automation rules (20) may override.\n  routing_strategy               String    @default(\"manual\")\n  /// 13 §1 — shared signature appended to agent replies (markdown).\n  signature                      String?\n  /// 13 §7 — automatic reply sent on first customer message (markdown); null = none.\n  auto_reply_body                String?\n  archived_at                    DateTime?\n  created_at                     DateTime  @default(now())\n  updated_at                     DateTime  @updatedAt\n\n  organization     Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team             Team?                 @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  branch           Branch?               @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  default_assignee Membership?           @relation(\"SupportInboxDefaultAssignee\", fields: [default_assignee_membership_id], references: [id], onDelete: SetNull)\n  channels         SupportChannel[]\n  conversations    SupportConversation[]\n  tickets          Ticket[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id])\n  @@index([team_id])\n  @@map(\"support_inboxes\")\n}\n\n/// 13 §1, §5 — a connected channel feeding an inbox: inbound email address, website/in-app widget,\n/// live chat, portal request form, API. Widget appearance lives in `config`; the portal-wide toggle is\n/// CustomerPortalSettings.widget_settings (07).\nmodel SupportChannel {\n  id                 String             @id @default(uuid())\n  organization_id    String\n  inbox_id           String\n  type               SupportChannelType\n  name               String\n  /// EMAIL: the inbound address (support@…); unique per organization.\n  email_address      String?\n  /// 11 SenderIdentity used for outbound replies from this channel; id only.\n  sender_identity_id String?\n  /// WIDGET / LIVE_CHAT: public embed key.\n  widget_key         String?            @unique\n  /// Allowed origins for the widget / API.\n  allowed_origins    String[]           @default([])\n  /// Type-specific configuration (widget colours, welcome text, office hours, form fields, forwarding).\n  config             Json?\n  /// 13 §3 — AI agent answers first on this channel before a human.\n  ai_agent_enabled   Boolean            @default(false)\n  is_active          Boolean            @default(true)\n  verified_at        DateTime?\n  created_at         DateTime           @default(now())\n  updated_at         DateTime           @updatedAt\n\n  organization  Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  inbox         SupportInbox          @relation(fields: [inbox_id], references: [id], onDelete: Cascade)\n  conversations SupportConversation[]\n\n  @@unique([organization_id, email_address])\n  @@index([inbox_id])\n  @@index([organization_id, type])\n  @@map(\"support_channels\")\n}\n\n// --- Conversations -----------------------------------------------------------------\n\n/// 13 §1, §14 — the communication thread between a customer and the team (chat, email, widget, portal).\n/// Identity resolves to a CRM Contact/Company (02) and/or a Customer Portal User (01 §79); anonymous\n/// widget visitors keep `visitor_key` + captured name/email until matched. Tags → taggings (02 §36).\nmodel SupportConversation {\n  id                          String                    @id @default(uuid())\n  organization_id             String\n  inbox_id                    String?\n  channel_id                  String?\n  channel_type                SupportChannelType\n  status                      SupportConversationStatus @default(OPEN)\n  priority                    TicketPriority            @default(NORMAL)\n  subject                     String?\n  // 13 §1, §8 — customer identity (shared with CRM).\n  contact_id                  String?\n  company_id                  String?\n  /// Customer Portal User (01 §79) when started from the portal/authenticated widget.\n  customer_user_id            String?\n  /// Anonymous widget visitor key (cookie) before identification.\n  visitor_key                 String?\n  customer_name               String?\n  customer_email              String?\n  // 13 §1 — ownership and team.\n  assignee_membership_id      String?\n  team_id                     String?\n  /// 13 §1 — snoozed until; status returns to OPEN when it passes (scheduled job, 20).\n  snoozed_until               DateTime?\n  /// 13 §1 — merging: this conversation was merged into another (status RESOLVED).\n  merged_into_conversation_id String?\n  /// 13 §1 — splitting: this conversation was split out of another.\n  split_from_conversation_id  String?\n  /// EMAIL: thread key (Message-ID / References) used to attach inbound replies.\n  email_thread_key            String?\n  /// 13 §3 — detected language (BCP 47) and sentiment.\n  language                    String?\n  sentiment                   SupportSentiment?\n  sentiment_score             Decimal?                  @db.Decimal(5, 4)\n  /// 13 §3 — AI-generated summary (refreshed on transfer / resolution).\n  ai_summary                  String?\n  ai_summary_at               DateTime?\n  // 13 §1, §9 — timestamps for metrics and read receipts.\n  message_count               Int                       @default(0)\n  first_customer_message_at   DateTime?\n  first_agent_response_at     DateTime?\n  last_message_at             DateTime?\n  last_customer_message_at    DateTime?\n  last_agent_message_at       DateTime?\n  /// 13 §1 — read receipts (customer side); agent side is per participant.\n  customer_last_read_at       DateTime?\n  resolved_at                 DateTime?\n  resolved_by_membership_id   String?\n  reopened_at                 DateTime?\n  created_by_membership_id    String?\n  created_at                  DateTime                  @default(now())\n  updated_at                  DateTime                  @updatedAt\n\n  organization Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  inbox        SupportInbox?         @relation(fields: [inbox_id], references: [id], onDelete: SetNull)\n  channel      SupportChannel?       @relation(fields: [channel_id], references: [id], onDelete: SetNull)\n  contact      CrmContact?           @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n  company      CrmCompany?           @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  customer     User?                 @relation(\"SupportConversationCustomer\", fields: [customer_user_id], references: [id], onDelete: SetNull)\n  assignee     Membership?           @relation(\"SupportConversationAssignee\", fields: [assignee_membership_id], references: [id], onDelete: SetNull)\n  team         Team?                 @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  merged_into  SupportConversation?  @relation(\"SupportConversationMerge\", fields: [merged_into_conversation_id], references: [id], onDelete: SetNull)\n  merged_from  SupportConversation[] @relation(\"SupportConversationMerge\")\n  split_from   SupportConversation?  @relation(\"SupportConversationSplit\", fields: [split_from_conversation_id], references: [id], onDelete: SetNull)\n  split_into   SupportConversation[] @relation(\"SupportConversationSplit\")\n\n  messages        SupportMessage[]\n  participants    SupportConversationParticipant[]\n  primary_tickets Ticket[]                         @relation(\"TicketPrimaryConversation\")\n  ticket_links    TicketConversation[]\n  ai_sessions     SupportAiSession[]\n  ai_suggestions  SupportAiSuggestion[]\n  csat_ratings    SupportCsatRating[]\n\n  @@index([organization_id, status, last_message_at])\n  @@index([inbox_id, status])\n  @@index([assignee_membership_id, status])\n  @@index([contact_id])\n  @@index([company_id])\n  @@index([customer_user_id])\n  @@index([organization_id, email_thread_key])\n  @@index([organization_id, visitor_key])\n  @@map(\"support_conversations\")\n}\n\n/// 13 §1 — internal members collaborating on a conversation (assignee, collaborators, @mentioned);\n/// `last_read_at` drives agent-side read receipts and unread counts.\nmodel SupportConversationParticipant {\n  conversation_id String\n  membership_id   String\n  role            SupportParticipantRole @default(COLLABORATOR)\n  last_read_at    DateTime?\n  joined_at       DateTime               @default(now())\n\n  conversation SupportConversation @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  membership   Membership          @relation(\"SupportConversationParticipant\", fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([conversation_id, membership_id])\n  @@index([membership_id])\n  @@map(\"support_conversation_participants\")\n}\n\n/// 13 §1, §2, §3 — one message in a conversation: customer message, agent reply, private internal note,\n/// AI agent answer or system event. Outbound email replies go through 11 (`comm_message_id`).\nmodel SupportMessage {\n  id                     String                        @id @default(uuid())\n  conversation_id        String\n  /// 13 §1 — denormalized tenant id for direct filtering (also reachable via conversation).\n  organization_id        String\n  kind                   SupportMessageKind\n  /// Channel the message came in / went out on (a conversation may mix email and chat).\n  channel_type           SupportChannelType?\n  author_membership_id   String?\n  /// Customer Portal User (01 §79) when written from the portal/widget.\n  author_user_id         String?\n  /// Captured sender identity for inbound email / anonymous widget messages.\n  author_name            String?\n  author_email           String?\n  /// Markdown body; `body_html` keeps the sanitized original for email.\n  body                   String\n  body_html              String?\n  /// 13 §1 — @mentions (membership ids) in internal notes.\n  mentions               String[]                      @default([])\n  /// 13 §1 — canned response used to compose this reply.\n  canned_response_id     String?\n  /// 13 §3 — AI suggestion this reply was generated from (accepted / rewritten).\n  ai_suggestion_id       String?\n  /// 13 §3 — detected language and stored translations { \"en\": \"...\", \"el\": \"...\" }.\n  language               String?\n  translations           Json?\n  // 13 §1, §10 — outbound delivery (email via 11 CommMessage; id only) and inbound email identifiers.\n  comm_message_id        String?\n  external_message_id    String?\n  in_reply_to_message_id String?\n  delivery_status        SupportMessageDeliveryStatus?\n  delivered_at           DateTime?\n  delivery_error         String?\n  /// 13 §1 — read receipt for the customer (public messages only).\n  read_by_customer_at    DateTime?\n  /// 13 §9 — marks the first agent/AI public reply (first response time).\n  is_first_response      Boolean                       @default(false)\n  edited_at              DateTime?\n  deleted_at             DateTime?\n  created_at             DateTime                      @default(now())\n  updated_at             DateTime                      @updatedAt\n  /// 13 §1 — Postgres full-text search vector over body; maintained by a database trigger (see migration). Not set by the API.\n  search_vector          Unsupported(\"tsvector\")?\n\n  conversation    SupportConversation        @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  author          Membership?                @relation(\"SupportMessageAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n  author_user     User?                      @relation(\"SupportMessageAuthorUser\", fields: [author_user_id], references: [id], onDelete: SetNull)\n  canned_response SupportCannedResponse?     @relation(fields: [canned_response_id], references: [id], onDelete: SetNull)\n  ai_suggestion   SupportAiSuggestion?       @relation(\"SupportMessageFromSuggestion\", fields: [ai_suggestion_id], references: [id], onDelete: SetNull)\n  attachments     SupportMessageAttachment[]\n  organization    Organization               @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@index([conversation_id, created_at])\n  @@index([search_vector], type: Gin)\n  @@index([organization_id, created_at])\n  @@index([author_membership_id])\n  @@index([external_message_id])\n  @@map(\"support_messages\")\n}\n\n/// 13 §1 — file and image attachments on a message are Documents (17 §2).\nmodel SupportMessageAttachment {\n  id          String   @id @default(uuid())\n  message_id  String\n  /// 17 Document.\n  document_id String\n  /// Denormalized for inbox previews.\n  file_name   String?\n  mime_type   String?\n  size_bytes  Int?\n  created_at  DateTime @default(now())\n\n  message SupportMessage @relation(fields: [message_id], references: [id], onDelete: Cascade)\n\n  @@unique([message_id, document_id])\n  @@map(\"support_message_attachments\")\n}\n\n// --- Ticket configuration ----------------------------------------------------------\n\n/// 13 §2, §13 — configurable ticket statuses with workflow transitions (organization-wide).\nmodel TicketStatus {\n  id                  String               @id @default(uuid())\n  organization_id     String\n  name                String\n  slug                String\n  category            TicketStatusCategory\n  color               String?\n  sort_order          Int                  @default(0)\n  is_default          Boolean              @default(false)\n  /// Slugs this status may transition to; empty = any.\n  allowed_transitions String[]             @default([])\n  /// 13 §2 — SLA timers pause while a ticket is in this status (e.g. waiting on customer).\n  pauses_sla          Boolean              @default(false)\n  /// 13 §5 — label shown to customers in the portal (defaults to name).\n  customer_label      String?\n  archived_at         DateTime?\n  created_at          DateTime             @default(now())\n\n  organization Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  tickets      Ticket[]\n  history_from TicketStatusHistory[] @relation(\"TicketStatusHistoryFrom\")\n  history_to   TicketStatusHistory[] @relation(\"TicketStatusHistoryTo\")\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, category])\n  @@map(\"ticket_statuses\")\n}\n\n/// 13 §2, §3 — custom ticket categories (hierarchical) with routing defaults used by AI\n/// categorization and automation rules (20).\nmodel TicketCategory {\n  id                    String          @id @default(uuid())\n  organization_id       String\n  parent_category_id    String?\n  name                  String\n  slug                  String\n  description           String?\n  color                 String?\n  icon                  String?\n  /// Routing defaults applied when the category is set (manually or by AI).\n  default_team_id       String?\n  default_inbox_id      String?\n  default_priority      TicketPriority?\n  default_sla_policy_id String?\n  /// 13 §4 — default project for tasks converted from tickets in this category (05 Project id).\n  default_project_id    String?\n  /// 13 §3 — keywords/examples that help the AI classifier.\n  ai_hints              String[]        @default([])\n  sort_order            Int             @default(0)\n  archived_at           DateTime?\n  created_at            DateTime        @default(now())\n  updated_at            DateTime        @updatedAt\n\n  organization Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent       TicketCategory?  @relation(\"TicketCategoryHierarchy\", fields: [parent_category_id], references: [id], onDelete: SetNull)\n  children     TicketCategory[] @relation(\"TicketCategoryHierarchy\")\n  tickets      Ticket[]\n\n  @@unique([organization_id, slug])\n  @@index([parent_category_id])\n  @@map(\"ticket_categories\")\n}\n\n// --- SLA ---------------------------------------------------------------------------\n\n/// 13 §2, §7 — SLA policy: response/resolution targets per priority, business-hours handling and\n/// escalation. Timers and auto-escalation are executed by 20 scheduled jobs / rules.\nmodel SlaPolicy {\n  id                        String    @id @default(uuid())\n  organization_id           String\n  name                      String\n  description               String?\n  is_default                Boolean   @default(false)\n  /// Count only business hours (Organization/Branch business_hours, 01 §14, §120) instead of calendar hours.\n  use_business_hours        Boolean   @default(true)\n  /// 19 Calendar id used for holidays when business hours apply; id only.\n  calendar_id               String?\n  /// Match conditions: { categories: [], channel_types: [], company_ids: [], ticket_types: [], tags: [] }; empty = any.\n  conditions                Json?\n  /// 13 §7 — percentage of target elapsed at which an \"SLA at risk\" event is emitted.\n  at_risk_threshold_percent Decimal   @default(80) @db.Decimal(5, 2)\n  /// 13 §7 — automation rules (20) run on at-risk / breach; ids only.\n  escalation_rule_ids       String[]  @default([])\n  sort_order                Int       @default(0)\n  archived_at               DateTime?\n  created_at                DateTime  @default(now())\n  updated_at                DateTime  @updatedAt\n\n  organization Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  targets      SlaPolicyTarget[]\n  tickets      Ticket[]\n  timers       TicketSlaTimer[]\n\n  @@unique([organization_id, name])\n  @@index([organization_id, is_default])\n  @@map(\"sla_policies\")\n}\n\n/// 13 §2 — targets per priority within a policy (minutes; null = not tracked).\nmodel SlaPolicyTarget {\n  id                     String         @id @default(uuid())\n  policy_id              String\n  priority               TicketPriority\n  first_response_minutes Int?\n  next_response_minutes  Int?\n  resolution_minutes     Int?\n\n  policy SlaPolicy @relation(fields: [policy_id], references: [id], onDelete: Cascade)\n\n  @@unique([policy_id, priority])\n  @@map(\"sla_policy_targets\")\n}\n\n// --- Ticket ------------------------------------------------------------------------\n\n/// 13 §2, §5, §14 — the structured support case: priority, SLA, status, ownership, resolution.\n/// Requester is a CRM Contact/Company (02) and/or a Customer Portal User (01 §79). Custom fields →\n/// custom_field_values, tags → taggings, saved views → saved_views (02), history → audit_events +\n/// TicketStatusHistory, time → 18 TimeEntry (entity TICKET), internal discussion → 12 (§11).\nmodel Ticket {\n  id                         String                   @id @default(uuid())\n  organization_id            String\n  /// 13 §2 — sequential per organization via number_sequences (03); `reference` = prefix + number (SUP-1042).\n  number                     Int\n  reference                  String\n  branch_id                  String?\n  inbox_id                   String?\n  /// Primary conversation; additional ones via TicketConversation (§14).\n  conversation_id            String?\n  subject                    String\n  /// Markdown description (first customer message or form body).\n  description                String?\n  type                       TicketType               @default(QUESTION)\n  source                     TicketSource             @default(MANUAL)\n  channel_type               SupportChannelType?\n  status_id                  String?\n  priority                   TicketPriority           @default(NORMAL)\n  category_id                String?\n  // 13 §2, §11 — requester (shared CRM identity).\n  requester_contact_id       String?\n  company_id                 String?\n  /// Customer Portal User who opened / may view the ticket (01 §79).\n  requester_user_id          String?\n  requester_email            String?\n  requester_name             String?\n  // 13 §2 — ownership.\n  assignee_membership_id     String?\n  team_id                    String?\n  // 13 §2, §4, §11 — related application entities.\n  project_id                 String?\n  /// Project Change Request (05 §45) created from this request.\n  change_request_id          String?\n  /// 06 Release that shipped the fix (notified to the customer, §4); id only.\n  release_id                 String?\n  // 13 §2 — SLA (policy + denormalized due dates; detail in TicketSlaTimer).\n  sla_policy_id              String?\n  first_response_due_at      DateTime?\n  next_response_due_at       DateTime?\n  resolution_due_at          DateTime?\n  sla_breached               Boolean                  @default(false)\n  sla_at_risk                Boolean                  @default(false)\n  // 13 §2, §9 — lifecycle timestamps.\n  first_responded_at         DateTime?\n  last_customer_reply_at     DateTime?\n  last_agent_reply_at        DateTime?\n  due_at                     DateTime?\n  resolved_at                DateTime?\n  resolved_by_membership_id  String?\n  resolution                 String?\n  closed_at                  DateTime?\n  /// 13 §7 — scheduled auto-close (20 ScheduledJob id).\n  auto_close_at              DateTime?\n  auto_close_job_id          String?\n  reopened_at                DateTime?\n  reopen_count               Int                      @default(0)\n  // 13 §2, §7 — escalation.\n  escalation_level           Int                      @default(0)\n  escalated_at               DateTime?\n  escalated_to_membership_id String?\n  // 13 §2 — merge / duplicates / incidents.\n  merged_into_ticket_id      String?\n  incident_id                String?\n  // 13 §3 — AI classification (latest accepted/auto-applied).\n  ai_classification          Json?\n  ai_confidence              Decimal?                 @db.Decimal(5, 4)\n  sentiment                  SupportSentiment?\n  sentiment_score            Decimal?                 @db.Decimal(5, 4)\n  language                   String?\n  /// 13 §3 — estimated complexity: low | medium | high.\n  ai_complexity              String?\n  ai_summary                 String?\n  /// 13 §9 — resolved by the AI agent without a human.\n  resolved_by_ai             Boolean                  @default(false)\n  /// 13 §5 — visible to the requester's portal users.\n  customer_visible           Boolean                  @default(true)\n  /// Messaging thread for internal discussion (12 §60); id only.\n  channel_id                 String?\n  created_by_membership_id   String?\n  created_by_user_id         String?\n  archived_at                DateTime?\n  created_at                 DateTime                 @default(now())\n  updated_at                 DateTime                 @updatedAt\n  /// 13 §1, §2 — Postgres full-text search vector over subject + description; maintained by a database trigger (see migration). Not set by the API.\n  search_vector              Unsupported(\"tsvector\")?\n\n  organization   Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch         Branch?               @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  inbox          SupportInbox?         @relation(fields: [inbox_id], references: [id], onDelete: SetNull)\n  conversation   SupportConversation?  @relation(\"TicketPrimaryConversation\", fields: [conversation_id], references: [id], onDelete: SetNull)\n  status         TicketStatus?         @relation(fields: [status_id], references: [id], onDelete: SetNull)\n  category       TicketCategory?       @relation(fields: [category_id], references: [id], onDelete: SetNull)\n  requester      CrmContact?           @relation(fields: [requester_contact_id], references: [id], onDelete: SetNull)\n  company        CrmCompany?           @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  requester_user User?                 @relation(\"TicketRequesterUser\", fields: [requester_user_id], references: [id], onDelete: SetNull)\n  assignee       Membership?           @relation(\"TicketAssignee\", fields: [assignee_membership_id], references: [id], onDelete: SetNull)\n  team           Team?                 @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  project        Project?              @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  change_request ProjectChangeRequest? @relation(fields: [change_request_id], references: [id], onDelete: SetNull)\n  sla_policy     SlaPolicy?            @relation(fields: [sla_policy_id], references: [id], onDelete: SetNull)\n  merged_into    Ticket?               @relation(\"TicketMerge\", fields: [merged_into_ticket_id], references: [id], onDelete: SetNull)\n  merged_from    Ticket[]              @relation(\"TicketMerge\")\n  incident       SupportIncident?      @relation(fields: [incident_id], references: [id], onDelete: SetNull)\n\n  conversations     TicketConversation[]\n  status_history    TicketStatusHistory[]\n  sla_timers        TicketSlaTimer[]\n  relations_from    TicketRelation[]      @relation(\"TicketRelationSource\")\n  relations_to      TicketRelation[]      @relation(\"TicketRelationTarget\")\n  task_links        TicketTaskLink[]\n  followers         TicketFollower[]\n  attachments       TicketAttachment[]\n  csat_ratings      SupportCsatRating[]\n  ai_suggestions    SupportAiSuggestion[]\n  ai_sessions       SupportAiSession[]    @relation(\"SupportAiSessionTicket\")\n  knowledge_sources KnowledgeArticle[]    @relation(\"KnowledgeArticleSourceTicket\")\n  project_issues    ProjectIssue[]\n\n  @@unique([organization_id, number])\n  @@unique([organization_id, reference])\n  @@index([search_vector], type: Gin)\n  @@index([organization_id, status_id])\n  @@index([organization_id, priority])\n  @@index([organization_id, category_id])\n  @@index([organization_id, created_at])\n  @@index([inbox_id, status_id])\n  @@index([assignee_membership_id, status_id])\n  @@index([team_id, status_id])\n  @@index([requester_contact_id])\n  @@index([company_id])\n  @@index([requester_user_id])\n  @@index([project_id])\n  @@index([conversation_id])\n  @@index([incident_id])\n  @@index([resolution_due_at])\n  @@index([first_response_due_at])\n  @@map(\"tickets\")\n}\n\n/// 13 §14 — additional conversations attached to a ticket (one conversation ↔ many tickets and vice versa).\nmodel TicketConversation {\n  ticket_id       String\n  conversation_id String\n  created_at      DateTime @default(now())\n\n  ticket       Ticket              @relation(fields: [ticket_id], references: [id], onDelete: Cascade)\n  conversation SupportConversation @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n\n  @@id([ticket_id, conversation_id])\n  @@index([conversation_id])\n  @@map(\"ticket_conversations\")\n}\n\n/// 13 §2, §9 — queryable status history for resolution-time, SLA and agent metrics.\nmodel TicketStatusHistory {\n  id                       String                @id @default(uuid())\n  ticket_id                String\n  from_status_id           String?\n  to_status_id             String?\n  /// Category snapshots so metrics survive status renames.\n  from_category            TicketStatusCategory?\n  to_category              TicketStatusCategory?\n  changed_by_membership_id String?\n  changed_by_user_id       String?\n  /// 13 §4, §7 — manual | automation | task_sync | ai | customer | auto_close\n  changed_via              String                @default(\"manual\")\n  reason                   String?\n  /// Seconds spent in the previous status.\n  seconds_in_previous      Int?\n  changed_at               DateTime              @default(now())\n\n  ticket      Ticket        @relation(fields: [ticket_id], references: [id], onDelete: Cascade)\n  from_status TicketStatus? @relation(\"TicketStatusHistoryFrom\", fields: [from_status_id], references: [id], onDelete: SetNull)\n  to_status   TicketStatus? @relation(\"TicketStatusHistoryTo\", fields: [to_status_id], references: [id], onDelete: SetNull)\n\n  @@index([ticket_id, changed_at])\n  @@index([to_status_id, changed_at])\n  @@map(\"ticket_status_history\")\n}\n\n/// 13 §2, §7 — one SLA timer per metric per ticket; paused while the status pauses SLA.\n/// The due reminder / breach check is a 20 ScheduledJob.\nmodel TicketSlaTimer {\n  id                   String         @id @default(uuid())\n  ticket_id            String\n  policy_id            String?\n  metric               SlaMetric\n  status               SlaTimerStatus @default(RUNNING)\n  target_minutes       Int\n  started_at           DateTime       @default(now())\n  due_at               DateTime\n  paused_at            DateTime?\n  paused_seconds_total Int            @default(0)\n  at_risk_at           DateTime?\n  at_risk_notified_at  DateTime?\n  completed_at         DateTime?\n  breached_at          DateTime?\n  /// Minutes elapsed when completed (business minutes when the policy uses business hours).\n  elapsed_minutes      Int?\n  /// 20 ScheduledJob id for the breach check; id only.\n  scheduled_job_id     String?\n  created_at           DateTime       @default(now())\n  updated_at           DateTime       @updatedAt\n\n  ticket Ticket     @relation(fields: [ticket_id], references: [id], onDelete: Cascade)\n  policy SlaPolicy? @relation(fields: [policy_id], references: [id], onDelete: SetNull)\n\n  @@index([ticket_id, metric])\n  @@index([status, due_at])\n  @@map(\"ticket_sla_timers\")\n}\n\n/// 13 §2, §3 — related / duplicate / blocking / same-incident relationships between tickets.\nmodel TicketRelation {\n  id                       String             @id @default(uuid())\n  source_ticket_id         String\n  target_ticket_id         String\n  type                     TicketRelationType @default(RELATED)\n  /// 13 §3 — detected by AI (duplicate / incident grouping) vs added manually.\n  detected_by_ai           Boolean            @default(false)\n  confidence               Decimal?           @db.Decimal(5, 4)\n  created_by_membership_id String?\n  created_at               DateTime           @default(now())\n\n  source Ticket @relation(\"TicketRelationSource\", fields: [source_ticket_id], references: [id], onDelete: Cascade)\n  target Ticket @relation(\"TicketRelationTarget\", fields: [target_ticket_id], references: [id], onDelete: Cascade)\n\n  @@unique([source_ticket_id, target_ticket_id, type])\n  @@index([target_ticket_id])\n  @@map(\"ticket_relations\")\n}\n\n/// 13 §4, §14 — permanent link between a ticket and a Task (06): many tickets ↔ many tasks.\n/// Creation is idempotent via `idempotency_key`; status sync follows SupportSettings.task_status_sync_mapping.\n/// The task side also carries a TaskLink (06 §13) with entity_type TICKET.\nmodel TicketTaskLink {\n  id                       String             @id @default(uuid())\n  ticket_id                String\n  task_id                  String\n  kind                     TicketTaskLinkKind @default(LINKED)\n  /// 13 §4 — synchronize task status changes back to the ticket.\n  sync_status              Boolean            @default(true)\n  /// 13 §4, §13 — prevents duplicate task creation on retries (ticket id + source hash).\n  idempotency_key          String?            @unique\n  /// 13 §3 — AI suggestion that proposed the conversion, when applicable.\n  ai_suggestion_id         String?\n  created_by_membership_id String?\n  /// 13 §4 — last synchronized task status category and when.\n  last_synced_task_status  String?\n  last_synced_at           DateTime?\n  created_at               DateTime           @default(now())\n\n  ticket        Ticket               @relation(fields: [ticket_id], references: [id], onDelete: Cascade)\n  task          Task                 @relation(fields: [task_id], references: [id], onDelete: Cascade)\n  ai_suggestion SupportAiSuggestion? @relation(\"TicketTaskLinkSuggestion\", fields: [ai_suggestion_id], references: [id], onDelete: SetNull)\n\n  @@unique([ticket_id, task_id])\n  @@index([task_id])\n  @@map(\"ticket_task_links\")\n}\n\n/// 13 §2, §10 — members following a ticket for notifications (14).\nmodel TicketFollower {\n  ticket_id     String\n  membership_id String\n  created_at    DateTime @default(now())\n\n  ticket     Ticket     @relation(fields: [ticket_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(\"TicketFollower\", fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([ticket_id, membership_id])\n  @@index([membership_id])\n  @@map(\"ticket_followers\")\n}\n\n/// 13 §2, §5 — attachments on a ticket (beyond message attachments) are Documents (17); id only.\nmodel TicketAttachment {\n  id                     String   @id @default(uuid())\n  ticket_id              String\n  /// 17 Document.\n  document_id            String\n  file_name              String?\n  mime_type              String?\n  size_bytes             Int?\n  /// 13 §5 — uploaded by a portal user (User id) or a member (Membership id).\n  added_by_user_id       String?\n  added_by_membership_id String?\n  created_at             DateTime @default(now())\n\n  ticket Ticket @relation(fields: [ticket_id], references: [id], onDelete: Cascade)\n\n  @@unique([ticket_id, document_id])\n  @@map(\"ticket_attachments\")\n}\n\n/// 13 §3, §9 — a grouped incident / recurring problem spanning several tickets (detected by AI or\n/// declared by an agent). Tickets point at it via Ticket.incident_id.\nmodel SupportIncident {\n  id                   String                @id @default(uuid())\n  organization_id      String\n  title                String\n  description          String?\n  status               SupportIncidentStatus @default(DETECTED)\n  detected_by_ai       Boolean               @default(false)\n  /// 05 Project / 06 Task the incident is tracked in; ids only.\n  project_id           String?\n  task_id              String?\n  /// 13 §6 — knowledge article published for the incident (workaround / status).\n  knowledge_article_id String?\n  owner_membership_id  String?\n  ticket_count         Int                   @default(0)\n  first_reported_at    DateTime?\n  resolved_at          DateTime?\n  created_at           DateTime              @default(now())\n  updated_at           DateTime              @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  tickets      Ticket[]\n\n  @@index([organization_id, status])\n  @@map(\"support_incidents\")\n}\n\n// --- CSAT --------------------------------------------------------------------------\n\n/// 13 §9 — customer satisfaction rating requested on resolution (ticket or conversation).\nmodel SupportCsatRating {\n  id                  String    @id @default(uuid())\n  organization_id     String\n  ticket_id           String?\n  conversation_id     String?\n  contact_id          String?\n  /// Customer Portal User who rated (01 §79).\n  rated_by_user_id    String?\n  /// Agent credited for the rating (assignee at resolution).\n  agent_membership_id String?\n  /// 1–5.\n  rating              Int?\n  comment             String?\n  /// Opaque token for the rating link in emails (11).\n  token               String    @unique @default(uuid())\n  requested_at        DateTime  @default(now())\n  submitted_at        DateTime?\n  expires_at          DateTime?\n\n  organization Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  ticket       Ticket?              @relation(fields: [ticket_id], references: [id], onDelete: Cascade)\n  conversation SupportConversation? @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  contact      CrmContact?          @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n  rated_by     User?                @relation(\"SupportCsatRatedBy\", fields: [rated_by_user_id], references: [id], onDelete: SetNull)\n  agent        Membership?          @relation(\"SupportCsatAgent\", fields: [agent_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, submitted_at])\n  @@index([ticket_id])\n  @@index([agent_membership_id, submitted_at])\n  @@map(\"support_csat_ratings\")\n}\n\n// --- Canned responses --------------------------------------------------------------\n\n/// 13 §1 — saved replies / response templates / macros with optional field actions.\nmodel SupportCannedResponse {\n  id                  String                     @id @default(uuid())\n  organization_id     String\n  scope               SupportCannedResponseScope @default(ORGANIZATION)\n  team_id             String?\n  owner_membership_id String?\n  name                String\n  /// Slash shortcut (e.g. \"/refund\").\n  shortcut            String?\n  category            String?\n  /// Markdown with placeholders ({{customer.first_name}}, {{ticket.reference}}, {{agent.name}}).\n  body                String\n  /// Macro actions applied when used: { status_slug, priority, assignee_membership_id, team_id, add_tag_ids, category_id }.\n  actions             Json?\n  usage_count         Int                        @default(0)\n  last_used_at        DateTime?\n  archived_at         DateTime?\n  created_at          DateTime                   @default(now())\n  updated_at          DateTime                   @updatedAt\n\n  organization Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team         Team?            @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  owner        Membership?      @relation(\"SupportCannedResponseOwner\", fields: [owner_membership_id], references: [id], onDelete: Cascade)\n  messages     SupportMessage[]\n\n  @@unique([organization_id, shortcut])\n  @@index([organization_id, scope])\n  @@index([team_id])\n  @@index([owner_membership_id])\n  @@map(\"support_canned_responses\")\n}\n\n// --- Knowledge base ----------------------------------------------------------------\n\n/// 13 §6 — categories / collections of the customer-facing help center (hierarchical).\nmodel KnowledgeCategory {\n  id                 String              @id @default(uuid())\n  organization_id    String\n  parent_category_id String?\n  name               String\n  slug               String\n  description        String?\n  icon               String?\n  /// Most restrictive visibility of the category; articles may be stricter.\n  visibility         KnowledgeVisibility @default(PUBLIC)\n  sort_order         Int                 @default(0)\n  archived_at        DateTime?\n  created_at         DateTime            @default(now())\n  updated_at         DateTime            @updatedAt\n\n  organization Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent       KnowledgeCategory?  @relation(\"KnowledgeCategoryHierarchy\", fields: [parent_category_id], references: [id], onDelete: SetNull)\n  children     KnowledgeCategory[] @relation(\"KnowledgeCategoryHierarchy\")\n  articles     KnowledgeArticle[]\n\n  @@unique([organization_id, slug])\n  @@index([parent_category_id])\n  @@map(\"knowledge_categories\")\n}\n\n/// 13 §6 — help-center article (rich text, versions, feedback). Public articles are served by the\n/// help center and the portal (07); INTERNAL ones only to agents. Approved content is the AI agent's\n/// primary source (§3). Tags → taggings (entity KNOWLEDGE_ARTICLE). Embedded media are Documents (17).\nmodel KnowledgeArticle {\n  id                      String                   @id @default(uuid())\n  organization_id         String\n  category_id             String?\n  title                   String\n  slug                    String\n  summary                 String?\n  /// Markdown/HTML body of the current version (denormalized from the latest version).\n  body                    String\n  status                  KnowledgeArticleStatus   @default(DRAFT)\n  visibility              KnowledgeVisibility      @default(PUBLIC)\n  /// 13 §6 — shown in the FAQ section.\n  is_faq                  Boolean                  @default(false)\n  locale                  String                   @default(\"en\")\n  keywords                String[]                 @default([])\n  /// Related article ids (manual + AI suggestions, §6).\n  related_article_ids     String[]                 @default([])\n  /// 17 Document ids for images/videos/attachments.\n  attachment_document_ids String[]                 @default([])\n  /// 06 Release whose notes this article publishes, when applicable; id only.\n  release_id              String?\n  /// 13 §6 — AI-generated draft from a resolved ticket.\n  ai_generated            Boolean                  @default(false)\n  source_ticket_id        String?\n  author_membership_id    String?\n  reviewer_membership_id  String?\n  current_version         Int                      @default(1)\n  published_at            DateTime?\n  last_reviewed_at        DateTime?\n  /// 13 §6, §9 — usage counters (detail in KnowledgeArticleFeedback).\n  view_count              Int                      @default(0)\n  helpful_count           Int                      @default(0)\n  not_helpful_count       Int                      @default(0)\n  /// SEO metadata for public articles { meta_title, meta_description, canonical_url }.\n  seo                     Json?\n  sort_order              Int                      @default(0)\n  archived_at             DateTime?\n  created_at              DateTime                 @default(now())\n  updated_at              DateTime                 @updatedAt\n  /// 13 §6 — Postgres full-text search vector over title + body; maintained by a database trigger (see migration). Not set by the API.\n  search_vector           Unsupported(\"tsvector\")?\n\n  organization     Organization               @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  category         KnowledgeCategory?         @relation(fields: [category_id], references: [id], onDelete: SetNull)\n  author           Membership?                @relation(\"KnowledgeArticleAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n  source_ticket    Ticket?                    @relation(\"KnowledgeArticleSourceTicket\", fields: [source_ticket_id], references: [id], onDelete: SetNull)\n  versions         KnowledgeArticleVersion[]\n  feedback         KnowledgeArticleFeedback[]\n  ai_index_entries WikiAiIndexEntry[]\n\n  @@unique([organization_id, slug, locale])\n  @@index([organization_id, status, visibility])\n  @@index([search_vector], type: Gin)\n  @@index([category_id, sort_order])\n  @@index([source_ticket_id])\n  @@map(\"knowledge_articles\")\n}\n\n/// 13 §6 — immutable article version history.\nmodel KnowledgeArticleVersion {\n  id                   String   @id @default(uuid())\n  article_id           String\n  version              Int\n  title                String\n  summary              String?\n  body                 String\n  change_note          String?\n  author_membership_id String?\n  ai_generated         Boolean  @default(false)\n  created_at           DateTime @default(now())\n\n  article KnowledgeArticle @relation(fields: [article_id], references: [id], onDelete: Cascade)\n\n  @@unique([article_id, version])\n  @@map(\"knowledge_article_versions\")\n}\n\n/// 13 §6 — ratings and feedback on an article from portal users, anonymous visitors or agents.\nmodel KnowledgeArticleFeedback {\n  id              String   @id @default(uuid())\n  article_id      String\n  is_helpful      Boolean\n  comment         String?\n  /// Customer Portal User (01 §79) when authenticated.\n  user_id         String?\n  contact_id      String?\n  /// Anonymous visitor key (cookie) to deduplicate public votes.\n  visitor_key     String?\n  /// Conversation where the article was recommended, when the feedback came from a chat (§6).\n  conversation_id String?\n  created_at      DateTime @default(now())\n\n  article KnowledgeArticle @relation(fields: [article_id], references: [id], onDelete: Cascade)\n  user    User?            @relation(\"KnowledgeArticleFeedbackUser\", fields: [user_id], references: [id], onDelete: SetNull)\n\n  @@index([article_id, created_at])\n  @@index([user_id])\n  @@map(\"knowledge_article_feedback\")\n}\n\n// --- AI ----------------------------------------------------------------------------\n\n/// 13 §3 — an AI support-agent session on a conversation: first-line answers from the knowledge base\n/// and authorized data, information collection, ticket creation and handover to a human with context.\n/// All AI actions are also written to audit_events (§13).\nmodel SupportAiSession {\n  id                String                 @id @default(uuid())\n  organization_id   String\n  conversation_id   String\n  /// Ticket created by the AI when human assistance was required.\n  ticket_id         String?\n  status            SupportAiSessionStatus @default(ACTIVE)\n  model             String\n  /// Structured data collected before escalation (issue, steps, environment, urgency …).\n  collected_data    Json?\n  /// Knowledge article ids used to answer.\n  cited_article_ids String[]               @default([])\n  /// Handover context passed to the human agent.\n  handover_summary  String?\n  handover_reason   String?\n  /// AI turns (messages of kind AI_AGENT) in this session.\n  turn_count        Int                    @default(0)\n  /// Token / cost accounting { input_tokens, output_tokens, cost }.\n  usage             Json?\n  started_at        DateTime               @default(now())\n  handed_over_at    DateTime?\n  ended_at          DateTime?\n\n  organization Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  conversation SupportConversation @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  ticket       Ticket?             @relation(\"SupportAiSessionTicket\", fields: [ticket_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status, started_at])\n  @@index([conversation_id])\n  @@map(\"support_ai_sessions\")\n}\n\n/// 13 §3 — one AI output awaiting / past human review: classification, priority, assignment, reply\n/// draft, summary, translation, article recommendation, duplicate, task-creation proposal, knowledge gap.\n/// `payload` holds the typed proposal; `confidence` is 0–1 and compared with SupportSettings thresholds.\nmodel SupportAiSuggestion {\n  id                        String                    @id @default(uuid())\n  organization_id           String\n  kind                      SupportAiSuggestionKind\n  conversation_id           String?\n  ticket_id                 String?\n  /// Message that triggered the suggestion (SupportMessage id).\n  source_message_id         String?\n  model                     String\n  payload                   Json\n  /// Human-readable rationale from the model.\n  explanation               String?\n  confidence                Decimal?                  @db.Decimal(5, 4)\n  status                    SupportAiSuggestionStatus @default(PENDING)\n  /// Applied automatically because confidence ≥ threshold (no human review).\n  auto_applied              Boolean                   @default(false)\n  reviewed_by_membership_id String?\n  reviewed_at               DateTime?\n  review_note               String?\n  applied_at                DateTime?\n  expires_at                DateTime?\n  /// 13 §9 — accuracy feedback: was the suggestion correct after the fact?\n  was_correct               Boolean?\n  created_at                DateTime                  @default(now())\n  updated_at                DateTime                  @updatedAt\n\n  organization Organization         @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  conversation SupportConversation? @relation(fields: [conversation_id], references: [id], onDelete: Cascade)\n  ticket       Ticket?              @relation(fields: [ticket_id], references: [id], onDelete: Cascade)\n  reviewed_by  Membership?          @relation(\"SupportAiSuggestionReviewer\", fields: [reviewed_by_membership_id], references: [id], onDelete: SetNull)\n  messages     SupportMessage[]     @relation(\"SupportMessageFromSuggestion\")\n  task_links   TicketTaskLink[]     @relation(\"TicketTaskLinkSuggestion\")\n\n  @@index([organization_id, kind, status])\n  @@index([conversation_id, kind])\n  @@index([ticket_id, kind])\n  @@map(\"support_ai_suggestions\")\n}\n\n// =====================================================================\n// 14 Notifications & Activity Center — docs/features/14-notifications-activity-center.md (LOG-403)\n// Owns: the platform notification engine — event catalog, ingested events (idempotent), per-recipient\n// notifications (inbox / Activity Center, portal inbox), per-channel deliveries, templates & localization,\n// organization defaults, per-recipient settings and preferences (incl. per-record follow/mute and keyword\n// subscriptions reused by 12), digests, push device tokens and delivery rules (dedup / coalesce / throttle).\n// Does not own: record activity/history (written by owning modules to audit_events), email/SMS sending\n// (11 CommMessage), campaigns/templates for customer messaging (11), outbound webhooks (20 OutboundWebhook),\n// the event bus (20 PlatformEvent), messaging channels/messages (12). Referenced by id only.\n// Audit of mandatory/security deliveries, template and default changes goes to audit_events (14 §13).\n// =====================================================================\n\n/// 14 §5 — delivery channels. IN_APP is the Activity Center for members and the portal inbox for\n/// Customer Portal users (14 §7). EMAIL and SMS are delivered through 11. SLACK is reserved for\n/// integration delivery (12 §37) and is not in the MVP channel list.\nenum NotificationChannel {\n  IN_APP\n  EMAIL\n  SMS\n  PUSH\n  DESKTOP\n  SLACK\n}\n\n/// 14 §3 — who a notification / preference / digest is addressed to.\nenum NotificationRecipientType {\n  MEMBERSHIP\n  PORTAL_USER\n}\n\n/// 14 §4, §7 — inbox category of an event type; drives the Activity Center filters (unread, mentions,\n/// assigned to me, approvals) and the 12 §18 categories (mentions, replies, DMs, reactions, invitations, reminders).\nenum NotificationCategory {\n  GENERAL\n  MENTION\n  DIRECT_MESSAGE\n  REPLY\n  REACTION\n  ASSIGNMENT\n  APPROVAL\n  STATUS_CHANGE\n  REMINDER\n  DUE_DATE\n  INVITATION\n  SHARE\n  SLA\n  SECURITY\n  BILLING\n  ANNOUNCEMENT\n  SYSTEM\n}\n\n/// 14 §6 — importance used by the \"important only\" preference level and by mandatory events.\nenum NotificationPriority {\n  LOW\n  NORMAL\n  IMPORTANT\n  CRITICAL\n}\n\n/// 14 §6 — recipient level: all events / important only / mentions and direct only / none.\n/// Also the 12 §17 per-channel options (all messages, mentions and DMs, only DMs → MENTIONS_AND_DIRECT, nothing).\nenum NotificationLevel {\n  ALL\n  IMPORTANT_ONLY\n  MENTIONS_AND_DIRECT\n  NONE\n}\n\n/// 14 §6, §8 — immediate delivery or batched into a digest.\nenum NotificationDeliveryMode {\n  IMMEDIATE\n  DIGEST\n  OFF\n}\n\n/// 14 §8 — digest cadence; IMMEDIATE means no digest.\nenum NotificationDigestFrequency {\n  IMMEDIATE\n  HOURLY\n  DAILY\n  WEEKLY\n}\n\n/// 14 §9, §14 — lifecycle of an ingested event.\nenum NotificationEventStatus {\n  RECEIVED\n  PROCESSING\n  PROCESSED\n  /// Duplicate idempotency key or no eligible recipients.\n  IGNORED\n  FAILED\n}\n\n/// 14 §9 — per-channel delivery lifecycle (retry with backoff; in-app never fails silently).\nenum NotificationDeliveryStatus {\n  PENDING\n  QUEUED\n  SENT\n  DELIVERED\n  FAILED\n  /// Not sent because of a preference, rule or channel restriction; see skip_reason.\n  SKIPPED\n  /// Held for a digest (14 §8); digest_id is set.\n  DIGESTED\n  EXPIRED\n  CANCELLED\n}\n\n/// 14 §6, §9, §11 — why a delivery was skipped.\nenum NotificationSkipReason {\n  PREFERENCE_OFF\n  LEVEL_FILTERED\n  RECORD_MUTED\n  QUIET_HOURS\n  CHANNEL_DISABLED\n  CHANNEL_NOT_AVAILABLE\n  NO_ADDRESS\n  NO_DEVICE\n  DEDUPLICATED\n  COALESCED\n  THROTTLED\n  PERMISSION_DENIED\n  NOT_CUSTOMER_VISIBLE\n  EXPIRED\n}\n\n/// 14 §8 — digest lifecycle.\nenum NotificationDigestStatus {\n  OPEN\n  SCHEDULED\n  SENDING\n  SENT\n  /// Period closed with no items.\n  EMPTY\n  FAILED\n}\n\n/// 14 §5 — push target platforms.\nenum NotificationPushPlatform {\n  IOS\n  ANDROID\n  WEB\n  DESKTOP\n}\n\n/// 14 §9, §16 — delivery rule kinds (coalescing rules are Phase 2).\nenum NotificationDeliveryRuleKind {\n  DEDUPLICATE\n  COALESCE\n  THROTTLE\n  SUPPRESS\n}\n\n/// 14 §9 — what a coalesce / throttle rule groups by.\nenum NotificationCoalesceKey {\n  RECORD\n  RECORD_AND_ACTOR\n  EVENT_TYPE\n  RECIPIENT\n}\n\n// --- Event catalog -----------------------------------------------------------------\n\n/// 14 §4, §10, §14 — the event catalog. Platform entries have organization_id = null; organizations may\n/// register additional event types (admin API, 14 §14). The owning module is the source of truth for meaning.\nmodel NotificationEventType {\n  id                      String                @id @default(uuid())\n  /// null = platform catalog entry shared by all organizations.\n  organization_id         String?\n  /// Stable key, e.g. `task.assigned`, `invoice.overdue`, `contract.expiring` (14 §4).\n  key                     String\n  /// Owning module (14 §4 table).\n  module                  ModuleKey\n  name                    String\n  description             String?\n  category                NotificationCategory  @default(GENERAL)\n  priority                NotificationPriority  @default(NORMAL)\n  /// 14 §5, §11 — may be delivered to Customer Portal users; internal-only events are never customer-visible.\n  customer_visible        Boolean               @default(false)\n  /// 14 §5 — channels enabled by platform default when no org default / preference applies.\n  default_channels        NotificationChannel[] @default([IN_APP])\n  /// 14 §6 — platform-mandatory (security alerts, legal notices); organizations extend via NotificationOrgDefault.\n  mandatory_by_default    Boolean               @default(false)\n  /// 14 §6, §9 — channels always used for this event when mandatory (e.g. security alerts → EMAIL), ignoring recipient preferences.\n  forced_channels         NotificationChannel[] @default([])\n  /// 14 §9 — rapid repeated events on the same record may collapse into one notification.\n  can_coalesce            Boolean               @default(false)\n  coalesce_window_seconds Int?\n  /// 14 §8 — may be batched into digests.\n  supports_digest         Boolean               @default(true)\n  /// 14 §9 — default expiry for notifications of this type (e.g. meeting reminders).\n  default_expiry_minutes  Int?\n  /// 14 §7 — actions the inbox can offer (approve, reply, complete, …), resolved by the owning module.\n  available_actions       String[]              @default([])\n  /// JSON schema of the event payload / template variables (14 §10).\n  payload_schema          Json?\n  is_active               Boolean               @default(true)\n  deprecated_at           DateTime?\n  sort_order              Int                   @default(0)\n  created_at              DateTime              @default(now())\n  updated_at              DateTime              @updatedAt\n\n  organization   Organization?              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  events         NotificationEvent[]\n  notifications  Notification[]\n  templates      NotificationTemplate[]\n  org_defaults   NotificationOrgDefault[]\n  preferences    NotificationPreference[]\n  delivery_rules NotificationDeliveryRule[]\n\n  @@unique([organization_id, key])\n  @@index([module, is_active])\n  @@index([category])\n  @@map(\"notification_event_types\")\n}\n\n// --- Events (ingestion) --------------------------------------------------------------\n\n/// 14 §2, §9, §14 — an event published by a module or the Automation Engine (20). Idempotent on\n/// (organization_id, idempotency_key): redelivered events never create duplicate notifications.\nmodel NotificationEvent {\n  id                       String                  @id @default(uuid())\n  organization_id          String\n  event_type_id            String\n  /// Denormalized event type key for querying without a join.\n  event_key                String\n  /// Caller-supplied id (14 §9 idempotency); defaults to the publisher's own event id.\n  idempotency_key          String\n  /// Source record (14 §2).\n  entity_type              RecordEntityType?\n  entity_id                String?\n  /// Display label of the source record at the time of the event.\n  entity_label             String?\n  actor_membership_id      String?\n  /// Platform / portal user actor when not a member (e.g. customer reply from the portal).\n  actor_user_id            String?\n  /// 01 ServiceAccount id when published by an integration.\n  actor_service_account_id String?\n  /// Event payload used for recipient resolution and template variables.\n  payload                  Json\n  /// 14 §3 — declared audiences before expansion: { membership_ids, user_ids, team_ids, role_ids, scope: … }.\n  /// Teams, roles and scopes are expanded to Memberships at delivery time.\n  targets                  Json?\n  /// 14 §9 — coalescing key (defaults to event_key + entity); notifications inherit it.\n  group_key                String?\n  /// 14 §9 — not delivered after this moment.\n  expires_at               DateTime?\n  /// 20 PlatformEvent id when the event came from the event bus.\n  platform_event_id        String?\n  /// 20 AutomationRule id when a rule published the event (14 §16).\n  automation_rule_id       String?\n  status                   NotificationEventStatus @default(RECEIVED)\n  /// Number of notifications produced.\n  notification_count       Int                     @default(0)\n  error                    String?\n  occurred_at              DateTime                @default(now())\n  received_at              DateTime                @default(now())\n  processed_at             DateTime?\n\n  organization  Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  event_type    NotificationEventType @relation(fields: [event_type_id], references: [id], onDelete: Restrict)\n  actor         Membership?           @relation(\"NotificationEventActor\", fields: [actor_membership_id], references: [id], onDelete: SetNull)\n  notifications Notification[]\n\n  @@unique([organization_id, idempotency_key])\n  @@index([organization_id, status, received_at])\n  @@index([organization_id, event_key, occurred_at])\n  @@index([entity_type, entity_id])\n  @@index([group_key])\n  @@map(\"notification_events\")\n}\n\n// --- Notifications (inbox) -------------------------------------------------------------\n\n/// 14 §2, §7, §9, 12 §16, §18 — a message produced from an event for one recipient (a Membership or a Customer Portal\n/// User). The in-app record is always stored (14 §5); per-channel deliveries hang off it.\nmodel Notification {\n  id                      String                    @id @default(uuid())\n  organization_id         String\n  event_id                String?\n  event_type_id           String\n  /// Denormalized for inbox filters without joins.\n  event_key               String\n  module                  ModuleKey\n  category                NotificationCategory      @default(GENERAL)\n  priority                NotificationPriority      @default(NORMAL)\n  recipient_type          NotificationRecipientType\n  recipient_membership_id String?\n  /// Customer Portal User (01 §79) — set with portal_membership_id for portal-scoped inboxes (14 §7).\n  recipient_user_id       String?\n  portal_membership_id    String?\n  /// 14 §3 — why this recipient was selected: assignee | watcher | mention | owner | team:<id> | role:<id> | follow.\n  audience_reason         String?\n  title                   String\n  /// Short plain-text body / preview. Hidden on push/desktop/email when previews are disabled (14 §11).\n  body                    String?\n  icon                    String?\n  /// Deep link to the source record or message (14 §8).\n  action_url              String?\n  entity_type             RecordEntityType?\n  entity_id               String?\n  entity_label            String?\n  actor_membership_id     String?\n  actor_user_id           String?\n  /// Extra template / UI data from the event payload.\n  data                    Json?\n  /// 14 §6 — cannot be muted (security alerts, SLA breaches, legal notices).\n  is_mandatory            Boolean                   @default(false)\n  /// 14 §7 — waiting on the recipient (approvals section); cleared when the action is taken.\n  requires_action         Boolean                   @default(false)\n  /// 14 §7 — inline actions offered: [{ key, label, style }].\n  actions                 Json?\n  action_taken            String?\n  action_taken_at         DateTime?\n  /// 14 §9 — coalescing: later events with the same key update this row instead of creating a new one.\n  group_key               String?\n  coalesced_count         Int                       @default(1)\n  last_event_at           DateTime                  @default(now())\n  /// 14 §7 — read / seen / archive / snooze state.\n  seen_at                 DateTime?\n  read_at                 DateTime?\n  archived_at             DateTime?\n  snoozed_until           DateTime?\n  /// 14 §9 — not delivered after this moment.\n  expires_at              DateTime?\n  created_at              DateTime                  @default(now())\n  updated_at              DateTime                  @updatedAt\n\n  organization         Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  event                NotificationEvent?        @relation(fields: [event_id], references: [id], onDelete: SetNull)\n  event_type           NotificationEventType     @relation(fields: [event_type_id], references: [id], onDelete: Restrict)\n  recipient_membership Membership?               @relation(\"NotificationRecipientMembership\", fields: [recipient_membership_id], references: [id], onDelete: Cascade)\n  recipient_user       User?                     @relation(\"NotificationRecipientUser\", fields: [recipient_user_id], references: [id], onDelete: Cascade)\n  portal_membership    CustomerPortalMembership? @relation(fields: [portal_membership_id], references: [id], onDelete: Cascade)\n  actor                Membership?               @relation(\"NotificationActorMembership\", fields: [actor_membership_id], references: [id], onDelete: SetNull)\n  deliveries           NotificationDelivery[]\n\n  // 14 §9 — the same event never produces two notifications for one recipient.\n  @@unique([event_id, recipient_membership_id])\n  @@unique([event_id, recipient_user_id])\n  @@index([organization_id, recipient_membership_id, read_at, created_at])\n  @@index([organization_id, recipient_user_id, read_at, created_at])\n  @@index([recipient_membership_id, requires_action])\n  @@index([recipient_membership_id, category])\n  @@index([organization_id, group_key])\n  @@index([entity_type, entity_id])\n  @@index([snoozed_until])\n  @@index([expires_at])\n  @@map(\"notifications\")\n}\n\n/// 14 §5, §9 — one delivery attempt record per channel of a notification. Email/SMS are sent through 11\n/// (comm_message_id); push through NotificationPushDevice; in-app is the Notification row itself.\nmodel NotificationDelivery {\n  id                  String                     @id @default(uuid())\n  organization_id     String\n  notification_id     String\n  channel             NotificationChannel\n  status              NotificationDeliveryStatus @default(PENDING)\n  skip_reason         NotificationSkipReason?\n  /// 14 §9 — retry with backoff.\n  attempt_count       Int                        @default(0)\n  max_attempts        Int                        @default(5)\n  next_attempt_at     DateTime?\n  last_attempted_at   DateTime?\n  sent_at             DateTime?\n  delivered_at        DateTime?\n  failed_at           DateTime?\n  failure_reason      String?\n  /// 14 §8 — set when held for / sent inside a digest.\n  digest_id           String?\n  /// Template and locale used to render this delivery (14 §10).\n  template_id         String?\n  locale              String?\n  rendered_subject    String?\n  rendered_body       String?\n  /// Address the delivery went to (email, phone, device label); previews may be hidden (14 §11).\n  destination         String?\n  preview_hidden      Boolean                    @default(false)\n  /// 11 CommMessage id for EMAIL / SMS deliveries.\n  comm_message_id     String?\n  push_device_id      String?\n  /// Provider name (resend, twilio, fcm, apns, web-push, slack) and its message id / raw response.\n  provider            String?\n  provider_message_id String?\n  provider_response   Json?\n  /// 14 §16 — notification analytics.\n  opened_at           DateTime?\n  clicked_at          DateTime?\n  expires_at          DateTime?\n  created_at          DateTime                   @default(now())\n  updated_at          DateTime                   @updatedAt\n\n  organization Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  notification Notification            @relation(fields: [notification_id], references: [id], onDelete: Cascade)\n  digest       NotificationDigest?     @relation(fields: [digest_id], references: [id], onDelete: SetNull)\n  template     NotificationTemplate?   @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  push_device  NotificationPushDevice? @relation(fields: [push_device_id], references: [id], onDelete: SetNull)\n\n  // 14 §9, §17 — one recipient, one channel, one delivery per notification.\n  @@unique([notification_id, channel])\n  @@index([organization_id, status, next_attempt_at])\n  @@index([organization_id, channel, created_at])\n  @@index([digest_id])\n  @@index([comm_message_id])\n  @@index([provider_message_id])\n  @@map(\"notification_deliveries\")\n}\n\n// --- Templates & localization ----------------------------------------------------------\n\n/// 14 §10 — notification template per event type, channel and locale. organization_id = null is the\n/// platform default; organization rows override it. Branding (01 §15) is applied to email at render time.\nmodel NotificationTemplate {\n  id                       String              @id @default(uuid())\n  organization_id          String?\n  event_type_id            String\n  channel                  NotificationChannel\n  /// BCP-47 locale (en, el, …); null = fallback for every locale.\n  locale                   String?\n  /// Email subject / push title; supports {{variables}} from the event payload.\n  subject                  String?\n  title                    String\n  /// Plain-text / markdown body with {{variables}}.\n  body                     String\n  /// HTML body for EMAIL.\n  html_body                String?\n  /// Template for the primary call-to-action label and link.\n  cta_label                String?\n  cta_url                  String?\n  /// Variables the template expects: [{ key, description, example }].\n  variables                Json?\n  version                  Int                 @default(1)\n  is_active                Boolean             @default(true)\n  created_by_membership_id String?\n  updated_by_membership_id String?\n  created_at               DateTime            @default(now())\n  updated_at               DateTime            @updatedAt\n\n  organization Organization?          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  event_type   NotificationEventType  @relation(fields: [event_type_id], references: [id], onDelete: Cascade)\n  deliveries   NotificationDelivery[]\n\n  @@unique([organization_id, event_type_id, channel, locale])\n  @@index([event_type_id, channel])\n  @@map(\"notification_templates\")\n}\n\n// --- Organization configuration -----------------------------------------------------------\n\n/// 14 §5, §6, §8, §11 — organization-wide notification settings (one row per organization).\nmodel NotificationOrgSettings {\n  organization_id          String                      @id\n  /// 14 §5 — channels available to members; others are restricted for the whole organization.\n  enabled_channels         NotificationChannel[]       @default([IN_APP, EMAIL])\n  /// 14 §5 — channels available to Customer Portal users (in-app, email, optionally SMS).\n  portal_enabled_channels  NotificationChannel[]       @default([IN_APP, EMAIL])\n  /// 11 SenderIdentity used for notification emails / SMS.\n  email_sender_identity_id String?\n  sms_sender_identity_id   String?\n  default_level            NotificationLevel           @default(ALL)\n  default_digest_frequency NotificationDigestFrequency @default(IMMEDIATE)\n  /// Local hour (0–23) / weekday (0–6) when daily / weekly digests are sent.\n  default_digest_hour      Int                         @default(8)\n  default_digest_weekday   Int                         @default(1)\n  /// 14 §11 — hide message content in push, desktop and email previews by default.\n  hide_previews_by_default Boolean                     @default(false)\n  /// 14 §9 — default retry policy for failed channel deliveries.\n  max_delivery_attempts    Int                         @default(5)\n  retry_backoff_seconds    Int                         @default(60)\n  /// Days to keep read / archived notifications before purge; null = keep.\n  retention_days           Int?\n  /// 14 §14 — emit notification.* webhook events through 20 OutboundWebhook.\n  webhook_events_enabled   Boolean                     @default(false)\n  updated_by_membership_id String?\n  created_at               DateTime                    @default(now())\n  updated_at               DateTime                    @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"notification_org_settings\")\n}\n\n/// 14 §6 — organization defaults per module or per event type (preference layer 4) and the list of\n/// mandatory events administrators configure. Exactly one of module / event_type_id is set.\nmodel NotificationOrgDefault {\n  id                       String                      @id @default(uuid())\n  organization_id          String\n  module                   ModuleKey?\n  event_type_id            String?\n  enabled                  Boolean                     @default(true)\n  /// Channels enabled by default for members.\n  channels                 NotificationChannel[]       @default([IN_APP])\n  /// Channels enabled by default for Customer Portal users (only for customer-visible events).\n  portal_channels          NotificationChannel[]       @default([IN_APP, EMAIL])\n  delivery_mode            NotificationDeliveryMode    @default(IMMEDIATE)\n  digest_frequency         NotificationDigestFrequency @default(DAILY)\n  /// 14 §6 — users cannot mute this event (security alerts, SLA breaches, legal notices).\n  is_mandatory             Boolean                     @default(false)\n  updated_by_membership_id String?\n  created_at               DateTime                    @default(now())\n  updated_at               DateTime                    @updatedAt\n\n  organization Organization           @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  event_type   NotificationEventType? @relation(fields: [event_type_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, module])\n  @@unique([organization_id, event_type_id])\n  @@map(\"notification_org_defaults\")\n}\n\n// --- Recipient settings & preferences ---------------------------------------------------------\n\n/// 14 §6 — per-recipient global settings (preference layer 3): level, Do Not Disturb / quiet hours,\n/// digest mode, preview privacy (12 §87) and channel master switches (12 §17). One row per Membership\n/// or per Customer Portal membership.\nmodel NotificationRecipientSettings {\n  id                     String                      @id @default(uuid())\n  organization_id        String\n  recipient_type         NotificationRecipientType\n  membership_id          String?                     @unique\n  portal_membership_id   String?                     @unique\n  level                  NotificationLevel           @default(ALL)\n  // Channel master switches (12 §17: desktop, mobile, email notifications, sound).\n  in_app_enabled         Boolean                     @default(true)\n  email_enabled          Boolean                     @default(true)\n  sms_enabled            Boolean                     @default(false)\n  push_enabled           Boolean                     @default(true)\n  desktop_enabled        Boolean                     @default(true)\n  sound_enabled          Boolean                     @default(true)\n  // 14 §6 — Do Not Disturb schedule and time zone.\n  dnd_enabled            Boolean                     @default(false)\n  /// \"HH:mm\" local time in `timezone`.\n  dnd_start_time         String?\n  dnd_end_time           String?\n  /// Weekdays (0 = Sunday … 6 = Saturday) the schedule applies to; empty = every day.\n  dnd_weekdays           Int[]                       @default([])\n  /// Temporary DND (\"pause for 1 hour / until tomorrow\").\n  dnd_until              DateTime?\n  /// IANA time zone; null = the user's / organization's time zone (01 §127).\n  timezone               String?\n  /// 14 §6 — deliver mandatory / CRITICAL notifications even during DND.\n  dnd_allow_critical     Boolean                     @default(true)\n  // 14 §8 — digest instead of immediate delivery.\n  digest_frequency       NotificationDigestFrequency @default(IMMEDIATE)\n  digest_channel         NotificationChannel         @default(EMAIL)\n  digest_hour            Int?\n  digest_weekday         Int?\n  /// 14 §6, §11 — whether push / desktop / email previews include message content (12 §87).\n  show_previews          Boolean                     @default(true)\n  // 12 §17 — messaging-specific toggles layered on 14.\n  thread_notifications   Boolean                     @default(true)\n  reaction_notifications Boolean                     @default(true)\n  keyword_notifications  Boolean                     @default(true)\n  /// Preferred notification language; null = user language (01 §127).\n  language               String?\n  created_at             DateTime                    @default(now())\n  updated_at             DateTime                    @updatedAt\n\n  organization      Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership        Membership?               @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  portal_membership CustomerPortalMembership? @relation(fields: [portal_membership_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id])\n  @@map(\"notification_recipient_settings\")\n}\n\n/// 14 §6 — per-recipient preference rows for layers 1–2, reusable by 12 §17 and §32 for channel /\n/// conversation mute. Scope is exactly one of: event_type_id (per event type), module (per module), or\n/// (entity_type, entity_id) (per record: follow / mute a messaging channel, project, ticket …).\n/// channel = null applies to every channel. `scope_key` and `recipient_key` are derived by the service\n/// (`event:<key>` | `module:<MODULE>` | `record:<ENTITY_TYPE>:<id>`, `m:<membership_id>` | `p:<portal_membership_id>`)\n/// so one unique index can cover the nullable scope columns.\nmodel NotificationPreference {\n  id                   String                    @id @default(uuid())\n  organization_id      String\n  recipient_type       NotificationRecipientType\n  membership_id        String?\n  portal_membership_id String?\n  recipient_key        String\n  // Scope\n  event_type_id        String?\n  module               ModuleKey?\n  entity_type          RecordEntityType?\n  entity_id            String?\n  scope_key            String\n  /// null = all channels.\n  channel              NotificationChannel?\n  /// false = muted for this scope / channel (14 §6 per-record mute, 12 §17 per-channel settings).\n  enabled              Boolean                   @default(true)\n  /// Record / module scope: all / important only / mentions and direct only / none (12 §17).\n  level                NotificationLevel?\n  delivery_mode        NotificationDeliveryMode  @default(IMMEDIATE)\n  /// Record scope: receive every event on the record even when not a participant (\"follow this project\").\n  is_following         Boolean                   @default(false)\n  /// Temporary mute (\"mute for 8 hours\"); null = indefinite while enabled = false.\n  muted_until          DateTime?\n  created_at           DateTime                  @default(now())\n  updated_at           DateTime                  @updatedAt\n\n  organization      Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership        Membership?               @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  portal_membership CustomerPortalMembership? @relation(fields: [portal_membership_id], references: [id], onDelete: Cascade)\n  event_type        NotificationEventType?    @relation(fields: [event_type_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, recipient_key, scope_key, channel])\n  @@index([membership_id, event_type_id])\n  @@index([membership_id, entity_type, entity_id])\n  @@index([portal_membership_id])\n  @@index([entity_type, entity_id])\n  @@map(\"notification_preferences\")\n}\n\n/// 14 §6, §16 — keyword subscriptions (12 §32): the member is notified when the term appears in an\n/// authorized conversation. Phase 2.\nmodel NotificationKeyword {\n  id               String                @id @default(uuid())\n  organization_id  String\n  membership_id    String\n  keyword          String\n  match_whole_word Boolean               @default(true)\n  case_sensitive   Boolean               @default(false)\n  /// Channels to notify on; empty = recipient's defaults.\n  channels         NotificationChannel[] @default([])\n  is_enabled       Boolean               @default(true)\n  /// 12 §32 — \"disable temporarily\".\n  disabled_until   DateTime?\n  created_at       DateTime              @default(now())\n  updated_at       DateTime              @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership   Membership   @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([membership_id, keyword])\n  @@index([organization_id, is_enabled])\n  @@map(\"notification_keywords\")\n}\n\n// --- Digests ----------------------------------------------------------------------------------\n\n/// 14 §8 — a batch of notifications for one recipient and period, per module or per record\n/// (12 Messaging channel digest). Deliveries held for the digest point at it; the digest itself is sent\n/// through 11 (comm_message_id) or push.\nmodel NotificationDigest {\n  id                   String                      @id @default(uuid())\n  organization_id      String\n  recipient_type       NotificationRecipientType\n  membership_id        String?\n  portal_membership_id String?\n  /// Portal User id for PORTAL_USER recipients.\n  recipient_user_id    String?\n  frequency            NotificationDigestFrequency\n  channel              NotificationChannel         @default(EMAIL)\n  /// Scope: null/null = all modules; module = per module; entity = per record (12 channel digest).\n  module               ModuleKey?\n  entity_type          RecordEntityType?\n  entity_id            String?\n  period_start         DateTime\n  period_end           DateTime\n  scheduled_for        DateTime\n  status               NotificationDigestStatus    @default(OPEN)\n  item_count           Int                         @default(0)\n  locale               String?\n  rendered_subject     String?\n  rendered_body        String?\n  /// 11 CommMessage id of the sent digest (EMAIL / SMS).\n  comm_message_id      String?\n  provider_message_id  String?\n  sent_at              DateTime?\n  failed_at            DateTime?\n  failure_reason       String?\n  attempt_count        Int                         @default(0)\n  created_at           DateTime                    @default(now())\n  updated_at           DateTime                    @updatedAt\n\n  organization      Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership        Membership?               @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  portal_membership CustomerPortalMembership? @relation(fields: [portal_membership_id], references: [id], onDelete: Cascade)\n  deliveries        NotificationDelivery[]\n\n  @@index([organization_id, status, scheduled_for])\n  @@index([membership_id, status, period_start])\n  @@index([portal_membership_id, status])\n  @@map(\"notification_digests\")\n}\n\n// --- Push devices ----------------------------------------------------------------------------\n\n/// 14 §5 — registered push targets (mobile, browser, desktop) per platform User. User-level because a\n/// device is not tenant-specific; the active membership at registration is kept for diagnostics.\nmodel NotificationPushDevice {\n  id            String                   @id @default(uuid())\n  user_id       String\n  /// Membership active when the device registered; informational only.\n  membership_id String?\n  platform      NotificationPushPlatform\n  /// fcm | apns | web-push | electron\n  provider      String\n  /// Device / registration token (FCM / APNs) or Web Push endpoint.\n  token         String\n  /// Web Push subscription (endpoint, keys) when platform = WEB.\n  subscription  Json?\n  device_name   String?\n  app_version   String?\n  locale        String?\n  last_seen_at  DateTime?\n  /// Consecutive provider failures; the device is disabled after the provider reports an invalid token.\n  failure_count Int                      @default(0)\n  disabled_at   DateTime?\n  created_at    DateTime                 @default(now())\n  updated_at    DateTime                 @updatedAt\n\n  user       User                   @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  deliveries NotificationDelivery[]\n\n  @@unique([platform, token])\n  @@index([user_id, disabled_at])\n  @@map(\"notification_push_devices\")\n}\n\n// --- Delivery rules -----------------------------------------------------------------------------\n\n/// 14 §9, §16 — organization-level dedup / coalesce / throttle / suppress rules evaluated before delivery.\n/// A rule applies to the matching event type (or module, or all) and channel (or all). Rules may be\n/// created by 20 Automation (automation_rule_id).\nmodel NotificationDeliveryRule {\n  id                       String                       @id @default(uuid())\n  organization_id          String\n  name                     String\n  kind                     NotificationDeliveryRuleKind\n  event_type_id            String?\n  module                   ModuleKey?\n  channel                  NotificationChannel?\n  /// Window in which DEDUPLICATE / COALESCE / THROTTLE apply.\n  window_seconds           Int?\n  /// THROTTLE: max notifications per recipient per window.\n  max_per_window           Int?\n  coalesce_key             NotificationCoalesceKey?\n  /// Extra matching conditions on the event payload (JSON logic), 14 §16.\n  conditions               Json?\n  /// 20 AutomationRule id when managed by the Automation Engine.\n  automation_rule_id       String?\n  priority                 Int                          @default(0)\n  is_active                Boolean                      @default(true)\n  created_by_membership_id String?\n  created_at               DateTime                     @default(now())\n  updated_at               DateTime                     @updatedAt\n\n  organization Organization           @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  event_type   NotificationEventType? @relation(fields: [event_type_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, is_active, kind])\n  @@index([event_type_id])\n  @@map(\"notification_delivery_rules\")\n}\n\n// =====================================================================\n// 15 Business Docs (Internal Knowledge) — docs/features/15-notion-business-docs.md (LOG-341)\n// Owns: wiki spaces, hierarchical pages (block content), page templates, versions, page-level\n// permissions, record links, comments, favorites, review/acknowledgement tracking, onboarding &\n// offboarding checklists, custom forms, form assignments & submissions, AI knowledge index.\n// Does not own: customer-facing help center (13 §6), file storage (17), project notes (05 §33–34),\n// members/teams/branches/roles (01), employees/departments (10), tasks (06), notifications (14),\n// automation rules (20). Those are related or referenced by id only. Activity goes to audit_events.\n// =====================================================================\n\n/// 15 §2 — what a space is organised around (department, team, branch, project or topic).\nenum WikiSpaceKind {\n  DEPARTMENT\n  TEAM\n  BRANCH\n  PROJECT\n  TOPIC\n}\n\n/// 15 §2 — page lifecycle: draft, published, needs review, archived.\nenum WikiPageStatus {\n  DRAFT\n  PUBLISHED\n  NEEDS_REVIEW\n  ARCHIVED\n}\n\n/// 15 §2, §3, §4 — template / page kinds (policy, procedure, runbook, meeting notes, decision record,\n/// handbook chapter, onboarding/offboarding guides, FAQ).\nenum WikiPageType {\n  GENERAL\n  POLICY\n  PROCEDURE\n  RUNBOOK\n  MEETING_NOTES\n  DECISION_RECORD\n  HANDBOOK_CHAPTER\n  ONBOARDING_GUIDE\n  OFFBOARDING_GUIDE\n  FAQ\n}\n\n/// 15 §2 — who may see a page: whole organization, a branch, a team, a role or explicit members.\n/// BRANCH / TEAM / ROLE / MEMBERS enumerate the principals in WikiPagePermission.\nenum WikiVisibility {\n  ORGANIZATION\n  BRANCH\n  TEAM\n  ROLE\n  MEMBERS\n}\n\n/// 15 §2, §8 — access level granted by a space membership or page permission.\nenum WikiPermissionLevel {\n  VIEW\n  COMMENT\n  EDIT\n  MANAGE\n}\n\n/// 15 §2 — principal kinds a page permission can be granted to. DEPARTMENT ids are Department = Team of kind DEPARTMENT (01 §43)s.\nenum WikiPrincipalType {\n  MEMBERSHIP\n  TEAM\n  BRANCH\n  ROLE\n  DEPARTMENT\n}\n\n/// 15 §3 — onboarding vs offboarding checklist.\nenum WikiChecklistKind {\n  ONBOARDING\n  OFFBOARDING\n}\n\n/// 15 §3 — who a checklist item's generated Task (06) is assigned to.\nenum WikiChecklistAssigneeKind {\n  SUBJECT\n  MANAGER\n  CHECKLIST_OWNER\n  SPECIFIC_MEMBER\n}\n\n/// 15 §3 — lifecycle of a checklist run for one member.\nenum WikiChecklistRunStatus {\n  NOT_STARTED\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\n/// 15 §3 — how a checklist run was started.\nenum WikiChecklistTrigger {\n  MEMBER_ONBOARDING\n  MEMBER_OFFBOARDING\n  MANUAL\n  AUTOMATION\n}\n\n/// 15 §3 — status of one item inside a checklist run.\nenum WikiChecklistItemStatus {\n  PENDING\n  IN_PROGRESS\n  COMPLETED\n  SKIPPED\n}\n\n/// 15 §5 — form lifecycle.\nenum CustomFormStatus {\n  DRAFT\n  PUBLISHED\n  CLOSED\n  ARCHIVED\n}\n\n/// 15 §5 — typical form kinds; CUSTOM for anything else.\nenum CustomFormKind {\n  FEEDBACK_SURVEY\n  CHECK_IN\n  EQUIPMENT_REQUEST\n  INCIDENT_REPORT\n  COMPLIANCE_ACKNOWLEDGEMENT\n  EXIT_INTERVIEW\n  CUSTOM\n}\n\n/// 15 §5 — allowed `type` values inside CustomForm.fields_schema. FILE_UPLOAD stores Documents (17);\n/// SIGNATURE captures a drawn/typed signature image stored as a Document (17) — not a 04 signature request.\nenum CustomFormFieldType {\n  SHORT_TEXT\n  LONG_TEXT\n  NUMBER\n  EMAIL\n  SINGLE_CHOICE\n  MULTI_CHOICE\n  CHECKBOX\n  SCALE\n  DATE\n  FILE_UPLOAD\n  SIGNATURE\n  SECTION\n}\n\n/// 15 §5 — who a form is assigned to; recipients are expanded per Membership.\nenum FormAssignmentTargetType {\n  MEMBERSHIP\n  TEAM\n  DEPARTMENT\n  BRANCH\n  ORGANIZATION\n}\n\n/// 15 §5 — per-recipient assignment state.\nenum FormAssignmentRecipientStatus {\n  PENDING\n  IN_PROGRESS\n  SUBMITTED\n  OVERDUE\n  CANCELLED\n}\n\n/// 15 §5 — submission lifecycle (review step is optional per form).\nenum FormSubmissionStatus {\n  DRAFT\n  SUBMITTED\n  UNDER_REVIEW\n  REVIEWED\n  REJECTED\n}\n\n/// 15 §6 — kind of content an AI knowledge index entry was built from.\nenum WikiAiSourceType {\n  WIKI_PAGE\n  CUSTOM_FORM\n  FORM_SUBMISSION\n  LINKED_RECORD\n  /// 13 §3, §6 — customer-facing help-center article (KnowledgeArticle), indexed for semantic search and the AI support agent.\n  KNOWLEDGE_ARTICLE\n}\n\n/// 15 §6 — index entry freshness.\nenum WikiAiIndexStatus {\n  PENDING\n  INDEXED\n  STALE\n  FAILED\n}\n\n/// 15 §6 — AI proposals: new page drafts, updates to existing pages, stale and contradiction flags.\nenum WikiAiSuggestionKind {\n  DRAFT_PAGE\n  UPDATE_PAGE\n  STALE_PAGE\n  CONTRADICTION\n}\n\n/// 15 §6 — review outcome of an AI suggestion.\nenum WikiAiSuggestionStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n  DISMISSED\n}\n\n// --- Spaces -----------------------------------------------------------------------\n\n/// 15 §2, §4 — a space groups pages per department, team, branch, project or topic.\n/// Exactly one of team_id / branch_id / department_id / project_id is normally set for the matching kind;\n/// TOPIC spaces set none.\nmodel WikiSpace {\n  id                  String         @id @default(uuid())\n  organization_id     String\n  name                String\n  slug                String\n  description         String?\n  icon                String?\n  color               String?\n  kind                WikiSpaceKind  @default(TOPIC)\n  team_id             String?\n  branch_id           String?\n  /// Department = Team of kind DEPARTMENT (01 §43).\n  department_id       String?\n  /// 15 §4 — project help center space (05 §34).\n  project_id          String?\n  owner_membership_id String?\n  /// Default visibility applied to new pages in this space (15 §2).\n  default_visibility  WikiVisibility @default(ORGANIZATION)\n  /// Private spaces are visible only to WikiSpaceMember rows regardless of page visibility.\n  is_private          Boolean        @default(false)\n  sort_order          Int            @default(0)\n  archived_at         DateTime?\n  created_by_user_id  String?\n  created_at          DateTime       @default(now())\n  updated_at          DateTime       @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  branch       Branch?      @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  project      Project?     @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  owner        Membership?  @relation(\"WikiSpaceOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n\n  members   WikiSpaceMember[]\n  pages     WikiPage[]\n  templates WikiPageTemplate[]\n  forms     CustomForm[]\n\n  department Team? @relation(\"WikiSpaceDepartment\", fields: [department_id], references: [id], onDelete: SetNull)\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, kind])\n  @@index([team_id])\n  @@index([branch_id])\n  @@index([project_id])\n  @@map(\"wiki_spaces\")\n}\n\n/// 15 §2, §8 — explicit space members with their access level (space managers hold `docs.spaces.manage`).\nmodel WikiSpaceMember {\n  space_id         String\n  membership_id    String\n  level            WikiPermissionLevel @default(VIEW)\n  added_by_user_id String?\n  created_at       DateTime            @default(now())\n\n  space      WikiSpace  @relation(fields: [space_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([space_id, membership_id])\n  @@index([membership_id])\n  @@map(\"wiki_space_members\")\n}\n\n// --- Templates --------------------------------------------------------------------\n\n/// 15 §2, §3 — page templates (policy, procedure, runbook, meeting notes, decision record, handbook chapter,\n/// onboarding/offboarding guide). organization_id null = platform-provided system template.\nmodel WikiPageTemplate {\n  id                           String       @id @default(uuid())\n  organization_id              String?\n  /// Optional: template offered only inside this space.\n  space_id                     String?\n  name                         String\n  slug                         String\n  description                  String?\n  icon                         String?\n  page_type                    WikiPageType @default(GENERAL)\n  /// Block-structured content (same shape as WikiPage.content).\n  content                      Json?\n  /// Markdown rendering of `content` for preview/search.\n  content_markdown             String?\n  /// Default review cadence for pages created from this template (15 §2).\n  default_review_interval_days Int?\n  is_system                    Boolean      @default(false)\n  sort_order                   Int          @default(0)\n  archived_at                  DateTime?\n  created_by_user_id           String?\n  created_at                   DateTime     @default(now())\n  updated_at                   DateTime     @updatedAt\n\n  organization Organization? @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  space        WikiSpace?    @relation(fields: [space_id], references: [id], onDelete: SetNull)\n  pages        WikiPage[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, page_type])\n  @@map(\"wiki_page_templates\")\n}\n\n// --- Pages ------------------------------------------------------------------------\n\n/// 15 §2, §4 — a nested page. `content` is a block tree (Notion-style: paragraph, heading, list, checklist,\n/// table, code, image/embed → Document (17), record link → RecordEntityType + id); `content_markdown` is\n/// the rendered markdown used for search (15 §7) and AI indexing (15 §6).\nmodel WikiPage {\n  id                             String                   @id @default(uuid())\n  organization_id                String\n  space_id                       String\n  parent_page_id                 String?\n  template_id                    String?\n  title                          String\n  slug                           String\n  icon                           String?\n  /// Cover image Document (17); id only.\n  cover_document_id              String?\n  page_type                      WikiPageType             @default(GENERAL)\n  status                         WikiPageStatus           @default(DRAFT)\n  /// Block tree: [{ id, type, props, children: [...] }].\n  content                        Json?\n  content_markdown               String?\n  /// Short plain-text excerpt for lists and search snippets.\n  excerpt                        String?\n  /// Materialized path of ancestor page ids (`/a/b/`), for subtree queries and breadcrumbs.\n  path                           String                   @default(\"\")\n  depth                          Int                      @default(0)\n  sort_order                     Int                      @default(0)\n  // 15 §2 — visibility & exposure\n  visibility                     WikiVisibility           @default(ORGANIZATION)\n  /// 15 §4 — exposed through the Customer Portal (07) / help center (13 §6). Audited (15 §9).\n  customer_visible               Boolean                  @default(false)\n  /// 13 §6 KnowledgeArticle view published from this page (13 owns the article; the page is the source); id only.\n  help_center_article_id         String?\n  help_center_published_at       DateTime?\n  // 15 §2 — ownership & review cadence\n  owner_membership_id            String?\n  review_interval_days           Int?\n  last_reviewed_at               DateTime?\n  last_reviewed_by_membership_id String?\n  next_review_at                 DateTime?                @db.Date\n  /// Set by stale detection (15 §2, §6) when next_review_at has passed or AI flagged it; cleared on review.\n  stale_flagged_at               DateTime?\n  /// 15 §3 — members assigned this page must acknowledge reading it (WikiPageAcknowledgement).\n  requires_acknowledgement       Boolean                  @default(false)\n  // 15 §2 — versions & publishing\n  current_version_number         Int                      @default(0)\n  published_at                   DateTime?\n  published_by_membership_id     String?\n  published_version_number       Int?\n  /// Set while a member holds an edit lock (collaborative editing guard).\n  locked_by_membership_id        String?\n  locked_at                      DateTime?\n  /// 15 §6 — page created or last rewritten by the AI assistant and accepted after review.\n  ai_generated                   Boolean                  @default(false)\n  last_edited_by_membership_id   String?\n  last_edited_at                 DateTime?\n  word_count                     Int                      @default(0)\n  archived_at                    DateTime?\n  created_by_user_id             String?\n  created_at                     DateTime                 @default(now())\n  updated_at                     DateTime                 @updatedAt\n  /// 15 §7 — Postgres full-text search vector over title + content_markdown; maintained by a database trigger (see migration). Not set by the API.\n  search_vector                  Unsupported(\"tsvector\")?\n\n  organization Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  space        WikiSpace         @relation(fields: [space_id], references: [id], onDelete: Cascade)\n  parent       WikiPage?         @relation(\"WikiPageHierarchy\", fields: [parent_page_id], references: [id], onDelete: SetNull)\n  children     WikiPage[]        @relation(\"WikiPageHierarchy\")\n  template     WikiPageTemplate? @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  owner        Membership?       @relation(\"WikiPageOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n\n  reviewers            WikiPageReviewer[]\n  versions             WikiPageVersion[]\n  permissions          WikiPagePermission[]\n  links                WikiPageLink[]\n  attachments          WikiPageAttachment[]\n  comments             WikiPageComment[]\n  favorites            WikiPageFavorite[]\n  acknowledgements     WikiPageAcknowledgement[]\n  checklist_guides     WikiChecklist[]           @relation(\"WikiChecklistGuidePage\")\n  checklist_items      WikiChecklistItem[]       @relation(\"WikiChecklistItemPage\")\n  ai_index_entries     WikiAiIndexEntry[]\n  ai_suggestions       WikiAiSuggestion[]        @relation(\"WikiAiSuggestionPage\")\n  ai_related_in        WikiAiSuggestion[]        @relation(\"WikiAiSuggestionRelatedPage\")\n  // 05 §34 — projects that use this page as their runbook (Project.runbook_page_id).\n  runbook_for_projects Project[]\n\n  @@unique([space_id, slug])\n  @@index([organization_id, status])\n  @@index([organization_id, customer_visible])\n  @@index([search_vector], type: Gin)\n  @@index([space_id, parent_page_id, sort_order])\n  @@index([parent_page_id])\n  @@index([owner_membership_id])\n  @@index([next_review_at])\n  @@index([path])\n  @@map(\"wiki_pages\")\n}\n\n/// 15 §2 — members responsible for reviewing a page on its cadence.\nmodel WikiPageReviewer {\n  page_id       String\n  membership_id String\n  created_at    DateTime @default(now())\n\n  page       WikiPage   @relation(fields: [page_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([page_id, membership_id])\n  @@index([membership_id])\n  @@map(\"wiki_page_reviewers\")\n}\n\n/// 15 §2 — immutable snapshot per save/publish; `WikiPage.current_version_number` points at the latest.\nmodel WikiPageVersion {\n  id                       String   @id @default(uuid())\n  page_id                  String\n  version_number           Int\n  title                    String\n  content                  Json?\n  content_markdown         String?\n  /// Optional author note describing the change.\n  change_summary           String?\n  /// True when this snapshot was the published copy at the time.\n  is_published_snapshot    Boolean  @default(false)\n  /// Version this one was restored from, when created by a rollback.\n  restored_from_version_id String?\n  /// 15 §6 — produced by accepting an AI suggestion.\n  ai_suggestion_id         String?\n  created_by_membership_id String?\n  created_at               DateTime @default(now())\n\n  page WikiPage @relation(fields: [page_id], references: [id], onDelete: Cascade)\n\n  @@unique([page_id, version_number])\n  @@index([page_id, created_at])\n  @@map(\"wiki_page_versions\")\n}\n\n/// 15 §2, §8 — explicit grant on a page to a member, team, branch, role or department (10).\n/// Enumerates the principals for BRANCH / TEAM / ROLE / MEMBERS visibility and allows per-page overrides.\n/// principal_id references memberships / teams / branches / roles or an Department = Team of kind DEPARTMENT (01 §43).\nmodel WikiPagePermission {\n  id                 String              @id @default(uuid())\n  page_id            String\n  principal_type     WikiPrincipalType\n  principal_id       String\n  level              WikiPermissionLevel @default(VIEW)\n  /// Grant also applies to descendant pages.\n  inherit            Boolean             @default(true)\n  granted_by_user_id String?\n  created_at         DateTime            @default(now())\n\n  page WikiPage @relation(fields: [page_id], references: [id], onDelete: Cascade)\n\n  @@unique([page_id, principal_type, principal_id])\n  @@index([principal_type, principal_id])\n  @@map(\"wiki_page_permissions\")\n}\n\n/// 15 §2, §4, §6 — link from a page to a platform record (project, customer, task, document, ticket …).\n/// Also fed to the AI index as context (15 §6).\nmodel WikiPageLink {\n  id                 String           @id @default(uuid())\n  page_id            String\n  entity_type        RecordEntityType\n  entity_id          String\n  /// Optional display label; block_id anchors the link to a content block.\n  label              String?\n  block_id           String?\n  created_by_user_id String?\n  created_at         DateTime         @default(now())\n\n  page WikiPage @relation(fields: [page_id], references: [id], onDelete: Cascade)\n\n  @@unique([page_id, entity_type, entity_id])\n  @@index([entity_type, entity_id])\n  @@map(\"wiki_page_links\")\n}\n\n/// 15 §2 — files/images embedded in a page are Documents (17); id only.\nmodel WikiPageAttachment {\n  id               String   @id @default(uuid())\n  page_id          String\n  document_id      String\n  /// Content block that embeds the document.\n  block_id         String?\n  added_by_user_id String?\n  created_at       DateTime @default(now())\n\n  page WikiPage @relation(fields: [page_id], references: [id], onDelete: Cascade)\n\n  @@unique([page_id, document_id])\n  @@index([document_id])\n  @@map(\"wiki_page_attachments\")\n}\n\n/// 15 §2 — threaded page comments with mentions (14 notifies), optionally anchored to a block, resolvable.\nmodel WikiPageComment {\n  id                        String    @id @default(uuid())\n  page_id                   String\n  parent_comment_id         String?\n  author_membership_id      String?\n  /// Content block the comment is anchored to; null = page-level comment.\n  block_id                  String?\n  body                      String\n  /// Membership ids mentioned.\n  mentions                  String[]  @default([])\n  /// { emoji: [membership_id, …] }\n  reactions                 Json?\n  resolved_at               DateTime?\n  resolved_by_membership_id String?\n  edited_at                 DateTime?\n  deleted_at                DateTime?\n  created_at                DateTime  @default(now())\n  updated_at                DateTime  @updatedAt\n\n  page    WikiPage          @relation(fields: [page_id], references: [id], onDelete: Cascade)\n  parent  WikiPageComment?  @relation(\"WikiPageCommentThread\", fields: [parent_comment_id], references: [id], onDelete: Cascade)\n  replies WikiPageComment[] @relation(\"WikiPageCommentThread\")\n  author  Membership?       @relation(\"WikiPageCommentAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([page_id, created_at])\n  @@index([parent_comment_id])\n  @@map(\"wiki_page_comments\")\n}\n\n/// 15 §2 — a member's favorite (starred) pages for the sidebar.\nmodel WikiPageFavorite {\n  page_id       String\n  membership_id String\n  sort_order    Int      @default(0)\n  created_at    DateTime @default(now())\n\n  page       WikiPage   @relation(fields: [page_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@id([page_id, membership_id])\n  @@index([membership_id])\n  @@map(\"wiki_page_favorites\")\n}\n\n/// 15 §3 — required-reading acknowledgement tracking: one row per member per page; re-acknowledgement\n/// is required when `acknowledged_version_number` falls behind the published version.\nmodel WikiPageAcknowledgement {\n  id                          String    @id @default(uuid())\n  page_id                     String\n  membership_id               String\n  /// Checklist run item that required the reading, when applicable.\n  checklist_run_item_id       String?\n  required_by                 DateTime? @db.Date\n  acknowledged_at             DateTime?\n  acknowledged_version_number Int?\n  created_at                  DateTime  @default(now())\n  updated_at                  DateTime  @updatedAt\n\n  page       WikiPage   @relation(fields: [page_id], references: [id], onDelete: Cascade)\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([page_id, membership_id])\n  @@index([membership_id, acknowledged_at])\n  @@index([required_by])\n  @@map(\"wiki_page_acknowledgements\")\n}\n\n// --- Onboarding & offboarding checklists ------------------------------------------\n\n/// 15 §3 — onboarding/offboarding checklist definition per department and/or role (01 §130–131).\n/// Items generate Tasks (06) when a run starts.\nmodel WikiChecklist {\n  id                  String            @id @default(uuid())\n  organization_id     String\n  kind                WikiChecklistKind\n  name                String\n  description         String?\n  /// Department = Team of kind DEPARTMENT (01 §43).\n  department_id       String?\n  /// Role (01) this checklist applies to; null = all roles.\n  role_id             String?\n  team_id             String?\n  branch_id           String?\n  /// Guide page shown to the member alongside the checklist.\n  guide_page_id       String?\n  owner_membership_id String?\n  /// Auto-start on member onboarding/offboarding (01 §130–131) when department/role match.\n  auto_assign         Boolean           @default(true)\n  is_active           Boolean           @default(true)\n  archived_at         DateTime?\n  created_by_user_id  String?\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  organization Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  role         Role?               @relation(fields: [role_id], references: [id], onDelete: SetNull)\n  guide_page   WikiPage?           @relation(\"WikiChecklistGuidePage\", fields: [guide_page_id], references: [id], onDelete: SetNull)\n  items        WikiChecklistItem[]\n  runs         WikiChecklistRun[]\n\n  department Team? @relation(\"WikiChecklistDepartment\", fields: [department_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, kind, is_active])\n  @@index([department_id])\n  @@index([role_id])\n  @@map(\"wiki_checklists\")\n}\n\n/// 15 §3 — a step in a checklist: a task to do, a page to read (with acknowledgement) or a form to fill (15 §5).\nmodel WikiChecklistItem {\n  id                       String                    @id @default(uuid())\n  checklist_id             String\n  title                    String\n  description              String?\n  sort_order               Int                       @default(0)\n  /// Required reading page.\n  page_id                  String?\n  requires_acknowledgement Boolean                   @default(false)\n  /// Form to complete (equipment request, compliance acknowledgement …).\n  form_id                  String?\n  /// Days after run start by which the generated Task is due.\n  due_offset_days          Int?\n  assignee_kind            WikiChecklistAssigneeKind @default(SUBJECT)\n  assignee_membership_id   String?\n  /// Task type (06 §3) for the generated Task; id only.\n  task_type_id             String?\n  is_required              Boolean                   @default(true)\n  created_at               DateTime                  @default(now())\n  updated_at               DateTime                  @updatedAt\n\n  checklist WikiChecklist          @relation(fields: [checklist_id], references: [id], onDelete: Cascade)\n  page      WikiPage?              @relation(\"WikiChecklistItemPage\", fields: [page_id], references: [id], onDelete: SetNull)\n  form      CustomForm?            @relation(fields: [form_id], references: [id], onDelete: SetNull)\n  run_items WikiChecklistRunItem[]\n\n  @@index([checklist_id, sort_order])\n  @@map(\"wiki_checklist_items\")\n}\n\n/// 15 §3 — a checklist executed for one member; progress is tracked per employee (10).\nmodel WikiChecklistRun {\n  id                    String                 @id @default(uuid())\n  organization_id       String\n  checklist_id          String\n  subject_membership_id String\n  /// Employees (10) Employee record of the subject; id only.\n  employee_id           String?\n  status                WikiChecklistRunStatus @default(NOT_STARTED)\n  triggered_by          WikiChecklistTrigger   @default(MANUAL)\n  /// Automation run (20) that started it; id only.\n  automation_run_id     String?\n  started_at            DateTime?\n  due_at                DateTime?              @db.Date\n  completed_at          DateTime?\n  cancelled_at          DateTime?\n  progress_percent      Int                    @default(0)\n  created_by_user_id    String?\n  created_at            DateTime               @default(now())\n  updated_at            DateTime               @updatedAt\n\n  organization Organization           @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  checklist    WikiChecklist          @relation(fields: [checklist_id], references: [id], onDelete: Cascade)\n  subject      Membership             @relation(\"WikiChecklistRunSubject\", fields: [subject_membership_id], references: [id], onDelete: Cascade)\n  items        WikiChecklistRunItem[]\n\n  @@index([organization_id, status])\n  @@index([checklist_id])\n  @@index([subject_membership_id, status])\n  @@index([employee_id])\n  @@map(\"wiki_checklist_runs\")\n}\n\n/// 15 §3 — item state inside a run; `task_id` is the generated Task (06).\nmodel WikiChecklistRunItem {\n  id                         String                  @id @default(uuid())\n  run_id                     String\n  checklist_item_id          String\n  task_id                    String?\n  status                     WikiChecklistItemStatus @default(PENDING)\n  /// Submission that satisfied a form item.\n  form_submission_id         String?\n  completed_by_membership_id String?\n  completed_at               DateTime?\n  skipped_reason             String?\n  created_at                 DateTime                @default(now())\n  updated_at                 DateTime                @updatedAt\n\n  run            WikiChecklistRun  @relation(fields: [run_id], references: [id], onDelete: Cascade)\n  checklist_item WikiChecklistItem @relation(fields: [checklist_item_id], references: [id], onDelete: Cascade)\n  task           Task?             @relation(fields: [task_id], references: [id], onDelete: SetNull)\n\n  @@unique([run_id, checklist_item_id])\n  @@index([task_id])\n  @@map(\"wiki_checklist_run_items\")\n}\n\n// --- Custom forms -----------------------------------------------------------------\n\n/// 15 §5 — form builder definition. `fields_schema` is the editable draft; each publish freezes a\n/// CustomFormVersion that submissions reference. Shape:\n/// [{ key, type: CustomFormFieldType, label, description?, required, options?: [{ value, label }],\n///    scale?: { min, max, min_label?, max_label? }, accept?: [mime], max_files?, conditions?: {...} }]\nmodel CustomForm {\n  id                         String           @id @default(uuid())\n  organization_id            String\n  /// Optional home space (15 §2) so the form is browsable with related pages.\n  space_id                   String?\n  name                       String\n  slug                       String\n  description                String?\n  kind                       CustomFormKind   @default(CUSTOM)\n  status                     CustomFormStatus @default(DRAFT)\n  fields_schema              Json\n  /// 15 §5 — anonymous forms never store respondent ids (enforced at storage).\n  is_anonymous               Boolean          @default(false)\n  allow_multiple_submissions Boolean          @default(false)\n  /// Submissions require review by a reviewer before they count as REVIEWED.\n  requires_review            Boolean          @default(false)\n  /// Membership ids allowed to review responses (`docs.forms.review`).\n  reviewer_membership_ids    String[]         @default([])\n  confirmation_message       String?\n  /// Automatic 06 Task / 13 Ticket creation is configured in 20 rules; this is the default hint shown there.\n  opens_at                   DateTime?\n  closes_at                  DateTime?\n  current_version_number     Int              @default(0)\n  owner_membership_id        String?\n  published_at               DateTime?\n  archived_at                DateTime?\n  created_by_user_id         String?\n  created_at                 DateTime         @default(now())\n  updated_at                 DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  space        WikiSpace?   @relation(fields: [space_id], references: [id], onDelete: SetNull)\n  owner        Membership?  @relation(\"CustomFormOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n\n  versions         CustomFormVersion[]\n  assignments      FormAssignment[]\n  submissions      FormSubmission[]\n  checklist_items  WikiChecklistItem[]\n  ai_index_entries WikiAiIndexEntry[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, status])\n  @@index([space_id])\n  @@map(\"custom_forms\")\n}\n\n/// 15 §5 — frozen copy of fields_schema at publish time so old submissions stay interpretable.\nmodel CustomFormVersion {\n  id                 String   @id @default(uuid())\n  form_id            String\n  version_number     Int\n  fields_schema      Json\n  change_summary     String?\n  created_by_user_id String?\n  created_at         DateTime @default(now())\n\n  form        CustomForm       @relation(fields: [form_id], references: [id], onDelete: Cascade)\n  submissions FormSubmission[]\n\n  @@unique([form_id, version_number])\n  @@map(\"custom_form_versions\")\n}\n\n/// 15 §5 — an assignment of a form to a member, team, department (10), branch or the whole organization,\n/// with due date and reminders (14, 20). Recipients are expanded into FormAssignmentRecipient rows.\nmodel FormAssignment {\n  id                        String                   @id @default(uuid())\n  organization_id           String\n  form_id                   String\n  target_type               FormAssignmentTargetType\n  /// memberships / teams / branches id or Department = Team of kind DEPARTMENT (01 §43) id; null for ORGANIZATION.\n  target_id                 String?\n  due_at                    DateTime?\n  /// Reminder schedule: { days_before: [7, 1], after_due_every_days?: 3 } delivered via 14/20.\n  reminders                 Json?\n  message                   String?\n  /// Automation rule (20) that created the assignment; id only.\n  automation_rule_id        String?\n  assigned_by_membership_id String?\n  recipient_count           Int                      @default(0)\n  submitted_count           Int                      @default(0)\n  cancelled_at              DateTime?\n  created_at                DateTime                 @default(now())\n  updated_at                DateTime                 @updatedAt\n\n  organization Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  form         CustomForm                @relation(fields: [form_id], references: [id], onDelete: Cascade)\n  recipients   FormAssignmentRecipient[]\n\n  @@index([organization_id, form_id])\n  @@index([target_type, target_id])\n  @@index([due_at])\n  @@map(\"form_assignments\")\n}\n\n/// 15 §5 — per-member state of an assignment. For anonymous forms `submission_id` stays null and only\n/// `status` moves to SUBMITTED, so completion is trackable without linking the response.\nmodel FormAssignmentRecipient {\n  id               String                        @id @default(uuid())\n  assignment_id    String\n  membership_id    String\n  status           FormAssignmentRecipientStatus @default(PENDING)\n  submission_id    String?                       @unique\n  last_reminded_at DateTime?\n  reminder_count   Int                           @default(0)\n  submitted_at     DateTime?\n  created_at       DateTime                      @default(now())\n  updated_at       DateTime                      @updatedAt\n\n  assignment FormAssignment  @relation(fields: [assignment_id], references: [id], onDelete: Cascade)\n  membership Membership      @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  submission FormSubmission? @relation(fields: [submission_id], references: [id], onDelete: SetNull)\n\n  @@unique([assignment_id, membership_id])\n  @@index([membership_id, status])\n  @@map(\"form_assignment_recipients\")\n}\n\n/// 15 §5 — a response. `answers` = { [field_key]: value } (files hold FormSubmissionFile ids). When the form\n/// is anonymous, respondent_membership_id, submitted_by_user_id and client metadata are never written.\nmodel FormSubmission {\n  id                        String               @id @default(uuid())\n  organization_id           String\n  form_id                   String\n  form_version_id           String\n  respondent_membership_id  String?\n  submitted_by_user_id      String?\n  is_anonymous              Boolean              @default(false)\n  status                    FormSubmissionStatus @default(SUBMITTED)\n  answers                   Json\n  submitted_at              DateTime?\n  // 15 §5 — review\n  reviewed_by_membership_id String?\n  reviewed_at               DateTime?\n  review_notes              String?\n  /// 15 §5 — records created from this response by 20 rules; ids only (Ticket is 13).\n  created_task_id           String?\n  created_ticket_id         String?\n  /// 15 §6 — excluded from AI indexing (always true for anonymous forms).\n  exclude_from_ai_index     Boolean              @default(false)\n  created_at                DateTime             @default(now())\n  updated_at                DateTime             @updatedAt\n\n  organization Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  form         CustomForm        @relation(fields: [form_id], references: [id], onDelete: Cascade)\n  form_version CustomFormVersion @relation(fields: [form_version_id], references: [id], onDelete: Restrict)\n  respondent   Membership?       @relation(\"FormSubmissionRespondent\", fields: [respondent_membership_id], references: [id], onDelete: SetNull)\n  created_task Task?             @relation(fields: [created_task_id], references: [id], onDelete: SetNull)\n\n  files                FormSubmissionFile[]\n  assignment_recipient FormAssignmentRecipient?\n  ai_index_entries     WikiAiIndexEntry[]\n\n  @@index([organization_id, form_id, status])\n  @@index([form_id, submitted_at])\n  @@index([respondent_membership_id])\n  @@map(\"form_submissions\")\n}\n\n/// 15 §5 — uploaded files and signature images for FILE_UPLOAD / SIGNATURE fields; stored as Documents (17).\nmodel FormSubmissionFile {\n  id            String   @id @default(uuid())\n  submission_id String\n  field_key     String\n  document_id   String\n  created_at    DateTime @default(now())\n\n  submission FormSubmission @relation(fields: [submission_id], references: [id], onDelete: Cascade)\n\n  @@index([submission_id, field_key])\n  @@index([document_id])\n  @@map(\"form_submission_files\")\n}\n\n// --- AI knowledge index -----------------------------------------------------------\n\n/// 15 §6, §7 — one retrievable chunk of a page, form or submission for the shared AI layer and semantic\n/// search. `embedding` is a float vector (switch to pgvector `Unsupported(\"vector\")` in a migration when\n/// ANN search is needed). Visibility columns are denormalised so retrieval can be permission-filtered\n/// before ranking (15 §6, §7).\nmodel WikiAiIndexEntry {\n  id               String            @id @default(uuid())\n  organization_id  String\n  source_type      WikiAiSourceType\n  source_id        String\n  page_id          String?\n  form_id          String?\n  submission_id    String?\n  /// Chunk position inside the source document.\n  chunk_index      Int               @default(0)\n  /// Heading path of the chunk (e.g. \"Onboarding > Day 1\").\n  heading_path     String?\n  content_text     String\n  content_hash     String\n  token_count      Int?\n  embedding        Float[]           @default([])\n  embedding_model  String?\n  // Denormalised permission context from the source page/space\n  space_id         String?\n  visibility       WikiVisibility?\n  customer_visible Boolean           @default(false)\n  source_version   Int?\n  status           WikiAiIndexStatus @default(PENDING)\n  indexed_at       DateTime?\n  error            String?\n  created_at       DateTime          @default(now())\n  updated_at       DateTime          @updatedAt\n\n  organization         Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  page                 WikiPage?         @relation(fields: [page_id], references: [id], onDelete: Cascade)\n  form                 CustomForm?       @relation(fields: [form_id], references: [id], onDelete: Cascade)\n  submission           FormSubmission?   @relation(fields: [submission_id], references: [id], onDelete: Cascade)\n  /// 13 §6 — source help-center article when source_type = KNOWLEDGE_ARTICLE; only PUBLISHED articles are indexed.\n  knowledge_article_id String?\n  knowledge_article    KnowledgeArticle? @relation(fields: [knowledge_article_id], references: [id], onDelete: Cascade)\n\n  @@unique([source_type, source_id, chunk_index])\n  @@index([organization_id, status])\n  @@index([organization_id, space_id, visibility])\n  @@index([page_id])\n  @@index([knowledge_article_id])\n  @@map(\"wiki_ai_index_entries\")\n}\n\n/// 15 §6 — AI-proposed page drafts/updates (from conversations, meetings, resolved tickets) and stale or\n/// contradiction flags, held for human review before they touch a page.\nmodel WikiAiSuggestion {\n  id                        String                 @id @default(uuid())\n  organization_id           String\n  kind                      WikiAiSuggestionKind\n  status                    WikiAiSuggestionStatus @default(PENDING)\n  /// Target page for UPDATE_PAGE / STALE_PAGE / CONTRADICTION; null for a brand-new draft.\n  page_id                   String?\n  /// Second page involved in a CONTRADICTION.\n  related_page_id           String?\n  /// Space a DRAFT_PAGE would be created in.\n  space_id                  String?\n  title                     String?\n  /// Proposed block content and markdown (same shapes as WikiPage).\n  content                   Json?\n  content_markdown          String?\n  /// Why the AI proposed this (summary, contradiction details).\n  rationale                 String?\n  /// Source the draft was derived from (ticket 13, conversation 12, calendar event 19 …).\n  source_entity_type        RecordEntityType?\n  source_entity_id          String?\n  /// Index entry ids cited as evidence.\n  citation_entry_ids        String[]               @default([])\n  confidence                Decimal?               @db.Decimal(5, 2)\n  model_name                String?\n  reviewed_by_membership_id String?\n  reviewed_at               DateTime?\n  review_notes              String?\n  /// Version created when the suggestion was accepted.\n  resulting_version_id      String?\n  created_at                DateTime               @default(now())\n  updated_at                DateTime               @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  page         WikiPage?    @relation(\"WikiAiSuggestionPage\", fields: [page_id], references: [id], onDelete: Cascade)\n  related_page WikiPage?    @relation(\"WikiAiSuggestionRelatedPage\", fields: [related_page_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status, kind])\n  @@index([page_id])\n  @@index([source_entity_type, source_entity_id])\n  @@map(\"wiki_ai_suggestions\")\n}\n\n// =====================================================================\n// 17 Documents & File Management — docs/features/17-documents-file-management.md (LOG-407)\n// Owns: the Document record and its file versions, folders and folder templates, upload/intake jobs,\n// previews, polymorphic attachments, shares (members, teams, portal users, external, public links),\n// document-level approvals, retention policies / legal hold / deletion, storage provider connections\n// and the encrypted credential vault (entries, grants, access log, per-organization keys).\n// Does not own: the meaning of a document (contracts 04, deliverables 05, invoices 08 reference it),\n// contract approval & signatures (04), deliverable acceptance (05 §47), notes/comments (02 crm_notes),\n// tags/custom fields (02), notifications (14), OCR extraction (09), employees (10). Referenced by id only.\n// Access events (download, share, reveal, retention changes) are written to audit_events (17 §15).\n// =====================================================================\n\n/// 17 §4 — lifecycle status of a Document record.\nenum DocumentStatus {\n  DRAFT\n  ACTIVE\n  APPROVED\n  ARCHIVED\n  DELETED\n}\n\n/// 17 §3 — scope that drives default visibility (01 §39, §85).\nenum DocumentScope {\n  ORGANIZATION\n  BRANCH\n  TEAM\n  PROJECT\n  CUSTOMER\n  EMPLOYEE\n  RECORD\n}\n\n/// 17 §5, §16 — how a document / version entered the system.\nenum DocumentSource {\n  UPLOAD\n  URL_IMPORT\n  PORTAL_UPLOAD\n  EMAIL_CAPTURE\n  GENERATED\n  OCR_INTAKE\n  EXTERNAL_LINK\n  API\n}\n\n/// 17 §5–6 — availability of a file version (scanning gates availability).\nenum DocumentVersionStatus {\n  PENDING\n  SCANNING\n  AVAILABLE\n  QUARANTINED\n  FAILED\n}\n\n/// 17 §5 — virus / malware scan result.\nenum DocumentScanStatus {\n  PENDING\n  SCANNING\n  CLEAN\n  INFECTED\n  FAILED\n  SKIPPED\n}\n\n/// 17 §16 — storage provider behind the storage abstraction.\nenum DocumentStorageProvider {\n  PLATFORM\n  S3_COMPATIBLE\n  GOOGLE_DRIVE\n  MICROSOFT_365\n}\n\n/// 17 §16 — external storage connection health.\nenum DocumentStorageConnectionStatus {\n  PENDING\n  CONNECTED\n  ERROR\n  DISCONNECTED\n}\n\n/// 17 §5 — upload / intake job states.\nenum DocumentUploadJobStatus {\n  PENDING\n  UPLOADING\n  SCANNING\n  PROCESSING\n  COMPLETED\n  FAILED\n  CANCELLED\n}\n\n/// 17 §8 — preview renditions.\nenum DocumentPreviewKind {\n  THUMBNAIL\n  IMAGE\n  PDF\n  TEXT\n  VIDEO\n  AUDIO\n}\n\n/// 17 §8\nenum DocumentPreviewStatus {\n  PENDING\n  READY\n  FAILED\n  UNSUPPORTED\n}\n\n/// 17 §9 — who a share targets.\nenum DocumentShareSubjectType {\n  MEMBERSHIP\n  TEAM\n  PORTAL_USER\n  EXTERNAL_EMAIL\n  PUBLIC_LINK\n}\n\n/// 17 §9 — permission levels of a share.\nenum DocumentSharePermission {\n  VIEW\n  COMMENT\n  EDIT\n  MANAGE\n}\n\n/// 17 §9\nenum DocumentShareStatus {\n  ACTIVE\n  EXPIRED\n  REVOKED\n}\n\n/// 17 §10 — approval request state.\nenum DocumentApprovalStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  CHANGES_REQUESTED\n  CANCELLED\n}\n\n/// 17 §10 — an approver's decision.\nenum DocumentApprovalDecision {\n  APPROVED\n  REJECTED\n  CHANGES_REQUESTED\n}\n\n/// 17 §10 — internal member or Customer Portal user (07 §7).\nenum DocumentApproverKind {\n  MEMBERSHIP\n  PORTAL_USER\n}\n\n/// 17 §7 — folder templates apply per project type (05 §36) or per customer.\nenum FolderTemplateTarget {\n  PROJECT_TYPE\n  CUSTOMER\n  EMPLOYEE\n  ORGANIZATION\n}\n\n/// 17 §13 — from which moment the retention period counts.\nenum DocumentRetentionAnchor {\n  CREATED\n  LAST_MODIFIED\n  ARCHIVED\n  RECORD_CLOSED\n}\n\n/// 17 §13 — what happens when the retention period ends.\nenum DocumentRetentionAction {\n  ARCHIVE\n  SOFT_DELETE\n  PERMANENT_DELETE\n}\n\n/// 17 §13 — restricted permanent deletion workflow.\nenum DocumentDeletionKind {\n  SOFT\n  PERMANENT\n  RETENTION\n}\n\n/// 17 §13\nenum DocumentDeletionStatus {\n  REQUESTED\n  APPROVED\n  EXECUTED\n  REJECTED\n  CANCELLED\n}\n\n/// 17 §12 — vault entry types.\nenum VaultEntryType {\n  PASSWORD\n  API_KEY\n  SSH_KEY\n  NOTE\n  FILE\n}\n\n/// 17 §12 — vault scope.\nenum VaultScope {\n  ORGANIZATION\n  CUSTOMER\n  PROJECT\n}\n\n/// 17 §12 — who a vault grant targets.\nenum VaultGrantSubjectType {\n  MEMBERSHIP\n  TEAM\n  PORTAL_USER\n}\n\n/// 17 §12, §15 — logged vault actions (reveal / copy are explicit).\nenum VaultAccessAction {\n  VIEW\n  REVEAL\n  COPY\n  CREATE\n  UPDATE\n  ROTATE\n  DELETE\n  GRANT\n  REVOKE\n}\n\n/// 17 §12 — per-organization encryption key lifecycle.\nenum VaultKeyStatus {\n  ACTIVE\n  ROTATING\n  RETIRED\n}\n\n// --- Configuration ----------------------------------------------------------------\n\n/// 17 §5, §8, §9, §13 — organization-level document settings: file type / size limits, scanning,\n/// public links, watermarking, soft-delete recovery window, folder depth, portal upload and vault sharing.\nmodel DocumentSettings {\n  organization_id              String                  @id\n  /// 17 §5 — max size of a single upload in bytes.\n  max_file_size_bytes          BigInt                  @default(104857600)\n  /// 17 §5 — allowed MIME types / extensions; empty = all except blocked.\n  allowed_mime_types           String[]                @default([])\n  blocked_extensions           String[]                @default([])\n  /// 17 §5 — a version becomes AVAILABLE only after a CLEAN scan.\n  virus_scan_required          Boolean                 @default(true)\n  /// 17 §7 — configurable folder hierarchy depth.\n  folder_max_depth             Int                     @default(10)\n  /// 17 §9 — public links only when enabled by organization policy, always expiring.\n  public_links_enabled         Boolean                 @default(false)\n  public_link_max_days         Int                     @default(30)\n  /// 17 §9 — default expiry for non-public shares (null = no expiry).\n  default_share_expiry_days    Int?\n  /// 17 §8 — watermark customer-facing documents by default.\n  watermark_customer_documents Boolean                 @default(false)\n  /// 17 §8 — lifetime of signed download / preview URLs.\n  signed_url_ttl_seconds       Int                     @default(900)\n  /// 17 §13 — soft delete recovery window.\n  soft_delete_recovery_days    Int                     @default(30)\n  /// 17 §5 — Customer Portal uploads into permitted folders, projects, tickets, conversations (07 §9).\n  portal_upload_enabled        Boolean                 @default(true)\n  /// 17 §12 — vault sharing to Customer Portal users (Phase 2).\n  vault_portal_sharing_enabled Boolean                 @default(false)\n  /// 17 §12 — reveal must be re-authenticated after this many minutes (null = never).\n  vault_reveal_reauth_minutes  Int?\n  /// 17 §11 — full-text extraction enabled (Phase 2).\n  full_text_extraction_enabled Boolean                 @default(false)\n  /// 17 §16 — default storage provider for new versions when no connection is marked default.\n  default_storage_provider     DocumentStorageProvider @default(PLATFORM)\n  created_at                   DateTime                @default(now())\n  updated_at                   DateTime                @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"document_settings\")\n}\n\n/// 17 §4 — configurable document categories (contract, proposal, deliverable, design, specification,\n/// invoice, receipt, HR document, policy, other). System categories are seeded per organization.\nmodel DocumentCategory {\n  id                          String    @id @default(uuid())\n  organization_id             String\n  name                        String\n  slug                        String\n  description                 String?\n  icon                        String?\n  color                       String?\n  /// Seeded by the platform; cannot be deleted, only archived.\n  is_system                   Boolean   @default(false)\n  /// 17 §8, §15 — downloads of this category are audited; documents default to is_sensitive.\n  is_sensitive                Boolean   @default(false)\n  /// 17 §8 — documents of this category default to customer_visible when shared to the portal.\n  customer_visible_default    Boolean   @default(false)\n  /// 17 §13 — default retention policy applied to new documents of this category.\n  default_retention_policy_id String?\n  sort_order                  Int       @default(0)\n  archived_at                 DateTime?\n  created_at                  DateTime  @default(now())\n  updated_at                  DateTime  @updatedAt\n\n  organization             Organization              @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_retention_policy DocumentRetentionPolicy?  @relation(\"DocumentCategoryDefaultRetention\", fields: [default_retention_policy_id], references: [id], onDelete: SetNull)\n  documents                Document[]\n  retention_policies       DocumentRetentionPolicy[] @relation(\"DocumentRetentionPolicyCategory\")\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, sort_order])\n  @@map(\"document_categories\")\n}\n\n/// 17 §16 — external storage provider connection (Google Drive, Microsoft 365, S3-compatible) behind the\n/// storage abstraction. The Document record stays in this module; only bytes live in the provider.\nmodel DocumentStorageConnection {\n  id                   String                          @id @default(uuid())\n  organization_id      String\n  provider             DocumentStorageProvider\n  name                 String\n  status               DocumentStorageConnectionStatus @default(PENDING)\n  /// Bucket / drive / site identifier and root prefix.\n  root_identifier      String?\n  root_path            String?\n  region               String?\n  endpoint_url         String?\n  /// Reference to encrypted credentials (vault key id + ciphertext); never plain text.\n  credentials_ref      String?\n  /// Non-secret provider options.\n  config               Json?\n  is_default           Boolean                         @default(false)\n  last_checked_at      DateTime?\n  last_error           String?\n  connected_by_user_id String?\n  disconnected_at      DateTime?\n  created_at           DateTime                        @default(now())\n  updated_at           DateTime                        @updatedAt\n\n  organization Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  versions     DocumentVersion[]\n\n  @@index([organization_id, provider])\n  @@index([organization_id, is_default])\n  @@map(\"document_storage_connections\")\n}\n\n/// 17 §13 — retention policies per category and scope (04 §84 contract retention is enforced here).\nmodel DocumentRetentionPolicy {\n  id                 String                  @id @default(uuid())\n  organization_id    String\n  name               String\n  description        String?\n  /// Null = any category.\n  category_id        String?\n  /// Null = any scope.\n  scope              DocumentScope?\n  /// Retention period in days; null = retain indefinitely (policy then only applies legal hold rules).\n  retain_days        Int?\n  anchor             DocumentRetentionAnchor @default(CREATED)\n  action             DocumentRetentionAction @default(ARCHIVE)\n  /// Module that mandates this policy (e.g. CONTRACTS for 04 §84); null for organization policies.\n  enforced_by_module ModuleKey?\n  is_active          Boolean                 @default(true)\n  is_default         Boolean                 @default(false)\n  created_by_user_id String?\n  archived_at        DateTime?\n  created_at         DateTime                @default(now())\n  updated_at         DateTime                @updatedAt\n\n  organization           Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  category               DocumentCategory?  @relation(\"DocumentRetentionPolicyCategory\", fields: [category_id], references: [id], onDelete: SetNull)\n  default_for_categories DocumentCategory[] @relation(\"DocumentCategoryDefaultRetention\")\n  documents              Document[]\n\n  @@index([organization_id, is_active])\n  @@index([category_id])\n  @@map(\"document_retention_policies\")\n}\n\n// --- Folders ------------------------------------------------------------------------\n\n/// 17 §7 — default folder structures per project type (05 §36), per customer, per employee or organization.\nmodel FolderTemplate {\n  id              String               @id @default(uuid())\n  organization_id String\n  name            String\n  description     String?\n  target          FolderTemplateTarget @default(PROJECT_TYPE)\n  /// Project type this template applies to (05 §36); null for customer / employee / organization templates.\n  project_type_id String?\n  /// Folder tree: [{ name, customer_visible, category_slug, children: [...] }].\n  structure       Json\n  is_default      Boolean              @default(false)\n  archived_at     DateTime?\n  created_at      DateTime             @default(now())\n  updated_at      DateTime             @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  project_type ProjectType? @relation(fields: [project_type_id], references: [id], onDelete: SetNull)\n  folders      Folder[]\n\n  @@index([organization_id, target])\n  @@index([project_type_id])\n  @@map(\"folder_templates\")\n}\n\n/// 17 §2, §3, §7 — hierarchical container scoped to an organization, branch, team, project, customer\n/// or employee. Moving / renaming / archiving a folder never changes Document ids.\nmodel Folder {\n  id                    String        @id @default(uuid())\n  organization_id       String\n  parent_folder_id      String?\n  name                  String\n  description           String?\n  /// Materialized path of ancestor ids for hierarchy queries (\"/a/b/\").\n  path                  String        @default(\"\")\n  depth                 Int           @default(0)\n  scope                 DocumentScope @default(ORGANIZATION)\n  branch_id             String?\n  team_id               String?\n  project_id            String?\n  /// Customer (CRM Company, 02) for CUSTOMER scope.\n  company_id            String?\n  /// 10 Employee for EMPLOYEE scope (HR documents); id only.\n  employee_id           String?\n  /// 17 §7 — created from a folder template.\n  template_id           String?\n  /// Default category for documents created in this folder.\n  default_category_id   String?\n  /// Visible in the Customer Portal (07 §9); customers may upload here when portal_upload_allowed.\n  customer_visible      Boolean       @default(false)\n  portal_upload_allowed Boolean       @default(false)\n  /// System folders (e.g. \"Generated PDFs\", \"Signed contracts\") cannot be deleted.\n  is_system             Boolean       @default(false)\n  color                 String?\n  icon                  String?\n  sort_order            Int           @default(0)\n  created_by_user_id    String?\n  archived_at           DateTime?\n  deleted_at            DateTime?\n  created_at            DateTime      @default(now())\n  updated_at            DateTime      @updatedAt\n\n  organization Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent       Folder?         @relation(\"FolderHierarchy\", fields: [parent_folder_id], references: [id], onDelete: Restrict)\n  children     Folder[]        @relation(\"FolderHierarchy\")\n  branch       Branch?         @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  team         Team?           @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  project      Project?        @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  company      CrmCompany?     @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  template     FolderTemplate? @relation(fields: [template_id], references: [id], onDelete: SetNull)\n\n  documents   Document[]\n  shares      DocumentShare[]\n  favorites   DocumentFavorite[]\n  upload_jobs DocumentUploadJob[]\n\n  @@unique([organization_id, parent_folder_id, name])\n  @@index([organization_id, scope])\n  @@index([parent_folder_id])\n  @@index([project_id])\n  @@index([company_id])\n  @@index([branch_id])\n  @@index([team_id])\n  @@index([employee_id])\n  @@map(\"folders\")\n}\n\n// --- Documents ----------------------------------------------------------------------\n\n/// 17 §2, §3, §4 — the Document record: a logical document with one or more immutable file versions,\n/// a title, category, scope, status, owner, retention policy and access rules. Modules own the\n/// relationship to a document; this module owns the document. Legacy columns (user_uuid, filename,\n/// mimetype, size, url, path, type) are kept for pre-module-17 rows (logo / avatar uploads) and now\n/// mirror the current version.\nmodel Document {\n  id              String       @id @default(uuid())\n  /// Legacy uploader (pre-module 17); superseded by created_by_user_id. Null for new rows.\n  user_uuid       String?\n  /// Null only for legacy rows; services backfill from organization-less uploads (notes).\n  organization_id String?\n  /// Legacy file name = current version file name (denormalized).\n  filename        String\n  /// Legacy / current version MIME type; null for link-only documents (17 §2).\n  mimetype        String?\n  /// Legacy / current version size in bytes; null for link-only documents.\n  size            BigInt?\n  /// Legacy storage URL. 17 §8: never a public URL for new rows — signed URLs are generated per request.\n  url             String?\n  /// Legacy / current version storage key.\n  path            String?\n  /// Legacy coarse file kind; kept for existing branding uploads (01 §15).\n  type            DocumentType @default(OTHER)\n\n  // 17 §4 — document record.\n  /// Null only for legacy rows; services fall back to filename.\n  title         String?\n  description   String?\n  category_id   String?\n  status        DocumentStatus @default(ACTIVE)\n  source        DocumentSource @default(UPLOAD)\n  /// Module that generated / captured the document (03, 04, 08 PDFs; 13 email capture; 09 OCR intake).\n  source_module ModuleKey?\n  /// 17 §2 — a Document can exist without a file: external link.\n  external_url  String?\n\n  // 17 §3 — scope and owning record references.\n  scope       DocumentScope     @default(ORGANIZATION)\n  folder_id   String?\n  branch_id   String?\n  team_id     String?\n  project_id  String?\n  /// Customer (CRM Company, 02) for CUSTOMER scope or customer-facing documents.\n  company_id  String?\n  /// 10 Employee for EMPLOYEE scope (HR documents); id only.\n  employee_id String?\n  /// 17 §2 Attachment — owning record for RECORD scope (task, ticket, message, financial record, …).\n  entity_type RecordEntityType?\n  entity_id   String?\n\n  // 17 §6 — versions.\n  current_version_id String? @unique\n  version_count      Int     @default(0)\n  /// Checksum of the current version (denormalized).\n  checksum           String?\n\n  // Ownership.\n  owner_membership_id String?\n  /// Uploader (member or Customer Portal user).\n  created_by_user_id  String?\n  /// 17 §5 — uploaded through the Customer Portal (07 §9).\n  uploaded_via_portal Boolean @default(false)\n\n  // 17 §8 — access.\n  /// Visible in the Customer Portal documents section (07 §9) in addition to explicit shares.\n  customer_visible  Boolean @default(false)\n  /// 17 §8, §15 — downloads are audited (defaults from category.is_sensitive).\n  is_sensitive      Boolean @default(false)\n  /// 17 §8 — watermark customer-facing downloads / previews.\n  watermark_enabled Boolean @default(false)\n\n  // 17 §10 — denormalized state of the latest approval request.\n  approval_status     DocumentApprovalStatus?\n  approved_version_id String?\n  approved_at         DateTime?\n\n  // 17 §11 — search.\n  /// Extracted full text of the current version (Phase 2); null when not extractable.\n  search_text String?\n  /// Denormalized keywords / tag names for quick filtering.\n  keywords    String[] @default([])\n\n  // 17 §13 — retention & deletion.\n  retention_policy_id       String?\n  /// Computed from the policy; null = retain indefinitely.\n  retention_expires_at      DateTime?\n  legal_hold                Boolean                  @default(false)\n  legal_hold_reason         String?\n  legal_hold_set_by_user_id String?\n  legal_hold_set_at         DateTime?\n  archived_at               DateTime?\n  /// Soft delete; recoverable until purge_scheduled_at.\n  deleted_at                DateTime?\n  deleted_by_user_id        String?\n  purge_scheduled_at        DateTime?\n  /// 17 §11 — Postgres full-text search vector over title + search_text; maintained by a database trigger (see migration). Not set by the API.\n  search_vector             Unsupported(\"tsvector\")?\n\n  last_accessed_at DateTime?\n  created_at       DateTime  @default(now())\n  updated_at       DateTime  @updatedAt\n\n  organization     Organization?            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  category         DocumentCategory?        @relation(fields: [category_id], references: [id], onDelete: SetNull)\n  folder           Folder?                  @relation(fields: [folder_id], references: [id], onDelete: SetNull)\n  branch           Branch?                  @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  team             Team?                    @relation(fields: [team_id], references: [id], onDelete: SetNull)\n  project          Project?                 @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  company          CrmCompany?              @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  owner            Membership?              @relation(\"DocumentOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  current_version  DocumentVersion?         @relation(\"DocumentCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  retention_policy DocumentRetentionPolicy? @relation(fields: [retention_policy_id], references: [id], onDelete: SetNull)\n\n  versions                       DocumentVersion[]         @relation(\"DocumentVersions\")\n  upload_jobs                    DocumentUploadJob[]\n  attachments                    DocumentAttachment[]\n  shares                         DocumentShare[]\n  approvals                      DocumentApproval[]\n  favorites                      DocumentFavorite[]\n  recent_accesses                DocumentRecentAccess[]\n  deletion_requests              DocumentDeletionRequest[]\n  crm_import_jobs                CrmImportJob[]\n  proposal_version_pdfs          ProposalVersion[]         @relation(\"ProposalVersionPdf\")\n  contract_version_drafts        ContractVersion[]         @relation(\"ContractVersionDocument\")\n  contract_version_signed        ContractVersion[]         @relation(\"ContractVersionSignedDocument\")\n  signature_request_signed       SignatureRequest[]        @relation(\"SignatureRequestSignedDocument\")\n  signature_request_certificates SignatureRequest[]        @relation(\"SignatureRequestAuditCertificate\")\n  contract_terminations          ContractTermination[]\n  project_decisions              ProjectDecision[]\n  task_attachments               TaskAttachment[]\n  release_notes                  Release[]                 @relation(\"ReleaseNotesDocument\")\n  invoice_pdfs                   Invoice[]                 @relation(\"InvoicePdf\")\n  payment_receipts               Payment[]                 @relation(\"PaymentReceipt\")\n  credit_note_pdfs               CreditNote[]              @relation(\"CreditNotePdf\")\n  calendar_event_attachments     CalendarEventAttachment[] @relation(\"CalendarEventAttachmentDocument\")\n\n  @@index([user_uuid])\n  @@index([organization_id, status])\n  @@index([organization_id, scope])\n  @@index([search_vector], type: Gin)\n  @@index([organization_id, category_id])\n  @@index([organization_id, created_at])\n  @@index([folder_id])\n  @@index([project_id])\n  @@index([company_id])\n  @@index([branch_id])\n  @@index([team_id])\n  @@index([employee_id])\n  @@index([entity_type, entity_id])\n  @@index([owner_membership_id])\n  @@index([retention_expires_at])\n  @@index([deleted_at])\n  @@map(\"documents\")\n}\n\n/// 17 §2 File, §6 Versioning — an immutable file snapshot inside a Document, with author, timestamp,\n/// change note, scan result and lock. Re-uploads create a new version; restore creates a new version\n/// from an older one.\nmodel DocumentVersion {\n  id                       String                  @id @default(uuid())\n  document_id              String\n  /// 1-based, unique per document.\n  version_number           Int\n  status                   DocumentVersionStatus   @default(PENDING)\n  filename                 String\n  mimetype                 String\n  size_bytes               BigInt\n  /// SHA-256 of the stored bytes (integrity, dedupe, 04 §17 hashes).\n  checksum_sha256          String\n  /// 17 §16 — where the bytes live.\n  storage_provider         DocumentStorageProvider @default(PLATFORM)\n  storage_connection_id    String?\n  /// Object key / path inside the storage provider; never exposed directly (17 §8).\n  storage_key              String\n  storage_bucket           String?\n  /// Provider-side file id for external drives.\n  external_file_id         String?\n  // 17 §5 — virus and malware scanning.\n  scan_status              DocumentScanStatus      @default(PENDING)\n  scan_result              Json?\n  scanned_at               DateTime?\n  // 17 §6 — authorship and change note.\n  change_note              String?\n  author_membership_id     String?\n  /// Portal user or member who uploaded this version.\n  author_user_id           String?\n  source                   DocumentSource          @default(UPLOAD)\n  /// 17 §6 — restored from a previous version.\n  restored_from_version_id String?\n  // 17 §6 — module lock (e.g. 04 locks the signed contract version).\n  is_locked                Boolean                 @default(false)\n  locked_by_module         ModuleKey?\n  locked_reason            String?\n  locked_at                DateTime?\n  // 17 §8, §11 — derived data.\n  /// Extracted text for full-text search (17 §11, Phase 2).\n  extracted_text           String?\n  page_count               Int?\n  width                    Int?\n  height                   Int?\n  duration_seconds         Int?\n  /// Other technical metadata (EXIF, encoding, office properties).\n  metadata                 Json?\n  created_at               DateTime                @default(now())\n\n  document           Document                   @relation(\"DocumentVersions\", fields: [document_id], references: [id], onDelete: Cascade)\n  current_of         Document?                  @relation(\"DocumentCurrentVersion\")\n  storage_connection DocumentStorageConnection? @relation(fields: [storage_connection_id], references: [id], onDelete: SetNull)\n  author             Membership?                @relation(\"DocumentVersionAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n  restored_from      DocumentVersion?           @relation(\"DocumentVersionRestoredFrom\", fields: [restored_from_version_id], references: [id], onDelete: SetNull)\n  restores           DocumentVersion[]          @relation(\"DocumentVersionRestoredFrom\")\n\n  previews    DocumentPreview[]\n  approvals   DocumentApproval[]\n  upload_jobs DocumentUploadJob[]\n\n  @@unique([document_id, version_number])\n  @@index([document_id, created_at])\n  @@index([checksum_sha256])\n  @@index([scan_status])\n  @@index([storage_connection_id])\n  @@map(\"document_versions\")\n}\n\n/// 17 §5 — upload / intake job: drag-and-drop and multi-file uploads, upload from URL, portal uploads,\n/// email captures (13), OCR intake (09) and generated PDFs (03/04/08). Tracks the transfer, scan and\n/// the resulting document / version.\nmodel DocumentUploadJob {\n  id                         String                  @id @default(uuid())\n  organization_id            String\n  /// Groups the files of one multi-file upload.\n  batch_id                   String?\n  status                     DocumentUploadJobStatus @default(PENDING)\n  source                     DocumentSource          @default(UPLOAD)\n  source_module              ModuleKey?\n  /// 17 §5 — upload from URL.\n  source_url                 String?\n  filename                   String\n  mimetype                   String?\n  expected_size_bytes        BigInt?\n  uploaded_bytes             BigInt                  @default(0)\n  /// Client-provided checksum to verify after transfer.\n  expected_checksum          String?\n  /// Provider upload session / multipart id and pre-signed target key.\n  upload_session_id          String?\n  storage_key                String?\n  // Target placement when the job completes.\n  /// Existing document to add a version to; null = create a new document.\n  document_id                String?\n  folder_id                  String?\n  scope                      DocumentScope           @default(ORGANIZATION)\n  project_id                 String?\n  company_id                 String?\n  entity_type                RecordEntityType?\n  entity_id                  String?\n  category_id                String?\n  title                      String?\n  change_note                String?\n  /// Resulting version once processing completed.\n  version_id                 String?\n  scan_status                DocumentScanStatus      @default(PENDING)\n  error_code                 String?\n  error_message              String?\n  initiated_by_membership_id String?\n  /// Member or Customer Portal user who started the upload.\n  initiated_by_user_id       String?\n  via_portal                 Boolean                 @default(false)\n  /// Upload URL / session expiry.\n  expires_at                 DateTime?\n  started_at                 DateTime?\n  completed_at               DateTime?\n  created_at                 DateTime                @default(now())\n  updated_at                 DateTime                @updatedAt\n\n  organization Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  document     Document?        @relation(fields: [document_id], references: [id], onDelete: SetNull)\n  folder       Folder?          @relation(fields: [folder_id], references: [id], onDelete: SetNull)\n  version      DocumentVersion? @relation(fields: [version_id], references: [id], onDelete: SetNull)\n  initiated_by Membership?      @relation(\"DocumentUploadJobInitiator\", fields: [initiated_by_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@index([organization_id, batch_id])\n  @@index([document_id])\n  @@index([initiated_by_user_id])\n  @@index([expires_at])\n  @@map(\"document_upload_jobs\")\n}\n\n/// 17 §8 — generated preview rendition of a version (thumbnail, image pages, PDF rendition, text\n/// extract, transcoded media). Served through signed URLs only.\nmodel DocumentPreview {\n  id           String                @id @default(uuid())\n  version_id   String\n  kind         DocumentPreviewKind\n  status       DocumentPreviewStatus @default(PENDING)\n  /// Page / frame index for multi-page renditions; 0 for single renditions.\n  page_number  Int                   @default(0)\n  mimetype     String?\n  storage_key  String?\n  size_bytes   BigInt?\n  width        Int?\n  height       Int?\n  /// Watermarked variant (17 §8).\n  watermarked  Boolean               @default(false)\n  error        String?\n  generated_at DateTime?\n  created_at   DateTime              @default(now())\n\n  version DocumentVersion @relation(fields: [version_id], references: [id], onDelete: Cascade)\n\n  @@unique([version_id, kind, page_number, watermarked])\n  @@index([version_id, status])\n  @@map(\"document_previews\")\n}\n\n/// 17 §2 Attachment, §11 — polymorphic link between a Document and a business record (task, ticket,\n/// message, financial record, CRM record, employee …). Modules with their own join table\n/// (06 task_attachments, 09 ledger_attachments, 13 ticket_attachments) keep it; other modules and\n/// generic \"related record\" lookups use this table.\nmodel DocumentAttachment {\n  id                String           @id @default(uuid())\n  organization_id   String\n  document_id       String\n  entity_type       RecordEntityType\n  entity_id         String\n  /// Role of the document on the record (attachment, generated_pdf, signed, receipt, source_file …).\n  role              String           @default(\"attachment\")\n  /// Module that created the link.\n  source_module     ModuleKey?\n  sort_order        Int              @default(0)\n  linked_by_user_id String?\n  created_at        DateTime         @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  document     Document     @relation(fields: [document_id], references: [id], onDelete: Cascade)\n\n  @@unique([document_id, entity_type, entity_id, role])\n  @@index([entity_type, entity_id])\n  @@index([organization_id, entity_type])\n  @@map(\"document_attachments\")\n}\n\n/// 17 §7 — favorites per member (document or folder).\nmodel DocumentFavorite {\n  id            String   @id @default(uuid())\n  membership_id String\n  document_id   String?\n  folder_id     String?\n  created_at    DateTime @default(now())\n\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  document   Document?  @relation(fields: [document_id], references: [id], onDelete: Cascade)\n  folder     Folder?    @relation(fields: [folder_id], references: [id], onDelete: Cascade)\n\n  @@unique([membership_id, document_id])\n  @@unique([membership_id, folder_id])\n  @@index([document_id])\n  @@index([folder_id])\n  @@map(\"document_favorites\")\n}\n\n/// 17 §7 — \"recent\" list per member; one row per member + document, bumped on each open.\n/// Download / preview audit for sensitive categories goes to audit_events (17 §15).\nmodel DocumentRecentAccess {\n  membership_id    String\n  document_id      String\n  last_accessed_at DateTime @default(now())\n  access_count     Int      @default(1)\n\n  membership Membership @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  document   Document   @relation(fields: [document_id], references: [id], onDelete: Cascade)\n\n  @@id([membership_id, document_id])\n  @@index([membership_id, last_accessed_at])\n  @@map(\"document_recent_accesses\")\n}\n\n// --- Sharing ------------------------------------------------------------------------\n\n/// 17 §2, §9 — explicit grant of access to a Document or Folder for a Member, Team, Customer Portal\n/// user, external collaborator (email) or public link. Public links require organization policy,\n/// always expire and are audited. Share activity is written to audit_events.\nmodel DocumentShare {\n  id                      String                   @id @default(uuid())\n  organization_id         String\n  /// Exactly one of document_id / folder_id is set.\n  document_id             String?\n  folder_id               String?\n  subject_type            DocumentShareSubjectType\n  membership_id           String?\n  team_id                 String?\n  /// Customer Portal user (User with a CustomerPortalMembership).\n  portal_user_id          String?\n  /// External collaborator.\n  external_email          String?\n  external_name           String?\n  /// 17 §9 — public / external link token (random, unique; the share URL carries it).\n  link_token              String?                  @unique\n  link_password_hash      String?\n  permission              DocumentSharePermission  @default(VIEW)\n  status                  DocumentShareStatus      @default(ACTIVE)\n  allow_download          Boolean                  @default(true)\n  /// 17 §8 — watermark downloads served through this share.\n  watermark               Boolean                  @default(false)\n  /// 17 §6 — pin the share to a specific version; null = always current.\n  pinned_version_id       String?\n  /// Optional cap for link shares.\n  max_access_count        Int?\n  access_count            Int                      @default(0)\n  download_count          Int                      @default(0)\n  last_accessed_at        DateTime?\n  message                 String?\n  /// 17 §9 — expiring shares (required for public links).\n  expires_at              DateTime?\n  shared_by_membership_id String?\n  shared_by_user_id       String?\n  revoked_at              DateTime?\n  revoked_by_user_id      String?\n  /// 14 — notification sent to the recipient.\n  notified_at             DateTime?\n  created_at              DateTime                 @default(now())\n  updated_at              DateTime                 @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  document     Document?    @relation(fields: [document_id], references: [id], onDelete: Cascade)\n  folder       Folder?      @relation(fields: [folder_id], references: [id], onDelete: Cascade)\n  membership   Membership?  @relation(\"DocumentShareMembership\", fields: [membership_id], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  portal_user  User?        @relation(\"DocumentSharePortalUser\", fields: [portal_user_id], references: [id], onDelete: Cascade)\n  shared_by    Membership?  @relation(\"DocumentShareSharer\", fields: [shared_by_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@index([document_id, status])\n  @@index([folder_id, status])\n  @@index([membership_id])\n  @@index([team_id])\n  @@index([portal_user_id])\n  @@index([external_email])\n  @@index([expires_at])\n  @@map(\"document_shares\")\n}\n\n// --- Approvals ----------------------------------------------------------------------\n\n/// 17 §10 — document-level approval request bound to an exact version (deliverables, specifications,\n/// HR documents). Shown as a pending approval in the Customer Portal (07 §4, §7) when a portal user is\n/// an approver. Contract approval / signature stay in 04; deliverable acceptance in 05 §47.\nmodel DocumentApproval {\n  id                         String                 @id @default(uuid())\n  organization_id            String\n  document_id                String\n  version_id                 String\n  title                      String?\n  message                    String?\n  status                     DocumentApprovalStatus @default(PENDING)\n  /// All approvers must approve (true) or any one approval completes the request (false).\n  require_all                Boolean                @default(true)\n  due_at                     DateTime?\n  requested_by_membership_id String?\n  requested_by_user_id       String?\n  /// Outcome summary when completed (last decision comment).\n  outcome_comment            String?\n  completed_at               DateTime?\n  cancelled_at               DateTime?\n  cancelled_by_user_id       String?\n  /// Reminder sent through 14.\n  last_reminded_at           DateTime?\n  created_at                 DateTime               @default(now())\n  updated_at                 DateTime               @updatedAt\n\n  organization Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  document     Document           @relation(fields: [document_id], references: [id], onDelete: Cascade)\n  version      DocumentVersion    @relation(fields: [version_id], references: [id], onDelete: Cascade)\n  requested_by Membership?        @relation(\"DocumentApprovalRequester\", fields: [requested_by_membership_id], references: [id], onDelete: SetNull)\n  approvers    DocumentApprover[]\n\n  @@index([organization_id, status])\n  @@index([document_id, created_at])\n  @@index([version_id])\n  @@index([due_at])\n  @@map(\"document_approvals\")\n}\n\n/// 17 §10 — one approver (member or Customer Portal user) on an approval request and their decision.\nmodel DocumentApprover {\n  id             String                    @id @default(uuid())\n  approval_id    String\n  kind           DocumentApproverKind      @default(MEMBERSHIP)\n  membership_id  String?\n  /// Customer Portal user (07 §7).\n  portal_user_id String?\n  sort_order     Int                       @default(0)\n  decision       DocumentApprovalDecision?\n  comment        String?\n  decided_at     DateTime?\n  /// 14 — approval request notification sent.\n  notified_at    DateTime?\n  created_at     DateTime                  @default(now())\n\n  approval    DocumentApproval @relation(fields: [approval_id], references: [id], onDelete: Cascade)\n  membership  Membership?      @relation(\"DocumentApproverMembership\", fields: [membership_id], references: [id], onDelete: Cascade)\n  portal_user User?            @relation(\"DocumentApproverPortalUser\", fields: [portal_user_id], references: [id], onDelete: Cascade)\n\n  @@unique([approval_id, membership_id])\n  @@unique([approval_id, portal_user_id])\n  @@index([membership_id, decision])\n  @@index([portal_user_id, decision])\n  @@map(\"document_approvers\")\n}\n\n// --- Retention & deletion -----------------------------------------------------------\n\n/// 17 §13 — restricted, audited deletion workflow: soft delete with recovery window, retention-driven\n/// deletion and permanent deletion that requires approval. Legal hold blocks execution.\nmodel DocumentDeletionRequest {\n  id                   String                 @id @default(uuid())\n  organization_id      String\n  /// Null after permanent deletion removed the row; document_title / storage_keys keep the trace.\n  document_id          String?\n  document_title       String\n  kind                 DocumentDeletionKind   @default(SOFT)\n  status               DocumentDeletionStatus @default(REQUESTED)\n  reason               String?\n  /// Retention policy that triggered this request (kind RETENTION).\n  retention_policy_id  String?\n  requested_by_user_id String?\n  approved_by_user_id  String?\n  approved_at          DateTime?\n  rejected_reason      String?\n  /// Storage keys purged on execution (all versions and previews).\n  purged_storage_keys  String[]               @default([])\n  executed_at          DateTime?\n  executed_by_user_id  String?\n  created_at           DateTime               @default(now())\n  updated_at           DateTime               @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  document     Document?    @relation(fields: [document_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, status])\n  @@index([document_id])\n  @@map(\"document_deletion_requests\")\n}\n\n// --- Secure Credential Vault --------------------------------------------------------\n\n/// 17 §12 — per-organization encryption key metadata (the key material lives in the KMS / secret\n/// manager; only its reference is stored). Rotations create a new version.\nmodel VaultKey {\n  id              String         @id @default(uuid())\n  organization_id String\n  /// KMS / secret-manager key reference.\n  key_ref         String\n  version         Int            @default(1)\n  algorithm       String         @default(\"AES-256-GCM\")\n  status          VaultKeyStatus @default(ACTIVE)\n  rotated_at      DateTime?\n  retired_at      DateTime?\n  created_at      DateTime       @default(now())\n\n  organization            Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  entries                 VaultEntry[]\n  integration_connections IntegrationConnection[]\n\n  @@unique([organization_id, version])\n  @@index([organization_id, status])\n  @@map(\"vault_keys\")\n}\n\n/// 17 §12 — an encrypted credential (hosting login, API key, service account, domain registrar,\n/// third-party credential) scoped to the organization, a customer or a project. Secrets are never\n/// stored in plain text nor as ordinary Documents. Tags via taggings (VAULT_ENTRY).\nmodel VaultEntry {\n  id                  String         @id @default(uuid())\n  organization_id     String\n  scope               VaultScope     @default(ORGANIZATION)\n  /// Customer (CRM Company, 02) for CUSTOMER scope.\n  company_id          String?\n  project_id          String?\n  name                String\n  type                VaultEntryType @default(PASSWORD)\n  username            String?\n  url                 String?\n  /// Plain-text notes (non-secret). Secret notes go into the ciphertext (type NOTE).\n  notes               String?\n  /// Envelope-encrypted secret (base64 ciphertext incl. nonce/tag) under vault_key_id.\n  secret_ciphertext   String?\n  vault_key_id        String?\n  /// Non-reversible hint shown in lists (e.g. last 4 chars), optional.\n  secret_hint         String?\n  // Type FILE — encrypted file stored outside ordinary documents.\n  file_name           String?\n  file_mimetype       String?\n  file_size_bytes     BigInt?\n  /// Storage key of the encrypted blob.\n  file_storage_key    String?\n  expires_at          DateTime?\n  owner_membership_id String?\n  created_by_user_id  String?\n  /// 17 §12 — visible to Customer Portal users of the customer scope when the organization enables it.\n  portal_visible      Boolean        @default(false)\n  last_rotated_at     DateTime?\n  last_revealed_at    DateTime?\n  reveal_count        Int            @default(0)\n  archived_at         DateTime?\n  deleted_at          DateTime?\n  created_at          DateTime       @default(now())\n  updated_at          DateTime       @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  company      CrmCompany?  @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  project      Project?     @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  owner        Membership?  @relation(\"VaultEntryOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  vault_key    VaultKey?    @relation(fields: [vault_key_id], references: [id], onDelete: Restrict)\n\n  grants      VaultEntryGrant[]\n  access_logs VaultAccessLog[]\n\n  @@index([organization_id, scope])\n  @@index([organization_id, type])\n  @@index([company_id])\n  @@index([project_id])\n  @@index([owner_membership_id])\n  @@index([expires_at])\n  @@map(\"vault_entries\")\n}\n\n/// 17 §12 — explicit access grant on a vault entry for a member, team or Customer Portal user.\n/// Vault permissions (documents.vault.read / reveal / manage) are separate from document permissions.\nmodel VaultEntryGrant {\n  id                 String                @id @default(uuid())\n  entry_id           String\n  subject_type       VaultGrantSubjectType\n  membership_id      String?\n  team_id            String?\n  /// Customer Portal user of the entry's customer scope (17 §12, Phase 2).\n  portal_user_id     String?\n  can_reveal         Boolean               @default(false)\n  can_manage         Boolean               @default(false)\n  expires_at         DateTime?\n  granted_by_user_id String?\n  revoked_at         DateTime?\n  revoked_by_user_id String?\n  created_at         DateTime              @default(now())\n\n  entry       VaultEntry  @relation(fields: [entry_id], references: [id], onDelete: Cascade)\n  membership  Membership? @relation(\"VaultGrantMembership\", fields: [membership_id], references: [id], onDelete: Cascade)\n  team        Team?       @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  portal_user User?       @relation(\"VaultGrantPortalUser\", fields: [portal_user_id], references: [id], onDelete: Cascade)\n\n  @@unique([entry_id, membership_id])\n  @@unique([entry_id, team_id])\n  @@unique([entry_id, portal_user_id])\n  @@index([membership_id])\n  @@index([portal_user_id])\n  @@map(\"vault_entry_grants\")\n}\n\n/// 17 §12, §15 — queryable access log for vault entries (reveal / copy are explicit, logged actions).\n/// Mirrored to audit_events; this table backs the per-entry \"access history\" view.\nmodel VaultAccessLog {\n  id                  String            @id @default(uuid())\n  organization_id     String\n  entry_id            String\n  action              VaultAccessAction\n  actor_user_id       String?\n  actor_membership_id String?\n  /// Actor acted through the Customer Portal.\n  via_portal          Boolean           @default(false)\n  ip_address          String?\n  user_agent          String?\n  /// Context (e.g. project / ticket the reveal happened from).\n  context             Json?\n  created_at          DateTime          @default(now())\n\n  organization     Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  entry            VaultEntry   @relation(fields: [entry_id], references: [id], onDelete: Cascade)\n  actor_user       User?        @relation(\"VaultAccessActorUser\", fields: [actor_user_id], references: [id], onDelete: SetNull)\n  actor_membership Membership?  @relation(\"VaultAccessActorMembership\", fields: [actor_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([entry_id, created_at])\n  @@index([organization_id, action, created_at])\n  @@index([actor_user_id, created_at])\n  @@map(\"vault_access_logs\")\n}\n\n// =====================================================================\n// 18 Time Tracking — docs/features/18-time-tracking.md (LOG-408)\n// Owns: time entries, running timers, timesheets and their approval history, billing/cost rate cards\n// and their snapshots on entries, activity types, capture suggestions (calendar/AI), invoicing-time\n// write-off/write-up adjustments, utilization snapshots and the organization's time-tracking settings.\n// Does not own: projects/workstreams/milestones (05), tasks (06), tickets (13), invoices and\n// products (08), employee compensation and attendance (10), calendar events (19), notifications (14).\n// Creation/edit/approval/unlock/rate-change/invoicing audit goes to audit_events (01).\n// =====================================================================\n\n/// 18 §3 — lifecycle of a time entry. LOCKED is reached after the containing period is locked (§5)\n/// or the entry was invoiced (§7); INVOICED entries are implicitly locked.\nenum TimeEntryStatus {\n  DRAFT\n  SUBMITTED\n  APPROVED\n  REJECTED\n  INVOICED\n  LOCKED\n}\n\n/// 18 §3, §4 — how the entry was captured.\nenum TimeEntrySource {\n  MANUAL\n  TIMER\n  CALENDAR\n  IMPORTED\n  GENERATED\n}\n\n/// 18 §6 — why an entry is not billable.\nenum TimeNonBillableCategory {\n  INTERNAL\n  PRE_SALES\n  WARRANTY\n  OVERHEAD\n  LEAVE\n  TRAINING\n  ADMIN\n}\n\n/// 18 §2, §5 — timesheet lifecycle.\nenum TimesheetStatus {\n  OPEN\n  SUBMITTED\n  APPROVED\n  REJECTED\n  LOCKED\n}\n\n/// 18 §2, §5 — timesheet period length (weekly by default, custom allowed).\nenum TimesheetPeriodType {\n  WEEKLY\n  BIWEEKLY\n  SEMI_MONTHLY\n  MONTHLY\n  CUSTOM\n}\n\n/// 18 §5 — who approves a member's timesheet, per organization policy.\nenum TimesheetApproverPolicy {\n  PROJECT_OWNER\n  TEAM_LEAD\n  MANAGER\n  SPECIFIC_MEMBER\n}\n\n/// 18 §5, §12 — queryable approval/lock history of a timesheet.\nenum TimesheetActionType {\n  SUBMITTED\n  APPROVED\n  REJECTED\n  REOPENED\n  LOCKED\n  UNLOCKED\n}\n\n/// 18 §2 — a rate card is either what the customer is charged or what the employee costs.\nenum TimeRateKind {\n  BILLING\n  COST\n}\n\n/// 18 §2, §6 — resolution scope of a rate card; most specific wins\n/// (PROJECT_MEMBER > PROJECT > MEMBER > PRODUCT > ORGANIZATION).\nenum BillingRateScope {\n  ORGANIZATION\n  PRODUCT\n  PROJECT\n  MEMBER\n  PROJECT_MEMBER\n}\n\n/// 18 §4 — origin of a suggested entry.\nenum TimeSuggestionSource {\n  CALENDAR\n  COMMIT\n  TASK_ACTIVITY\n  ATTENDANCE\n  AI\n}\n\n/// 18 §4 — review state of a suggested entry (review is always required).\nenum TimeSuggestionStatus {\n  PENDING\n  ACCEPTED\n  DISMISSED\n  EXPIRED\n}\n\n/// 18 §6 — invoicing-time adjustment applied to an entry without editing it.\nenum TimeAdjustmentType {\n  WRITE_OFF\n  WRITE_UP\n  WRITE_DOWN\n}\n\n/// 18 §4 — rounding applied to durations at capture / invoicing time.\nenum TimeRoundingMode {\n  NONE\n  NEAREST\n  UP\n  DOWN\n}\n\n/// 18 §4 — bulk import jobs for IMPORTED entries.\nenum TimeImportStatus {\n  PENDING\n  PROCESSING\n  COMPLETED\n  FAILED\n  CANCELLED\n}\n\n// --- Configuration ----------------------------------------------------------------\n\n/// 18 §4, §5, §6, §9 — organization-wide time tracking settings (one row per organization).\nmodel TimeTrackingSettings {\n  organization_id                  String                  @id\n  // 18 §5 — timesheet periods & approval.\n  period_type                      TimesheetPeriodType     @default(WEEKLY)\n  /// 1 = Monday … 7 = Sunday; falls back to Organization.week_start (01 §14).\n  week_start                       Int?\n  require_approval                 Boolean                 @default(true)\n  approver_policy                  TimesheetApproverPolicy @default(MANAGER)\n  /// Approver when approver_policy = SPECIFIC_MEMBER.\n  default_approver_membership_id   String?\n  /// Approved periods are locked automatically (18 §5).\n  lock_on_approval                 Boolean                 @default(true)\n  /// Members may still edit rejected entries of a locked period.\n  allow_self_approval              Boolean                 @default(false)\n  // 18 §6 — billability defaults.\n  default_billable                 Boolean                 @default(true)\n  require_billable_override_reason Boolean                 @default(true)\n  // 18 §4 — capture rules.\n  rounding_increment_minutes       Int                     @default(1)\n  rounding_mode                    TimeRoundingMode        @default(NONE)\n  min_entry_minutes                Int?\n  max_hours_per_day                Decimal?                @db.Decimal(5, 2)\n  allow_overlapping_entries        Boolean                 @default(false)\n  allow_future_entries             Boolean                 @default(false)\n  require_project                  Boolean                 @default(false)\n  require_task_or_ticket           Boolean                 @default(false)\n  require_description              Boolean                 @default(false)\n  require_activity_type            Boolean                 @default(false)\n  /// Days back a member may still add or edit DRAFT entries; null = unlimited.\n  edit_window_days                 Int?\n  /// Timer idle detection threshold (18 §4); null disables.\n  idle_timeout_minutes             Int?\n  /// Stop a forgotten timer automatically after this many hours; null = never.\n  timer_auto_stop_hours            Int?\n  calendar_capture_enabled         Boolean                 @default(false)\n  ai_suggestions_enabled           Boolean                 @default(false)\n  /// Attendance (10) pre-fills the daily total (18 §9).\n  attendance_prefill_enabled       Boolean                 @default(false)\n  // 18 §5 — reminders for missing/unsubmitted time, delivered by 14.\n  missing_time_reminder_enabled    Boolean                 @default(true)\n  /// Days of the week (1–7) on which the missing-time reminder is sent.\n  missing_time_reminder_days       Int[]                   @default([])\n  /// Local time \"HH:mm\" for reminders.\n  missing_time_reminder_time       String?\n  submission_reminder_enabled      Boolean                 @default(true)\n  /// Days after period end before the submission reminder fires.\n  submission_reminder_offset_days  Int                     @default(1)\n  // 18 §9, §10 — utilization.\n  /// Fallback expected hours per week when 10 Employees has no working-hours record.\n  default_expected_hours_per_week  Decimal                 @default(40) @db.Decimal(5, 2)\n  utilization_target_percent       Decimal?                @db.Decimal(5, 2)\n  /// Count only billable hours in utilization (otherwise all logged hours).\n  utilization_billable_only        Boolean                 @default(false)\n  /// Reporting currency for mixed-currency rate reports; falls back to Organization.default_currency.\n  reporting_currency               String?\n  updated_at                       DateTime                @updatedAt\n\n  organization     Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_approver Membership?  @relation(\"TimeTrackingDefaultApprover\", fields: [default_approver_membership_id], references: [id], onDelete: SetNull)\n\n  @@map(\"time_tracking_settings\")\n}\n\n/// 18 §3 — configurable activity types (development, design, meeting, support, admin …).\nmodel TimeActivityType {\n  id                            String                   @id @default(uuid())\n  organization_id               String\n  name                          String\n  slug                          String\n  description                   String?\n  color                         String?\n  icon                          String?\n  /// Default billability for entries of this type (18 §6); null = inherit project/org default.\n  default_billable              Boolean?\n  /// Non-billable category applied when default_billable = false.\n  default_non_billable_category TimeNonBillableCategory?\n  is_default                    Boolean                  @default(false)\n  sort_order                    Int                      @default(0)\n  archived_at                   DateTime?\n  created_at                    DateTime                 @default(now())\n  updated_at                    DateTime                 @updatedAt\n\n  organization     Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  time_entries     TimeEntry[]\n  timers           Timer[]\n  billing_rates    BillingRate[]\n  suggestions      TimeSuggestion[]\n  project_settings TimeProjectSettings[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, archived_at])\n  @@map(\"time_activity_types\")\n}\n\n/// 18 §6, §8 — per-project time tracking overrides. Billing model and T&M hourly rate stay in\n/// ProjectBillingSettings (08); this row carries default billability derived from the project type\n/// and contract (04 §54) plus approval and capture overrides.\nmodel TimeProjectSettings {\n  project_id                    String                   @id\n  /// Default billability for entries on this project; null = organization default.\n  default_billable              Boolean?\n  default_non_billable_category TimeNonBillableCategory?\n  default_activity_type_id      String?\n  /// Contract that defines the billing context (04 §54).\n  contract_id                   String?\n  /// Approver override for entries on this project (18 §5); null = organization policy.\n  approver_membership_id        String?\n  /// Whether members can log time against this project at all.\n  time_tracking_enabled         Boolean                  @default(true)\n  /// Only project members (05 §16) may log time.\n  members_only                  Boolean                  @default(true)\n  require_task                  Boolean                  @default(false)\n  /// Alert when logged hours reach this percent of Project.budget_hours (05 §51).\n  hours_alert_percent           Int?\n  hours_alert_sent_at           DateTime?\n  updated_at                    DateTime                 @updatedAt\n\n  project               Project           @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  default_activity_type TimeActivityType? @relation(fields: [default_activity_type_id], references: [id], onDelete: SetNull)\n  contract              Contract?         @relation(fields: [contract_id], references: [id], onDelete: SetNull)\n  approver              Membership?       @relation(\"TimeProjectApprover\", fields: [approver_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([contract_id])\n  @@map(\"time_project_settings\")\n}\n\n// --- Rates --------------------------------------------------------------------------\n\n/// 18 §2, §6 — rate cards with effective dates. BILLING rates (customer price per hour) resolve by\n/// scope: organization default, product/service (08), project override, member, project+member.\n/// COST rates (employee cost per hour) are synced from 10 Employees compensation\n/// (source_compensation_id) or entered here for members without an Employee record. Cost rates are\n/// a sensitive field (01 §60, 18 §11). Rate changes are audited (18 §12).\nmodel BillingRate {\n  id                       String           @id @default(uuid())\n  organization_id          String\n  kind                     TimeRateKind     @default(BILLING)\n  scope                    BillingRateScope\n  /// 08 product/service the rate belongs to (unit = hour).\n  product_id               String?\n  project_id               String?\n  membership_id            String?\n  /// Optional narrowing by activity type (e.g. meetings billed at a different rate).\n  activity_type_id         String?\n  name                     String?\n  currency                 String\n  hourly_rate              Decimal          @db.Decimal(18, 2)\n  effective_from           DateTime         @db.Date\n  /// Null = open-ended.\n  effective_to             DateTime?        @db.Date\n  /// 10 Employee compensation record this COST rate was synced from; id only.\n  source_compensation_id   String?\n  notes                    String?\n  created_by_membership_id String?\n  archived_at              DateTime?\n  created_at               DateTime         @default(now())\n  updated_at               DateTime         @updatedAt\n\n  organization  Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  product       Product?          @relation(fields: [product_id], references: [id], onDelete: Cascade)\n  project       Project?          @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  membership    Membership?       @relation(\"BillingRateMember\", fields: [membership_id], references: [id], onDelete: Cascade)\n  activity_type TimeActivityType? @relation(fields: [activity_type_id], references: [id], onDelete: SetNull)\n  created_by    Membership?       @relation(\"BillingRateCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n\n  billed_entries TimeEntry[] @relation(\"TimeEntryBillingRate\")\n  costed_entries TimeEntry[] @relation(\"TimeEntryCostRate\")\n\n  @@index([organization_id, kind, scope, effective_from])\n  @@index([project_id, membership_id, effective_from])\n  @@index([membership_id, kind, effective_from])\n  @@index([product_id])\n  @@map(\"billing_rates\")\n}\n\n// --- Time entries -------------------------------------------------------------------\n\n/// 18 §3 — a unit of recorded work. Project is optional for internal time (admin, training, leave);\n/// task and ticket are optional. Rate snapshots (18 §3) are copied at approval time so later rate\n/// changes never alter history. Status transitions, edits, unlocks and invoicing are audited (§12).\nmodel TimeEntry {\n  id                        String                   @id @default(uuid())\n  organization_id           String\n  /// The member who performed the work (Member with an Employee record, 01 §80).\n  membership_id             String\n  /// 10 Employee record of the member at the time of logging; id only.\n  employee_id               String?\n  /// Branch scope for reporting (01 §123–124): the project's primary branch or the member's primary branch.\n  branch_id                 String?\n  /// Working date the time belongs to (entries never span days).\n  date                      DateTime                 @db.Date\n  start_at                  DateTime?\n  end_at                    DateTime?\n  /// Always stored, derived from start/end when both are present.\n  duration_minutes          Int\n  /// Duration after organization rounding rules (18 §4); equals duration_minutes when rounding is NONE.\n  billable_minutes          Int\n  project_id                String?\n  workstream_id             String?\n  milestone_id              String?\n  task_id                   String?\n  /// Support ticket (13 §4); id only.\n  ticket_id                 String?\n  activity_type_id          String?\n  description               String?\n  // 18 §6 — billable classification.\n  is_billable               Boolean                  @default(true)\n  /// True when the member/approver overrode the default billability; the reason is required (18 §6).\n  billable_overridden       Boolean                  @default(false)\n  billable_override_reason  String?\n  non_billable_category     TimeNonBillableCategory?\n  // 18 §3 — rate snapshots, stored at approval time.\n  billing_rate_id           String?\n  billing_rate_amount       Decimal?                 @db.Decimal(18, 2)\n  billing_currency          String?\n  /// billable_minutes / 60 × billing_rate_amount, snapshotted with the rate.\n  billable_amount           Decimal?                 @db.Decimal(18, 2)\n  cost_rate_id              String?\n  cost_rate_amount          Decimal?                 @db.Decimal(18, 2)\n  cost_currency             String?\n  /// duration_minutes / 60 × cost_rate_amount; consumed by 09 for project profitability (18 §7).\n  cost_amount               Decimal?                 @db.Decimal(18, 2)\n  rates_snapshotted_at      DateTime?\n  // 18 §3 — status & source.\n  status                    TimeEntryStatus          @default(DRAFT)\n  source                    TimeEntrySource          @default(MANUAL)\n  /// Timer this entry was produced from (18 §4).\n  timer_id                  String?                  @unique\n  /// Calendar event (19) this entry was captured from; id only.\n  calendar_event_id         String?\n  /// Attendance record (10) that pre-filled this entry; id only.\n  attendance_record_id      String?\n  import_job_id             String?\n  /// Identifier of the row in the import source, for idempotent re-imports.\n  external_ref              String?\n  // 18 §5 — timesheet & approval.\n  timesheet_id              String?\n  submitted_at              DateTime?\n  approved_by_membership_id String?\n  approved_at               DateTime?\n  rejected_by_membership_id String?\n  rejected_at               DateTime?\n  rejection_reason          String?\n  // 18 §7 — invoicing link, set by 08 when the entry is billed.\n  invoice_id                String?\n  invoice_line_item_id      String?\n  invoiced_at               DateTime?\n  // 18 §5 — locking; unlock requires `time.entries.unlock` and is audited.\n  is_locked                 Boolean                  @default(false)\n  locked_at                 DateTime?\n  locked_by_membership_id   String?\n  unlocked_at               DateTime?\n  unlocked_by_membership_id String?\n  unlock_reason             String?\n  created_by_user_id        String?\n  /// Soft delete (deleted entries stay for audit; invoiced entries cannot be deleted).\n  deleted_at                DateTime?\n  created_at                DateTime                 @default(now())\n  updated_at                DateTime                 @updatedAt\n\n  organization      Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership        Membership         @relation(\"TimeEntryMember\", fields: [membership_id], references: [id], onDelete: Cascade)\n  branch            Branch?            @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  project           Project?           @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  workstream        ProjectWorkstream? @relation(fields: [workstream_id], references: [id], onDelete: SetNull)\n  milestone         ProjectMilestone?  @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n  task              Task?              @relation(fields: [task_id], references: [id], onDelete: SetNull)\n  activity_type     TimeActivityType?  @relation(fields: [activity_type_id], references: [id], onDelete: SetNull)\n  billing_rate      BillingRate?       @relation(\"TimeEntryBillingRate\", fields: [billing_rate_id], references: [id], onDelete: SetNull)\n  cost_rate         BillingRate?       @relation(\"TimeEntryCostRate\", fields: [cost_rate_id], references: [id], onDelete: SetNull)\n  timer             Timer?             @relation(fields: [timer_id], references: [id], onDelete: SetNull)\n  import_job        TimeImportJob?     @relation(fields: [import_job_id], references: [id], onDelete: SetNull)\n  timesheet         Timesheet?         @relation(fields: [timesheet_id], references: [id], onDelete: SetNull)\n  approved_by       Membership?        @relation(\"TimeEntryApprover\", fields: [approved_by_membership_id], references: [id], onDelete: SetNull)\n  rejected_by       Membership?        @relation(\"TimeEntryRejecter\", fields: [rejected_by_membership_id], references: [id], onDelete: SetNull)\n  locked_by         Membership?        @relation(\"TimeEntryLocker\", fields: [locked_by_membership_id], references: [id], onDelete: SetNull)\n  unlocked_by       Membership?        @relation(\"TimeEntryUnlocker\", fields: [unlocked_by_membership_id], references: [id], onDelete: SetNull)\n  invoice           Invoice?           @relation(fields: [invoice_id], references: [id], onDelete: SetNull)\n  invoice_line_item InvoiceLineItem?   @relation(fields: [invoice_line_item_id], references: [id], onDelete: SetNull)\n\n  adjustments TimeEntryAdjustment[]\n  suggestion  TimeSuggestion?       @relation(\"TimeSuggestionAcceptedEntry\")\n\n  @@unique([organization_id, import_job_id, external_ref])\n  @@index([organization_id, status])\n  @@index([organization_id, date])\n  @@index([membership_id, date])\n  @@index([membership_id, status])\n  @@index([project_id, date])\n  @@index([project_id, is_billable, status])\n  @@index([task_id])\n  @@index([ticket_id])\n  @@index([milestone_id])\n  @@index([workstream_id])\n  @@index([timesheet_id])\n  @@index([invoice_id])\n  @@index([invoice_line_item_id])\n  @@index([branch_id, date])\n  @@index([activity_type_id])\n  @@map(\"time_entries\")\n}\n\n/// 18 §2, §4 — a running timer started from a task, ticket or project. At most one running timer\n/// per member (enforced by the service: stopped_at IS NULL). Stopping creates a TimeEntry with\n/// source TIMER; discarding leaves no entry.\nmodel Timer {\n  id                     String    @id @default(uuid())\n  organization_id        String\n  membership_id          String\n  project_id             String?\n  workstream_id          String?\n  milestone_id           String?\n  task_id                String?\n  /// Support ticket (13 §4); id only.\n  ticket_id              String?\n  activity_type_id       String?\n  description            String?\n  is_billable            Boolean?\n  started_at             DateTime  @default(now())\n  /// Pause support: accumulated paused time is excluded from the resulting duration.\n  paused_at              DateTime?\n  paused_minutes         Int       @default(0)\n  /// Client heartbeat for idle detection (18 §4).\n  last_heartbeat_at      DateTime?\n  idle_detected_at       DateTime?\n  /// Idle minutes the member chose to discard when prompted.\n  idle_discarded_minutes Int       @default(0)\n  stopped_at             DateTime?\n  discarded_at           DateTime?\n  /// Set when the timer was stopped automatically (timer_auto_stop_hours).\n  auto_stopped           Boolean   @default(false)\n  /// web | mobile | api | browser_extension\n  device                 String?\n  created_at             DateTime  @default(now())\n  updated_at             DateTime  @updatedAt\n\n  organization  Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership    Membership         @relation(\"TimerMember\", fields: [membership_id], references: [id], onDelete: Cascade)\n  project       Project?           @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  workstream    ProjectWorkstream? @relation(fields: [workstream_id], references: [id], onDelete: SetNull)\n  milestone     ProjectMilestone?  @relation(fields: [milestone_id], references: [id], onDelete: SetNull)\n  task          Task?              @relation(fields: [task_id], references: [id], onDelete: SetNull)\n  activity_type TimeActivityType?  @relation(fields: [activity_type_id], references: [id], onDelete: SetNull)\n  time_entry    TimeEntry?\n\n  @@index([organization_id, stopped_at])\n  @@index([membership_id, stopped_at])\n  @@index([task_id, stopped_at])\n  @@index([project_id, stopped_at])\n  @@index([ticket_id])\n  @@map(\"timers\")\n}\n\n/// 18 §4 — bulk/CSV/external imports producing IMPORTED entries.\nmodel TimeImportJob {\n  id                       String           @id @default(uuid())\n  organization_id          String\n  /// csv | external system key\n  source                   String\n  /// Uploaded file (17 Document); id only.\n  file_document_id         String?\n  status                   TimeImportStatus @default(PENDING)\n  /// Column → field mapping used for the run.\n  mapping                  Json?\n  total_rows               Int              @default(0)\n  imported_rows            Int              @default(0)\n  skipped_rows             Int              @default(0)\n  failed_rows              Int              @default(0)\n  /// [{ row, message }]\n  errors                   Json?\n  started_at               DateTime?\n  completed_at             DateTime?\n  created_by_membership_id String?\n  created_at               DateTime         @default(now())\n  updated_at               DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  created_by   Membership?  @relation(\"TimeImportJobCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  entries      TimeEntry[]\n\n  @@index([organization_id, status])\n  @@map(\"time_import_jobs\")\n}\n\n/// 18 §4 — suggested entries from calendar events (19), commits, task activity (06), attendance (10)\n/// or AI. Review is always required: accepting creates a TimeEntry, dismissing keeps the suggestion\n/// so it is not re-proposed.\nmodel TimeSuggestion {\n  id                     String               @id @default(uuid())\n  organization_id        String\n  membership_id          String\n  source                 TimeSuggestionSource\n  status                 TimeSuggestionStatus @default(PENDING)\n  date                   DateTime             @db.Date\n  start_at               DateTime?\n  end_at                 DateTime?\n  duration_minutes       Int\n  project_id             String?\n  task_id                String?\n  /// Support ticket (13); id only.\n  ticket_id              String?\n  activity_type_id       String?\n  description            String?\n  is_billable            Boolean?\n  /// Calendar event (19) the suggestion came from; id only.\n  calendar_event_id      String?\n  /// Commit sha, attendance record id, task audit event id, …\n  external_ref           String?\n  /// 0–1 confidence for AI suggestions.\n  confidence             Decimal?             @db.Decimal(5, 4)\n  /// Model/rule explanation shown to the reviewer.\n  rationale              String?\n  /// Raw source payload (event title, commit message, …).\n  payload                Json?\n  accepted_time_entry_id String?              @unique\n  reviewed_at            DateTime?\n  expires_at             DateTime?\n  created_at             DateTime             @default(now())\n  updated_at             DateTime             @updatedAt\n\n  organization   Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership     Membership        @relation(\"TimeSuggestionMember\", fields: [membership_id], references: [id], onDelete: Cascade)\n  project        Project?          @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  task           Task?             @relation(fields: [task_id], references: [id], onDelete: SetNull)\n  activity_type  TimeActivityType? @relation(fields: [activity_type_id], references: [id], onDelete: SetNull)\n  accepted_entry TimeEntry?        @relation(\"TimeSuggestionAcceptedEntry\", fields: [accepted_time_entry_id], references: [id], onDelete: SetNull)\n\n  @@unique([membership_id, source, external_ref])\n  @@index([membership_id, status, date])\n  @@index([organization_id, status])\n  @@map(\"time_suggestions\")\n}\n\n/// 18 §6 — write-off / write-up / write-down applied at invoicing time. The entry itself is never\n/// edited: the adjustment records the delta between the snapshotted billable amount and what was\n/// actually billed on the invoice line (08 \"Invoicing\").\nmodel TimeEntryAdjustment {\n  id                        String             @id @default(uuid())\n  organization_id           String\n  time_entry_id             String\n  type                      TimeAdjustmentType\n  /// Minutes actually billed after the adjustment (null = unchanged).\n  adjusted_billable_minutes Int?\n  /// Amount actually billed after the adjustment.\n  adjusted_amount           Decimal            @db.Decimal(18, 2)\n  /// adjusted_amount − TimeEntry.billable_amount (negative for write-offs).\n  delta_amount              Decimal            @db.Decimal(18, 2)\n  currency                  String\n  reason                    String\n  invoice_line_item_id      String?\n  created_by_membership_id  String?\n  created_at                DateTime           @default(now())\n\n  organization      Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  time_entry        TimeEntry        @relation(fields: [time_entry_id], references: [id], onDelete: Cascade)\n  invoice_line_item InvoiceLineItem? @relation(fields: [invoice_line_item_id], references: [id], onDelete: SetNull)\n  created_by        Membership?      @relation(\"TimeEntryAdjustmentCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([time_entry_id])\n  @@index([invoice_line_item_id])\n  @@index([organization_id, type, created_at])\n  @@map(\"time_entry_adjustments\")\n}\n\n// --- Timesheets ---------------------------------------------------------------------\n\n/// 18 §2, §5 — a periodic collection of one member's entries submitted for approval. Created lazily\n/// when the first entry of a period is logged or on submission. Totals are denormalized on\n/// submission/approval for timesheet-compliance reporting (18 §10).\nmodel Timesheet {\n  id                        String              @id @default(uuid())\n  organization_id           String\n  membership_id             String\n  period_type               TimesheetPeriodType @default(WEEKLY)\n  period_start              DateTime            @db.Date\n  period_end                DateTime            @db.Date\n  status                    TimesheetStatus     @default(OPEN)\n  // Denormalized totals (minutes).\n  total_minutes             Int                 @default(0)\n  billable_minutes          Int                 @default(0)\n  non_billable_minutes      Int                 @default(0)\n  /// Expected capacity for the period from working hours, leave and holidays (10, 01 §121–122).\n  expected_minutes          Int?\n  /// Snapshot of billable amount across entries, in reporting currency.\n  billable_amount           Decimal?            @db.Decimal(18, 2)\n  currency                  String?\n  // 18 §5 — submit / approve / reject.\n  submitted_at              DateTime?\n  /// Resolved approver for this timesheet (project owner, team lead or manager per policy).\n  approver_membership_id    String?\n  approved_at               DateTime?\n  approved_by_membership_id String?\n  rejected_at               DateTime?\n  rejected_by_membership_id String?\n  rejection_comment         String?\n  /// Member comment attached on submission.\n  submission_comment        String?\n  // 18 §5 — locking.\n  locked_at                 DateTime?\n  locked_by_membership_id   String?\n  unlocked_at               DateTime?\n  unlocked_by_membership_id String?\n  unlock_reason             String?\n  last_reminder_sent_at     DateTime?\n  reminder_count            Int                 @default(0)\n  created_at                DateTime            @default(now())\n  updated_at                DateTime            @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership   Membership   @relation(\"TimesheetMember\", fields: [membership_id], references: [id], onDelete: Cascade)\n  approver     Membership?  @relation(\"TimesheetApprover\", fields: [approver_membership_id], references: [id], onDelete: SetNull)\n  approved_by  Membership?  @relation(\"TimesheetApprovedBy\", fields: [approved_by_membership_id], references: [id], onDelete: SetNull)\n  rejected_by  Membership?  @relation(\"TimesheetRejectedBy\", fields: [rejected_by_membership_id], references: [id], onDelete: SetNull)\n  locked_by    Membership?  @relation(\"TimesheetLockedBy\", fields: [locked_by_membership_id], references: [id], onDelete: SetNull)\n  unlocked_by  Membership?  @relation(\"TimesheetUnlockedBy\", fields: [unlocked_by_membership_id], references: [id], onDelete: SetNull)\n\n  entries TimeEntry[]\n  actions TimesheetAction[]\n\n  @@unique([membership_id, period_start, period_end])\n  @@index([organization_id, status])\n  @@index([organization_id, period_start])\n  @@index([approver_membership_id, status])\n  @@map(\"timesheets\")\n}\n\n/// 18 §5, §12 — submit/approve/reject/reopen/lock/unlock history with comments. Mirrors audit_events\n/// but is kept queryable for compliance reporting (18 §10).\nmodel TimesheetAction {\n  id                  String              @id @default(uuid())\n  timesheet_id        String\n  action              TimesheetActionType\n  actor_membership_id String?\n  comment             String?\n  /// Status before → after.\n  from_status         TimesheetStatus?\n  to_status           TimesheetStatus?\n  created_at          DateTime            @default(now())\n\n  timesheet Timesheet   @relation(fields: [timesheet_id], references: [id], onDelete: Cascade)\n  actor     Membership? @relation(\"TimesheetActionActor\", fields: [actor_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([timesheet_id, created_at])\n  @@map(\"timesheet_actions\")\n}\n\n// --- Reporting ----------------------------------------------------------------------\n\n/// 18 §9, §10 — per-member, per-period utilization snapshot. Utilization = logged / expected hours;\n/// computed here (expected capacity from 10 and 01 §121–122), displayed in 10 and 05. Recomputed\n/// whenever entries, leave or holidays in the period change.\nmodel TimeUtilizationPeriod {\n  id                  String   @id @default(uuid())\n  organization_id     String\n  membership_id       String\n  branch_id           String?\n  period_start        DateTime @db.Date\n  period_end          DateTime @db.Date\n  expected_minutes    Int      @default(0)\n  logged_minutes      Int      @default(0)\n  billable_minutes    Int      @default(0)\n  /// Minutes of approved leave and holidays removed from capacity (10, 01 §122).\n  leave_minutes       Int      @default(0)\n  utilization_percent Decimal? @db.Decimal(5, 2)\n  billable_ratio      Decimal? @db.Decimal(5, 2)\n  computed_at         DateTime @default(now())\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership   Membership   @relation(\"TimeUtilizationMember\", fields: [membership_id], references: [id], onDelete: Cascade)\n  branch       Branch?      @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n\n  @@unique([membership_id, period_start, period_end])\n  @@index([organization_id, period_start])\n  @@index([branch_id, period_start])\n  @@map(\"time_utilization_periods\")\n}\n\n// =====================================================================\n// 19 Calendar — docs/features/19-calendar.md (LOG-409)\n// Owns: calendars (personal/team/project/customer/branch/resource/organization/external), calendar\n// sharing, the only CalendarEvent record (recurrence, attendees, RSVP, reminders, resources, links,\n// attachments), bookable resources, availability schedules used for scheduling and booking,\n// booking links and bookings, external calendar connections (Google / Microsoft 365) with per-event\n// sync mappings, conferencing provider accounts and per-member calendar preferences.\n// Does not own: projected dates (milestones 05, contract dates 04, task due dates 06, leave 10 —\n// rendered read-only from the source record, never stored here), employee working hours / capacity\n// (10), branch business hours and holidays (01 §120–122), CRM meeting outcomes (02 §15 — CrmActivity\n// points at the event), notifications (14), documents (17). Audit log goes to audit_events (§11).\n// =====================================================================\n\n/// 19 §2 — kinds of calendar. EXTERNAL calendars are created by a CalendarConnection (§7).\nenum CalendarKind {\n  PERSONAL\n  TEAM\n  PROJECT\n  CUSTOMER\n  BRANCH\n  ORGANIZATION\n  RESOURCE\n  EXTERNAL\n}\n\n/// 19 §6 — bookable resource kinds (rooms, equipment).\nenum CalendarResourceKind {\n  ROOM\n  EQUIPMENT\n  VEHICLE\n  OTHER\n}\n\n/// 19 §7, §10 — what a calendar share grants. FREE_BUSY exposes only busy blocks (§7).\nenum CalendarShareRole {\n  FREE_BUSY\n  READ\n  WRITE\n  MANAGE\n}\n\n/// 19 §3 — event lifecycle. CANCELLED rows are kept for history, sync and notifications (§9).\nenum CalendarEventStatus {\n  TENTATIVE\n  CONFIRMED\n  CANCELLED\n}\n\n/// 19 §3, §8 — visibility. CUSTOMER_VISIBLE events surface in the Customer Portal (07 §11).\nenum CalendarEventVisibility {\n  PRIVATE\n  TEAM\n  ORGANIZATION\n  CUSTOMER_VISIBLE\n}\n\n/// 19 §3 — where the event came from.\nenum CalendarEventSource {\n  INTERNAL\n  SYNCED\n  BOOKING\n  API\n}\n\n/// 19 §3 — who an attendee is: Member, Customer Portal user, CRM contact or an external email.\nenum CalendarAttendeeKind {\n  MEMBER\n  PORTAL_USER\n  CONTACT\n  EXTERNAL\n}\n\n/// 19 §3 — attendee participation role.\nenum CalendarAttendeeRole {\n  REQUIRED\n  OPTIONAL\n  INFORMATIONAL\n}\n\n/// 19 §3 — RSVP state (iCalendar PARTSTAT).\nenum CalendarAttendeeResponse {\n  NEEDS_ACTION\n  ACCEPTED\n  TENTATIVE\n  DECLINED\n}\n\n/// 19 §6 — resource booking approval state.\nenum CalendarResourceBookingStatus {\n  REQUESTED\n  APPROVED\n  DECLINED\n  CANCELLED\n}\n\n/// 19 §9 — reminder delivery channel; delivery itself happens in 14.\nenum CalendarReminderMethod {\n  NOTIFICATION\n  EMAIL\n  SMS\n  PUSH\n}\n\n/// 19 §6 — availability override kind: block time off or open extra hours.\nenum CalendarAvailabilityOverrideKind {\n  UNAVAILABLE\n  AVAILABLE\n}\n\n/// 19 §6 — booking link lifecycle.\nenum BookingLinkStatus {\n  DRAFT\n  ACTIVE\n  PAUSED\n  ARCHIVED\n}\n\n/// 19 §6 — how hosts are picked for a booking link with several hosts.\nenum BookingHostAssignment {\n  SINGLE\n  ROUND_ROBIN\n  COLLECTIVE\n}\n\n/// 19 §6 — who may use a booking link.\nenum BookingLinkAudience {\n  PUBLIC\n  PORTAL\n  INTERNAL\n}\n\n/// 19 §6 — booking lifecycle.\nenum CalendarBookingStatus {\n  PENDING\n  CONFIRMED\n  RESCHEDULED\n  CANCELLED\n  NO_SHOW\n  COMPLETED\n}\n\n/// 19 §6 — how a booking was made.\nenum CalendarBookingSource {\n  PUBLIC_LINK\n  PORTAL\n  INTERNAL\n  API\n}\n\n/// 19 §7 — external calendar providers.\nenum CalendarProvider {\n  GOOGLE\n  MICROSOFT\n}\n\n/// 19 §7 — connection lifecycle.\nenum CalendarConnectionStatus {\n  PENDING_AUTH\n  ACTIVE\n  PAUSED\n  ERROR\n  DISCONNECTED\n}\n\n/// 19 §7 — sync direction per connected calendar.\nenum CalendarSyncDirection {\n  TWO_WAY\n  PULL_ONLY\n  PUSH_ONLY\n}\n\n/// 19 §7 — per-event sync state.\nenum CalendarSyncMappingStatus {\n  SYNCED\n  PENDING_PUSH\n  PENDING_PULL\n  CONFLICT\n  FAILED\n  DELETED_REMOTELY\n}\n\n/// 19 §7 — sync run outcome.\nenum CalendarSyncRunStatus {\n  RUNNING\n  SUCCEEDED\n  PARTIAL\n  FAILED\n}\n\n/// 19 §3 — external video / conferencing providers for meeting links.\nenum ConferencingProvider {\n  GOOGLE_MEET\n  MICROSOFT_TEAMS\n  ZOOM\n  CUSTOM\n}\n\n/// 19 §3 — conferencing account state.\nenum ConferencingAccountStatus {\n  ACTIVE\n  ERROR\n  DISCONNECTED\n}\n\n// --- Configuration ----------------------------------------------------------------\n\n/// 19 §4 — configurable event types (meeting, customer meeting, kickoff, review, interview, deadline,\n/// out of office, focus time, booking …). System types are seeded per organization and cannot be deleted.\nmodel CalendarEventType {\n  id                       String                  @id @default(uuid())\n  organization_id          String\n  name                     String\n  slug                     String\n  description              String?\n  color                    String?\n  icon                     String?\n  /// Seeded type (customer_meeting, booking, out_of_office …) referenced by other modules; not deletable.\n  is_system                Boolean                 @default(false)\n  is_default               Boolean                 @default(false)\n  default_duration_minutes Int?\n  default_visibility       CalendarEventVisibility @default(TEAM)\n  /// Whether events of this type block free/busy (§6). False for focus time / informational types.\n  shows_as_busy            Boolean                 @default(true)\n  /// Default reminders applied to new events: [{ method, minutes_before }] (§9).\n  default_reminders        Json?\n  /// Customer meeting type used by CRM meetings (02 §15).\n  is_customer_facing       Boolean                 @default(false)\n  sort_order               Int                     @default(0)\n  archived_at              DateTime?\n  created_at               DateTime                @default(now())\n  updated_at               DateTime                @updatedAt\n\n  organization  Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  events        CalendarEvent[]\n  booking_links BookingLink[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, archived_at])\n  @@map(\"calendar_event_types\")\n}\n\n/// 19 §5, §9 — per-member calendar preferences (default calendar, reminder defaults, view settings).\n/// Reminder timing is a user preference (§9).\nmodel CalendarPreference {\n  id                       String   @id @default(uuid())\n  membership_id            String   @unique\n  default_calendar_id      String?\n  /// IANA zone override; falls back to User.timezone, then Branch/Organization (01 §120).\n  timezone                 String?\n  /// day | week | month | agenda (§5).\n  default_view             String   @default(\"week\")\n  week_start               Int?\n  show_weekends            Boolean  @default(true)\n  show_declined_events     Boolean  @default(false)\n  default_event_duration   Int      @default(30)\n  /// Default reminders for events the member creates or is invited to: [{ method, minutes_before }].\n  default_reminders        Json?\n  /// Modules whose projected dates are shown (§5 filter): [\"projects\",\"tasks\",\"contracts\",\"employees\"].\n  projected_modules        String[] @default([])\n  /// Calendar ids overlaid by default (§5).\n  overlay_calendar_ids     String[] @default([])\n  /// Working-hours schedule used for free/busy and suggestions when set (§6).\n  availability_schedule_id String?\n  created_at               DateTime @default(now())\n  updated_at               DateTime @updatedAt\n\n  membership            Membership                    @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  default_calendar      Calendar?                     @relation(\"CalendarPreferenceDefault\", fields: [default_calendar_id], references: [id], onDelete: SetNull)\n  availability_schedule CalendarAvailabilitySchedule? @relation(fields: [availability_schedule_id], references: [id], onDelete: SetNull)\n\n  @@map(\"calendar_preferences\")\n}\n\n// --- Calendars ---------------------------------------------------------------------\n\n/// 19 §2, §5 — a named collection of events. Exactly one scope column is set according to kind:\n/// PERSONAL → owner_membership_id, TEAM → team_id, PROJECT → project_id, CUSTOMER → company_id,\n/// BRANCH → branch_id, RESOURCE → resource_id, EXTERNAL → connection_calendar (see\n/// CalendarConnectionCalendar.calendar_id), ORGANIZATION → none.\nmodel Calendar {\n  id                  String                  @id @default(uuid())\n  organization_id     String\n  kind                CalendarKind\n  name                String\n  description         String?\n  color               String?\n  /// IANA zone used to render all-day events and recurrence expansion; null = owner / organization default.\n  timezone            String?\n  owner_membership_id String?\n  team_id             String?\n  project_id          String?\n  /// Customer calendar (CRM company, 02 §2) — holds customer-visible events shown in the portal (§8).\n  company_id          String?\n  branch_id           String?\n  resource_id         String?                 @unique\n  /// Member's default personal calendar (one per member).\n  is_default          Boolean                 @default(false)\n  /// Default visibility for events created in this calendar.\n  default_visibility  CalendarEventVisibility @default(TEAM)\n  /// §7 — when true, other Members only ever see free/busy for this calendar unless shared explicitly.\n  free_busy_only      Boolean                 @default(false)\n  /// Portal users may see customer-visible events of this calendar (§8).\n  portal_visible      Boolean                 @default(false)\n  sort_order          Int                     @default(0)\n  created_by_user_id  String?\n  archived_at         DateTime?\n  created_at          DateTime                @default(now())\n  updated_at          DateTime                @updatedAt\n\n  organization Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner        Membership?       @relation(\"CalendarOwner\", fields: [owner_membership_id], references: [id], onDelete: Cascade)\n  team         Team?             @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  project      Project?          @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  company      CrmCompany?       @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  branch       Branch?           @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n  resource     CalendarResource? @relation(fields: [resource_id], references: [id], onDelete: Cascade)\n\n  events                  CalendarEvent[]\n  shares                  CalendarShare[]\n  booking_links           BookingLink[]\n  connection_calendars    CalendarConnectionCalendar[]\n  default_for_preferences CalendarPreference[]         @relation(\"CalendarPreferenceDefault\")\n\n  @@index([organization_id, kind])\n  @@index([owner_membership_id])\n  @@index([team_id])\n  @@index([project_id])\n  @@index([company_id])\n  @@index([branch_id])\n  @@map(\"calendars\")\n}\n\n/// 19 §7, §10, §11 — explicit sharing of a calendar with a Member or a Team. Sharing is audited.\nmodel CalendarShare {\n  id                String            @id @default(uuid())\n  calendar_id       String\n  membership_id     String?\n  team_id           String?\n  role              CalendarShareRole @default(READ)\n  shared_by_user_id String?\n  expires_at        DateTime?\n  created_at        DateTime          @default(now())\n  updated_at        DateTime          @updatedAt\n\n  calendar   Calendar    @relation(fields: [calendar_id], references: [id], onDelete: Cascade)\n  membership Membership? @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  team       Team?       @relation(fields: [team_id], references: [id], onDelete: Cascade)\n\n  @@unique([calendar_id, membership_id])\n  @@unique([calendar_id, team_id])\n  @@index([membership_id])\n  @@index([team_id])\n  @@map(\"calendar_shares\")\n}\n\n/// 19 §6 — bookable resources (meeting rooms, equipment). Each resource has a RESOURCE calendar\n/// (Calendar.resource_id) that holds its bookings for conflict detection.\nmodel CalendarResource {\n  id                     String               @id @default(uuid())\n  organization_id        String\n  branch_id              String?\n  kind                   CalendarResourceKind @default(ROOM)\n  name                   String\n  code                   String?\n  description            String?\n  /// Seats (rooms) or units (equipment).\n  capacity               Int?\n  location               String?\n  color                  String?\n  /// Bookings need approval from a resource manager (CalendarEventResource.status).\n  requires_approval      Boolean              @default(false)\n  /// Membership ids that approve bookings when requires_approval is set.\n  manager_membership_ids String[]             @default([])\n  /// Hours the resource can be booked: { mon: [{start,end}], … }; null = branch business hours (01 §121).\n  availability           Json?\n  /// Equipment, features, floor … free-form.\n  attributes             Json?\n  archived_at            DateTime?\n  created_at             DateTime             @default(now())\n  updated_at             DateTime             @updatedAt\n\n  organization   Organization            @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  branch         Branch?                 @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n  calendar       Calendar?\n  event_bookings CalendarEventResource[]\n\n  @@unique([organization_id, code])\n  @@index([organization_id, kind])\n  @@index([branch_id])\n  @@map(\"calendar_resources\")\n}\n\n// --- Events ------------------------------------------------------------------------\n\n/// 19 §3–4 — the event record. Recurring series: the master row carries recurrence_rule; modified or\n/// cancelled occurrences are stored as child rows with recurring_event_id + original_start_at\n/// (status CANCELLED = exception). Unmodified occurrences are expanded at read time.\n/// CRM meetings (02 §15) are events of a customer-facing type; CrmActivity.calendar_event_id points here.\nmodel CalendarEvent {\n  id                      String                  @id @default(uuid())\n  organization_id         String\n  calendar_id             String\n  event_type_id           String?\n  title                   String\n  /// Markdown body.\n  description             String?\n  status                  CalendarEventStatus     @default(CONFIRMED)\n  starts_at               DateTime\n  ends_at                 DateTime\n  all_day                 Boolean                 @default(false)\n  /// IANA zone the event was scheduled in; drives all-day boundaries and recurrence expansion.\n  timezone                String\n  /// RFC 5545 RRULE (e.g. \"FREQ=WEEKLY;BYDAY=MO,WE;UNTIL=20270101T000000Z\"); master rows only.\n  recurrence_rule         String?\n  /// Explicit excluded occurrence starts (EXDATE) for the series.\n  recurrence_exdates      DateTime[]              @default([])\n  /// Last occurrence of the series, materialised from the rule for range queries.\n  recurrence_ends_at      DateTime?\n  recurring_event_id      String?\n  /// Start of the occurrence this exception row replaces.\n  original_start_at       DateTime?\n  organizer_membership_id String?\n  /// Organizer when the event was pulled from an external calendar and is not a Member (§7).\n  organizer_email         String?\n  visibility              CalendarEventVisibility @default(TEAM)\n  /// Blocks free/busy (§6); false for focus time, out-of-office markers that should stay available, etc.\n  shows_as_busy           Boolean                 @default(true)\n  location                String?\n  /// Structured location (address, room name, geo) when available.\n  location_details        Json?\n  conferencing_provider   ConferencingProvider?\n  meeting_url             String?\n  /// Provider meeting id (Zoom meeting id, Teams join id …).\n  meeting_external_id     String?\n  /// Dial-in numbers, passcodes, host key …; secrets are encrypted by the API.\n  meeting_details         Json?\n  /// Customer context: CRM company (02 §2). Required for CUSTOMER_VISIBLE events (§8).\n  company_id              String?\n  project_id              String?\n  /// Branch whose business hours / holidays apply (01 §120–122); null = organization.\n  branch_id               String?\n  source                  CalendarEventSource     @default(INTERNAL)\n  /// Event colour override; null = calendar / type colour.\n  color                   String?\n  /// iCalendar UID for invitations and interop; stable across edits.\n  ical_uid                String                  @default(uuid())\n  /// iCalendar SEQUENCE; incremented on every change that re-sends invitations (§9).\n  sequence                Int                     @default(0)\n  cancelled_at            DateTime?\n  cancelled_by_user_id    String?\n  cancellation_reason     String?\n  /// 20 AutomationRule when created by a rule.\n  automation_rule_id      String?\n  created_by_user_id      String?\n  created_at              DateTime                @default(now())\n  updated_at              DateTime                @updatedAt\n\n  organization    Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  calendar        Calendar           @relation(fields: [calendar_id], references: [id], onDelete: Cascade)\n  event_type      CalendarEventType? @relation(fields: [event_type_id], references: [id], onDelete: SetNull)\n  recurring_event CalendarEvent?     @relation(\"CalendarEventRecurrence\", fields: [recurring_event_id], references: [id], onDelete: Cascade)\n  occurrences     CalendarEvent[]    @relation(\"CalendarEventRecurrence\")\n  organizer       Membership?        @relation(\"CalendarEventOrganizer\", fields: [organizer_membership_id], references: [id], onDelete: SetNull)\n  company         CrmCompany?        @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  project         Project?           @relation(fields: [project_id], references: [id], onDelete: SetNull)\n  branch          Branch?            @relation(fields: [branch_id], references: [id], onDelete: SetNull)\n\n  attendees     CalendarEventAttendee[]\n  resources     CalendarEventResource[]\n  reminders     CalendarEventReminder[]\n  links         CalendarEventLink[]\n  attachments   CalendarEventAttachment[]\n  sync_mappings CalendarEventSyncMapping[]\n  booking       CalendarBooking?\n\n  // Back-links from other modules' records that reference this event\n  crm_activities CrmActivity[]\n\n  @@unique([organization_id, ical_uid])\n  @@unique([recurring_event_id, original_start_at])\n  @@index([organization_id, starts_at, ends_at])\n  @@index([calendar_id, starts_at])\n  @@index([organization_id, status])\n  @@index([organizer_membership_id, starts_at])\n  @@index([company_id])\n  @@index([project_id])\n  @@index([event_type_id])\n  @@index([recurrence_ends_at])\n  @@map(\"calendar_events\")\n}\n\n/// 19 §3, §9 — attendees: Members (membership_id), Customer Portal users (user_id, 01 §79),\n/// CRM contacts (contact_id, 02) or plain external emails. Exactly one identity column per kind;\n/// email is always filled so invitations (14) and iCalendar exports work.\nmodel CalendarEventAttendee {\n  id                   String                   @id @default(uuid())\n  event_id             String\n  kind                 CalendarAttendeeKind\n  membership_id        String?\n  /// Customer Portal user (User with a CustomerPortalMembership).\n  user_id              String?\n  contact_id           String?\n  email                String\n  name                 String?\n  role                 CalendarAttendeeRole     @default(REQUIRED)\n  response             CalendarAttendeeResponse @default(NEEDS_ACTION)\n  response_comment     String?\n  responded_at         DateTime?\n  /// Organizer is also listed as an attendee for RSVP tracking and sync.\n  is_organizer         Boolean                  @default(false)\n  /// Per-attendee invitation emission (§9): null = not sent yet.\n  invited_at           DateTime?\n  /// Token for one-click RSVP links sent to external / portal attendees.\n  response_token       String?                  @unique\n  /// Attendee's own copy lives in another synced calendar; id only.\n  external_attendee_id String?\n  created_at           DateTime                 @default(now())\n  updated_at           DateTime                 @updatedAt\n\n  event      CalendarEvent @relation(fields: [event_id], references: [id], onDelete: Cascade)\n  membership Membership?   @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  user       User?         @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  contact    CrmContact?   @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n\n  @@unique([event_id, email])\n  @@unique([event_id, membership_id])\n  @@index([membership_id, response])\n  @@index([user_id])\n  @@index([contact_id])\n  @@map(\"calendar_event_attendees\")\n}\n\n/// 19 §6 — resource booking (room / equipment) attached to an event, with optional approval.\n/// Conflicts are detected against other APPROVED rows for the same resource and overlapping time.\nmodel CalendarEventResource {\n  id                 String                        @id @default(uuid())\n  event_id           String\n  resource_id        String\n  status             CalendarResourceBookingStatus @default(APPROVED)\n  /// Units booked for equipment with capacity > 1.\n  quantity           Int                           @default(1)\n  decided_by_user_id String?\n  decided_at         DateTime?\n  decision_note      String?\n  created_at         DateTime                      @default(now())\n  updated_at         DateTime                      @updatedAt\n\n  event    CalendarEvent    @relation(fields: [event_id], references: [id], onDelete: Cascade)\n  resource CalendarResource @relation(fields: [resource_id], references: [id], onDelete: Cascade)\n\n  @@unique([event_id, resource_id])\n  @@index([resource_id, status])\n  @@map(\"calendar_event_resources\")\n}\n\n/// 19 §3, §9 — reminders. membership_id null = event default for every attendee; set = a Member's\n/// personal override. Emitted to 14 at scheduled_at (next_occurrence for series); sent_at records\n/// the last emission.\nmodel CalendarEventReminder {\n  id             String                 @id @default(uuid())\n  event_id       String\n  membership_id  String?\n  method         CalendarReminderMethod @default(NOTIFICATION)\n  minutes_before Int\n  /// Next emission time, recomputed when the event moves or a recurrence occurrence passes.\n  scheduled_at   DateTime?\n  sent_at        DateTime?\n  created_at     DateTime               @default(now())\n\n  event      CalendarEvent @relation(fields: [event_id], references: [id], onDelete: Cascade)\n  membership Membership?   @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([event_id, membership_id, method, minutes_before])\n  @@index([scheduled_at, sent_at])\n  @@index([membership_id])\n  @@map(\"calendar_event_reminders\")\n}\n\n/// 19 §3 — related records: project, customer, deal, contract, ticket (13), task, lead, proposal,\n/// invoice … Polymorphic via RecordEntityType; company_id / project_id on the event are the primary\n/// context, this table carries the rest.\nmodel CalendarEventLink {\n  id                 String           @id @default(uuid())\n  event_id           String\n  entity_type        RecordEntityType\n  entity_id          String\n  /// origin | related — origin marks the record the event was created from (CRM meeting, ticket callback).\n  relation           String           @default(\"related\")\n  created_by_user_id String?\n  created_at         DateTime         @default(now())\n\n  event CalendarEvent @relation(fields: [event_id], references: [id], onDelete: Cascade)\n\n  @@unique([event_id, entity_type, entity_id])\n  @@index([entity_type, entity_id])\n  @@map(\"calendar_event_links\")\n}\n\n/// 19 §3 — attachments are Documents (17); id only.\nmodel CalendarEventAttachment {\n  id               String   @id @default(uuid())\n  event_id         String\n  /// 19 §3 — the attachment is a 17 Document.\n  document_id      String\n  /// Attachment pulled from an external calendar (Drive / OneDrive link) before it is imported into 17.\n  external_url     String?\n  title            String?\n  added_by_user_id String?\n  created_at       DateTime @default(now())\n\n  event    CalendarEvent @relation(fields: [event_id], references: [id], onDelete: Cascade)\n  document Document      @relation(\"CalendarEventAttachmentDocument\", fields: [document_id], references: [id], onDelete: Cascade)\n\n  @@unique([event_id, document_id])\n  @@index([document_id])\n  @@map(\"calendar_event_attachments\")\n}\n\n// --- Availability ------------------------------------------------------------------\n\n/// 19 §6 — a scheduling availability schedule (weekly hours + date overrides) for free/busy, slot\n/// suggestions and booking links. Employee working hours, leave and capacity are owned by 10\n/// (\"Attendance & Working Hours\"); this is the Member's scheduling-layer override and the schedule a\n/// booking link offers. membership_id null = organization-level schedule (e.g. \"Support hours\").\nmodel CalendarAvailabilitySchedule {\n  id              String    @id @default(uuid())\n  organization_id String\n  membership_id   String?\n  name            String\n  /// IANA zone the rules are expressed in.\n  timezone        String\n  is_default      Boolean   @default(false)\n  /// Respect branch holidays (01 §122) and approved leave (10) on top of the rules.\n  honor_holidays  Boolean   @default(true)\n  honor_leave     Boolean   @default(true)\n  archived_at     DateTime?\n  created_at      DateTime  @default(now())\n  updated_at      DateTime  @updatedAt\n\n  organization  Organization                   @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership    Membership?                    @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  rules         CalendarAvailabilityRule[]\n  overrides     CalendarAvailabilityOverride[]\n  booking_links BookingLink[]\n  preferences   CalendarPreference[]\n\n  @@index([organization_id])\n  @@index([membership_id, is_default])\n  @@map(\"calendar_availability_schedules\")\n}\n\n/// 19 §6 — weekly recurring availability window. Several rows per weekday allow split shifts.\nmodel CalendarAvailabilityRule {\n  id          String @id @default(uuid())\n  schedule_id String\n  /// 0 = Sunday … 6 = Saturday.\n  weekday     Int\n  /// \"HH:MM\" in the schedule's timezone.\n  start_time  String\n  end_time    String\n\n  schedule CalendarAvailabilitySchedule @relation(fields: [schedule_id], references: [id], onDelete: Cascade)\n\n  @@index([schedule_id, weekday])\n  @@map(\"calendar_availability_rules\")\n}\n\n/// 19 §6 — date-specific override: block a day / hours (UNAVAILABLE) or open extra hours (AVAILABLE).\n/// Null start/end times mean the whole day.\nmodel CalendarAvailabilityOverride {\n  id          String                           @id @default(uuid())\n  schedule_id String\n  date        DateTime                         @db.Date\n  kind        CalendarAvailabilityOverrideKind @default(UNAVAILABLE)\n  start_time  String?\n  end_time    String?\n  reason      String?\n  created_at  DateTime                         @default(now())\n\n  schedule CalendarAvailabilitySchedule @relation(fields: [schedule_id], references: [id], onDelete: Cascade)\n\n  @@index([schedule_id, date])\n  @@map(\"calendar_availability_overrides\")\n}\n\n// --- Booking links -----------------------------------------------------------------\n\n/// 19 §6, §8 — self-scheduling page for customers and prospects (used by 02 and 13; portal users see\n/// them in 07 §11). Slots are computed from the hosts' availability schedules, their busy events,\n/// branch holidays (01 §122) and leave (10); confirmed bookings create a CalendarEvent of event_type.\nmodel BookingLink {\n  id                          String                @id @default(uuid())\n  organization_id             String\n  /// Public URL segment: /book/{org-slug}/{slug}.\n  slug                        String\n  name                        String\n  /// Markdown shown on the booking page.\n  description                 String?\n  status                      BookingLinkStatus     @default(DRAFT)\n  audience                    BookingLinkAudience   @default(PUBLIC)\n  owner_membership_id         String?\n  /// Restrict the link to one customer (CRM company, 02); portal users of that customer see it in 07.\n  company_id                  String?\n  /// Event type given to booked events (default: the system \"booking\" type).\n  event_type_id               String?\n  /// Calendar that receives the booked events; null = the assigned host's default personal calendar.\n  calendar_id                 String?\n  availability_schedule_id    String?\n  host_assignment             BookingHostAssignment @default(SINGLE)\n  duration_minutes            Int                   @default(30)\n  /// Alternative durations the invitee may pick; empty = fixed duration.\n  duration_options            Int[]                 @default([])\n  slot_interval_minutes       Int                   @default(30)\n  buffer_before_minutes       Int                   @default(0)\n  buffer_after_minutes        Int                   @default(0)\n  min_notice_minutes          Int                   @default(60)\n  max_days_ahead              Int                   @default(60)\n  /// Optional fixed booking window.\n  available_from              DateTime?             @db.Date\n  available_until             DateTime?             @db.Date\n  max_bookings_per_day        Int?\n  /// Collective / group links: invitees per slot (1 = one-to-one).\n  seats_per_slot              Int                   @default(1)\n  /// Bookings start PENDING until a host confirms.\n  requires_confirmation       Boolean               @default(false)\n  /// Fallback timezone shown on the page; invitees pick their own.\n  timezone                    String?\n  location                    String?\n  conferencing_provider       ConferencingProvider?\n  conferencing_account_id     String?\n  /// Questions asked at booking: [{ key, label, type, required, options }].\n  questions                   Json?\n  /// Reminders for the booked event: [{ method, minutes_before }] (§9).\n  reminders                   Json?\n  /// Invitee may cancel / reschedule until N minutes before start; null = always.\n  cancellation_notice_minutes Int?\n  allow_rescheduling          Boolean               @default(true)\n  /// Markdown shown after booking; redirect_url wins when set.\n  confirmation_message        String?\n  redirect_url                String?\n  /// Page branding overrides (01 §15 branding is the default).\n  branding                    Json?\n  /// Template for the created event title, e.g. \"{invitee_name} × {host_name}\".\n  event_title_template        String?\n  created_by_user_id          String?\n  archived_at                 DateTime?\n  created_at                  DateTime              @default(now())\n  updated_at                  DateTime              @updatedAt\n\n  organization          Organization                  @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  owner                 Membership?                   @relation(\"BookingLinkOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  company               CrmCompany?                   @relation(fields: [company_id], references: [id], onDelete: Cascade)\n  event_type            CalendarEventType?            @relation(fields: [event_type_id], references: [id], onDelete: SetNull)\n  calendar              Calendar?                     @relation(fields: [calendar_id], references: [id], onDelete: SetNull)\n  availability_schedule CalendarAvailabilitySchedule? @relation(fields: [availability_schedule_id], references: [id], onDelete: SetNull)\n  conferencing_account  CalendarConferencingAccount?  @relation(fields: [conferencing_account_id], references: [id], onDelete: SetNull)\n  hosts                 BookingLinkHost[]\n  bookings              CalendarBooking[]\n\n  @@unique([organization_id, slug])\n  @@index([organization_id, status])\n  @@index([owner_membership_id])\n  @@index([company_id])\n  @@map(\"booking_links\")\n}\n\n/// 19 §6 — Members who can be booked through a link. For ROUND_ROBIN the next host is chosen by\n/// priority then least-recently-booked; COLLECTIVE requires every host to be free.\nmodel BookingLinkHost {\n  id                       String   @id @default(uuid())\n  booking_link_id          String\n  membership_id            String\n  priority                 Int      @default(0)\n  /// Optional per-host schedule override; null = host's default schedule.\n  availability_schedule_id String?\n  created_at               DateTime @default(now())\n\n  booking_link BookingLink @relation(fields: [booking_link_id], references: [id], onDelete: Cascade)\n  membership   Membership  @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n\n  @@unique([booking_link_id, membership_id])\n  @@index([membership_id])\n  @@map(\"booking_link_hosts\")\n}\n\n/// 19 §6, §8, §12 — a booked slot. Confirmed bookings own one CalendarEvent (source BOOKING) and emit\n/// `calendar.booking_created`. The invitee is a portal user (user_id), a CRM contact (contact_id) or\n/// just a name + email.\nmodel CalendarBooking {\n  id                          String                @id @default(uuid())\n  organization_id             String\n  booking_link_id             String\n  event_id                    String?               @unique\n  host_membership_id          String?\n  status                      CalendarBookingStatus @default(CONFIRMED)\n  source                      CalendarBookingSource @default(PUBLIC_LINK)\n  starts_at                   DateTime\n  ends_at                     DateTime\n  /// Invitee's timezone at booking time.\n  timezone                    String\n  invitee_name                String\n  invitee_email               String\n  invitee_phone               String?\n  /// Customer Portal user who booked (01 §79).\n  invitee_user_id             String?\n  contact_id                  String?\n  company_id                  String?\n  /// Answers to BookingLink.questions: { key: value }.\n  answers                     Json?\n  /// Invitee note shown to the host.\n  notes                       String?\n  /// Record that triggered the booking (ticket 13, deal/lead 02) — polymorphic.\n  origin_entity_type          RecordEntityType?\n  origin_entity_id            String?\n  /// Token for the invitee's manage page (cancel / reschedule) without login.\n  manage_token                String                @unique @default(uuid())\n  confirmed_at                DateTime?\n  confirmed_by_user_id        String?\n  cancelled_at                DateTime?\n  /// invitee | host | system\n  cancelled_by                String?\n  cancellation_reason         String?\n  rescheduled_from_booking_id String?\n  no_show_marked_at           DateTime?\n  completed_at                DateTime?\n  /// Marketing attribution captured from the booking page (utm_*, referrer).\n  attribution                 Json?\n  created_at                  DateTime              @default(now())\n  updated_at                  DateTime              @updatedAt\n\n  organization     Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  booking_link     BookingLink       @relation(fields: [booking_link_id], references: [id], onDelete: Cascade)\n  event            CalendarEvent?    @relation(fields: [event_id], references: [id], onDelete: SetNull)\n  host             Membership?       @relation(\"CalendarBookingHost\", fields: [host_membership_id], references: [id], onDelete: SetNull)\n  invitee_user     User?             @relation(fields: [invitee_user_id], references: [id], onDelete: SetNull)\n  contact          CrmContact?       @relation(fields: [contact_id], references: [id], onDelete: SetNull)\n  company          CrmCompany?       @relation(fields: [company_id], references: [id], onDelete: SetNull)\n  rescheduled_from CalendarBooking?  @relation(\"CalendarBookingReschedule\", fields: [rescheduled_from_booking_id], references: [id], onDelete: SetNull)\n  rescheduled_to   CalendarBooking[] @relation(\"CalendarBookingReschedule\")\n\n  @@index([organization_id, status, starts_at])\n  @@index([booking_link_id, starts_at])\n  @@index([host_membership_id, starts_at])\n  @@index([invitee_email])\n  @@index([invitee_user_id])\n  @@index([contact_id])\n  @@index([company_id])\n  @@index([origin_entity_type, origin_entity_id])\n  @@map(\"calendar_bookings\")\n}\n\n// --- External sync -----------------------------------------------------------------\n\n/// 19 §7, §10 — an OAuth connection to Google Calendar or Microsoft 365. membership_id set = a Member's\n/// personal connection (calendar.sync.manage_own); null = organization-level connection for shared\n/// calendars. Tokens are stored encrypted by the API.\nmodel CalendarConnection {\n  id                   String                   @id @default(uuid())\n  organization_id      String\n  membership_id        String?\n  provider             CalendarProvider\n  status               CalendarConnectionStatus @default(PENDING_AUTH)\n  /// Provider account identity (Google sub / Microsoft oid) and the mailbox address.\n  external_account_id  String?\n  account_email        String?\n  /// Encrypted OAuth credentials: { access_token, refresh_token, expires_at, token_type }.\n  credentials          Json?\n  scopes               String[]                 @default([])\n  default_direction    CalendarSyncDirection    @default(TWO_WAY)\n  /// Provider push channel (Google watch / Microsoft subscription) for incremental sync.\n  watch_channel_id     String?\n  watch_resource_id    String?\n  watch_expires_at     DateTime?\n  last_synced_at       DateTime?\n  last_error           String?\n  last_error_at        DateTime?\n  connected_by_user_id String?\n  disconnected_at      DateTime?\n  created_at           DateTime                 @default(now())\n  updated_at           DateTime                 @updatedAt\n\n  organization Organization                 @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership   Membership?                  @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  calendars    CalendarConnectionCalendar[]\n  sync_runs    CalendarSyncRun[]\n\n  @@unique([organization_id, membership_id, provider, external_account_id])\n  @@index([organization_id, status])\n  @@index([membership_id])\n  @@index([watch_expires_at])\n  @@map(\"calendar_connections\")\n}\n\n/// 19 §7 — a remote calendar discovered on a connection and its mapping to a local Calendar. Local\n/// events of calendar_id are pushed and remote events are pulled according to direction.\n/// free_busy_only enforces §7: pulled events expose only busy blocks to other Members.\nmodel CalendarConnectionCalendar {\n  id             String                @id @default(uuid())\n  connection_id  String\n  /// Provider calendar id.\n  external_id    String\n  name           String\n  color          String?\n  is_primary     Boolean               @default(false)\n  /// Remote access level (owner | writer | reader) as reported by the provider.\n  access_role    String?\n  sync_enabled   Boolean               @default(false)\n  direction      CalendarSyncDirection @default(TWO_WAY)\n  /// Local calendar receiving pulled events / providing pushed events; null until sync is enabled.\n  calendar_id    String?\n  free_busy_only Boolean               @default(true)\n  /// Incremental sync cursor (Google syncToken / Microsoft deltaLink).\n  sync_cursor    String?\n  last_synced_at DateTime?\n  last_error     String?\n  created_at     DateTime              @default(now())\n  updated_at     DateTime              @updatedAt\n\n  connection    CalendarConnection         @relation(fields: [connection_id], references: [id], onDelete: Cascade)\n  calendar      Calendar?                  @relation(fields: [calendar_id], references: [id], onDelete: SetNull)\n  sync_mappings CalendarEventSyncMapping[]\n\n  @@unique([connection_id, external_id])\n  @@index([calendar_id])\n  @@map(\"calendar_connection_calendars\")\n}\n\n/// 19 §7 — one row per (event, connected calendar): the remote id, the provider's last-modified\n/// timestamp used to resolve conflicts, and the sync state. Overwritten local changes are also\n/// written to audit_events (`calendar.sync_overwritten`).\nmodel CalendarEventSyncMapping {\n  id                     String                    @id @default(uuid())\n  event_id               String\n  connection_calendar_id String\n  /// Provider event id; for recurring series the master id, with the instance id on exception rows.\n  external_id            String\n  external_ical_uid      String?\n  external_etag          String?\n  /// Provider-side updated timestamp; conflicts are resolved by the newer timestamp (§7).\n  external_updated_at    DateTime?\n  /// Local updated_at that was last pushed, to detect local-vs-remote divergence.\n  local_synced_version   DateTime?\n  status                 CalendarSyncMappingStatus @default(SYNCED)\n  last_pulled_at         DateTime?\n  last_pushed_at         DateTime?\n  /// Snapshot of the losing side when a conflict was auto-resolved (also audited).\n  conflict_snapshot      Json?\n  last_error             String?\n  created_at             DateTime                  @default(now())\n  updated_at             DateTime                  @updatedAt\n\n  event               CalendarEvent              @relation(fields: [event_id], references: [id], onDelete: Cascade)\n  connection_calendar CalendarConnectionCalendar @relation(fields: [connection_calendar_id], references: [id], onDelete: Cascade)\n\n  @@unique([connection_calendar_id, external_id])\n  @@unique([event_id, connection_calendar_id])\n  @@index([status])\n  @@map(\"calendar_event_sync_mappings\")\n}\n\n/// 19 §7 — queryable history of sync runs per connection (full or incremental), for diagnostics.\nmodel CalendarSyncRun {\n  id             String                @id @default(uuid())\n  connection_id  String\n  status         CalendarSyncRunStatus @default(RUNNING)\n  /// full | incremental | webhook\n  trigger        String                @default(\"incremental\")\n  started_at     DateTime              @default(now())\n  finished_at    DateTime?\n  events_pulled  Int                   @default(0)\n  events_pushed  Int                   @default(0)\n  events_deleted Int                   @default(0)\n  conflicts      Int                   @default(0)\n  error          String?\n  /// Per-calendar counters and provider diagnostics.\n  details        Json?\n\n  connection CalendarConnection @relation(fields: [connection_id], references: [id], onDelete: Cascade)\n\n  @@index([connection_id, started_at])\n  @@map(\"calendar_sync_runs\")\n}\n\n// --- Conferencing ------------------------------------------------------------------\n\n/// 19 §3 — connected video-conferencing accounts used to auto-create meeting links for events and\n/// bookings. GOOGLE_MEET / MICROSOFT_TEAMS may reuse the CalendarConnection credentials\n/// (calendar_connection_id); ZOOM has its own OAuth. membership_id null = organization-level account.\nmodel CalendarConferencingAccount {\n  id                     String                    @id @default(uuid())\n  organization_id        String\n  membership_id          String?\n  provider               ConferencingProvider\n  status                 ConferencingAccountStatus @default(ACTIVE)\n  external_account_id    String?\n  account_email          String?\n  /// Encrypted OAuth credentials or API key for providers with their own auth.\n  credentials            Json?\n  /// Reuses a calendar connection's token when the provider is Google Meet / Teams; id only (same module).\n  calendar_connection_id String?\n  /// Default meeting settings (waiting room, passcode, recording …).\n  settings               Json?\n  is_default             Boolean                   @default(false)\n  last_error             String?\n  disconnected_at        DateTime?\n  created_at             DateTime                  @default(now())\n  updated_at             DateTime                  @updatedAt\n\n  organization  Organization  @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  membership    Membership?   @relation(fields: [membership_id], references: [id], onDelete: Cascade)\n  booking_links BookingLink[]\n\n  @@unique([organization_id, membership_id, provider, external_account_id])\n  @@index([organization_id, provider])\n  @@index([membership_id])\n  @@map(\"calendar_conferencing_accounts\")\n}\n\n// =====================================================================\n// 20 Automation Engine — docs/features/20-automation-engine.md (LOG-410)\n// Owns: the trigger/action catalog modules register, automation rules and their versions, rule\n// templates, runs with per-action steps, approvals and AI steps, the platform event bus\n// (PlatformEvent), module-owned scheduled jobs and their runs, outbound webhooks and deliveries,\n// inbound webhook endpoints, run locks and per-organization engine settings.\n// Does not own: the records actions touch (tasks 06, tickets 13, projects 05, …), notification\n// delivery (14), outbound email/SMS (11), chat messages (12), service accounts (01 §76),\n// provider webhooks such as payment providers (08 provider_webhook_events), the audit log (01). Rule\n// create/edit/enable and destructive runs are also written to audit_events (20 §11).\n// =====================================================================\n\n/// 20 §2, §3 — what starts a rule.\nenum AutomationTriggerKind {\n  EVENT\n  SCHEDULE\n  DATE_RELATIVE\n  MANUAL\n  INBOUND_WEBHOOK\n}\n\n/// 20 §4 — category of an action exposed by a module or built into the engine.\nenum AutomationActionKind {\n  UPDATE_FIELD\n  ADD_TAG\n  SET_CUSTOM_FIELD\n  CHANGE_STATUS\n  ASSIGN\n  CREATE_RECORD\n  NOTIFY\n  SEND_COMMUNICATION\n  POST_MESSAGE\n  MANAGE_CHANNEL\n  CALL_WEBHOOK\n  AI_STEP\n  WAIT\n  APPROVAL\n  BRANCH\n  CUSTOM\n}\n\n/// 20 §4 — assignment strategy for ASSIGN actions.\nenum AutomationAssignStrategy {\n  MEMBER\n  TEAM\n  ROUND_ROBIN\n  LEAST_LOADED\n}\n\n/// 20 §5 — where a rule applies.\nenum AutomationRuleScopeType {\n  ORGANIZATION\n  BRANCH\n  TEAM\n  PROJECT_TYPE\n  PROJECT\n}\n\n/// 20 §5 — rule lifecycle. `enabled` is the user switch; status tracks draft/archive.\nenum AutomationRuleStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\n/// 20 §5 — live, test (sample event) or dry run (nothing is executed).\nenum AutomationRunMode {\n  LIVE\n  TEST\n  DRY_RUN\n}\n\n/// 20 §6, §8 — run lifecycle including retry and dead-letter states.\nenum AutomationRunStatus {\n  PENDING\n  RUNNING\n  WAITING\n  AWAITING_APPROVAL\n  RETRY_SCHEDULED\n  SUCCEEDED\n  FAILED\n  DEAD_LETTERED\n  SKIPPED\n  CANCELLED\n}\n\n/// 20 §6, §8 — per-action result inside a run.\nenum AutomationStepStatus {\n  PENDING\n  RUNNING\n  WAITING\n  AWAITING_APPROVAL\n  SUCCEEDED\n  FAILED\n  SKIPPED\n  CANCELLED\n}\n\n/// 20 §4, §6 — human approval gate decision.\nenum AutomationApprovalDecision {\n  PENDING\n  APPROVED\n  REJECTED\n  EXPIRED\n  CANCELLED\n}\n\n/// 20 §4, §9 — AI step operation through the shared AI layer.\nenum AutomationAiStepKind {\n  CLASSIFY\n  SUMMARIZE\n  EXTRACT\n  DRAFT\n}\n\n/// 20 §2 — who published an event to the bus.\nenum PlatformEventSource {\n  MODULE\n  API\n  INBOUND_WEBHOOK\n  SCHEDULED_JOB\n  AUTOMATION\n  SYSTEM\n}\n\n/// 20 §7 — schedule type of a module-owned job.\nenum ScheduledJobKind {\n  CRON\n  INTERVAL\n  ONCE\n}\n\n/// 20 §7\nenum ScheduledJobStatus {\n  ACTIVE\n  PAUSED\n  DISABLED\n  COMPLETED\n}\n\n/// 20 §7 — outcome of one job execution.\nenum ScheduledJobRunStatus {\n  PENDING\n  RUNNING\n  SUCCEEDED\n  FAILED\n  SKIPPED\n  CANCELLED\n  TIMED_OUT\n}\n\n/// 20 §12 — outbound webhook endpoint lifecycle; DISABLED after repeated failures.\nenum OutboundWebhookStatus {\n  ACTIVE\n  PAUSED\n  DISABLED\n}\n\n/// 20 §6, §12 — delivery attempt lifecycle.\nenum WebhookDeliveryStatus {\n  PENDING\n  RETRY_SCHEDULED\n  SUCCEEDED\n  FAILED\n  DEAD_LETTERED\n}\n\n/// 20 §12, §14 — inbound webhook endpoint lifecycle.\nenum InboundWebhookStatus {\n  ACTIVE\n  PAUSED\n  REVOKED\n}\n\n/// 20 §12, §14 — how an inbound webhook payload is authenticated.\nenum InboundWebhookAuthScheme {\n  HMAC_SHA256\n  BEARER_TOKEN\n  BASIC\n  NONE\n}\n\n// --- Organization settings -------------------------------------------------------\n\n/// 20 §6, §8, §10 — per-organization engine guardrails: rate limits, loop depth, retention,\n/// destructive-action enablement and the default service account rules may run under.\nmodel AutomationSettings {\n  organization_id                              String    @id\n  /// 20 §6 — rate limit per organization (runs started per hour).\n  org_rate_limit_per_hour                      Int       @default(10000)\n  /// 20 §6 — default per-rule rate limit; a rule may lower it.\n  default_rule_rate_limit_per_hour             Int       @default(1000)\n  /// 20 §6 — loop protection: max depth of rule → event → rule chains.\n  max_trigger_depth                            Int       @default(3)\n  /// 20 §6 — default retry policy applied to runs and deliveries.\n  default_max_retries                          Int       @default(5)\n  default_retry_backoff_seconds                Int       @default(60)\n  /// 20 §6, §10 — destructive actions must be explicitly enabled (automation.actions.destructive.enable).\n  destructive_actions_enabled                  Boolean   @default(false)\n  destructive_actions_enabled_at               DateTime?\n  destructive_actions_enabled_by_membership_id String?\n  /// 20 §6 — destructive / customer-facing actions require human approval by default.\n  destructive_requires_approval                Boolean   @default(true)\n  /// 20 §8 — run history retention; null = keep forever.\n  run_retention_days                           Int?      @default(365)\n  /// 20 §2 — event bus log retention.\n  event_retention_days                         Int?      @default(90)\n  /// 20 §7 — scheduled job run log retention.\n  job_run_retention_days                       Int?      @default(90)\n  /// 20 §6 — dead-letter alerting through 14 Notifications.\n  dead_letter_alerts_enabled                   Boolean   @default(true)\n  /// 20 §4, §14 — service account used when a rule has none of its own (01 §76).\n  default_service_account_id                   String?\n  /// 20 §9 — default confidence gate (0–100) for AI steps.\n  ai_default_confidence_threshold              Decimal   @default(80) @db.Decimal(5, 2)\n  updated_at                                   DateTime  @updatedAt\n\n  organization            Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_service_account ServiceAccount? @relation(\"AutomationSettingsDefaultServiceAccount\", fields: [default_service_account_id], references: [id], onDelete: SetNull)\n\n  @@map(\"automation_settings\")\n}\n\n// --- Trigger & action catalog ------------------------------------------------------\n\n/// 20 §3, §12 — a trigger a module registers (platform-wide, not tenant-scoped). `key` is the\n/// stable event key modules publish, e.g. `crm.deal.stage_changed`, `contracts.expiring`,\n/// `schedule.cron`, `record.date_relative`.\nmodel AutomationTriggerDefinition {\n  id                   String                @id @default(uuid())\n  module               ModuleKey\n  key                  String                @unique\n  name                 String\n  description          String?\n  kind                 AutomationTriggerKind @default(EVENT)\n  /// Primary record type the event is about (polymorphic entity on the rule run).\n  entity_type          RecordEntityType?\n  /// JSON Schema of the event payload; the rule builder uses it for condition fields (20 §5).\n  payload_schema       Json?\n  /// Sample event for test mode (20 §5).\n  sample_payload       Json?\n  /// DATE_RELATIVE triggers: date fields of the record that may be used, [{ key, label }] (20 §3).\n  date_fields          Json?\n  /// Trigger-specific config schema (e.g. { days: 30, direction: \"before\" } or cron) (20 §3).\n  config_schema        Json?\n  /// Permission needed to build a rule on this trigger (20 §10).\n  required_permission  String?\n  /// Also mirrored to 14 Notifications and outbound webhooks (20 §2).\n  notifiable           Boolean               @default(true)\n  webhook_subscribable Boolean               @default(true)\n  version              Int                   @default(1)\n  is_active            Boolean               @default(true)\n  sort_order           Int                   @default(0)\n  created_at           DateTime              @default(now())\n  updated_at           DateTime              @updatedAt\n\n  rules AutomationRule[]\n\n  @@index([module, is_active])\n  @@index([kind])\n  @@map(\"automation_trigger_definitions\")\n}\n\n/// 20 §4, §12 — an action a module exposes with its input schema and required permission.\n/// `key` e.g. `tasks.create`, `crm.deal.change_status`, `notifications.notify`, `engine.wait`.\nmodel AutomationActionDefinition {\n  id                  String               @id @default(uuid())\n  module              ModuleKey\n  key                 String               @unique\n  name                String\n  description         String?\n  kind                AutomationActionKind\n  /// Record type the action operates on, when it targets one.\n  entity_type         RecordEntityType?\n  /// JSON Schema of the action inputs (20 §4).\n  input_schema        Json?\n  /// JSON Schema of what the action returns; later steps can reference it (20 §4, §9).\n  output_schema       Json?\n  /// Permission the executing principal must hold (20 §4, §10).\n  required_permission String?\n  /// 20 §6 — delete, payment, external send to customers: needs explicit enablement.\n  is_destructive      Boolean              @default(false)\n  /// 20 §6 — sends to customers / external parties.\n  is_customer_facing  Boolean              @default(false)\n  /// 20 §6 — the action can be safely re-executed with the same idempotency key.\n  is_idempotent       Boolean              @default(true)\n  /// 20 §6 — default retry policy for transient failures.\n  retryable           Boolean              @default(true)\n  /// 20 §4 — AI steps and approval/wait steps are executed by the engine itself.\n  is_engine_builtin   Boolean              @default(false)\n  version             Int                  @default(1)\n  is_active           Boolean              @default(true)\n  sort_order          Int                  @default(0)\n  created_at          DateTime             @default(now())\n  updated_at          DateTime             @updatedAt\n\n  run_steps AutomationRunStep[]\n\n  @@index([module, is_active])\n  @@index([kind])\n  @@map(\"automation_action_definitions\")\n}\n\n// --- Rules -------------------------------------------------------------------------\n\n/// 20 §5, §14 — rule templates / recipes library (\"Deal won → create project from template\").\n/// organization_id null = system template shipped by the platform; otherwise an organization's own.\nmodel AutomationRuleTemplate {\n  id                       String    @id @default(uuid())\n  organization_id          String?\n  module                   ModuleKey\n  key                      String\n  name                     String\n  description              String?\n  category                 String?\n  /// Trigger kind/key + config, conditions and actions in the same shape as AutomationRule.\n  definition               Json\n  /// Variables the user fills when instantiating: [{ key, label, type, required, default }].\n  variables                Json?\n  is_system                Boolean   @default(false)\n  is_published             Boolean   @default(true)\n  usage_count              Int       @default(0)\n  created_by_membership_id String?\n  created_at               DateTime  @default(now())\n  updated_at               DateTime  @updatedAt\n\n  organization Organization?    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  created_by   Membership?      @relation(\"AutomationRuleTemplateAuthor\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  rules        AutomationRule[]\n\n  @@unique([organization_id, key])\n  @@index([module, is_published])\n  @@map(\"automation_rule_templates\")\n}\n\n/// 20 §2, §5, §6 — a rule: trigger + conditions + ordered actions, owned by an organization,\n/// versioned, enabled/disabled, scoped. The live definition is on the rule; each published edit\n/// is snapshotted in AutomationRuleVersion.\nmodel AutomationRule {\n  id              String               @id @default(uuid())\n  organization_id String\n  name            String\n  description     String?\n  /// Primary module the rule belongs to (for module filters and templates per module, 20 §5).\n  module          ModuleKey?\n  status          AutomationRuleStatus @default(DRAFT)\n  /// 20 §5 — user switch; only PUBLISHED + enabled rules run.\n  enabled         Boolean              @default(false)\n  /// 20 §5 — current published version number; incremented on every edit of a live rule.\n  current_version Int                  @default(1)\n\n  // 20 §2, §3 — trigger\n  trigger_kind          AutomationTriggerKind\n  /// Event key from the trigger catalog (e.g. `crm.deal.stage_changed`), `schedule.*`, `record.date_relative`, `manual`, `inbound_webhook`.\n  trigger_key           String\n  trigger_definition_id String?\n  /// Trigger configuration: event filters, { cron, timezone } / { interval_seconds }, { entity_type, date_field, offset_days, direction } for DATE_RELATIVE (20 §3).\n  trigger_config        Json?\n  /// Record type the rule primarily operates on (20 §2).\n  entity_type           RecordEntityType?\n\n  // 20 §2 — conditions and actions\n  /// Condition tree: { all: [...], any: [...], not: [...] } with predicates on payload, related records, custom fields, scope and time (20 §2).\n  conditions Json?\n  /// Ordered steps: [{ key, action_key, inputs, on_error: \"stop\"|\"continue\", branch?: {...}, wait?: {...}, approval?: {...}, ai?: {...} }] (20 §2, §4).\n  actions    Json\n\n  // 20 §5 — scope\n  scope_type      AutomationRuleScopeType @default(ORGANIZATION)\n  branch_id       String?\n  team_id         String?\n  project_type_id String?\n  project_id      String?\n\n  // 20 §4, §10 — execution principal\n  owner_membership_id       String?\n  /// 20 §4, §14 — run under a service account instead of the owner (01 §76).\n  run_as_service_account_id String?\n\n  // 20 §6 — execution semantics\n  /// Template for the per-run idempotency key, e.g. \"{{event.id}}\" or \"{{record.id}}:{{date}}\".\n  idempotency_key_template         String?\n  /// 20 §6 — runs for the same record are serialized when true.\n  serialize_per_record             Boolean @default(false)\n  max_retries                      Int?\n  retry_backoff_seconds            Int?\n  /// 20 §6 — per-rule rate limit; null = organization default.\n  rate_limit_per_hour              Int?\n  /// 20 §6 — loop protection; null = organization default.\n  max_trigger_depth                Int?\n  /// 20 §6 — rule contains destructive actions and they were explicitly allowed.\n  allow_destructive_actions        Boolean @default(false)\n  /// 20 §6 — destructive / customer-facing steps pause for human approval.\n  require_approval_for_destructive Boolean @default(true)\n  /// 20 §6 — maximum run time before the run is failed.\n  timeout_seconds                  Int?\n\n  // 20 §5 — provenance\n  template_id             String?\n  duplicated_from_rule_id String?\n  /// Import source metadata when the rule came from an export file (20 §5).\n  imported_from           Json?\n\n  // 20 §8 — rollups\n  last_run_at     DateTime?\n  last_run_status AutomationRunStatus?\n  run_count       Int                  @default(0)\n  failure_count   Int                  @default(0)\n  /// 20 §3 — next evaluation for SCHEDULE and DATE_RELATIVE triggers (mirrors the hosting ScheduledJob).\n  next_run_at     DateTime?\n\n  enabled_at         DateTime?\n  disabled_at        DateTime?\n  published_at       DateTime?\n  archived_at        DateTime?\n  created_by_user_id String?\n  created_at         DateTime  @default(now())\n  updated_at         DateTime  @updatedAt\n\n  organization       Organization                 @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  trigger_definition AutomationTriggerDefinition? @relation(fields: [trigger_definition_id], references: [id], onDelete: SetNull)\n  owner              Membership?                  @relation(\"AutomationRuleOwner\", fields: [owner_membership_id], references: [id], onDelete: SetNull)\n  run_as             ServiceAccount?              @relation(\"AutomationRuleRunAs\", fields: [run_as_service_account_id], references: [id], onDelete: SetNull)\n  branch             Branch?                      @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n  team               Team?                        @relation(fields: [team_id], references: [id], onDelete: Cascade)\n  project_type       ProjectType?                 @relation(fields: [project_type_id], references: [id], onDelete: Cascade)\n  project            Project?                     @relation(fields: [project_id], references: [id], onDelete: Cascade)\n  template           AutomationRuleTemplate?      @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  duplicated_from    AutomationRule?              @relation(\"AutomationRuleDuplicate\", fields: [duplicated_from_rule_id], references: [id], onDelete: SetNull)\n  duplicates         AutomationRule[]             @relation(\"AutomationRuleDuplicate\")\n\n  versions         AutomationRuleVersion[]\n  runs             AutomationRun[]\n  scheduled_jobs   ScheduledJob[]             @relation(\"ScheduledJobRule\")\n  inbound_webhooks AutomationInboundWebhook[]\n  run_locks        AutomationRunLock[]\n  /// 06 — recurring task instances created by this rule.\n  tasks            Task[]                     @relation(\"TaskAutomationRule\")\n  /// 02 §31 — activities created by this rule.\n  crm_activities   CrmActivity[]              @relation(\"CrmActivityAutomationRule\")\n\n  @@index([organization_id, status, enabled])\n  @@index([organization_id, trigger_kind, trigger_key])\n  @@index([organization_id, module])\n  @@index([trigger_definition_id])\n  @@index([owner_membership_id])\n  @@index([run_as_service_account_id])\n  @@index([branch_id])\n  @@index([team_id])\n  @@index([project_type_id])\n  @@index([project_id])\n  @@index([template_id])\n  @@index([next_run_at])\n  @@map(\"automation_rules\")\n}\n\n/// 20 §5 — immutable snapshot of a rule at each publish; editing a live rule creates a new version.\n/// Runs reference the version they executed (20 §8).\nmodel AutomationRuleVersion {\n  id                   String                  @id @default(uuid())\n  rule_id              String\n  version              Int\n  name                 String\n  description          String?\n  trigger_kind         AutomationTriggerKind\n  trigger_key          String\n  trigger_config       Json?\n  conditions           Json?\n  actions              Json\n  scope_type           AutomationRuleScopeType\n  /// { branch_id, team_id, project_type_id, project_id } at publish time.\n  scope                Json?\n  /// Execution settings at publish time (idempotency, retries, rate limit, destructive flags).\n  settings             Json?\n  change_summary       String?\n  author_membership_id String?\n  published_at         DateTime                @default(now())\n  /// Set when a newer version replaced this one.\n  superseded_at        DateTime?\n  created_at           DateTime                @default(now())\n\n  rule   AutomationRule  @relation(fields: [rule_id], references: [id], onDelete: Cascade)\n  author Membership?     @relation(\"AutomationRuleVersionAuthor\", fields: [author_membership_id], references: [id], onDelete: SetNull)\n  runs   AutomationRun[]\n\n  @@unique([rule_id, version])\n  @@index([author_membership_id])\n  @@map(\"automation_rule_versions\")\n}\n\n// --- Event bus -----------------------------------------------------------------------\n\n/// 20 §2, §6, §12 — the event bus log: a domain fact published by a module, the API, an inbound\n/// webhook or a scheduled job. Consumed by rules (20), 14 Notifications and outbound webhooks.\n/// `dedupe_key` gives at-least-once delivery with idempotent consumers.\nmodel PlatformEvent {\n  id               String              @id @default(uuid())\n  organization_id  String?\n  /// Stable key from the trigger catalog, e.g. `crm.deal.stage_changed`.\n  event_key        String\n  module           ModuleKey\n  source           PlatformEventSource @default(MODULE)\n  /// Primary record the event is about.\n  entity_type      RecordEntityType?\n  entity_id        String?\n  /// Free-form record kind when RecordEntityType has no value yet (e.g. \"leave_request\").\n  entity_kind      String?\n  /// Additional record references: [{ entity_type|entity_kind, entity_id, role }].\n  related_entities Json?\n  payload          Json\n  /// Before/after diff for *.updated / *.status_changed events, when the module provides it.\n  changes          Json?\n\n  // 20 §2 — actor\n  actor_type               AuditActorType @default(USER)\n  actor_user_id            String?\n  actor_membership_id      String?\n  actor_service_account_id String?\n\n  // 20 §6 — delivery & loop protection\n  /// Publisher-supplied idempotency key (module + record + version); duplicates are dropped.\n  dedupe_key           String?\n  /// Groups events of one business transaction.\n  correlation_id       String?\n  /// Run that caused this event, when published by an automation action (loop protection).\n  causation_run_id     String?\n  /// Depth of rule → event → rule chaining; rules stop at the configured max (20 §6).\n  trigger_depth        Int      @default(0)\n  inbound_webhook_id   String?\n  scheduled_job_run_id String?\n  occurred_at          DateTime @default(now())\n  received_at          DateTime @default(now())\n\n  // 20 §6 — consumer processing flags\n  rules_processed_at         DateTime?\n  rules_matched_count        Int       @default(0)\n  /// 14 Notifications fan-out done.\n  notifications_processed_at DateTime?\n  /// Outbound webhook fan-out done (20 §12).\n  webhooks_processed_at      DateTime?\n  /// All consumers done.\n  processed_at               DateTime?\n  processing_attempts        Int       @default(0)\n  processing_error           String?\n  next_processing_at         DateTime?\n  dead_lettered_at           DateTime?\n\n  organization          Organization?             @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  actor_user            User?                     @relation(\"PlatformEventActor\", fields: [actor_user_id], references: [id], onDelete: SetNull)\n  actor_membership      Membership?               @relation(\"PlatformEventActorMembership\", fields: [actor_membership_id], references: [id], onDelete: SetNull)\n  actor_service_account ServiceAccount?           @relation(\"PlatformEventActorServiceAccount\", fields: [actor_service_account_id], references: [id], onDelete: SetNull)\n  causation_run         AutomationRun?            @relation(\"PlatformEventCausationRun\", fields: [causation_run_id], references: [id], onDelete: SetNull)\n  inbound_webhook       AutomationInboundWebhook? @relation(fields: [inbound_webhook_id], references: [id], onDelete: SetNull)\n  scheduled_job_run     ScheduledJobRun?          @relation(fields: [scheduled_job_run_id], references: [id], onDelete: SetNull)\n\n  triggered_runs     AutomationRun[]   @relation(\"AutomationRunTriggerEvent\")\n  webhook_deliveries WebhookDelivery[]\n\n  @@unique([organization_id, dedupe_key])\n  @@index([organization_id, event_key, occurred_at])\n  @@index([organization_id, entity_type, entity_id])\n  @@index([organization_id, processed_at])\n  @@index([event_key, occurred_at])\n  @@index([next_processing_at])\n  @@index([correlation_id])\n  @@index([causation_run_id])\n  @@index([actor_user_id])\n  @@index([actor_membership_id])\n  @@index([actor_service_account_id])\n  @@index([inbound_webhook_id])\n  @@index([scheduled_job_run_id])\n  @@index([occurred_at])\n  @@map(\"platform_events\")\n}\n\n// --- Runs ------------------------------------------------------------------------------\n\n/// 20 §2, §6, §8 — one execution of a rule: trigger, inputs, conditions evaluated, status,\n/// duration, errors and retries. Steps hold each action result.\nmodel AutomationRun {\n  id                   String                @id @default(uuid())\n  organization_id      String\n  rule_id              String\n  rule_version_id      String?\n  /// Version number executed, kept even if the version row is pruned.\n  rule_version         Int\n  mode                 AutomationRunMode     @default(LIVE)\n  status               AutomationRunStatus   @default(PENDING)\n  trigger_kind         AutomationTriggerKind\n  trigger_key          String\n  event_id             String?\n  scheduled_job_run_id String?\n  /// 20 §6 — idempotency key; the same key never starts a second run for the rule.\n  idempotency_key      String\n  /// Primary record the run operates on (20 §8 — searchable by record).\n  entity_type          RecordEntityType?\n  entity_id            String?\n  entity_kind          String?\n  /// Trigger payload / sample event as received (20 §8).\n  input                Json?\n  /// Evaluated conditions: [{ path, operator, expected, actual, passed }] (20 §8).\n  conditions_result    Json?\n  /// False = conditions did not match; the run is SKIPPED.\n  conditions_passed    Boolean?\n  /// Final outputs keyed by step key (20 §4 — results are inputs to later actions).\n  output               Json?\n\n  // 20 §4, §8 — actor / principal\n  actor_type                AuditActorType @default(SYSTEM)\n  /// Member who ran the rule manually (20 §12).\n  actor_membership_id       String?\n  /// Principal the actions executed as (20 §4, §14).\n  run_as_service_account_id String?\n\n  // 20 §6 — chaining, retries, waiting\n  /// Run whose actions published the triggering event (loop protection).\n  parent_run_id                String?\n  trigger_depth                Int       @default(0)\n  attempt                      Int       @default(1)\n  max_attempts                 Int       @default(1)\n  next_retry_at                DateTime?\n  /// Index of the step currently executing / waiting.\n  current_step_index           Int?\n  /// WAIT step: resume at this time.\n  wait_until                   DateTime?\n  /// 20 §6, §11 — run executed a destructive or customer-facing action (audited).\n  performed_destructive_action Boolean   @default(false)\n\n  // 20 §8 — timing and errors\n  queued_at                  DateTime  @default(now())\n  started_at                 DateTime?\n  finished_at                DateTime?\n  duration_ms                Int?\n  error_code                 String?\n  error_message              String?\n  /// Structured error (stack, failing step, upstream response).\n  error                      Json?\n  dead_lettered_at           DateTime?\n  dead_letter_reason         String?\n  cancelled_at               DateTime?\n  cancelled_by_membership_id String?\n  created_at                 DateTime  @default(now())\n  updated_at                 DateTime  @updatedAt\n\n  organization      Organization           @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  rule              AutomationRule         @relation(fields: [rule_id], references: [id], onDelete: Cascade)\n  rule_version_ref  AutomationRuleVersion? @relation(fields: [rule_version_id], references: [id], onDelete: SetNull)\n  event             PlatformEvent?         @relation(\"AutomationRunTriggerEvent\", fields: [event_id], references: [id], onDelete: SetNull)\n  scheduled_job_run ScheduledJobRun?       @relation(fields: [scheduled_job_run_id], references: [id], onDelete: SetNull)\n  actor_membership  Membership?            @relation(\"AutomationRunActor\", fields: [actor_membership_id], references: [id], onDelete: SetNull)\n  run_as            ServiceAccount?        @relation(\"AutomationRunRunAs\", fields: [run_as_service_account_id], references: [id], onDelete: SetNull)\n  parent_run        AutomationRun?         @relation(\"AutomationRunChain\", fields: [parent_run_id], references: [id], onDelete: SetNull)\n  child_runs        AutomationRun[]        @relation(\"AutomationRunChain\")\n\n  steps         AutomationRunStep[]\n  approvals     AutomationApproval[]\n  ai_steps      AutomationAiStep[]\n  caused_events PlatformEvent[]      @relation(\"PlatformEventCausationRun\")\n  locks         AutomationRunLock[]\n\n  @@unique([rule_id, idempotency_key])\n  @@index([organization_id, status, created_at])\n  @@index([organization_id, rule_id, created_at])\n  @@index([organization_id, entity_type, entity_id])\n  @@index([rule_version_id])\n  @@index([event_id])\n  @@index([scheduled_job_run_id])\n  @@index([actor_membership_id])\n  @@index([run_as_service_account_id])\n  @@index([parent_run_id])\n  @@index([status, next_retry_at])\n  @@index([status, wait_until])\n  @@index([created_at])\n  @@map(\"automation_runs\")\n}\n\n/// 20 §4, §6, §8 — one action (step) inside a run with its inputs, result, retries and timing.\nmodel AutomationRunStep {\n  id                   String               @id @default(uuid())\n  run_id               String\n  /// 0-based position in the rule's actions list.\n  step_index           Int\n  /// Step key from the rule definition (referenced by later steps).\n  step_key             String\n  action_key           String\n  action_definition_id String?\n  kind                 AutomationActionKind\n  status               AutomationStepStatus @default(PENDING)\n  /// Resolved inputs after template interpolation.\n  input                Json?\n  output               Json?\n  /// 20 §6 — per-step idempotency key handed to the module action.\n  idempotency_key      String?\n  attempt              Int                  @default(1)\n  max_attempts         Int                  @default(1)\n  next_retry_at        DateTime?\n  /// WAIT step: resume time.\n  wait_until           DateTime?\n  /// BRANCH step: which branch key was taken.\n  branch_taken         String?\n  skipped_reason       String?\n  /// 20 §6 — this step was destructive / customer-facing.\n  is_destructive       Boolean              @default(false)\n  started_at           DateTime?\n  finished_at          DateTime?\n  duration_ms          Int?\n  error_code           String?\n  error_message        String?\n  error                Json?\n  created_at           DateTime             @default(now())\n  updated_at           DateTime             @updatedAt\n\n  run                AutomationRun               @relation(fields: [run_id], references: [id], onDelete: Cascade)\n  action_definition  AutomationActionDefinition? @relation(fields: [action_definition_id], references: [id], onDelete: SetNull)\n  approval           AutomationApproval?\n  ai_step            AutomationAiStep?\n  webhook_deliveries WebhookDelivery[]\n\n  @@unique([run_id, step_index])\n  @@index([action_definition_id])\n  @@index([status, next_retry_at])\n  @@index([status, wait_until])\n  @@map(\"automation_run_steps\")\n}\n\n/// 20 §4, §6, §9, §14 — human approval gate: a run pauses until a member approves or rejects.\nmodel AutomationApproval {\n  id                           String                     @id @default(uuid())\n  organization_id              String\n  run_id                       String\n  step_id                      String                     @unique\n  decision                     AutomationApprovalDecision @default(PENDING)\n  /// What is about to happen (action summary, record, AI output) shown to the approver.\n  context                      Json?\n  /// Member (or members, via Json) asked to approve; the first decision wins.\n  requested_from_membership_id String?\n  /// Additional approvers / team ids when more than one may decide.\n  requested_from               Json?\n  approver_membership_id       String?\n  comment                      String?\n  requested_at                 DateTime                   @default(now())\n  expires_at                   DateTime?\n  decided_at                   DateTime?\n  /// 14 Notification id sent for this request; id only.\n  notification_id              String?\n\n  organization          Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  run                   AutomationRun     @relation(fields: [run_id], references: [id], onDelete: Cascade)\n  step                  AutomationRunStep @relation(fields: [step_id], references: [id], onDelete: Cascade)\n  requested_from_member Membership?       @relation(\"AutomationApprovalRequestedFrom\", fields: [requested_from_membership_id], references: [id], onDelete: SetNull)\n  approver              Membership?       @relation(\"AutomationApprovalApprover\", fields: [approver_membership_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, decision])\n  @@index([run_id])\n  @@index([requested_from_membership_id, decision])\n  @@index([approver_membership_id])\n  @@index([expires_at])\n  @@map(\"automation_approvals\")\n}\n\n/// 20 §4, §9, §14 — AI step record: structured output with confidence, threshold gate and the\n/// approval it may require. Never executes irreversible actions by itself.\nmodel AutomationAiStep {\n  id                   String               @id @default(uuid())\n  organization_id      String\n  run_id               String\n  step_id              String               @unique\n  kind                 AutomationAiStepKind\n  /// Shared AI layer provider/model identifiers (Product_Specification §6).\n  provider             String?\n  model                String?\n  /// Prompt template key or inline instructions used.\n  prompt_template      String?\n  /// Resolved prompt / inputs sent to the model.\n  input                Json?\n  /// JSON Schema the output must match (classify labels, extract fields, …).\n  output_schema        Json?\n  /// Structured result.\n  output               Json?\n  /// 0–100.\n  confidence           Decimal?             @db.Decimal(5, 2)\n  /// Gate: below this the next step waits for approval or the run stops (20 §9).\n  confidence_threshold Decimal?             @db.Decimal(5, 2)\n  passed_threshold     Boolean?\n  requires_approval    Boolean              @default(false)\n  input_tokens         Int?\n  output_tokens        Int?\n  /// Provider cost in the organization currency; 6 decimals because unit prices are fractions of a cent.\n  cost_amount          Decimal?             @db.Decimal(18, 6)\n  latency_ms           Int?\n  error                String?\n  created_at           DateTime             @default(now())\n\n  organization Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  run          AutomationRun     @relation(fields: [run_id], references: [id], onDelete: Cascade)\n  step         AutomationRunStep @relation(fields: [step_id], references: [id], onDelete: Cascade)\n\n  @@index([organization_id, kind, created_at])\n  @@index([run_id])\n  @@map(\"automation_ai_steps\")\n}\n\n/// 20 §6 — serialization lock: runs for the same record are executed one at a time when the\n/// rule requires it. Rows are short-lived; expired locks are reclaimed by the worker.\nmodel AutomationRunLock {\n  id              String            @id @default(uuid())\n  organization_id String\n  rule_id         String?\n  run_id          String\n  entity_type     RecordEntityType?\n  entity_kind     String?\n  entity_id       String\n  /// Lock key as hashed: rule (or \"*\") + entity.\n  lock_key        String\n  acquired_at     DateTime          @default(now())\n  expires_at      DateTime\n\n  organization Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  rule         AutomationRule? @relation(fields: [rule_id], references: [id], onDelete: Cascade)\n  run          AutomationRun   @relation(fields: [run_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, lock_key])\n  @@index([run_id])\n  @@index([rule_id])\n  @@index([expires_at])\n  @@map(\"automation_run_locks\")\n}\n\n// --- Scheduled jobs --------------------------------------------------------------------\n\n/// 20 §7 — module-owned recurring job hosted by the engine (04 expiration monitoring,\n/// 08 billing/dunning, 09 recurring expenses, 12 channel archival, 13 SLA timers,\n/// 14 digests, 17 retention). Also hosts the schedule of SCHEDULE/DATE_RELATIVE rules\n/// (rule_id set). organization_id null = platform-wide job.\nmodel ScheduledJob {\n  id                    String                 @id @default(uuid())\n  organization_id       String?\n  /// 20 §7 — optional branch scope for branch-level module jobs (01 §34 branch reporting).\n  branch_id             String?\n  module                ModuleKey\n  /// Stable per-module job key, e.g. `finance.dunning.tick`, `contracts.expiration_monitor`.\n  key                   String\n  name                  String\n  description           String?\n  kind                  ScheduledJobKind       @default(CRON)\n  /// 5/6-field cron expression (CRON).\n  cron_expression       String?\n  interval_seconds      Int?\n  /// Single execution time (ONCE).\n  run_at                DateTime?\n  timezone              String                 @default(\"UTC\")\n  /// Handler the module registered for this job (service method key).\n  handler               String\n  /// Arguments passed to the handler on every run (e.g. { policy_id }).\n  payload               Json?\n  status                ScheduledJobStatus     @default(ACTIVE)\n  /// User rule whose schedule this job drives (20 §3).\n  rule_id               String?\n  next_run_at           DateTime?\n  last_run_at           DateTime?\n  last_run_status       ScheduledJobRunStatus?\n  last_error            String?\n  last_duration_ms      Int?\n  run_count             Int                    @default(0)\n  failure_count         Int                    @default(0)\n  consecutive_failures  Int                    @default(0)\n  /// 20 §6, §7 — retries with backoff.\n  max_retries           Int                    @default(3)\n  retry_backoff_seconds Int                    @default(60)\n  timeout_seconds       Int?\n  /// Skip the tick if the previous run is still running.\n  allow_overlap         Boolean                @default(false)\n  /// Run missed ticks after downtime, otherwise skip to the next one.\n  catch_up_missed       Boolean                @default(false)\n  /// Worker lease for exactly-one-runner scheduling.\n  locked_by             String?\n  locked_at             DateTime?\n  lock_expires_at       DateTime?\n  paused_at             DateTime?\n  created_at            DateTime               @default(now())\n  updated_at            DateTime               @updatedAt\n\n  organization Organization?     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  rule         AutomationRule?   @relation(\"ScheduledJobRule\", fields: [rule_id], references: [id], onDelete: Cascade)\n  runs         ScheduledJobRun[]\n  branch       Branch?           @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, module, key])\n  @@index([status, next_run_at])\n  @@index([organization_id, module])\n  @@index([rule_id])\n  @@index([branch_id])\n  @@index([lock_expires_at])\n  @@map(\"scheduled_jobs\")\n}\n\n/// 20 §7, §8 — one execution of a scheduled job.\nmodel ScheduledJobRun {\n  id                         String                @id @default(uuid())\n  job_id                     String\n  organization_id            String?\n  status                     ScheduledJobRunStatus @default(PENDING)\n  /// Tick this run was scheduled for.\n  scheduled_for              DateTime\n  started_at                 DateTime?\n  finished_at                DateTime?\n  duration_ms                Int?\n  attempt                    Int                   @default(1)\n  max_attempts               Int                   @default(1)\n  next_retry_at              DateTime?\n  /// Payload as passed to the handler for this run.\n  input                      Json?\n  /// Handler result / counters (e.g. { invoices_processed: 12 }).\n  output                     Json?\n  error_code                 String?\n  error_message              String?\n  error                      Json?\n  worker_id                  String?\n  /// Set when a member ran the job on demand.\n  triggered_by_membership_id String?\n  created_at                 DateTime              @default(now())\n  updated_at                 DateTime              @updatedAt\n\n  job          ScheduledJob  @relation(fields: [job_id], references: [id], onDelete: Cascade)\n  organization Organization? @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  triggered_by Membership?   @relation(\"ScheduledJobRunTriggeredBy\", fields: [triggered_by_membership_id], references: [id], onDelete: SetNull)\n\n  automation_runs  AutomationRun[]\n  published_events PlatformEvent[]\n\n  @@index([job_id, scheduled_for])\n  @@index([organization_id, status, created_at])\n  @@index([status, next_retry_at])\n  @@index([triggered_by_membership_id])\n  @@map(\"scheduled_job_runs\")\n}\n\n// --- Webhooks --------------------------------------------------------------------------\n\n/// 20 §12 — outbound webhook endpoint subscribed to platform events (and the target of the\n/// CALL_WEBHOOK action). `secret` is stored encrypted and used for HMAC signatures.\n/// Also the single webhook mechanism for every module's \"API & Webhooks\" section (02 §38, 03, 04, 05 §116,\n/// 06 §16, 09, 11, 13 §11, 14 §14, 15 §10, 17 §17, 18 §13, 19 §12) — modules publish events with their\n/// `<module>.<entity>.<action>` keys. Messaging webhooks (12 §39–40, §52) are rows here with\n/// `messaging.*` event keys and the optional channel filter below.\nmodel OutboundWebhook {\n  id                       String                @id @default(uuid())\n  organization_id          String\n  name                     String\n  description              String?\n  url                      String\n  /// Encrypted signing secret; shown once on creation.\n  secret                   String\n  /// Signature header algorithm, e.g. `hmac-sha256`.\n  signing_algorithm        String                @default(\"hmac-sha256\")\n  /// Event keys this endpoint receives, e.g. `automation.rule_run_failed`, `crm.deal.won`; `*` = all (20 §12).\n  subscribed_events        String[]              @default([])\n  /// Static headers added to every delivery.\n  headers                  Json?\n  /// 12 §40 — only messaging events from this channel; null = all channels the endpoint may see.\n  channel_id               String?\n  /// 12 §40, §53 — direct-message events are excluded unless explicitly enabled.\n  include_direct_messages  Boolean               @default(false)\n  content_type             String                @default(\"application/json\")\n  /// Payload shape version sent to the endpoint.\n  api_version              String?\n  status                   OutboundWebhookStatus @default(ACTIVE)\n  max_attempts             Int                   @default(5)\n  retry_backoff_seconds    Int                   @default(60)\n  timeout_seconds          Int                   @default(10)\n  /// Disabled automatically after this many consecutive failures; null = never.\n  disable_after_failures   Int?                  @default(50)\n  consecutive_failures     Int                   @default(0)\n  last_delivery_at         DateTime?\n  last_success_at          DateTime?\n  last_failure_at          DateTime?\n  disabled_at              DateTime?\n  disabled_reason          String?\n  created_by_membership_id String?\n  created_at               DateTime              @default(now())\n  updated_at               DateTime              @updatedAt\n\n  organization Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  created_by   Membership?       @relation(\"OutboundWebhookCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  channel      Channel?          @relation(\"WebhookChannelFilter\", fields: [channel_id], references: [id], onDelete: Cascade)\n  deliveries   WebhookDelivery[]\n\n  @@index([organization_id, status])\n  @@index([created_by_membership_id])\n  @@index([channel_id])\n  @@map(\"outbound_webhooks\")\n}\n\n/// 20 §6, §12 — one delivery of an event (or a CALL_WEBHOOK step) to an endpoint, with attempts,\n/// response code and retry state.\nmodel WebhookDelivery {\n  id                   String                @id @default(uuid())\n  organization_id      String\n  webhook_id           String\n  event_id             String?\n  /// Set when the delivery was produced by a CALL_WEBHOOK action rather than a subscription.\n  run_step_id          String?\n  event_key            String\n  status               WebhookDeliveryStatus @default(PENDING)\n  /// Body sent (after api_version shaping).\n  payload              Json\n  request_headers      Json?\n  attempt              Int                   @default(0)\n  max_attempts         Int                   @default(5)\n  next_retry_at        DateTime?\n  response_status_code Int?\n  /// Truncated response body for debugging.\n  response_body        String?\n  response_headers     Json?\n  error_message        String?\n  duration_ms          Int?\n  /// Per-delivery idempotency id sent in the signature header.\n  delivery_key         String                @unique @default(uuid())\n  last_attempt_at      DateTime?\n  delivered_at         DateTime?\n  dead_lettered_at     DateTime?\n  created_at           DateTime              @default(now())\n  updated_at           DateTime              @updatedAt\n\n  organization Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  webhook      OutboundWebhook    @relation(fields: [webhook_id], references: [id], onDelete: Cascade)\n  event        PlatformEvent?     @relation(fields: [event_id], references: [id], onDelete: SetNull)\n  run_step     AutomationRunStep? @relation(fields: [run_step_id], references: [id], onDelete: SetNull)\n\n  @@index([webhook_id, created_at])\n  @@index([organization_id, status, created_at])\n  @@index([event_id])\n  @@index([run_step_id])\n  @@index([status, next_retry_at])\n  @@map(\"webhook_deliveries\")\n}\n\n/// 20 §12, §14 — inbound webhook endpoint: external systems trigger rules with a signed payload.\n/// The request is logged as a PlatformEvent (source INBOUND_WEBHOOK, event_key `inbound_webhook.<slug>`).\nmodel AutomationInboundWebhook {\n  id                       String                   @id @default(uuid())\n  organization_id          String\n  /// Rule started by this endpoint; null = publishes the event for any rule with trigger_key `inbound_webhook.<slug>`.\n  rule_id                  String?\n  name                     String\n  description              String?\n  /// Public path token: /webhooks/in/{slug}.\n  slug                     String                   @unique\n  auth_scheme              InboundWebhookAuthScheme @default(HMAC_SHA256)\n  /// Encrypted secret / token used to verify the signature.\n  secret                   String\n  /// Header carrying the signature or token.\n  signature_header         String?\n  /// JSON Schema the payload must match; invalid payloads are rejected and logged.\n  payload_schema           Json?\n  /// Optional mapping from raw payload to the event payload (JSONPath / template).\n  payload_mapping          Json?\n  allowed_ip_ranges        String[]                 @default([])\n  status                   InboundWebhookStatus     @default(ACTIVE)\n  /// Requests per minute; null = organization default.\n  rate_limit_per_minute    Int?\n  received_count           Int                      @default(0)\n  rejected_count           Int                      @default(0)\n  last_received_at         DateTime?\n  last_rejected_at         DateTime?\n  last_rejection_reason    String?\n  secret_rotated_at        DateTime?\n  revoked_at               DateTime?\n  created_by_membership_id String?\n  created_at               DateTime                 @default(now())\n  updated_at               DateTime                 @updatedAt\n\n  organization Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  rule         AutomationRule? @relation(fields: [rule_id], references: [id], onDelete: SetNull)\n  created_by   Membership?     @relation(\"InboundWebhookCreator\", fields: [created_by_membership_id], references: [id], onDelete: SetNull)\n  events       PlatformEvent[]\n\n  @@index([organization_id, status])\n  @@index([rule_id])\n  @@index([created_by_membership_id])\n  @@map(\"automation_inbound_webhooks\")\n}\n"
}

